  sort(A.begin(), A.end());

  vector<Int>  X(N);
  for(Int i=0;i<N;i++){
    Int x, d; tie(x, d) = A[i];
    X[i] = x;
  }

  Compress <Int> cmpX;
  cmpX.add(X); cmpX.build();

  RMQ<Int, 1> seg(cmpX.size(), -INF);
  pr(cmpX.X);
  for(Int i=N-1;i>=0;i--){
    Int x, d; tie(x, d) = A[i];
    Int l = cmpX.getL(x);
    Int r = cmpX.getL(x + d);
    Int R = max(l, seg.get(l, r));
    pr(i, x, d, l, r, R);
    seg.ifupdate(l, l + 1, R);
  }

  vector<Int> used(N + 1), mem(N + 1);
  function<Int(Int)> dfs=[&](Int idx)->Int{
    if(idx == N) return 1;
    if(used[idx]++) return mem[idx];
    Int x, d; tie(x, d) = A[idx];

    //起爆
    Int R = seg.get(cmpX.getL(x), cmpX.getL(x) + 1);
    int i = lower_bound(X.begin(), X.end(), cmpX.X[R]) - X.begin();
    Int a = dfs(i + 1);

    //残す
    Int b = dfs(idx + 1);
    Int res = (a + b) % mod;
    return mem[idx] = res;
  };

  Int ans = dfs(0);
  cout<<ans<<endl;
  return 0;
}

