const int MOD = 998244353;
const int MAX = 2e5 + 5;
ii robots[MAX];
int memo[MAX], nxt[MAX];
int n;

inline int add(int a, int b) {
    return (a + b) % MOD;
}

int roll(int idx) {
    if (idx > n) {
        return 1;
    }
    int &ans = memo[idx];
    if (~ans) {
        return ans;
    }
    ans = add(roll(idx + 1), roll(nxt[idx]));
    return ans;
}

int aaa[MAX];

int dumb(int x) {
    if (aaa[x] > 0) return aaa[x];
    int &until = aaa[x];
    until = x;
    fori (i, x + 1, n + 1) {
        if (robots[x].first + robots[x].second <= robots[i].first) break;
        until = max(until, dumb(i));
    }
    return until;
}

void solve() {
    cin >> n;
    fori (i, 1, n + 1) cin >> robots[i].first >> robots[i].second;
    sort(robots + 1, robots + n + 1);
    vector<ii> stac;
    ford (i, n, 1) {
        int farthest = lower_bound(robots + 1, robots + n + 1, ii(robots[i].first + robots[i].second, 0)) - robots - 1; 
        int got = -1;
        int left = 0, right = (int) stac.size() - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (stac[mid].first <= farthest) {
                got = stac[mid].second - 1;
                right = mid - 1;
            }
            else {
                left = mid + 1;
            }
        }
        nxt[i] = max(farthest, got) + 1;
        while (!stac.empty() and nxt[i] >= stac.back().second) {
            stac.pop_back();
        }
        stac.emplace_back(i, nxt[i]);
    }
    memset(memo, -1, sizeof memo);
    cout << roll(1) << endl;
}

