ll thunder(ll currInd){
    if(currInd==N){
        return 1;
    }
    if(dp[currInd] != -1){
        return dp[currInd];
    }
    dp[currInd] = (thunder(indexes[currInd]+1)+thunder(currInd+1))%mod;
