int solve(int idx)
{
    if(idx==n) return 1;
    int &ret=dp[idx];
    if(~ret) return ret;
    ret=solve(idx+1);
    ret+=solve(nxt[idx]);
    ret%=mod;
    return ret;
}
void update(int idx,int val,int id=1,int l=0,int r=n-1)
{
    if(l==r)
    {
        seg[id]=val;
        return;
    }
    int mid=(l+r)/2;
    if(idx<=mid) update(idx,val,id*2,l,mid);
    else update(idx,val,id*2+1,mid+1,r);
    seg[id]=max(seg[id*2],seg[id*2+1]);
}
int query(int sq,int eq,int id=1,int l=0,int r=n-1)
{
    if(r<sq||l>eq) return 0;
    if(l>=sq&&r<=eq) return seg[id];
    int mid=(l+r)/2;
    return max(query(sq,eq,id*2,l,mid),query(sq,eq,id*2+1,mid+1,r));
}
