int n;
P v[225816],segtree[816225];

void init(int i, int l, int r){
	if(r-l>1){
		init(i*2+1,l,(l+r)/2);
		init(i*2+2,(l+r)/2,r);
		segtree[i] = max(segtree[i*2+1],segtree[i*2+2]);
	}else{
		segtree[i] = P(v[l].second,l);
	}
}

P query(int a, int b, int i, int l, int r){
	if(r<=a || b<=l){
		return P(-1ll,0ll);
	}else if(a<=l && r<=b){
		return segtree[i];
	}else{
		return max(query(a,b,i*2+1,l,(l+r)/2),query(a,b,i*2+2,(l+r)/2,r));
	}
}

bool done[225816][2];
ll memo[225816][2];

ll solve(int i, int st){
	int j;
	if(done[i][st]){
		return memo[i][st];
	}
	done[i][st] = true;
	if(i==n-1){
		return memo[i][st] = 1ll;
	}
	if(st){
		j = (int)(lower_bound(v,v+n,P(v[i].second,0ll))-v); --j;
		if(i==j){
			memo[i][st] = (solve(i+1,0)+solve(i+1,1))%MOD;
		}else{
			j = query(i+1,j+1,0,0,n).second;
			memo[i][st] = solve(j,1);
		}
	}else{
		memo[i][st] = (solve(i+1,0)+solve(i+1,1))%MOD;
	}
	return memo[i][st];
}

