ll dp[M];
ll seg[4*M],nxt[M];
void update(ll i,ll s,ll e,ll x,ll y)
{
	if(s==e)
	{
		seg[i]=y;
		return;
	}
	ll m=(s+e)/2;
	if(x<=m)
		update(2*i,s,m,x,y);
	else
		update(2*i+1,m+1,e,x,y);
	seg[i]=max(seg[2*i],seg[2*i+1]);
}
ll query(ll i,ll s,ll e,ll l,ll r)
{
	if(s>r || l>e)
		return 0;
	if(s>=l && e<=r)
		return seg[i];
	ll m=(s+e)/2;
	return max(query(2*i,s,m,l,r),query(2*i+1,m+1,e,l,r));
}
