	{
		ll x,d;
		cin>>x>>d;
		v.pb({x,d});
	}
	sort(all(v));
	dp[n]=1;
	for(ll i=n-1;i>=0;i--)
	{
		ll z=(ll)(lower_bound(all(v),mp(v[i].ff+v[i].ss,(ll)-1))-v.begin());
		//start from i end at z-1
		if(z==i+1)
		{
			update(1,0,n-1,i,i+1);
			dp[i]=(2*dp[i+1])%mod;
		}
		else
		{
			ll q=query(1,0,n-1,i+1,z-1);
			dp[i]=(dp[q]+dp[i+1])%mod;
			update(1,0,n-1,i,q);			
		}	
	}
	cout<<dp[0]<<"\n";
	return 0;
}

