      if (p.first < robots[i].first + robots[i].second) {
        e[i].emplace_back(p.second);
        topo.emplace_back(p.second);
        s.pop();
      }
      else
        break;
    }

    s.push({robots[i].first, i});
  }

  vector<int> roots;
  while (!s.empty()) {
    int i = s.top().second;
    topo.emplace_back(i);
    roots.emplace_back(i);
    s.pop();
  }

  vector<int> f(n);
  for (int i = 0; i < n; i++) {
    long long t = 1;
    for (int j = 0; j < e[topo[i]].size(); j++)
      t = t * f[e[topo[i]][j]] % mod;
    f[topo[i]] = (t + 1) % mod;
  }

  int ans = 1;
  for (int i = 0; i < roots.size(); i++)
    ans = 1LL * ans * f[roots[i]] % mod;
  printf("%d\n", ans);

  return 0;
}

