class SegTree {
	int** c;
	int level;
	int (*func)(int, int);
	int outval;
public:
	SegTree(int (*func)(int, int), int n, int t = 0, int outval = 0) :func(func), outval(outval) {
		for (int i = 0; i < 30; i++) {
			if (1 << i >= n) {
				level = i + 1;
				break;
			}
		}
		c = new int* [level];
		for (int i = 0; i < level; i++) {
			c[i] = new int[1 << (level - 1 - i)];
			for (int j = 0; j < 1 << (level - 1 - i); j++) {
				if (i == 0) {
					c[0][j] = j < n ? t : outval;
				}
				else {
					c[i][j] = func(c[i - 1][j << 1], c[i - 1][(j << 1) + 1]);
				}
			}
		}
	}
	SegTree(int (*func)(int, int), int n, int* t, int outval = 0) :func(func), outval(outval) {
		for (int i = 0; i < 30; i++) {
			if (1 << i >= n) {
				level = i + 1;
				break;
			}
		}
		c = new int* [level];
		for (int i = 0; i < level; i++) {
			c[i] = new int[1 << (level - 1 - i)];
			for (int j = 0; j < 1 << (level - 1 - i); j++) {
				if (i == 0) {
					c[0][j] = j < n ? t[j] : outval;
				}
				else {
					c[i][j] = func(c[i - 1][j << 1], c[i - 1][(j << 1) + 1]);
				}
			}
		}
	}
	void modval(int ind, int val) {
		c[0][ind] = val;
		for (int i = 1; i < level; i++) {
			c[i][ind >> 1] = func(c[i - 1][ind], c[i - 1][ind ^ 1]);
			ind >>= 1;
		}
	}
	int valInc(int from, int to) {
		int fv = c[0][from];
		int tv = c[0][to];
		for (int i = 0; i < level; i++) {
			if (from >> 1 == to >> 1)break;
			if (!(from & 1)) {
				fv = func(fv, c[i][from ^ 1]);
			}
			from >>= 1;
			if (to & 1) {
				tv = func(tv, c[i][to ^ 1]);
			}
			to >>= 1;
		}
		return func(fv, tv);
	}
};

int search(pair<int, int>* p, int t, int n) {
	int r = 0;
	for (int i = 30; i >= 0; i--) {
		int c = r | (1 << i);
		if (c >= n)continue;
		if (p[c].first < t)r = c;
	}
	return r;
}

