	dp[N] = 1;
	for (int i = N - 1; i >= 0; i--) {
		int r = search(p, p[i].second, N);
		r = maximum(st.valInc(i, r), r);
		st.modval(i, r);
		dp[i] = dp[i + 1] + dp[r + 1];
		dp[i] %= mod;
	}
