      }
    }
    vector<mint> dp(N + 1, mint(0));
    dp[0] = 1;
    for (int i = 0; i < N; i++) {
      dp[i + 1] += dp[i];
      dp[leftMost[i] + 1] += dp[i];
    }
    cout << dp[N].value() << endl;
  }
  return 0;
}

