#include <bits/stdc++.h>

using namespace std;

vector<int> tree;

void update(int node, int nl, int nr, int id, int val) {
	if (nl == nr) {
		tree[node] = val;
		return;	
	}
	int mid = nl + nr >> 1;
	if (id <= mid) {
		update(2 * node, nl, mid, id, val);
	} else {
		update(2 * node + 1, mid + 1, nr, id, val);
	}
	tree[node] = max(tree[2 * node], tree[2 * node + 1]);
	return;
}

int query(int node, int nl, int nr, int l, int r) {
	if (nr < l || r < nl) {
		return -1;
	}
	if (l <= nl && nr <= r) {
		return tree[node];
	}
	int mid = nl + nr >> 1;
	return max(query(2 * node, nl, mid, l, r), query(2 * node + 1, mid + 1, nr, l, r));
}

int main() {
	int n;
	cin >> n;
	tree.resize(n << 2);
	vector<pair<int, int>> a(n);
	vector<int> x(n), d(n), to(n);
	for (int i = 0; i < n; ++i)
		cin >> a[i].first >> a[i].second;
	sort(a.begin(), a.end());
	for (int i = 0; i < n; ++i) {
		x[i] = a[i].first;
		d[i] = a[i].second;
	}	
	to[n - 1] = n;
	update(1, 0, n - 1, n - 1, to[n - 1]);
	for (int i = n - 2; ~i; --i) {
		int r = lower_bound(x.begin() + i + 1, x.end(), x[i] + d[i]) - x.begin() - 1;
		if (r < i + 1) {
			to[i] = i + 1;
		} else {
			to[i] = query(1, 0, n - 1, i + 1, r);
		}
		update(1, 0, n - 1, i, to[i]);
	}
	vector<int> dp(n + 1);
	dp[n] = 1;
	for (int i = n - 1; ~i; --i) {
		dp[i] = dp[i + 1] + dp[to[i]];		
	}
	cout << dp[0] << '\n';
	return 0;
}

