	int max[N << 2];
	void insert(int l, int r, int x, int id, int k) {
		if (l == r) { max[x] = k; return;}
		int mid = l + r >> 1;
		if (id <= mid) insert(l, mid, x << 1, id, k);
		else insert(mid + 1, r, x << 1 | 1, id, k);
		max[x] = std::max(max[x << 1], max[x << 1 | 1]);
	}
	int query(int l, int r, int x, int ql, int qr, int ret = -1) {
		if (ql > qr || l > qr || r < ql) return -1;
		if (ql <= l && r <= qr) return max[x];
		int mid = l + r >> 1;
		if (ql <= mid) ret = std::max(ret, query(l, mid, x << 1, ql, qr));
		if (qr > mid) ret = std::max(ret, query(mid + 1, r, x << 1 | 1, ql, qr));
		return ret;
	}
}
