int N;
int turnon (deque<deque <long>> &localXD, int i, long maxX)
{
	int count = i;

	if (localXD.size () <= i + 1)
	{
		//ほかと相互作用しない場合はiを返す。
		localXD.erase (localXD.begin () + i);
		return i;
	}
	if (localXD[i+1][0] < maxX)
	{
		localXD.erase (localXD.begin () + i);
		if (localXD.size () > i)
			return max (i+1, turnon (localXD, i, max (maxX, localXD[i][0] + localXD[i][1])) + 1);
	}
	return count;
}
void pseudomain (deque<deque <long>> XD, int depth)
{
	int Nnew = XD.size ();
	deque<deque<deque <long>>> localXD (Nnew);
	for (auto &e: localXD)
	{
		e.resize (Nnew);
		for (int i = 0; i < Nnew; i++)
		{
			e [i].resize (2);
			e [i][0] = XD [i][0];
			e [i][1] = XD [i][1];
		}
	}

	int Cases = 1;
	int Sizei = 0;
	for (int i = 0; i < Nnew; i++)
	{
		int Deleted = turnon (localXD[i], i, localXD[i][i][0]+localXD[i][i][1]);
		if (depth == 0)
			Ri[i] = Deleted; //消去されるブロックの最大値
	}

}

