const int N = 2e5 + 1;
vi par(N, -1);

int root(int u) { return par[u] < 0 ? u : par[u] = root(par[u]); }
int merge(int u, int v) {
    u = root(u), v = root(v);
    if (u == v) return u;
    if (u > v) swap(u, v);
    par[u] += par[v];
    return par[v] = u;
}

void solve() {
    int n;
    cin >> n;
    vector<ii> a(n);
    vi nxt(n);
    for (int i = 0; i < n; ++i) cin >> a[i].fi >> a[i].se;
    sort(all(a));

    stack<int> in;
    for (int i = n; i--;) {
        int x = upper_bound(all(a), ii{a[i].fi + a[i].se, 0}) - a.begin() - 1;

        if (i == x) {
            nxt[i] = i + 1;
            in.push(i);
            continue;
        }

        while (!in.empty()) {
            int f = in.top();

            if (f > x) break;

            in.pop();
            merge(i, f);
        }
        nxt[i] = i - par[i];
        in.push(i);
    }

    vi dp(n + 1, 1);
    for (int i = n; i--;) dp[i] = (dp[nxt[i]] + dp[i + 1]) % M;
    cout << dp[0] << '\n';
}

