		if(a.at(i).first>=a.at(r).first+a.at(r).second) break ;
		res = res*robot(a,use,i,right)%mod ;
	}
//	cout << r << " " << res << endl ;
	right = max(right,r) ;
	return (res+1)%mod ;
}

