	Segmenttree seg = Segmenttree();
	seg.init();

	vector<pair<ll, ll>>p(N);
	for (int i = 0; i < N; i++) {
		ll X, D;
		cin >> X >> D;
		p[i].first = X;
		p[i].second = D;
	}
	sort(all(p));

	for (int i = 0; i < N; i++) {
		seg.st(i,p[i].first + p[i].second);
	}


	dp[0] = 1;
	sum[0] = 1;
	for (int i = 1; i < N; i++) {
		int ok = i, ng = -1;
		while (ok - ng > 1) {
			int mid = (ok + ng) / 2;
			if (seg.get(mid + 1,i-1) <= p[i].first)ok = mid;
			else ng = mid;
		}
		if (ok == 0)dp[i] = sum[i - 1];
		else dp[i] = (sum[i - 1] - sum[ok-1] + 8LL*MOD)%MOD;
		if (seg.get(0, i - 1) <= p[i].first)dp[i]++;
		sum[i] = sum[i - 1] + dp[i];
		sum[i] %= MOD;
	}
	ll ans = 1;
	for (int i = 0; i < N; i++) {
		ans += dp[i];
		ans %= MOD;
	}
	puts(ans);

	return 0;
}

