	for(int i=N+1;i<Maxn;i++)	dp[i]= 1;	//因为空的也算一种 
	for(int i=N-1;i>=1;i--)
	{
		dp[i] = dp[i+1] + dp[Touch_Far_Robot[i]+1];
		dp[i]%=Mod;
	}
