struct mint {
	ll x;
	mint(ll x=0):x((x%MOD+MOD)%MOD){}
	mint operator-() const { return mint(-x);}
	mint& operator+=(const mint a) {if ((x+=a.x)>=MOD) x-=MOD; return *this;}
	mint& operator-=(const mint a) {if ((x+=MOD-a.x)>=MOD) x-=MOD; return *this;}
	mint& operator*=(const mint a) {(x*=a.x)%=MOD; return *this;}
	mint operator+(const mint a) const {mint res(*this); return res+=a;}
	mint operator-(const mint a) const {mint res(*this); return res-=a;}
	mint operator*(const mint a) const {mint res(*this); return res*=a;}
	mint pow(ll t) const {
		if (!t) return 1;
		mint a = pow(t>>1);
		a *= a;
		if (t&1) a *= *this;
 		return a;
	}

	// For prime mod.
	// Do not use if MOD is not prime number !!
	mint inv() const { return pow(MOD-2);}
	mint& operator/=(const mint a) { return (*this) *= a.inv();}
	mint operator/(const mint a) const {mint res(*this); return res/=a;}
};

vvll g;

mint dfs(ll s) {
    mint ret = 1;
    for(auto i : g[s]) {
        ret *= dfs(i);
    }
    return ret + 1;
}

void solve() {
    ll n;
    cin >> n;
    vpll p;
    for(ll i = 0; i < n; i++) {
        ll x, d;
        cin >> x >> d;
        p.push_back(make_pair(x, d));
    }
    sort(p.begin(), p.end(), greater<pll>());
    g = vvll(n);
    priority_queue<pll, vpll, greater<pll>> q;
    for(ll i = 0; i < n; i++) {
        ll x = p[i].first, d = p[i].second;
        while(!q.empty() && q.top().first < x + d) {
            g[i].push_back(q.top().second);
            q.pop();
        }
        q.push(make_pair(x, i));
    }
    mint ans = 1;
    while(!q.empty()) {
        ans *= dfs(q.top().second);
        q.pop();
    }
    cout << ans.x << endl;
    return;
}

