constexpr long long int MOD = 998244353;
struct Robot {
	int id, position, distance;
	int right() const { return position + distance; }
};
int lower_bound(const std::deque<int>& deque, const std::vector<Robot> &robots, int position) {
	int min = 0;
	int max = deque.size();
	while (min < max) {
		const auto mid = (min + max) / 2;
		if (robots[deque[mid]].position < position) min = mid + 1;
		else max = mid;
	}
	return min;
}
int main() {
	int n; std::cin >> n;
	std::vector<Robot> robots(n);
	for (auto i = 0; i < n; ++i) {
		robots[i].id = i;
		std::cin >> robots[i].position >> robots[i].distance;
	}
	std::sort(robots.begin(), robots.end(), [](const Robot a, const Robot b) {return a.position < b.position; });
	std::vector<int> next(n);
	std::deque<int> deque; 
	for (int i = n - 1; i >= 0; --i) {
		const auto current = robots[i];
		const auto right = lower_bound(deque, robots, current.right());
		if (right == 0) {
			next[i] = i + 1;
		}
		else if (right == deque.size()) {
			next[i] = n;
		}
		else {
			next[i] = deque[right];
		}
		for (auto j = 0; j < right; ++j) 
			deque.pop_front();
		deque.push_front(i);
	}
	std::vector<long long int> dp(n + 1, 0); dp.back() = 1;
	for (int i = n - 1; i >= 0; --i) {
		dp[i] = (dp[i + 1] + dp[next[i]]) % MOD;
	}
	std::cout << dp.front() << '\n';
}

