// ----- Solve -----

using Robot = tuple<ll, ll>;
using Info = tuple<ll, int>;

class Solve
{
  int N;
  vector<Robot> robots;
  vector<vector<int>> V;

public:
  Solve(int N) : N{N}, robots(N), V(N)
  {
    for (auto i{0}; i < N; ++i)
    {
      auto &[x, d]{robots[i]};
      cin >> x >> d;
    }
    sort(robots.rbegin(), robots.rend());
  }

  void flush()
  {
    set<Info> S;
    for (auto i{0}; i < N; ++i)
    {
      auto [x, d]{robots[i]};
      while (!S.empty())
      {
        auto it{S.begin()};
        auto [y, ind]{*it};
        if (y < x + d)
        {
          V[i].push_back(ind);
          S.erase(it);
        }
        else
        {
          break;
        }
      }
      S.emplace(x, i);
    }
    mint ans{1};
    for (auto e : S)
    {
      ans *= dfs(get<1>(e));
    }
    cout << ans << endl;
  }

private:
  mint dfs(int src)
  {
    mint ans{1};
    for (auto dst : V[src])
    {
      ans *= dfs(dst);
    }
    return ans + 1;
  }
};

// ----- main() -----

int main()
{
  int N;
  cin >> N;
  Solve solve(N);
  solve.flush();
}

