  std::sort(all(robot));

  std::vector<std::vector<ll>> dp(n+1,std::vector<ll>(2,0));

  dp[n][0]=1;
  dp[n][1]=0;

  SegmentTree<ll> seg(n,-1,[](ll a,ll b){return std::max(a,b);});

  for(ll i=n-1;i>=0;i--){
    ll lower=std::lower_bound(all(robot),P(robot[i].first,-1))-robot.begin();
    ll upper=std::lower_bound(all(robot),P(robot[i].first+robot[i].second,-1))-robot.begin();
    seg.update(i,i,true);

