template<typename T>
struct SegmentTree { // 1-indexed
  int n; // size of original vector
  vector<T> d;
  T idt = -1; // identity element
  T op(T &a, T &b) {
    // return a + b;
    return max(a, b);
    // return gcd(a, b);
  }
  SegmentTree(int n=0) : n(n) { d.assign(n<<1, idt); }
  SegmentTree(vector<T> &v) : n(v.size()) {
    d.reserve(n<<1);
    copy(all(v), d.begin()+n);
    drep2(i, n, 1) d[i] = op(d[i<<1], d[i<<1|1]);
  }
  void update(int i) { while (i > 1) i >>= 1, d[i] = op(d[i<<1], d[i<<1|1]); }
  void add(int i, T x) { i += n, d[i] += x; update(i); }
  void set(int i, T x) { i += n, d[i] = x; update(i); }
  T op_range(int l, int r) {
    T vl = idt, vr = idt;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l&1) vl = op(vl, d[l++]);
      if (r&1) vr = op(d[--r], vr);
    }
    return op(vl, vr);
  }
  T operator[](const int i) { return d[n+i]; }
};


int main() {
