    auto [x, d] = xd[i];
    int j = lower_bound(all(xd), Pi{x+d, -1}) - xd.begin();
    r.set(i, max(i, r.op_range(i+1, j)));
    dp[i] = dp[i+1] + dp[r[i]+1];
  }
  cout << dp[0] << '\n';
}

