    for (int i = n - 1; i >= 0; --i) {
        int x = lower_bound(ALL(s), pair<ll, ll>(s[i].first + s[i].second, 0)) - s.begin();
        ST.update(i, max(x, ST.get(i + 1, x)));
        dp[i] = dp[i + 1] + dp[ST.get(i, i + 1)];
    }
