int seg[4*MAXN];
vector<pair<ll, int> > robots;

void init()
{
	while ((1<<p) < n) ++p;
	deb = (1<<p) - 1;
}

int query(int l, int r)
{
	l += deb;
	r += deb;
	int ans(0);
	while (l < r)
	{
		if (l%2==0)
			ans = max(ans, seg[l]);
		if (r%2)
			ans = max(ans, seg[r]);
		l /= 2;
		r = (r-2)/2;
	}
	if (l == r)
		ans = max(ans, seg[l]);
	return ans;
}	

void update(int pos, int x)
{
	pos += deb;
	seg[pos] = x;
	while (pos > 0)
	{
		pos = (pos-1)/2;
		seg[pos] = max(seg[2*pos+1], seg[2*pos+2]);
	}
}

