typedef pair<lint, lint> P;
const lint MOD = 1000000007;
const lint MOD9 = 998244353;
const lint INF = MOD * MOD;
const int MAX = 600000;

/* ...o(^-^)o... */
lint arr[MAX];
struct segtree{
    int n;
    segtree(int n_){
        n = 2;
        while(n < n_) n *= 2;
        rep(i, n*2) arr[i] = 0;
    }
    void update(int k, lint a){
        k += n - 1;
        arr[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            arr[k] = max(arr[k * 2 + 1], arr[k * 2 + 2]);
        }
    }
    long query_(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return 0;
        if(a <= l && r <= b) return arr[k];
        else{
            int vl = query_(a, b, k * 2 + 1, l, (l + r) / 2);
            int vr = query_(a, b, k * 2 + 2, (l + r) / 2, r);
            return max(vl, vr);
        }
    }
    long query(int a, int b){
        return query_(a, b, 0, 0, n);
    }
};

int main(){
    int n; cin >> n;
    vector<P> vp;
    rep(i, n){
        lint x, d; cin >> x >> d;
        vp.push_back(P(x, x + d));
    }
    sort(all(vp));

    rep(i, n){
        P p = P(vp[i].se, -INF);
        auto itr = lower_bound(all(vp), p);
        vp[i].se = itr - vp.begin();
    }

    segtree st(n+1);
    rep(i, n) st.update(i, i);
    vector<lint> r(n);
    repr(i, n){
        lint q = st.query(i, vp[i].se);
        r[i] = q;
        st.update(i, q);
    }

    vector<lint> dp(n+1);
    dp[n] = 1;
    repr(i, n){
        dp[i] = dp[i+1];
        if(r[i] + 1 <= n) dp[i] += dp[r[i]+1];
        dp[i] %= MOD9;
    }

    out(dp[0]);
}

