void dodaj(int t, int l, int r,int x, int val)
{
    seg[t]=max(seg[t],val);
    if(l==r)
        return;
    int mid=(l+r)/2;
    if(x<=mid) dodaj(2*t,l,mid,x,val);
    else dodaj(2*t+1,mid+1,r,x,val);
}

int maxq(int t, int l, int r, int L, int R)
{
    if(l>R || L>r) return 0;
    if(l>=L && r<=R) return seg[t];
    int mid=(l+r)/2;
    int r1=maxq(2*t,l,mid,L,R);
    int r2=maxq(2*t+1,mid+1,r,L,R);
    return max(r1,r2);
}

int nadji(int i)
{
    int val=a[i].first+a[i].second;
