class Solver {
 public:
  int n;
  vector<LL> x, d;
  Solver(LL n) : n(n), x(n), d(n){};

  void solve() {
    for (int i = 0; i < n; ++i) {
      cin >> x[i] >> d[i];
    }
    vector<int> perm;
    for (int i = 0; i < n; ++i) {
      perm.push_back(i);
    }
    sort(perm.begin(), perm.end(), [&](int a, int b) -> bool { return x[a] < x[b]; });
    {
      vector<LL> tmp(x);
      vector<LL> tmpd(d);
      for (int i = 0; i < n; ++i) {
        x[i] = tmp[perm[i]];
        d[i] = tmpd[perm[i]];
      }
    }
    vector<Modint<>> dp(n + 1);
    vector<Modint<>> sum(n + 1);
    vector<int> r_bound(n + 1);
    dp[n] = Modint<>(1);
    sum[n] = dp[n];
    stack<pair<int, int>> S;
    r_bound[n] = n;
    S.emplace(n, n);
    for (int i = n - 1; i >= 0; --i) {
      int p = distance(x.begin(), lower_bound(x.begin(), x.end(), x[i] + d[i])) - 1;
      while (!S.empty()) {
        if (S.top().first <= p) {
          p = max(p, S.top().second);
          S.pop();
        } else {
          break;
        }
      }
      r_bound[i] = p;
      S.emplace(i, p);
    }
    for (int i = n - 1; i >= 0; --i) {
      dp[i] = sum[r_bound[i] + 1];
      sum[i] = sum[i + 1] + dp[i];
    }
    cout << accumulate(dp.begin(), dp.end(), Modint<>(0)) << endl;
  }
};

