int tree[1000005];
int mod = 998244353;

void updateTree(int node, int start, int ends, int ind, int val)
{
    if(start == ends)
    {
        tree[node] = val;
        return;
    }
    int mid = (start+ends)/2;
    if(mid>=ind)
        updateTree(node*2, start, mid, ind, val);
    else
        updateTree(node*2+1, mid+1, ends, ind, val);
    tree[node] = max(tree[node*2], tree[node*2+1]);
}

int queryTree(int node, int start, int ends, int l, int r)
{
    if(start == ends || (start >= l && ends <= r))
        return tree[node];
    int mid = (start + ends) / 2;
    int p1 = 0, p2 = 0;
    if(mid>=l)
        p1 = queryTree(node*2, start, mid, l, r);
    if(mid < r)
        p2 = queryTree(node*2+1, mid+1, ends, l, r);
    return max(p1, p2);
}

