class mint {
  int n;
public:
  mint(int n_ = 0) : n(n_) {}
  explicit operator int() { return n; }
  friend mint operator-(mint a) { return -a.n + MOD * (a.n != 0); }
  friend mint operator+(mint a, mint b) { int x = a.n + b.n; return x - (x >= MOD) * MOD; }
  friend mint operator-(mint a, mint b) { int x = a.n - b.n; return x + (x < 0) * MOD; }
  friend mint operator*(mint a, mint b) { return (long long)a.n * b.n % MOD; }
  friend mint &operator+=(mint &a, mint b) { return a = a + b; }
  friend mint &operator-=(mint &a, mint b) { return a = a - b; }
  friend mint &operator*=(mint &a, mint b) { return a = a * b; }
  friend bool operator==(mint a, mint b) { return a.n == b.n; }
  friend bool operator<(mint a, mint b) { return a.n < b.n; }
  friend bool operator!=(mint a, mint b) { return a.n != b.n; }
  friend istream &operator>>(istream &i, mint &a) { return i >> a.n; }
  friend ostream &operator<<(ostream &o, mint a) { return o << a.n; }
};

mint modinv(mint n) {
  int a = (int)n, b = MOD;
  int s = 1, t = 0;
  while (b != 0) {
    int q = a / b;
    a -= q * b;
    s -= q * t;
    swap(a, b);
    swap(s, t);
  }
  return s >= 0 ? s : s + MOD;
}

const int INF = 1e9;

class segment_tree {
  using T = int;
  int N;
  vector<T> dat;
  T mempty = -INF;
  int mappend(int x, int y) {
    return max(x, y);
  }

public:
  segment_tree(int n) {
    N = 1;
    while (N < n) N *= 2;
    dat.resize(N * 2, mempty);
    for (int i = 0; i < n; i++) {
      dat[i + N] = mempty;
    }
    for (int i = N - 1; i >= 1; i--) {
      dat[i] = mappend(dat[i * 2], dat[i * 2 + 1]);
    }
  }

  void update(int k, T v) {
    k += N;
    dat[k] = v;
    while (k > 1) {
      k >>= 1;
      dat[k] = mappend(dat[k * 2], dat[k * 2 + 1]);
    }
  }

  T query(int l, int r) {
    l += N;
    r += N - 1;
    T x = mempty, y = mempty;
    while (l <= r) {
      if ((l & 1) == 1) x = mappend(x, dat[l++]);
      if ((r & 1) == 0) y = mappend(dat[r--], y);
      l >>= 1;
      r >>= 1;
    }
    return mappend(x, y);
  }
};

