  for (int i = N - 1; i >= 0; i--) {
    next[i] = i;
    // X[j] < X[i] + D[i]
    int j = lower_bound(range(X), X[i] + D[i]) - X.begin();
    if (i + 1 < j) {
      next[i] = seg.query(i, j);
    }
    seg.update(i, next[i]);
  }
  vector<mint> dp(N + 1);
  dp[0] = 1;
  rep(i, N) {
    dp[i + 1] += dp[i];
    dp[next[i] + 1] += dp[i];
  }
  cout << dp[N] << endl;
}

