typedef pair<LL, LL> PII;

LL MOD = 998244353;
void solve(long long N, std::vector<long long> X, std::vector<long long> D)
{
  vector<PII> data;
  for (int i = 0; i < N; i++)
    data.push_back(PII(X[i], D[i]));
  sort(data.begin(), data.end());

  LL ans = 1;
  stack<PII> sta;
  for (auto xd : data)
  {
    LL x = xd.first;
    LL d = xd.second;

    while (!sta.empty())
    {
      auto val = sta.top();
      if (x >= val.first)
      {
        // /cout << x << " " << val.second << endl;
        ans += val.second;
        ans %= MOD;
        sta.pop();
      }
      else
        break;
    }
    sta.push(PII(x + d, ans));
  }
  while (!sta.empty())
  {
    ans += sta.top().second;
    ans %= MOD;
    sta.pop();
  }
  cout << ans << endl;
}

