        nx[i]=query(1,1,n,i,lo);
        nx[i]=max(nx[i],i);
        upd(1,1,n,i,nx[i]);
    }
    dp[0]=1;
    fo(i,1,n){
        dp[nx[i]]=(dp[nx[i]]+dp[i-1])%md;
        dp[i]=(dp[i]+dp[i-1])%md;
    }
    cout<<dp[n]<<endl;
    return 0;
}

