int64_t Q=998244353;

int MAX_N=262144;
vector<int64_t> seg(MAX_N*2-1,2147483647);
int64_t qu(int a,int b,int k,int l, int r){
  if(r<=a||b<=l){
    return 2147483647;
  }
  else if(a<=l&&r<=b){
    return seg[k];
  }
  else{
    int64_t X=qu(a,b,k*2+1,l,(l+r)/2);
    int64_t Y=qu(a,b,k*2+2,(l+r)/2,r);
    return min(X,Y);
  }
}
void chmin(int64_t a,int b){
  int D=MAX_N-1+b;
  seg[D]=a;
  while(D>0){
    D--;
    D/=2;
    seg[D]=min(seg[2*D+1],seg[2*D+2]);
  }
}

