// segtree {{{
template <class Monoid>
class segtree {
  public:
    using value_type = typename Monoid::value_type;
  private:
    int size;
    vector<value_type> data;
    value_type query_impl(int left, int right, int node, int a, int b) const {
      if (right <= a || b <= left) return 0;
      if (left <= a && b <= right) return data[node];
      auto lv = query_impl(left, right, 2 * node + 1, a, (a + b) / 2),
           rv = query_impl(left, right, 2 * node + 2, (a + b) / 2, b);
      return Monoid::product(lv, rv);
    }
  public:
    segtree(int n) {
      size = 1;
      while (size < n) size *= 2;
      data.resize(size * 2 - 1, Monoid::identity);
    }

    value_type query(int left, int right) const {
      return query_impl(left, right, 0, 0, size);
    }

    void update(int i, value_type const& v) {
      int node = i + size - 1;
      data[node] = v;
      while (node > 0) {
        node = (node - 1) / 2;
        data[node] = Monoid::product(data[2 * node + 1], data[2 * node + 2]);
      }
    }
};
