class STM{//maximum
    const int MXN=1<<18;
    ll n;vl seg;
public:
    void seg_init(int n_){
        n=1;
        while(n<n_){
            n*=2;
        }
        seg.assign(2*n-1,-INF);
    }
    void update(int k,ll a){
        k+=n-1;
        seg[k]=a;
        while(k>0){
            k=(k-1)/2;
            seg[k]=max(seg[2*k+1],seg[2*k+2]);
        }
    }
    ll get_max(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0){
            return get_max(a,b,k,0,n);
        }
        if(r<=a||b<=l){
            return -INF;
        }
        if(a<=l&&r<=b){
            return seg[k];
        }
        else{
            ll maxl=get_max(a,b,2*k+1,l,(l+r)/2);
            ll maxr=get_max(a,b,2*k+2,(l+r)/2,r);
            return max(maxl,maxr);
        }
    }
};

