map<int,modint> memo;
vector<bool> used;
modint bfs(int node){
    used[node]=true;
    modint ans=1;
    if(memo[node]!=0) return memo[node];
    if(toList[node].empty()) return memo[node] = modint(2);
    if(toList[node].size()==1) {ans = bfs(toList[node][0])+1; return memo[node] = ans;}
    else {for(auto child:toList[node]) {ans*=bfs(child);} ans+=1;}
    return memo[node] = ans;
}

vector<int> seekDig(int i){
    vector<int> ret;
    ll ter=XD[i].second;
    int l,r;
    // rを範囲外のNからはじめることによって
    // l=N-1をとりうる。
    l=0;r=N;
    while(l+1<r){
        int m=(l+r)/2;
        if(XD[m].first<ter) l=m;
        else r=m; 
    }
    if(i>=l) return ret;
    if(i+1==l){ ret.push_back(i+1); return ret;}
    if(i+1<l) for(int k=i+1;k<=l;k++) {
        if(k==i+1) {ret.push_back(k); ter=XD[k].second;}
        else if(ter<=XD[k].first) {ret.push_back(k);}
        ter=max(ter,XD[k].second);
        }
    return ret;
}

