map<int,int> memoR;
int seekR(int i){
  if(memoR[i]!=0) return memoR[i];
  ll ter=XD[i].second;
  int l,r;
  // rを範囲外のNからはじめることによって
  // l=N-1をとりうる。
  l=i;r=N;
  while(l+1<r){
      int m=(l+r)/2;
      if(XD[m].first<ter) l=m;
      else r=m; 
  }
  if(l==i) return memoR[i] = l;
  int ans=l;
  for (int k = l; k > i; k--)
  {
    ans = max(ans,seekR(k));
  }
  return memoR[i] = ans;
}

