inline void updata(int n){a[n].ma=max(a[lch].ma,a[rch].ma);}
void tree_add(int n,int l,int r,int lc,int k)
{
	if (l==r) {a[n].ma=k; return;}
	int mid=(l+r)>>1;
	if (lc<=mid) tree_add(lch,l,mid,lc,k);else tree_add(rch,mid+1,r,lc,k);
	updata(n);
}
int qury(int n,int L,int R,int l,int r)
{
	if (L==l && R==r) return a[n].ma;
	int mid=(L+R)>>1;
	if (r<=mid) return qury(lch,L,mid,l,r);
	else if (l>=mid+1) return qury(rch,mid+1,R,l,r);
	else return max(qury(lch,L,mid,l,mid),qury(rch,mid+1,R,mid+1,r));
}
