struct segment_tree {
	vector <int> t;
	void upd (int v, int tl, int tr, int pos, int new_val) {
		if (tl == tr - 1)
			t[v] = new_val;
		else {
			int tm = (tl + tr) / 2;
			if (pos < tm)
				upd (v*2, tl, tm, pos, new_val);
			else
				upd (v*2+1, tm, tr, pos, new_val);
			t[v] = max(t[v*2], t[v*2+1]);
		}
	}	
	// void upd(int v, int l, int r, int idx, int x) {
	// 	if (l > idx || r <= idx) {
	// 		return;
	// 	}
	// 	if (l == r - 1) {
	// 		t[v] = x;
	// 		return;
	// 	}
	// 	int mid = (l + r) / 2;
	// 	upd(v * 2, l, mid, idx, x);
	// 	upd(v * 2 + 1, mid, r, idx, x);
	// 	t[v] = max(t[v * 2], t[v * 2 + 1]);
	// }
	void build(int n, vector <int>& a) {
		t.assign(4 * n, 0);
		upd(1, 0, n, n - 1, a[n - 1]);
	}
	int get(int v, int l, int r, int a, int b) {
		if (l >= a && r <= b) {
			return t[v];
		}
		if (l >= b || r <= a) {
			return 0;
		}
		int mid = (l + r) / 2;
		return max(get(v * 2, l, mid, a, b), get(v * 2 + 1, mid, r, a, b));
	}
};

void solve() {
	int n;
	cin >> n;
