	cnt[n] = 1;
	vector <int> r(n + 1);
	r[n] = n;
	segment_tree t;
	t.build(n + 1, r);
	for (int i = n - 1; i >= 0; --i) {
		int to = a[i].fi + a[i].se;
		int idx = upper_bound(all(a), make_pair(to - 1, INF)) - a.begin();
		// cout << idx << "\n";
		// continue;
