struct TakaTree {
	int al, ar;
	TakaTree *left, *right;
	int rmax;
	TakaTree(int i, int j) : al(i), ar(j), left(nullptr), right(nullptr),
	rmax(-INF) {
		if (i != j) {
			int k = (i + j) / 2;
			left = new TakaTree(i, k);
			right = new TakaTree(k + 1, j);
		}
	}
	int getMax(int i, int j) {
		if (j < al || ar < i) return -INF;
		else if (i <= al && ar <= j) return rmax;
		else return max(left->getMax(i, j), right->getMax(i, j));
	}
	void setElem(int i, int v) {
		if (i < al || ar < i) return;
		else if (al == ar) rmax = v;
		else {
			left->setElem(i, v);
			right->setElem(i, v);
			rmax = max(left->rmax, right->rmax);
		}
	}
};

