		realst[i] = comp[x[i]];
		realed[i] = comp[x[i] + d[i] - 1];
		cfing.setElem(realst[i], realed[i]);
//		printf("comp %d is %d %d\n", i, realst[i], realed[i]);
	}
	vector<ll> ans(ect + 1, 1);
	for (int x = ect - 1; x >= 0; --x) {
