using namespace std;
const int N = 200100;
int dp[N],n;
const int Mod = 998244353;
pair < int , int > a[N];

int Add_self(int &x , int y){
    x = (x + y)%Mod;
}

int Next[N];

int Rec(int i){

    if(i >= n)  return 1;

    if(dp[i] != -1)  return dp[i];

    int Res = 0;

    Add_self(Res , Rec(i + 1) + Rec(Next[i]));

    return dp[i] = Res;
}

int x[200100],Seg[N * 4];

void Update(int i , int v , int p = 1, int L = 1, int R = N)
{
    if (i < L || i > R) return;
    if (L == R)
    {
        Seg[p] = v;
        return;
    }
    int mid = (L + R)/2;
    Update(i , v , p * 2, L, mid);
    Update(i , v , p * 2 + 1, mid + 1, R);

    Seg[p] = max(Seg[p * 2] , Seg[p * 2 + 1]);
}

int Query(int i, int j, int p = 1, int L = 1, int R = N)
{
    if (L > j || R < i) return 0;
    if (L >= i && R <= j)
        return Seg[p];

    int mid = (L + R)/2;
    return max(Query(i, j, p * 2, L, mid) , Query(i, j, p * 2 + 1, mid + 1, R));
}


int main()
{
    memset(dp , -1 , sizeof(dp));
    cin >> n;
    for(int i = 0;i<n;i++)  cin >> a[i].first >> a[i].second;
