void add_edge(Graph& G, ll from, ll to, ll cap, bool revFlag, ll revCap) {
	G[from].push_back(Edge(to, cap, (ll)G[to].size()));
	if (revFlag)G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}


void solve() {
	ll n;
	cin >> n;
	vector<P> xd(n);
	REP(i, n) cin >> xd[i].first >> xd[i].second;
	sort(all(xd));
	set<P> st;
	Array dp(n, 0);
	rep2(i, 0, n) {
		ll x = xd[i].first;
		ll d = xd[i].second;
		auto it2 = st.lower_bound({ x+d,i });
		auto it = st.lower_bound({ x,i });

		ll ret = 1;
		while (it != it2) {
			ll x2 = it->first;
			ll i2 = it->second;
			(ret *= dp[i2]) %= MOD;
			it=st.erase(it);
		}

		(dp[i] = ret + 1) %= MOD;

		st.insert({ x,i });
	}

	ll ans = 1;
	for (auto i : st) {
		(ans *= dp[i.second])%=MOD;
	}
	cout << ans << en;

}

