	sort(a+1,a+1+n);
	dp[n+1]=1;
	for(int i=n;i;i--){
		int t=a[i].x+a[i].d;
		int idx=i+1;
		while(!s.empty()&&t>a[s.top().x].x){
			idx=s.top().d;
			s.pop();
		}
		node tmp;tmp.x=i;tmp.d=idx;
		s.push(tmp);
		dp[i]=(dp[i+1]+dp[idx])%mod;
	}
	cout<<dp[1]<<endl;
	return 0;
}

