template <class T>
struct Compress{
	int N;
	map<T,int> idx;
	vector<T> cmp;
	Compress(vector<T> v){
		for(auto& x:v) cmp.push_back(x);
		sort(cmp.begin(),cmp.end());
		cmp.erase(unique(cmp.begin(),cmp.end()),cmp.end());
		N=cmp.size();
		for(int i=0;i<N;i++) idx[cmp[i]]=i;
	}
	int id(T val){return idx[val];}//前→後
	T val(int id){return cmp[id];}//後→前
};

