int lower_bound(ll num) {
	int le = 0, ri = n;
	while (le < ri) {
		int mid = (le + ri) / 2;
		int ii = index[mid];
		if (x[ii] < num) {
			le = mid + 1;
		}
		else {
			ri = mid;
		}
	}
	return le;
}

int upper_bound(ll num) {
	int le = 0, ri = n;
	while (le < ri) {
		int mid = (le + ri) / 2;
		int ii = index[mid];
		if (x[ii] <= num) {
			le = mid + 1;
		}
		else {
			ri = mid;
		}
	}
	return le;
}

namespace SegmentTree {
	int n;

	struct Node {
		int maxn;
	};

	Node nodes[4 * MAXN];

	void init(int n_) {
		//为了简单起见，将元素扩大到2的幂
		n = 1;
		while (n < n_) n *= 2;

		memset(nodes, 0, sizeof(nodes));
	}

	//将第k个值更新为a
	void update(int k, int a) {
		//叶子节点
		k += n - 1;
		nodes[k].maxn = a;
		//向上更新
		while (k > 0) {
			k = (k - 1) / 2;
			nodes[k].maxn = max(nodes[k * 2 + 1].maxn, nodes[k * 2 + 2].maxn);
		}
	}

	//求[a,b)的最大prefix_max
	//后面的参数是为了计算方便传入的
	//k是节点的编号，l,r表示这个节点代表区间[l,r)
	//外部调用时，使用query(a,b,0,0,n);
	int query(int a, int b, int k, int l, int r) {
		//如果[a,b)和[l,r)不相交，返回0
		if (r <= a || b <= l) return 0;
		//如果[a,b)完全包含[l,r)，返回当前节点值
		if (a <= l && r <= b) return nodes[k].maxn;
		else {
			int v1 = query(a, b, k * 2 + 1, l, (l + r) / 2);
			int v2 = query(a, b, k * 2 + 2, (l + r) / 2, r);
			return max(v1, v2);
		}
	}
}


