using namespace std;
template <typename Mnd> struct segment_tree {
    int sz;
    vector<Mnd> data;
    function<Mnd(Mnd, Mnd)> f;
    Mnd e;
    //サイズだけ指定して初期化
    segment_tree(int _sz, function<Mnd(Mnd, Mnd)> _f, Mnd _e) : f(_f), e(_e) {
        sz = 1;
        while(sz < _sz)
            sz <<= 1;
        data.assign(sz * 2, e);
    }
    //参照渡しなので代入とかもできる
    Mnd &operator[](const int &k) { return data[k + sz]; }
    //木を構築 O(n)
    void build() {
        for(int i = sz - 1; i > 0; i--)
            data[i] = f(data[2 * i], data[2 * i + 1]);
    }
    //更新しつつ木を再構築 O(log n)
    void update(int k, Mnd x) {
        data[k += sz] = x;
        while(k >>= 1)
            data[k] = f(data[2 * k], data[2 * k + 1]);
    }
    //[a,b)でのクエリに答える　O(log n)
    Mnd query(int a, int b) const {
        Mnd l = e, r = e;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
            if(a & 1)
                l = f(l, data[a++]);
            if(b & 1)
                r = f(r, data[--b]);
        }
        return f(l, r);
    }
};
int main() {
    int n;
    cin >> n;
    segment_tree<int> seg(n, [](int a, int b) { return max(a, b); }, INT_MIN);
    vector<pair<ll, ll>> xd(n);
    for(int i = 0; i < n; i++) {
        cin >> xd[i].first >> xd[i].second;
    }
    sort(all(xd));
    seg.update(n - 1, n - 1);
    for(int i = n - 2; i >= 0; i--) {
        auto ind = lower_bound(all(xd), make_pair(xd[i].first + xd[i].second,
                                                  LLONG_MIN)) -
                   xd.begin();
        seg.update(i, max(i, seg.query(i, ind)));
    }
    vector<ll> dp(n + 1);
    dp[n] = 1;
    dp[n - 1] = 2;
    for(int i = n - 2; i >= 0; i--) {
        dp[i] = dp[i + 1] + dp[seg[i] + 1];
    }
    cout << dp[0] << endl;
}

