int my_search(int ll, int rr, int val)
{
    int sol = ll;

    while (ll <= rr)
    {
        int m = (ll + rr) / 2;

        if (in[m].fst <= val) { sol = m; ll = m + 1; }
        else
            rr = m - 1;
    }

    return sol;
}

int f(int x)
{
    if (x >= MOD) return x - MOD; else
        return x;
}

void update(int node, int l, int r, int pos, int val)
{
    if (l == r) {

        arb[node] = val;

        return;
    }

    int m = (l + r) / 2;

    if (pos <= m) update(node * 2, l, m, pos, val); else
        update(node * 2 + 1, m + 1, r, pos, val);

    arb[node] = max(arb[node * 2], arb[node * 2 + 1]);
}

int query(int node, int l, int r, int lp, int rp)
{
    if (l >= lp && r <= rp) return arb[node];

    int maxx = -1;
    int m = (l + r) / 2;

    if (lp <= m) maxx = max(maxx, query(node * 2, l, m, lp, rp));
    if (rp > m) maxx = max(maxx, query(node * 2 + 1, m + 1, r, lp, rp));

    return maxx;
}

