#include <bits/stdc++.h>
#include <boost/dynamic_bitset.hpp>
using namespace std;
using u32 = uint32_t;
using s64 = int64_t;
using u64 = uint64_t;

void gen_tree(vector<vector<u32>>& tree,
	boost::dynamic_bitset<>& regs,
	const vector<pair<s64, s64>>& xd,
	const u32 v) {

	auto rp = make_pair(xd[v].second, INT64_MIN);
	auto itr = lower_bound(xd.begin() + v + 1, xd.end(), rp);
	auto idx = distance(xd.begin(), itr);

	for(u32 i=v+1; i<idx; i++) {
		if(~regs[i]) {
			regs[i] = 1;
			tree[v].push_back(i);
			gen_tree(tree, regs, xd, i);
		}
	}
}

int main() {
	u32 N;
	cin >> N;

	vector<pair<s64, s64>> XD(N);

	for(u32 i=0; i<N; i++) {
		s64 X, D;
		cin >> X >> D;
		XD[i] = make_pair(X, X+D);
	}

	sort(XD.begin(), XD.end());

	vector<vector<u32>> tree(N, vector<u32>());
	boost::dynamic_bitset<> regs(N);

	for(u32 i=0; i<N; i++) {
		if(~regs[i]) {
			gen_tree(tree, regs, XD, i);
		}
	}

	vector<u64> dp(N);
	u64 ans = 1;
	u64 mod = 998244353;

	for(u32 i=N; i>0; i--) {
		u32 c = i - 1;
		dp[c] = 1;

		for(u32 s=0; s<tree[c].size(); s++) {
			dp[c] = (dp[c] * dp[tree[c][s]]) % mod;
		}

		dp[c]++; // 起動した場合

		if(~regs[c]) { // root 
			ans = (ans * dp[c]) % mod;
		}
	}

	cout << ans;
	return 0;
}

