void sset(i64 i, i64 tl, i64 tr, i64 j, i64 v) {
    if (tl == tr) {
        st[i] = v;
        return;
    }

    i64 t = (tl + tr) / 2;
    if (j <= t) {
        sset(i * 2, tl, t, j, v);
    }
    else {
        sset(i * 2 + 1, t + 1, tr, j, v);
    }
    st[i] = max(st[i * 2], st[i * 2 + 1]);
}

void sset(i64 j, i64 v) {
