}

i64 smax(i64 i, i64 tl, i64 tr, i64 l, i64 r) {
    if (l > r) {
        return 0;
    }

    if (tl == l && tr == r) {
        return st[i];
    }

    i64 t = (tl + tr) / 2;
    i64 v1 = smax(i * 2, tl, t, max(tl, l), min(t, r));
    i64 v2 = smax(i * 2 + 1, t + 1, tr, max(t + 1, l), min(tr, r));

    return max(v1, v2);
}

