	dp[n-1][1] = 1;

	auto last_go = [&](int pos) {
		int val = v[pos].first + v[pos].second - 1;
		for(int j = n - 1; j >= 0; j--) {
			if(val >= v[j].first) return j;
		}
		return -1;
	};

	auto mx_go = [&](int l, int r) {
		if(l>r) return -1;
		int mx = go[l];
		for(int i = l + 1; i <= r; i++) {
			mx = max(mx, go[i]);
		}
		return mx;
	};

	go[n - 1] = n - 1;

	for(int i = n - 2; i >= 0; i--) {
		go[i] = last_go(i);
		go[i] = max(go[i], mx_go(i+1, go[i]));
