struct RMaxQ{
private:
  int n;
  vector<long long> data;
public:
  RMaxQ(int N){
    vector<long long> V(N,-INF);
    int sz = V.size();
    n = 1;
    while(n < sz) n *= 2;
    data.resize(2*n-1,-INF);
    for(int i = 0; i < sz; ++i) data[n-1+i] = V[i];
    for(int i = n-2; i >= 0; --i) data[i] = max(data[2*i+1],data[2*i+2]);
  }
  RMaxQ(vector<long long> V){
    int sz = V.size();
    n = 1;
    while(n < sz) n *= 2;
    data.resize(2*n-1,-INF);
    for(int i = 0; i < sz; ++i) data[n-1+i] = V[i];
    for(int i = n-2; i >= 0; --i) data[i] = max(data[2*i+1],data[2*i+2]);
  }
  void update(int idx, long long val){//0-indexed
    idx += n-1;
    data[idx] = val;
    while(idx > 0){
      idx = (idx-1)/2;
      data[idx] = max(data[2*idx+1],data[2*idx+2]);
    }
  }
  long long get_max(int l, int r){//[l,r)の区間の最大値
    long long ret = -INF;
    l += n-1, r += n-1;
    while(l < r){
      if((l&1) == 0){
        ret = max(ret,data[l]);
      }
      if((r&1) == 0){
        ret = max(ret,data[r-1]);
      }
      l /= 2;
      r = (r-1)/2;
    }
    return ret;
  }
};

