int rig[N], dp[N];
SegmentTree<int> ST;

inline void solve()
{
    cin >> n;
    for (int i = 1; i <= n; ++i) cin >> a[i];
    sort(a+1, a+n+1);
    ST.build(n); // ST.query(i) == i
    dp[n+1] = 1;
    for (int i = n; i; --i) {
        int p = lower_bound(a+i, a+n+1, (Node)(a[i].x+a[i].d))-a-1;
        rig[i] = ST.query(i, p);
        ST.modify(i, rig[i]);
        // i'th is choose or not
        dp[i] = (dp[rig[i]+1]+dp[i+1])%MOD;
    }
