    rep(i, N) cin >> p[i].first >> p[i].second;

    sort(p.begin(), p.end());

    set<P> s;
    repr(i, N) {
        while (s.size() && s.begin()->first < p[i].first + p[i].second) {
            G[i].push_back(s.begin()->second);
            s.erase(s.begin());
        }
        s.emplace(p[i].first, i);
    }

    mint ans = 1;
    for (P i : s) ans *= dfs(i.second);
    cout << ans << endl;
}

