int query(Tree *p,int l,int r){
	if(!p)return inf;
	if(L<=l&&R>=r)return p->mi;
	int mid=(1ll*l+r)>>1,ans=inf;
	if(L<=mid)ans=min(ans,query(p->l,l,mid));
	if(R>mid)ans=min(ans,query(p->r,mid+1,r));
