void change(Tree *&p,int l,int r){
	if(!p)p=new Tree{R,0,0};
	if(l==r)return;
	p->mi=min(p->mi,R);
	int mid=(1ll*l+r)>>1,ans=inf;
	if(L<=mid)change(p->l,l,mid);
	else change(p->r,mid+1,r);
}
