using namespace std;
int n;
struct Node {
	int x, d;
} node[N];

struct Sgtree {
	int mx[N<<2];
	void build (int id, int l, int r) {
		mx[id] = inf;
		if (l == r) return ;
		int mid = l + r >> 1;
		build (id<<1, l, mid);
		build (id<<1|1, mid+1, r);
	}
	void update (int id, int l, int r, int pos, int val) {
		if (pos == l && l == r) {
			mx[id] = val;
			return ;
		}
		int mid = l + r >> 1;
		if (pos <= mid) update (id<<1, l, mid, pos, val);
		else update (id<<1|1, mid+1, r, pos, val);
		mx[id] = max (mx[id<<1], mx[id<<1|1]);
	}
	int query (int id, int l, int r, int L, int R) {
		if (L <= l && r <= R) return mx[id];
		int mid = l + r >> 1;
		int ret = inf;
		if (L <= mid) ret = max (ret, query (id<<1, l, mid, L, R));
		if (mid < R) ret = max (ret, query (id<<1|1, mid+1, r, L, R));
		return ret;
	}
} sgtree;

int b[N];
int dp[N];

bool cmp (const Node & x, const Node & y) {
	return x.x < y.x;
}

int main () {
	cin >> n;
	for (int i = 1; i <= n; i ++) cin >> node[i].x >> node[i].d, b[i] = node[i].x;

	sort (node+1, node+n+1, cmp);
	sort (b+1, b+n+1);

	sgtree.build (1, 1, n);

	dp[n+1] = 1;
	for (int i = n; i >= 1; i --) {
		int pos = upper_bound (b+1, b+n+1, node[i].x+node[i].d-1) - b - 1;
		int tmp = sgtree.query (1, 1, n, i, pos);
		int j = upper_bound (b+1, b+n+1, max (tmp, node[i].x+node[i].d-1)) - b;
		sgtree.update (1, 1, n, i, max (tmp, node[i].x+node[i].d-1));
//		cout << j << " " << tmp << " " << pos << endl;
		dp[i] = (dp[i+1] + dp[j]) % MOD;
	}

	cout << dp[1] << endl;
}

