class SparseTable {
public:
	int size_ = 1;
	vector<int> vec[19];
	vector<int> eval;

	void init(int sz) {
		while (size_ <= sz) size_ *= 2;
		for (int i = 0; i <= 18; i++) vec[i].resize(size_, 0);
		eval.resize(1 << 19);
		for (int i = 0; i <= 18; i++) {
			for (int j = (1 << i); j < (2 << i); j++) eval[j] = i;
		}
	}
	void update(int pos, int x) {
		vec[0][pos] = x;
	}
	void initq() {
		for (int i = 0; i < 18; i++) {
			for (int j = 0; j < size_; j++) {
				int v1 = j + (1 << i);
				vec[i + 1][j] = vec[i][j];
				if (v1 < size_) vec[i + 1][j] = max(vec[i + 1][j], vec[i][v1]);
			}
		}
	}
	int query(int cl, int cr) {
		// 閉区間 [cl, cr)
		int haba = cr - cl;
		int ev = eval[haba];
		return max(vec[ev][cl], vec[ev][cr - (1 << ev)]);
	}
};

class BIT {
public:
	int size_ = 1;
	vector<long long> bit;

	void init(int sz) {
		size_ = sz + 2;
		bit.resize(size_ + 2, 0);
	}
	void add(int pos, long long x) {
		pos++;
		while (pos <= size_) {
			bit[pos] += x;
			pos += (pos & -pos);
		}
	}
	long long sum(int pos) {
		long long s = 0; pos++;
		while (pos >= 1) {
			s += bit[pos];
			pos -= (pos & -pos);
		}
		return s;
	}
};

