void solve(std::istream &in, std::ostream &out) {
  int n, p;
  in >> n >> p >> s;
  map<int, int> mp;
  mp[0]++;
  int sm = 0;
  assert(p != 2 && p != 5);
  int64_t ans = 0;
  int p10 = 1;
  for (int i = n - 1; i >= 0; --i) {
    sm = (sm + (s[i] - '0') * p10) % p;
