const int N = 2e5+10;
const int MOD = 998244353;

int n, link[N];
struct data{
  int x, d;
}a[N];
ll dp[N];

int t[N << 2];
void upd(int u, int L, int R, int i, int x) {
  if(L == R) {
    t[u] = x;
    return;
  } int mid = L + R >> 1, lc = u << 1, rc = lc | 1;
  if(i <= mid) upd(lc, L, mid, i, x);
  else upd(rc, mid + 1, R, i, x);
  t[u] = max(t[lc], t[rc]);
}

int get(int u, int L, int R, int l, int r) {
  if(r < L || R < l) return 0;
  if(l <= L && R <= r) return t[u];
  int mid = L + R >> 1, lc = u << 1, rc = lc | 1;
  return max(get(lc, L, mid, l, r), get(rc, mid + 1, R, l, r));
}

int main () {
  scanf("%d", &n);
  for(int i = 0; i < n; i++) 
    scanf("%d %d", &a[i].x, &a[i].d);
  sort(a, a + n, [&](data x, data y) {
    return x.x < y.x;
  });

  link[n - 1] = n;
  upd(1, 0, n - 1, n - 1, n);

  for(int i = n - 2; i >= 0; i--) {
    if(a[i].x + a[i].d <= a[i + 1].x) {
      link[i] = i + 1;
      upd(1, 0, n - 1, i, i + 1);
      continue;
    }

    int lo = i + 1, hi = n - 1, idx = n;
    while(lo <= hi) {
      int mid = lo + hi >> 1;
      if(a[i].x + a[i].d > a[mid].x)
        lo = mid + 1;
      else hi = mid - 1, idx = mid;
    } idx--;
    link[i] = get(1, 0, n - 1, i + 1, idx);
    upd(1, 0, n - 1, i, link[i]);
  }

  dp[n] = 1;
  for(int i = n - 1; i >= 0; i--) {
    dp[i] = dp[i + 1] + dp[link[i]];
    if(dp[i] >= MOD) dp[i] -= MOD;
  }
  printf("%lld\n", dp[0]);
  return 0;
}

