ll merge(ll a, ll b) {
	return max(a, b);
}
void build(ll pos, ll l, ll r) {
	if(l > r) {
		return;
	}
	if(l == r) {
		seg[pos] = l;
		return;
	}
	ll mid = (l + r) / 2;
	build(2*pos + 1, l, mid);
	build(2*pos + 2, mid + 1, r);
	seg[pos] = merge(seg[2*pos + 1], seg[2*pos + 2]);
	return;
}
ll query(ll pos, ll l, ll r, ll l1, ll r1) {
	if(l > r || r1 < l || l1 > r) {
		return -1;
	}
	if(l1 <= l && r <= r1) {
		return seg[pos];
	}
	ll mid = (l + r) / 2;
	return(merge(query(2*pos + 1, l, mid, l1, r1), query(2*pos + 2, mid + 1, r, l1, r1)));
}
void update(ll pos, ll l, ll r, ll x, ll val) {
	if(l > r || x < l || x > r) {
		return;
	}
	if(l == r) {
		seg[pos] = val;
		return;
	}
	ll mid = (l + r) / 2;
	update(2*pos + 1, l, mid, x, val);
	update(2*pos + 2, mid + 1, r, x, val);
	seg[pos] = merge(seg[2*pos + 1], seg[2*pos + 2]);
	return;
}
