PP p[200000];

bool inter(int i, int j) {
  return p[i].first + p[i].second > p[j].first;
}

long rec(int begin, int& end) {
  long prod = 1;
  int curr = begin + 1;
  while (curr < n && inter(begin, curr)) {
    int next;
    long res = rec(curr, next);
    prod = prod * res % mod;
    curr = next;
  }
  end = curr;
  return (prod + 1) % mod;
}

