void build(int no, int st, int la)
{
    if(st == la){
        tree[no] = st;
        return ;
    }
    int mid = (st+la)/2;
    build(2*no,st,mid);
    build(2*no+1,mid+1,la);
    if(v[tree[2*no]].se >= v[tree[2*no+1]].se){
        tree[no] = tree[2*no];
    }
    else tree[no] = tree[2*no+1]; 
}

int query(int no,int st,int la,int l,int r){

    if(l <= st && r >= la)return tree[no];
    if(l > la || r < st)return 0;
    int mid = (st+la)/2;
    int l1 = query(2*no,st,mid,l,r);
    int l2 = query(2*no+1,mid+1,la,l,r);
    if(v[l1].se >= v[l2].se)return l1;
    return l2;
}   

