typedef pair<int, int> ii;
struct seg {
	int s, e, m, v;
	seg *l, *r;
	seg(int _s, int _e) {
		s = _s, e = _e, m = (s + e) / 2, v = -1;
		if (s != e) {
			l = new seg(s, m);
			r = new seg(m + 1, e);
		}
	}
	void update(int i, int nv) {
		if (s == e) {
			v = nv;
			return;
		} else if (i > m) r -> update(i, nv);
		else l -> update(i, nv);
		v = max(l -> v, r -> v);
	}
	int query(int a, int b) {
		if (s == a && e == b) return v;
		if (a > m) return r -> query(a, b);
		if (b <= m) return l -> query(a, b);
		return max(l -> query(a, m), r -> query(m + 1, b));
	}
} *root;
