		int ptr = lower_bound(XD, XD + N, ii(XD[i].first + XD[i].second, 0)) - XD;
		if (ptr == i + 1) reach[i] = i, root -> update(i, i);
		else reach[i] = root -> query(i + 1, ptr - 1), root -> update(i, reach[i]);
