	int range[n];
	std::deque<std::pair<int, int> > increasing;
	for (int i = n; i--; ) {
		range[i] = std::lower_bound(all, all + n, std::pair<int, int>{all[i].first + all[i].second, 0}) - all;
		int pos = std::lower_bound(increasing.begin(), increasing.end(), std::pair<int, int>{range[i], -1}) - increasing.begin();
		if (pos) range[i] = increasing[pos - 1].second;
		while (increasing.size() && increasing.front().second <= range[i]) increasing.pop_front();
		increasing.push_front({i, range[i]});
	}

	int dp[n];
	int res = 1;
	std::vector<int> child[n];
	std::vector<int> stack;
	for (int i = 0; i <= n; i++) {
		while (stack.size() && (i == n || range[stack.back()] < range[i])) {
			int back = stack.back();
			dp[back] = 1;
			for (auto j : child[back]) dp[back] = (int64_t) dp[back] * dp[j] % MOD;
			if (++dp[back] == MOD) dp[back] = 0;
			if (stack.size() == 1) res = (int64_t) res * dp[back] % MOD;
			stack.pop_back();
		}
		if (i == n) break;
		if (stack.size()) child[stack.back()].push_back(i);
		stack.push_back(i);
	}
