class mint {
  using u64 = std::uint_fast64_t;
    public:
    u64 a;
    constexpr mint(const long long x = 0)noexcept:a(x>=0?x%get_mod():get_mod()-(-x)%get_mod()){}
    constexpr u64 &value()noexcept{return a;}
    constexpr const u64 &value() const noexcept {return a;}
    constexpr mint operator+(const mint rhs)const noexcept{return mint(*this) += rhs;}
    constexpr mint operator-(const mint rhs)const noexcept{return mint(*this)-=rhs;}
    constexpr mint operator*(const mint rhs) const noexcept {return mint(*this) *= rhs;}
    constexpr mint operator/(const mint rhs) const noexcept {return mint(*this) /= rhs;}
    constexpr mint &operator+=(const mint rhs) noexcept {
        a += rhs.a;
        if (a >= get_mod())a -= get_mod();
        return *this;
    }
    constexpr mint &operator-=(const mint rhs) noexcept {
        if (a<rhs.a)a += get_mod();
        a -= rhs.a;
        return *this;
    }
    constexpr mint &operator*=(const mint rhs) noexcept {
        a = a * rhs.a % get_mod();
        return *this;
    }
    constexpr mint operator++(int n) noexcept {
        a += 1;
        if (a >= get_mod())a -= get_mod();
        return *this;
    }
    constexpr mint operator--(int n) noexcept {
        if (a<1)a += get_mod();
        a -= 1;
        return *this;
    }
    constexpr mint &operator/=(mint rhs) noexcept {
        return *this*= rhs.inv();
    }
    constexpr bool operator==(mint x) noexcept {
        return a==x.a;
    }
    constexpr bool operator!=(mint x) noexcept {
        return a!=x.a;
    }
    constexpr static int root(){
        mint root = 2;
        while(root.pow((get_mod()-1)>>1).a==1)root++;
        return root.a;
    }
    constexpr mint pow(long long n){
        long long x=a;
        mint ret = 1;
        while(n>0) {
            if(n&1)(ret*=x);
            (x*=x)%=get_mod();
            n>>=1;
        }
        return ret;
    }
    constexpr mint inv()const{
        int x=a,y=get_mod(),u=1,v=0,t=0;
        while(y > 0) {
            t=x/y;
            x-=t*y;x^=y;y^=x;x^=y;
            u-=t*v;u^=v;v^=u;u^=v;
        }
        return mint(u);
    }
    mint comb(lint b){
        using lint=long long;
        static bool init=1;
        static lint fac[3000001],ifac[3000001];
        if(init){
            init=0;
            fac[0]=1;
            ifac[0]=1;
            auto mod_pow=[&](lint x,lint n){
                lint ans = 1;
                while(n != 0){
                    if(n&1)ans=ans*x%get_mod();
                    x=x*x%get_mod();
                    n=n>>1;
                }
                return ans;
            };
            for(int i=0;i<3000000;i++){
                fac[i+1]=fac[i]*(i+1)%get_mod();
                ifac[i+1]=ifac[i]*mod_pow(i+1, get_mod()-2)%get_mod();
            }
        }
        if(a==0&&b==0)return 1;
        if((lint)a<b||a<0)return 0;
        lint tmp=ifac[a-b]*ifac[b]%get_mod();
        return tmp*fac[a]%get_mod();
    }
    mint fact(){
        using lint=long long;
        static bool init=1;
        static lint fac[3000001];
        if(init){
            init=0;
            fac[0]=1;
            for(int i=0;i<3000000;i++){
                fac[i+1]=fac[i]*(i+1)%get_mod();
            }
        }
        return fac[a];
    }
    friend ostream& operator<<(ostream& lhs, const mint& rhs) noexcept {
        lhs << rhs.a;
        return lhs;
    }
    friend istream& operator>>(istream& lhs,mint& rhs) noexcept {
        lhs >> rhs.a;
        return lhs;
    }
    constexpr static u64 get_mod(){return MOD;}
};

template<typename T>
class segment{
	T* node;
	int n=1;
	public:
	segment(int sz){
		while(n<=sz)n<<=1;
		node=new T[(n<<1)-1];
		for(int i=0;i<(n<<1)-1;i++)node[i]=e;
	}
	segment(const vector<T>& v){
		while(n<(int)v.size())n<<=1;
		node=new T[(n<<1)-1];
		for(int i=0;i<(int)v.size();i++)node[i+n-1]=v[i];
		for(int i=n-2;i>=0;i--)node[i]=f(node[(i<<1)+1],node[(i<<1)+2]);
	}
	T get(auto l,auto r){
		l+=n;r+=n;
		T s=e,t=e;
		while(l<r){
			if(l&1)s=f(s,node[l++-1]);
			if(r&1)t=f(node[--r-1],t);
			l>>=1;r>>=1;
		}
		return f(s,t);
	}
    void change(auto t,T val){
		t+=n-1;
        node[t]=val;
		while(t){
			t=(t-1)>>1;
            node[t]=f(node[t*2+1],node[t*2+2]);
		}
	}
	void update(auto t,T val){
		t+=n-1;
        node[t]=f(node[t],val);
		while(t){
			t=(t-1)>>1;
            node[t]=f(node[t*2+1],node[t*2+2]);
		}
	}
	T e=-1;
	T f(const T& s,const T& t){
		return max(s,t);
	}
};

