using dynamic_modint = modint_base<id, true>;
int main()
{
    using mint = modint<998244353>;
    auto N     = in<int>();
    std::vector<ll> xs(N), ds(N), ys(N);
    for (int i = 0; i < N; i++) { xs[i] = in<ll>(), ds[i] = in<ll>(), ys[i] = xs[i] + ds[i]; }
    {
        std::vector<int> is(N);
        std::iota(is.begin(), is.end(), 0);
        std::sort(is.begin(), is.end(), [&](int i, int j) { return xs[i] < xs[j]; });
        auto xs_ = xs, ds_ = ds, ys_ = ys;
        for (int i = 0; i < N; i++) { xs[i] = xs_[is[i]], ds[i] = ds_[is[i]], ys[i] = ys_[is[i]]; }
    }
    std::vector<int> rs(N);  // ロボiを動かして動かない最左のロボ
    segtree<max<int>> Mrs(N);
    for (int i = 0; i < N; i++) { rs[i] = i + 1, Mrs.set(i, i + 1); }
    for (int i = N - 1; i >= 0; i--) {
        const int ri  = std::lower_bound(xs.begin(), xs.end(), ys[i]) - xs.begin();
        const auto Mr = Mrs.fold(i, ri);
        rs[i]         = Mr;
        Mrs.set(i, rs[i]);
    }
    SHOW(rs);
    auto used      = make_v<bool>({N + 1}, false);
    auto memo      = make_v<mint>({N + 1}, 0);
    const auto ans = mfp([&](auto&& self, const int i) -> mint {
        if (i == N) { return 1; }
        if (used[i]) { return memo[i]; }
        mint ans = self(self, i + 1);
        ans += self(self, rs[i]);
        return used[i] = true, memo[i] = ans;
    })(0);
    SHOW(memo);
    outln(ans);
    return 0;
}

