struct segtree{
    int n; lint arr[MAX];
    segtree(int n_){
        n = 2;
        while(n < n_) n *= 2;
        rep(i, n*2) arr[i] = 0;
    }
    void update(int k, lint a){
        k += n - 1;
        arr[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            arr[k] = max(arr[k * 2 + 1], arr[k * 2 + 2]);
        }
    }
    long query_(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return 0;
        if(a <= l && r <= b) return arr[k];
        else{
            int vl = query_(a, b, k * 2 + 1, l, (l + r) / 2);
            int vr = query_(a, b, k * 2 + 2, (l + r) / 2, r);
            return max(vl, vr);
        }
    }
    long query(int a, int b){
        return query_(a, b, 0, 0, n);
    }
};

