void solve() {
  int n;
  cin >> n;
  vi32 x(n), d(n);
  rep(i, n) {
    cin >> x[i] >> d[i];
  }
  vi32 sx = x;
  sort(all(sx));
  vi32 o(n);
  iota(all(o), 0);
  sort(all(o), [&](int i, int j) {
    return x[i] < x[j];
  });
  SegmentTree<int> st(n, [](int a, int b) { return max(a, b); }, 0);
  vi32 right(n);
  rrep(i, n) {
    int j = o[i];
    int k = lower_bound(all(sx), x[j] + d[j]) - sx.begin();
    right[i] = max(i + 1, st.query(i, k));
    st.update(i, right[i]);
  }
  vector<mint> dp(n + 1);
  dp[0] = 1;
  rep(i, n) {
    dp[i + 1] += dp[i];
    dp[right[i]] += dp[i];
  }
  cout << dp[n] << endl;
}

