struct BIT{
    int size;
    vector<int> bit;
    void init(int n){
        size = n;
        bit.assign(size+1, 0);
    }

    int sum(int x){
        int res = 0;
        while(x > 0){
            res = max(res, bit[x]);
            x -= (x & -x);
        }
        return res;
    }

    void add(int x, int y){
        while(x <= size){
            bit[x] = max(bit[x], y);
            x += (x & -x);
        }
    }
};

