template <typename T>
class SegmentTree {
  using F = function<T(T, T)>;

 private:
  int _size;
  vector<T> _seg;
  const F f;
  const T id;

 public:
  SegmentTree(int n, const F f, const T &id) : f(f), id(id) {
    _size = 1;
    while (_size < n) _size <<= 1;
    _seg.assign(_size * 2, id);
  }

  void set(int k, const T &x) {
    _seg[k + _size] = x;
  }

  void build() {
    for (int k = _size - 1; k > 0; k--)
      _seg[k] = f(_seg[k * 2], _seg[k * 2 + 1]);
  }

  void update(int k, const T &x) {
    k += _size;
    _seg[k] = x;
    while (k >>= 1)
      _seg[k] = f(_seg[k * 2], _seg[k * 2 + 1]);
  }

  // [l, r)
  T query(int l, int r) {
    T left = id, right = id;
    for (l += _size, r += _size; l < r; l >>= 1, r >>= 1) {
      if (l & 1) left = f(left, _seg[l++]);
      if (r & 1) right = f(_seg[--r], right);
    }
    return f(left, right);
  }
};

ll modpow(ll a, ll b, ll mod = MOD) {
  ll res = 1;
  while (b > 0) {
    if (b & 1) res = res * a % mod;
    a = a * a % mod;
    b >>= 1;
  }
  return res;
}

int main() {
  init();

  int N;
  cin >> N;
  vector<pair<int, int>> XD(N);
  cin >> XD;
  sort(all(XD));

  ll ans = 0;

  SegmentTree<ll> st(N, [](ll a, ll b) { return (a + b) % MOD; }, 0);
  irep(i, N) {
    int x, d;
    x = XD[i].first;
    d = XD[i].second;
    auto lo = lower_bound(all(XD), make_pair(x + d, 0));
    // if (lo == XD.end()) {
