    // }
    if (i == N - 1) {
      st.update(i, 1);
      ans++;
      continue;
    }
    int r = distance(XD.begin(), lo);

    int q = st.query(i + 1, r + 1);
    st.update(i, q);
    ans = (ans + q) % MOD;
  }

  ll p = modpow(2, N);

  out((p - ans + MOD+1) % MOD);
}

