class SegTree {
    using T = long long;
    static const T& op(const T& lhs, const T& rhs) { // binary operator
        return max(lhs, rhs);
    }
    constexpr static T unit = -1LL<<60; // unit element
    const int N;
    T *data;
    static int calc_size(int sz) {
        int n = 1;
        while (sz > n) n *= 2;
        return n;
    }
public:
    explicit SegTree(int sz) : N(calc_size(sz)) {
        data = new T[2*N-1];
    }
    ~SegTree() { delete[] data; }
    T query(int a, int b, int i = -1, int l = -1, int r = -1) const {
        if (i == -1) { i = 0; l = 0; r = N; }
        if (r <= a || b <= l) return unit; // need this if a query can be empty
        if (a <= l && r <= b) return data[i];
        int m = (l+r)/2;
        if (b <= m) return query(a, b, 2*i+1, l, m);
        if (m <= a) return query(a, b, 2*i+2, m, r);
        T v1 = query(a, b, 2*i+1, l, m),
          v2 = query(a, b, 2*i+2, m, r);
        return op(v1, v2);
    }
    T get(int i) const {
        return data[i + N - 1];
    }
    void update(int i, T v) {
        int x = i + N - 1;
        data[x] = v;
        while (x > 0) {
            x = (x-1)/2;
            data[x] = op(data[2*x+1], data[2*x+2]);
        }
    }
};

int main() {
    int n; cin >> n;
    pair<int, int> x[n];
    for (int i = 0; i < n; i++) cin >> x[i].first >> x[i].second;
    sort(x, x+n);
    int u[n];
    u[n-1] = n;
    SegTree st(n+1);
    st.update(n-1, n);
    for (int i = n-2; i >= 0; i--) {
        int j = upper_bound(x+i, x+n, make_pair(x[i].first+x[i].second, -1)) - x;
        if (i == j-1) u[i] = i+1;
        else u[i] = st.query(i, j);
        st.update(i, u[i]);
    }
    long long dp[n+1];
    const int M = 998244353;
    dp[n] = 1;
    dp[n-1] = 2;
    for (int i = n-2; i >= 0; i--) dp[i] = (dp[i+1] + dp[u[i]]) % M;
    cout << dp[0] << endl;
}

