ll n,m,seg[600000];
void segstart(void){
    memset(seg,0,sizeof(seg));
    for(ll i=1;;i*=2){
        if(n<=i){m=i;break;}
    }
    m--;
    for(int i=m-1;i>=0;i--){
        seg[i]=max(seg[2*i+1],seg[2*i+2]);
    }

}
void update(ll a,ll b){
    a+=m;seg[a]=b;
    while(a){
        a=(a-1)/2;
        seg[a]=max(seg[2*a+1],seg[2*a+2]);
    }
}
ll ans(ll a,ll b){
    ll ret=a;a+=m;b+=m;
    while(1){
        if(a==b){
            ret=max(ret,seg[a]);
            break;
        }
        if(b==a+1){
            ret=max(ret,seg[a]);
            ret=max(ret,seg[b]);
            break;
        }
        if(a%2)a/=2;
        else{
            ret=max(ret,seg[a]);
            a/=2;
        }
        if(b%2){
            ret=max(ret,seg[b]);
            b/=2;b--;
        }
        else{b/=2;b--;}
    }
    return ret;
}

ll a[200001];
ll solve(ll le,ll ri){
	if(le==ri)return 2LL;
	if(a[le]==le)return (2*solve(le+1,ri))%mod;
	if(a[le]==ri)return (solve(le+1,ri)+1)%mod;
	return (solve(le,a[le])*solve(a[le]+1,ri))%mod;
}
int main() {
    cin.tie(0);
