    for(int i=0;i<n;i++){
    	cin>>x[i]>>d[i];d[i]--;
    	v.pb(make_pair(x[i],d[i]));
    }
    sort(be(v));
    a[n-1]=n-1;
    for(int i=0;i<n;i++){
    	x[i]=v[i].first;
    	d[i]=v[i].second;
    }
    for(int i=n-1;i>=0;i--){
    	ll idx=(upper_bound(x,x+n,x[i]+d[i])-x);
    	idx--;
    	a[i]=max(ans(i,idx),idx);
    	update(i,a[i]);
    }
    cout << solve(0,n-1) <<endl;
    return 0;
}

