  SegmentTree<ll> sg(n, my_max, -LINF);

  for (int i = n; i > 0; --i)
  {
    ll x = p[i - 1].first, d = p[i - 1].second;
    auto itr = lower_bound(all(p), MP(x + d, -LINF));
    int r = distance(p.begin(), itr);
