    dp[i - 1] = dp[i];
    dp[i - 1] += dp[index];
    sg.update(i - 1, index);
  }
  cout << dp[0] << endl;
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAX = 3e5 + 5;
const int MOD = 998244353;
int n, dp[MAX], z[MAX], lg[MAX];
pair <int, int> a[MAX], rmq[MAX][20];

void build_rmq() {
	for(int i = 1; i <= n; i++) {
		lg[i] = log2(i);
		rmq[i][0] = { a[i].first + a[i].second, i };
	}

	for(int j = 1; (1 << j) <= n; j++) {
		for(int i = 1; i <= n; i++) {
			int pos = i + (1 << (j - 1));
			rmq[i][j] = rmq[i][j - 1];

			if(pos <= n)
				rmq[i][j] = max(rmq[i][j], rmq[pos][j - 1]);
		}
	}
}

pair <int, int> query(int a, int b) {
	int k = lg[b - a + 1];
	return max(rmq[a][k], rmq[b - (1 << k) + 1][k]);
}

int main() {
	scanf("%d", &n);

	for(int i = 1; i <= n; i++) {
		scanf("%d%d", &a[i].first, &a[i].second);
		a[i].second--;
	}

	sort(a + 1, a + n + 1);

	build_rmq();

	z[n + 1] = 1;
	for(int i = n; i > 0; i--) {
		int p = upper_bound(a + 1, a + n + 1, make_pair(a[i].first + a[i].second, (int) 2e9)) - a - 1;
		assert(p >= i);

		int q = query(i, p).second;

		if(a[q].first + a[q].second > a[i].first + a[i].second)
			dp[i] = dp[q];

		else dp[i] = a[i].first + a[i].second;

		int who = upper_bound(a + 1, a + n + 1, make_pair(dp[i], (int) 2e9)) - a - 1;

		z[i] = (z[i + 1] + z[who + 1]) % MOD;
	}

	printf("%d\n", z[1]);
