using Robot = tuple<ll, ll>;

class Solve
{
  int N;
  vector<Robot> robots;

public:
  Solve(int N) : N{N}, robots(N)
  {
    for (auto i{0}; i < N; ++i)
    {
      auto &[x, d] = robots[i];
      cin >> x >> d;
    }
    sort(robots.rbegin(), robots.rend());
  }

  void flush()
  {
    auto tree{RangeMinQuery<int>(N)};
    for (auto i{0}; i < N; ++i)
    {
      auto [x, d] = robots[i];
      int ng{-1}, ok{i};
      while (abs(ok - ng) > 1)
      {
        int t{(ng + ok) / 2};
        if (get<0>(robots[t]) < x + d)
        {
          ok = t;
        }
        else
        {
          ng = t;
        }
      }
      tree.update(i, min(tree.query(ok, i), i));
    }
    vector<mint> DP(N + 1, 0);
    DP[0] = 1;
    for (auto i{0}; i < N; ++i)
    {
      DP[i + 1] = DP[i] + DP[tree[i]];
    }
    cout << DP[N] << endl;
  }

private:
};

// ----- main() -----

int main()
{
  int N;
  cin >> N;
  Solve solve(N);
  solve.flush();
}

