#include<bits/stdc++.h>
using namespace std;
using u32 = uint_fast32_t;
using i32 = int_fast32_t;
using u64 = uint_fast64_t;

struct Segtree {
	u32 n;
	vector<u32> data;
	u32 U = numeric_limits<u32>::min();
	Segtree(u32 N) : n(calc_n(N)), data(n*2, U) {}
	void set(u32 p, u32 v) {
		p += n;
		data[p] = v;
		while (p) {
			p /= 2;
			data[p] = max(data[p*2], data[p*2+1]);
		}
	}
	u32 get(u32 l, u32 r) {
		u32 res = U;
		for (l += n, r += n; l < r; l /= 2, r /= 2) {
			if (l & 1) res = max(res, data[l++]);
			if (r & 1) res = max(res, data[--r]);
		}
		return res;
	}
	u32 get(u32 p) {
		return data[p+n];
	}
private:
	u32 calc_n(u32 N) {
		u32 n = 1;
		while (n < N) n *= 2;
		return n;
	}
