const int N = 2e5 + 5;
const int mod = 998244353;

vector < pair < int, int > > t (4 * N), vec;

void build (int v, int tl, int tr) {
  if (tl == tr) {
    t[v] = {vec[tl].first + vec[tl].second, tl};
  } else {
    int tm = (tr - tl) / 2 + tl;
    build (2 * v, tl, tm);
    build (2 * v + 1, tm + 1, tr);
    t[v] = max(t[2 * v], t[2 * v + 1]);
  }
}

pair < int, int > query (int v, int tl, int tr, int l, int r) {
  if (l > r) return {INT_MIN, INT_MIN};
  if (tl == l && tr == r) {
    return t[v];
  }
  int tm = (tr - tl) / 2 + tl;
  return max (query (2 * v, tl, tm, l, min (r, tm)), query (2 * v + 1, tm + 1, tr, max (l, tm + 1), r));
}

int main () {
  ios_base::sync_with_stdio(false);
  cin.tie(0);cout.tie(0);

  int n;
  cin >> n;
  vec.resize (n);
  for (auto &i : vec) cin >> i.first >> i.second;

  vec.push_back ({INT_MIN, INT_MIN});
  sort (vec.begin(), vec.end());
  vec.push_back ({INT_MAX, INT_MAX});

  build (1, 1, n);

  vector < ll > dp (n + 2), idx (n + 2);
  dp[n] = 2;
  idx[n] = n + 1;
  for (int i = n - 1; i >= 1; i--) {
    idx[i] = i;
    int j = upper_bound (vec.begin(), vec.end(), make_pair (vec[i].first + vec[i].second, INT_MIN)) - vec.begin();
    if (j == i) idx[i] = i + 1;
    else {
      pair < int, int > p = query (1, 1, n, i, j - 1);
      if (p.second == i) {
        idx[i] = j;
      } else {
        idx[i] = idx[p.second];
      }
    }

    dp[i] = dp[i + 1] + max (dp[idx[i]], (ll)1);
    dp[i] %= mod;
  }

  cout << dp[1] << '\n';
}

