template <typename T, typename Cmb, typename Upd>
struct segtree {
  const int n;
  const T unit;
  const Cmb cmb;
  const Upd upd;
  vector<T> data;
  segtree(int n, T unit = T(), Cmb cmb = Cmb(), Upd upd = Upd())
      : n(n), unit(unit), cmb(cmb), upd(upd), data(n<<1, unit) {
    build();
  }
  template <typename Iter>
  segtree(Iter first, Iter last, int n,
          T unit = T(), Cmb cmb = Cmb(), Upd upd = Upd())
      : n(n), unit(unit), cmb(cmb), upd(upd), data(n<<1) {
    assign(first, last);
  }
  void build() {
    repr(i, n) data[i] = cmb(data[i<<1], data[i<<1|1]);
  }
  template <typename Iter>
  void assign(Iter first, Iter last) {
    copy(first, last, data.begin()+n);
    build();
  }
  void modify(int l, T v) {
    l += n;
    data[l] = upd(data[l], v);
    for (; l > 1; l >>= 1) data[l>>1] = cmb(data[l&(~1)], data[l|1]);
  }
  T query(int l, int r) {
    T resl = unit, resr = unit;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l&1) resl = cmb(resl, data[l++]);
      if (r&1) resr = cmb(data[--r], resr);
    }
    return cmb(resl, resr);
  }
};
class modint;
constexpr modint pow(modint, size_t);
constexpr ll MOD = 998244353LL;

class modint {
public:
  ll value;

  constexpr modint(const ll x = 0) noexcept : value(x) {
    value %= MOD;
    if (value < 0) value += MOD;
  }
  constexpr bool operator==(const modint& rhs) {
    return value == rhs.value;
  }
  constexpr bool operator!=(const modint& rhs) {
    return value != rhs.value;
  }
  constexpr modint operator+(const modint& rhs) const {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint& rhs) const {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint& rhs) const {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint& rhs) const {
    return modint(*this) /= rhs;
  }
  constexpr modint &operator+=(const modint& rhs) {
    value += rhs.value;
    if (value >= MOD) value -= MOD;
    return *this;
  }
  constexpr modint &operator-=(const modint& rhs) {
    if (value < rhs.value) value += MOD;
    value -= rhs.value;
    return *this;
  }
  constexpr modint &operator*=(const modint& rhs) {
    value = value * rhs.value % MOD;
    return *this;
  }
  constexpr modint &operator/=(const modint& rhs) {
    return *this *= pow(rhs, MOD - 2);
  }
  constexpr modint &operator++() {
    return *this += 1;
  }
  constexpr modint operator++(int) {
    modint tmp(*this);
    ++(*this);
    return tmp;
  }
  constexpr modint &operator--() {
    return *this -= 1;
  }
  constexpr modint operator--(int) {
    modint tmp(*this);
    --(*this);
    return tmp;
  }
  constexpr operator int() const {
    return (int)value;
  }
  constexpr operator ll() const {
    return value;
  }
};


