    }
    int mid = (st+en)/2;
    if (idx >= st && idx <= mid) update(2*node , st , mid , idx , val);
    else update(2*node+1 , mid+1 , en , idx , val);
    seg[node] = max(seg[2*node] , seg[2*node+1]);
