class FRemovingRobots {
public:
    void solve() {
        int n = in.readInt();
        auto r = in.readArray<int, int>(n);

        mod = MODF;
        sort(all(r));
        arr<modint> ans(n + 1, 0);
        ans[n] = 1;
        SegmentTree<int, int> tree(n, [&](int a, int b) -> int {
                                       return max(a, b);
                                   }, [&](int a, int b) -> int { return max(a, b); },
                                   [&](int a, int b, int, int) -> int {
                                       return max(a, b);
                                   });
        for (int i : RevRange(n)) {
            ans[i] = ans[i + 1];
            auto up = lower_bound(all(r), pii(r[i].first + r[i].second, 0)) - r.begin();
            int to = max(i, tree.query(i + 1, up));
            ans[i] += ans[to + 1];
            tree.update(i, i + 1, to);
        }
        out.printLine(ans[0]);
    }
};


