    while (!right_st.empty() && R[right_st.top()].first < go) {
      right_st.pop();
    }
    int right = N;
    if (!right_st.empty()) {
      right = right_st.top();
    }
    right_st.push(i);
    ll n_sets = (ll)dp[right] + dp[i + 1];
    n_sets %= mod;
    dp[i] = n_sets;
  }
  cout << dp[0] << endl;
  return 0;
}

