	}
	int mid=l+r>>1;
	ll ans=0;
	if(mid>=x)ans=max(ans,query(o<<1,l,mid,x,y));
	if(mid<y)ans=max(ans,query(o<<1|1,mid+1,r,x,y));
	return ans;
}
