pair <int, int> mINF = {-INF, -INF};

struct Tree
{
	int offset, qbegin, qend;
	pair <int, int> T[maxTS], res;

	void qpriv(int v, int left, int right)
	{
		if (left >= qend or right <= qbegin)	
			return;
		if (left >= qbegin and right <= qend)
		{
			res = max(res, T[v]);
			return;
		}
		qpriv(v * 2, left, (left + right) / 2);
		qpriv(v*2+1, (left + right) / 2, right);
	}

	void init(int n)
	{
		for (offset = 1; offset < n; offset *= 2);
		FOR(i, 1, offset*2)
			T[i] = mINF;			
	}

	void updt(int i, pair <int, int> v)
	{
		for (i += offset; i != 0; i /= 2)
			T[i] = max(T[i], v);		
	}

	pair <int, int> query(int a, int b)
	{
		qbegin = a + offset;
		qend = b + offset;
		res = mINF;
		qpriv(1, offset, offset * 2);
		return res;
	}
}tree;

