	tree.updt(n-1, {End(n-1), n-1});
	FORD(i, n-2, -1)
	{
		dp[i][1] = (dp[i+1][0] + dp[i+1][1]) % mod;
		int j = lower_bound(T, T+n, make_pair(End(i), -INF)) - T;
		if (j == i+1)
			dp[i][0] = dp[i][1];
		else
		{
			j = tree.query(i, j).sd;
			dp[i][0] = dp[j][0];
		}
		tree.updt(i, {End(i), i});
	}

	printf("%lld\n", (dp[0][0] + dp[0][1]) % mod);
} 


