int bin (int x, int i) {
    int l = i, r = a.size();
    while (r - l > 1) {
        int m = (r + l) >> 1ll;
        if (a[m].ff < x) l = m;
        else r = m;
    }
    return l;
}

void upd (int v, int l, int r, int pos, int x) {
    if (r - l == 1) {
        t[v] = x;
        return;
    }
    else {
        int m = (r + l) >> 1;
        if (m <= pos) upd(v * 2 + 2, m, r, pos, x);
        else upd(v * 2 + 1, l, m, pos, x);
        t[v] = max(t[v * 2 + 1], t[v * 2 + 2]);
    }
}

int ask (int v, int l, int r, int tl, int tr) {
    if (l >= tr || r <= tl) return -1;
    if (tl <= l && r <= tr) {
        return t[v];
    }
    int m = (r + l) >> 1;
    return max(ask(v * 2 + 1, l, m, tl, tr), ask(v * 2 + 2, m, r, tl, tr));
}


