    vector<int> v(n, 0);
    for (int i = 0; i < n; ++i) {
        v[i] = i;
    }
    SegmentTree<int> left(v, f, 0);
    left.update(n - 1, n - 1);
    for (int i = n - 2; i >= 0; --i) {
        pair<lint, lint> b = {xd[i].first + xd[i].second - 1, lint(1e10)};
        int l              = upper_bound(xd.begin(), xd.end(), b) - xd.begin() - 1;
        int maxi           = left.query(i, l + 1);
        left.update(i, maxi);
    }
    vector<mint> ret(n + 1, 1);
    for (int i = n - 1; i >= 0; --i) {
        ret[i] = ret[left.query(i, i + 1) + 1] + ret[i + 1];
    }
