using namespace std;

void BuildTree(const vector<int> v, int start, int end, unordered_map<int, unordered_map<int, int>>& um) {
	if (start == end) {
		um[start][end] = v[start];
		return;
	}
	int mid = (start + end) / 2;
	BuildTree(v, start, mid, um);
	BuildTree(v, mid + 1, end, um);
	um[start][end] = max(um[start][mid], um[mid + 1][end]);
}

int QueryTree(unordered_map<int, unordered_map<int, int>>& um, int start, int end, int now_start, int now_end) {
	if (now_start > end || now_end < start) return 0;
	if (now_start >= start && now_end <= end) return um[now_start][now_end];
	int mid = (now_end + now_start) / 2;
	return max(QueryTree(um, start, end, now_start, mid), QueryTree(um, start, end, mid + 1, now_end));
}

void UpdateTree(unordered_map<int, unordered_map<int, int>>& um, int index, int value, int start, int end) {
	if (start > index || end < index) return;
	if (start == end) {
		um[start][end] = value;
		return;
	}
	int mid = (start + end) / 2;

	UpdateTree(um, index, value, start, mid);
	UpdateTree(um, index, value, mid + 1, end);
	um[start][end] = max(um[start][mid], um[mid + 1][end]);
}

