struct SegTree{ //Current implementation is range sum.
    struct ra{ll l, r;};
    vi st;
    SegTree(ll N){
        st.resize(4*N, -1ll);
    }
    void update(ll node, ra R, ra T, ll delta){
        if(R.r < T.l or T.r < R.l) return;
        if(T.l <= R.l and R.r <= T.r){
            st[node] = max(st[node], delta); //Change here as reqd! (2)
            return;
        }
        ll m = (R.l + R.r) / 2;
        update(node*2,{R.l,m},T,delta);
        update(node*2+1,{m+1,R.r},T,delta);
        st[node] = max(st[node*2], st[node*2+1]); //Change here as reqd! (3)
        return; 
    }
    ll query(ll node, ra R, ra T){
        if(R.r < T.l or T.r < R.l) return -1ll;
        if(T.l <= R.l and R.r <= T.r) return st[node];
        ll m = (R.l + R.r) / 2;
        return max(query(node*2,{R.l,m},T), query(node*2+1,{m+1,R.r},T));
        //Change here as reqd! (4)
    }
};

