        ll t = A[x].first + A[x].second;
        ll l = lower_bound(all(A), make_pair(t, -5ll)) - A.begin();

        ll r = Val.query(1, {0, N-1}, {x, l-1});
        r = max(r, x);
        CC[x] = (CC[x+1] + CC[r+1]) % MOD;
        Val.update(1, {0, N-1}, {x, x}, r);
    }

    cout << CC[0] << endl;

    return 0;
}

