int leaf(int n) {
  int a=1;
  while(a<n) a *= 2;
  return a;
}


struct RSQ {





  vector<mint> value;

  RSQ(int n) : value(0) {
    int ct = leaf(n)*2-1;
    mint qw = 0;
    rep(i,0,ct) value.pb(qw); // 全部0
  }

  void update(int i, mint x) { // i 番目の葉の値に x を足す
    int N = (value.size()+1)/2;
    i += N - 1; // i 番目の葉のノード番号
    value[i] += x;
    while (i > 0) {
      i = (i - 1) / 2; // ノード i の親ノードの番号に変える
      value[i] = value[i * 2 + 1]+value[i * 2 + 2]; // 左右の子のsumを計算しなおす
    }
    return;
  }

  mint at(int i) { //i番目の要素にアクセス
    int N = (value.size()+1)/2;
    return value[i-1+N];
  }

  mint RSQ2(int a, int b, int k, int l, int r) {
    // [a, b) の区間に対するクエリについて
    // ノード k （区間 [l, r) 担当）が答える
    if (r <= a || b <= l) return 0; // 区間が被らない場合は0を返す
    if (a <= l && r <= b)
      return value[k]; // ノード k の担当範囲がクエリ区間 [a, b)に完全に含まれる
    else {
      mint c1 = RSQ2(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
      mint c2 = RSQ2(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子に値を聞く
      return c1+c2; // 左右の子の値の sum を取る
    }
  }

  mint rsum(int a,int b) {
    int N = (value.size()+1)/2;
    return RSQ2(a,b+1,0,0,N);
  }
};

