	bool operator<(const struct Info &arg) const{

		return X < arg.X;
	}

	int X,D;
};

int N;
int table[1000005];
int R[200005];
ll dp[200005];


void init(int first_N){
	while(N < first_N)N *= 2;
}

void update(int loc,int value){
	loc += N-1;

	table[loc] = value;

	if(N == 1)return;

	int parent = (loc-1)/2;

	while(true){
		table[parent] = max(table[2*parent+1],table[2*parent+2]);

		if(parent == 0)break;
		else{
			parent = (parent-1)/2;
		}
	}
}


int query(int search_left,int search_right,int node_id,int node_left,int node_right){

	if(search_right < node_left || search_left > node_right)return NUM;

	if(search_left <= node_left && search_right >= node_right){
		return table[node_id];
	}

	int left_max = query(search_left,search_right,2*node_id+1,node_left,(node_left+node_right)/2);
	int right_max = query(search_left,search_right,2*node_id+2,(node_left+node_right)/2+1,node_right);

	return max(left_max,right_max);
}


int main(){

	int first_N;
	N = 1;

	scanf("%d",&first_N);

	init(first_N);

	for(int i = 0; i <= 2*N-2; i++)table[i] = NUM;

	int X,D;
	vector<Info> info;

	for(int i = 0; i < first_N; i++){

		scanf("%d %d",&X,&D);
		info.push_back(Info(X,D));
	}

	sort(info.begin(),info.end());

	int left,right,mid;

	for(int i = 0; i < info.size(); i++){

		left = i,right = info.size()-1,mid = (left+right)/2;
		R[i] = i;

		while(left <= right){

			if(info[i].X+info[i].D > info[mid].X){

				R[i] = mid;
				left = mid+1;

			}else{

				right = mid-1;
			}
			mid = (left+right)/2;
		}
		//printf("i:%d X:%d R:%d\n",i,info[i].X,R[i]);
		update(i,R[i]);
	}

	dp[first_N] = 1;

	for(int i = info.size()-1; i >= 0; i--){

		int tmp = query(i,R[i],0,0,N-1)+1;

		dp[i] = dp[i+1]+dp[tmp];
		dp[i] %= MOD;

		update(i,tmp-1);
	}

	printf("%lld\n",dp[0]);

	return 0;
}

