};

bool robot_sort(const robot a, const robot b) {
	return a.x < b.x;
}

ll sgt[4*2*(int)1e5];

void build(int v, int l, int r, ll *ar) {
	if (l == r) {
		sgt[v] = ar[l];
		return;
	}
	int mid = (l + r)/2;
	build(2*v, l, mid, ar);
	build(2*v+1, mid+1, r, ar);
	sgt[v] = max(sgt[2*v], sgt[2*v+1]);
}

ll maxq(int v, int l, int r, int ql, int qr) {
	debug(v, l, r, ql, qr);
	if (ql > qr)
		return -1;
	if (l == ql and r == qr)
		return sgt[v];
	int mid = (l + r)/2;
	ll a = maxq(2*v, l, mid, ql, min(mid, qr));
	ll b = maxq(2*v+1, mid+1, r, max(mid+1, ql), qr);
	return max(a, b);
}

void update(int v, int l, int r, int pos, ll val) {
	if (l == r) {
		sgt[v] = val;
		return;
	}
	int mid = (l + r)/2;
	if (pos <= mid)
		update(2*v, l, mid, pos, val);
	else
		update(2*v+1, mid+1, r, pos, val);
	sgt[v] = max(sgt[2*v], sgt[2*v+1]);
}


