struct SegMax {
	int val[1 << (DEPTH + 1)];
	SegMax() { int i; rep(i, (1 << (DEPTH + 1))) val[i] = -INF; }
	int getMax(int l, int r, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) return -INF;
		if (l <= a && b <= r) { return val[id]; }
		int res1 = getMax(l, r, a, (a + b) / 2, id * 2 + 1);
		int res2 = getMax(l, r, (a + b) / 2, b, id * 2 + 2);
		return max(res1, res2);
	}
	void update(int pos, int x) {
		pos += (1 << DEPTH) - 1;
		val[pos] = x;
		while (pos > 0) {
			pos = (pos - 1) / 2;
			val[pos] = max(val[pos * 2 + 1], val[pos * 2 + 2]);
		}
	}
};

