    sort(ALL(vec));
    SegmentTree<ll> sg(2e9+1);
    for (int i = 0; i < n; i++) {
        sg.update(vec[i].first, i);
    }
    for (int i = n-1; i >= 0; i--) {
        r[i] = sg.query(vec[i].first, vec[i].first+vec[i].second);
        sg.update(vec[i].first, r[i]);
    }

    dp[n] = 1;
    for (int i = n-1; i >= 0; i--) {
        dp[i] = dp[i+1];
        dp[i] += dp[r[i]+1];
        dp[i] %= mod;
    }
    return dp[0];
