    }

    friend istream &operator >> (istream& lhs, modint& rhs){
        long long tmp;
        lhs >> rhs.num;
        return lhs;
    }
};

template<class T>
struct seg_tree{
    T N;
    T init = 0;
    vector<T> node;

    seg_tree(int n){
        N = 1;
        while(N < n) N *= 2;
        node.resize(N * 2 - 1, 0);
    }

    void update(int i, T x){
        i += N - 1;
        node[i] = x;
        while(i > 0){
            i = (i - 1) / 2;
            node[i] = max(node[i * 2 + 1], node[i * 2 + 2]);
        }
    }

    T get_max(int a, int b, int k = 0, int l = 0, int r = -1){
        if(r == -1) r = N;
        if(b <= l || r <= a) return init;
        if(a <= l && r <= b) return node[k];

        T vl = get_max(a, b, k * 2 + 1, l, (l + r) / 2);
        T vr = get_max(a, b, k * 2 + 2, (l + r) / 2, r);
        return max(vl, vr);
    }
};

