int removing_robots(int N, vector<pair<int, int>>& R) {
	int d, mod = 998244353;
	vector<int> dp(N + 1);
	vector<pair<int, int>> st;

	dp[N] = 1;
	st.emplace_back(N, numeric_limits<int>::max());
	sort(R.begin(), R.end());

