// Segment-Tree
struct SegmentTree {
  int n;
  vector<int> dat;

  SegmentTree(int _n) {
    init(_n);
  }

  void init(int _n) {
    n = 1;
    while (n < _n) n *= 2;
    dat.assign(2 * n - 1, -1);
  }

  // i番目の値をxに変更
  void update(int i, int x) {
    i += n - 1; // 葉のノード
    dat[i] = x;
    while (i > 0) { // 更新
      i = (i - 1) / 2;
      dat[i] = max(dat[2 * i + 1], dat[2 * i + 2]);
    }
  }

  // [a, b)の最大値
  // k:ノードの番号 [l, r)がkに対応づいている
  // query(a, b, 0, 0, n)と呼ぶ
  int query(int a, int b, int k = 0, int l = 0, int r = -1) {
    if (r == -1) r = n;
    if (r <= a || b <= l) return -1;
    if (a <= l && r <= b) return dat[k];
    else {
      int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
      int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
      return max(vl, vr);
    }
  }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<pair<int, int>> x(n);
  for (int i = 0; i < n; i++) cin >> x.at(i).first >> x.at(i).second;

  sort(x.begin(), x.end());

  SegmentTree st(n);
  for (int i = 0; i < n; i++) st.update(i, i);
  for (int i = n - 2; i >= 0; i--) {
    int keep = x.at(i).first + x.at(i).second;
    int l = i, r = n;
    while (r - l > 1) {
      int mid = (l + r) / 2;
      if (x.at(mid).first < keep) l = mid;
      else r = mid;
    }
    st.update(i, st.query(i, r));
  }

  vector<ll> dp(n);
  dp[n - 1] = 2;
  for (int i = n - 2; i >= 0; i--) {
    if (st.query(i, i + 1) + 1 < n) dp[i] = dp[i + 1] + dp[st.query(i, i + 1) + 1];
    else dp[i] = dp[i + 1] + 1;
    dp[i] %= MOD;
  }

  cout << dp[0] << '\n';
}

