struct segmentTree {
    int N;
    vector<int> tree;
    segmentTree(int n) {
        int i;
        int size = 1;
        rep(i, n) {
            if (size > n) break;
            size *= 2;
        }
        this->N = size;
        this->tree.resize(2 * size - 1);
        rep(i, size) this->tree[i] = 0;
    }
    void update(int idx, int val) {
        int i = N + idx - 1;
        tree[i] = val;
        while (i > 0) {
            i = (i - 1) / 2;
            tree[i] = max(tree[i], val);
        }
    }
    int query(int l, int r) {
        return innerQuery(0, l, r, 0, N);
    }
    int innerQuery(int idx, int l, int r, int cl, int cr) {
        if (cl >= r || cr <= l) return 0;
        if (cl >= l && cr <= r) return tree[idx];
        int cm = (cl + cr) / 2;
        return max(innerQuery(idx * 2 + 1, l, r, cl, cm), innerQuery(idx * 2 + 2, l, r, cm, cr));
    }
};

int compress(vector<ll>& x, map<ll, ll>& zip, vector<ll>& unzip) {
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());
    rep(i, x.size()) {
        zip[x[i]] = i;
        unzip[i] = x[i];
    }
    return x.size();
}

