/*** MOD CALCULATION ***/

// const int MOD = 1e9+7;
const int MOD = 998244353;
const int MAX = 2'000'005;

ll addM(ll a, ll b){
	return ((a % MOD) + (b % MOD)) % MOD;
}

ll mulM(ll a, ll b){
	return ((a % MOD) * (b % MOD)) % MOD;
}

ll powM(ll a, ll b){
	if(b == 0) return 1;
  	else if(b == 1) return a % MOD;
  	else if(b%2==0) return mulM(powM(a, b/2), powM(a, b/2));
  	else return mulM(a, mulM(powM(a, (b-1)/2), powM(a, (b-1)/2)));
}

// b^{-1} = b^{p-2} (mod p)
// a/b = a*b^{p-2} (mod p)
ll divM(ll a, ll b){ 
  	return mulM(a, powM(b, MOD-2));
}

// n!, (n!)^{-1} のテーブル作成
ll fac[MAX], finv[MAX], inv[MAX];
void COMBinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    rep3(i,2,MAX-1){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}

// 二項係数計算
ll COMB(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % MOD) % MOD;
}

/*** MOD CALCULATION ここまで ***/

vvi to;

int dfs(int v){
    int res = 1;
    for(auto u : to[v]){
        res = mulM(res, dfs(u));
    }
    return addM(res, 1);
}

void Main(){
    int n; cin >> n;
    vector<P> robot(n);
    rep(i, n) cin >> robot[i].fi >> robot[i].se;
    sort(all(robot));

    // to は有向グラフだが実は木になる
    to.resize(n);
    // s には {x, id} を記憶
    set<P> s;

    rep3rev(i, n-1, 0){
        int x = robot[i].fi, d = robot[i].se;
        while(!s.empty() && s.begin()->fi < x+d){
            to[i].pb(s.begin()->se);
            s.erase(s.begin());
        }
        s.insert({x, i});
    }

    int ans = 1;
    for(auto [x, v] : s){
        ans = mulM(ans, dfs(v));
    }

    cout << ans << endl;
    return;
}

