class Solution
{
private:
public:
    Solution() {}
    ~Solution() {}
    void solveCase()
    {
        int n;
        cin >> n;
        vector<pair<int, int>> X(n);
        vector<int> xonly;
        for (auto &x : X)
        {
            cin >> x.f >> x.s;
        }
        for (size_t i = 0; i < n; i++)
            xonly.pb(X[i].f);
        sort(all(X));
        sort(all(xonly));
        dp[n - 1][0] = dp[n - 1][1] = 1;
        Segtree S(n + 1);
        S.update(n - 1, Node(X[n - 1].f + X[n - 1].s - 1, dp[n - 1][1]));
        for (int i = n - 2; i >= 0; i--)
        {
            dp[i][0] = add(dp[i + 1][0], dp[i + 1][1]);
            auto it = lower_bound(all(xonly), xonly[i] + X[i].s);
            if (it == xonly.begin())
            {
                dp[i][1] = add(dp[i + 1][0], dp[i + 1][1]);
            }
            else
            {
                --it;
                auto idx = it - xonly.begin();
                db(i, idx);
                if (idx == i)
                    dp[i][1] = add(dp[i + 1][0], dp[i + 1][1]);
                else
                {
                    auto q = S.query(i + 1, idx);
                    db(q.val);
                    if (q.val.f == -1)
                        dp[i][1] = add(dp[i + 1][0], dp[i + 1][1]);
                    else
                        dp[i][1] = q.val.s;
                }
            }
            S.update(i, Node(X[i].f + X[i].s - 1, dp[i][1]));
            db(i, dp[i][0], dp[i][1]);
        }
        cout << add(dp[0][0], dp[0][1]) << '\n';
    }
};

