            });

    vector<vector<int>> G(N);

    int covered = -1e9;
    for (int i = 0; i < N; ++i) {
        int id = ord[i];

        if (covered > X[id] + D[id]) {
            continue;
        }

        for (int j = i+1; j < N; ++j) {
            int id2 = ord[j];
            if (X[id] + D[id] <= X[id2]) {
                break;
            }
            G[id].push_back(id2);
