    for (int id : order) {
        for (int u : scc.t[id]) {
            int id2 = scc.comp[u];
            dp[0][id] *= (dp[0][id2] + dp[1][id2]);
        }
        for (int u : scc.t[id]) {
            int id2 = scc.comp[u];
            dp[1][id] *= dp[1][id2];
        }
    }
    DUMP(dp[0]);
    DUMP(dp[1]);

    vector<int> indeg(scc.t.size());
    for (int i = 0; i < scc.t.size(); ++i) {
        for (int u : scc.t[i]) {
            ++indeg[u];
        }
    }
    DUMP(indeg);

    Int ans = 1;
    for (int i = 0; i < scc.t.size(); ++i) {
        if (indeg[i] == 0) {
            ans *= (dp[0][i] + dp[1][i]);
        }
    }

    DUMP(ans);


    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct dor {
	dor *l, *r;
	int sd;
} *rt;

const int LN = -1e9, NR = 2e9, mod = 998244353;

int M(long long l, long long r) {
	int m = (l + r) / 2;
	if(m == r) --m;
	return m;
}

int si, vl;
void rgnk(int l, int r, dor *&t) {
	if(t == NULL)
		t = new dor();
	if(l == r)
		t->sd = vl;
	else if((l + r) / 2 >= si)
		rgnk(l, M(l, r), t->l);
	else
		rgnk(M(l, r) + 1, r, t->r);
}

void gnk(int Si, int Vl) {
	si = Si, vl = Vl;
	rgnk(LN, NR, rt);
}

int sl, sr;
int rsgm(int l, int r, dor *&t) {
	if(l > sr || r < sl || t == NULL)
		return LN;
	if(l >= sl && r <= sr)
		return t->sd;
	return max(rsgm(l, M(l, r), t->l), rsgm(M(l, r) + 1, r, t->r));
}

int sgm(int l, int r) {
	sl = l, sr = r;
	return rsgm(LN, NR, rt);
}

