    vector<vector<int>> graph(n);
    set<P> st;
    for(int i = n - 1; i >= 0; --i){
        int x = table[i].first, d = table[i].second;
        while(st.size() && st.begin()->first < x + d){
            graph[i].emplace_back(st.begin()->second);
            st.erase(st.begin());
        }
        st.emplace(x, i);
    }

    function<modint(int)> rec = [&](int from) -> modint {
        modint res = 1;
        for(int to : graph[from]){
            res *= rec(to);
        }
        return res + 1;
    };

    modint ans = 1;
    for(auto p : st){
        int u = p.second;
        ans *= rec(u);
    }
    cout << ans << endl;
}

