        int tar=min((LL)i,N-bit2.qq(N-ll));
        bit2.ins(N-i,N-tar);
        if(!tar)ADD(dp[i],dp[i-1]+1);
        else{
            ADD(dp[i],dp[i-1]+dp[tar-1]);
        }
    }
    W(dp[N-1]);
    return 0;
}

