      d.Set(n-i-1,n-i,max(d.Getmax(n-i,it),it));
    }
    ll id=n-d.Getmax(n-i-1,n-i);
    (dp[i+1]=ans[id])%=mod;
    (ans[i+1]=ans[i]+dp[i+1])%=mod;
  }
  cout << ans[n] << endl;
}

