ll n, m;
vll x, d, f;
vll dp;
vll segtree;

void mktree() {
    m = 1;
    while (m < n)
        m *= 2;
    segtree.resize(2 * m, 0);
}

void upd(ll i, ll x) {
    i += m;
    while (i > 0) {
        segtree[i] = max(segtree[i], x);
        i /= 2;
    }
}

ll getmax(ll l, ll r) {
    l += m;
    r += m;
    ll ans = 0;
    while (l <= r) {
        if (l % 2 == 1)
            ans = max(ans, segtree[l++]);
        if (r % 2 == 0)
            ans = max(ans, segtree[r--]);
        l /= 2;
        r /= 2;
    }
    return ans;
}

void solve() {
    cin >> n;
    vpll a(n);
    rep(i, 0, n) {
        cin >> a[i].first >> a[i].second;
    }
    sort(a.begin(), a.end());

    x.resize(n);
    d.resize(n);
    rep(i, 0, n) {
        x[i] = a[i].first;
        d[i] = a[i].second;
    }

    mktree();
    f.resize(n, 0);

    for (ll i = n - 1; i >= 0; i--) {
        ll lo = i;
        ll hi = n - 1;
        ll best = i;
        while (lo <= hi) {
            ll mid = (lo + hi) / 2;
            if (x[mid] < x[i] + d[i]) {
                best = mid;
                lo = mid + 1;
            }
            else {
                hi = mid - 1;
            }
        }
        f[i] = i;
        f[i] = max(f[i], getmax(i, best));
        upd(i, f[i]);
    }

    dp.resize(n + 1, 1);
    for (ll i = n - 1; i >= 0; i--) {
        dp[i] = dp[i + 1] + dp[f[i] + 1];
        dp[i] = dp[i] % mod;
    }
    cout << dp[0] << endl;
}


