const int N = 222222;
pair<int, int> ro[N];
int stree[N << 2];
int dp[N];
int n;

void update(int i, int cl, int cr, int v, int pos) {
    if(cl > i || cr < i) {
        return;
    } else if(cl == i && cr == i) {
        stree[pos] = v;
        return;
    }
    int m = cl + cr >> 1;
    update(i, cl, m, v, pos * 2 + 1);
    update(i, m + 1, cr, v, pos * 2 + 2);
    stree[pos] = max(stree[pos * 2 + 1], stree[pos * 2 + 2]);
}

int query(int l, int r, int cl, int cr, int pos) {
    if(cl > r || cr < l) {
        return 0;
    } else if(cl >= l && cr <= r) {
        return stree[pos];
    }
    int m = cl + cr >> 1;
    int x = query(l, r, cl, m, pos * 2 + 1);
    int y = query(l, r, m + 1, cr, pos * 2 + 2);
    return max(x, y);
}

int getIndBefore(int x) {
    int lo = 1, hi = n;
    while(lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;
        if(x <= ro[mid].fi) {
            hi = mid - 1;
        } else {
            lo = mid;
        }
    }
    return hi;
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    rep(i, 1, n) {
        int x, d;
        cin >> x >> d;
        ro[i] = {x, d};
    }
    sort(ro + 1, ro + n + 1);
    rrep(i, 1, n) {
        int x = ro[i].fi, d = ro[i].se;
        int j = getIndBefore(x + d);
        int r = max(i, query(i, j, 1, n, 0));
        update(i, 1, n, r, 0);
    }
    dp[n + 1] = 1;
    rrep(i, 1, n) {
        int j = query(i, i, 1, n, 0);
        dp[i] = (dp[i + 1] + dp[j + 1]) % MOD;
    }
    cout << dp[1] << endl;
    return 0;
}

