const int MAXN = 2e5 + 20;
const int MOD = 998244353;
vector<int> unq;
vector<pii> srt;
int x[MAXN], d[MAXN], dp[MAXN][2], n;
struct SegmentTree {
	#define lson (root << 1)
	#define rson (root << 1 | 1) 
	int val[1 << 19];
	inline void modify(int p, int v, int root = 1, int stdl = 1, int stdr = n) {
		if (stdl == stdr) {
			val[root] = v;
			return;
		}
		int mid = (stdl + stdr) >> 1;
		if (p <= mid) {
			modify(p, v, lson, stdl, mid);
		} else {
			modify(p, v, rson, mid + 1, stdr);
		}
		val[root] = max(val[lson], val[rson]);
	}
	inline int query(int l, int r, int root = 1, int stdl = 1, int stdr = n) {
		if (l <= stdl && stdr <= r) return val[root];
		int res = 0, mid = (stdl + stdr) >> 1;
		if (l <= mid) res = query(l, r, lson, stdl, mid);
		if (r > mid) res = max(res, query(l, r, rson, mid + 1, stdr)); 
		return res;
	}
}	tr;
int main() {
	ios::sync_with_stdio(false);
	cin.tie(NULL), cout.tie(NULL);
	cin >> n;
	rep (i, 1, n) {
		cin >> x[i] >> d[i];
		unq.emplace_back(x[i]);
		srt.emplace_back(x[i], d[i]);
	}
	sort(all(unq));
	sort(all(srt));
	rep (i, 0, n - 1) {
		x[i + 1] = srt[i].fst;
		d[i + 1] = srt[i].sed;
	}
	dp[n + 1][0] = 1;
	dp[n][0] = dp[n][1] = 1;
	tr.modify(n, n);
	per (i, n - 1, 1) {
		dp[i][0] = (dp[i + 1][0] + dp[i + 1][1]) % MOD;
		int pos = upper_bound(all(unq), x[i] + d[i] - 1) - unq.begin();
		int far = max(i, tr.query(i, pos)); tr.modify(i, far);
		dp[i][1] = (dp[far + 1][0] + dp[far + 1][1]) % MOD;
	}
	cout << (dp[1][0] + dp[1][1]) % MOD << endl;
	return 0;
}

