int N;
int turnon (deque<deque <long>> &localXD, int i, long maxX)
{
	int count = i;

	if (localXD.size () <= i + 1)
	{
		//ほかと相互作用しない場合はiを返す。
		localXD.erase (localXD.begin () + i);
		return i;
	}
	if (localXD[i+1][0] < maxX)
	{
		localXD.erase (localXD.begin () + i);
		if (localXD.size () > i)
			return max (i+1, turnon (localXD, i, max (maxX, localXD[i][0] + localXD[i][1])) + 1);
	}
	return count;
}
void pseudomain (deque<deque <long>> XD)
{
	int N = XD.size ();
	deque<deque <long>> localXD;

	for (int i = 0; i < N; i++)
	{
		localXD.resize (N);
		for (auto &e: localXD)
			e.resize (2);
		for (int k = 0; k < N; k++)
		{
			localXD[k][0] = XD[k][0];
			localXD[k][1] = XD[k][1];
		}
		int Deleted = turnon (localXD, i, localXD[i][0]+localXD[i][1]);
		Ri[i] = Deleted; //消去されるブロックの最大値
	}
}

