//firstで初期化された、葉がn要素を超えるように2のべき乗個用意されたリストを返す
vector<int> make_ST(int n,int first){

    int i = 0;
    vector<int> ret(0,0);

    while ((1<<(i-1)) < n){

        for (int j = 0 ; j < (1<<i) ; j++){
            ret.push_back(first);
        }

        i++;

    }

    return ret;
}

void RMQ_update_point(int num,int point,vector<int>& tree){

    int i = (tree.size()-1)/2 + point;
    tree[i] = num;
    while (i > 0){
        i = (i-1)/2;
        tree[i] = min(tree[i*2+2] , tree[i*2+1]);
    }
    return ;
}

int RMQ_query(int a,int b,int k,int l,int r,vector<int>& tree){

    if ((r <= a) || (b <= l)) return INT_MAX;
    if ((a <= l) && (r <= b)) return tree[k];

    int c1 = RMQ_query(a,b,2*k+1,l,(l+r)/2,tree);
    int c2 = RMQ_query(a,b,2*k+2,(l+r)/2,r,tree);

    return min(c1,c2);
}


