    vector<int> tree = make_ST(N,0);
    vector<int> lis(0);

    rep(i,0,N){
        X = XD[N-1-i][0];
        D = XD[N-1-i][1];
        int ind = distance(Xlis.begin(),lower_bound(Xlis.begin(), Xlis.end(), X+D));

        int nans = RMQ_query(N-i-1,ind,0,0,(tree.size()+1)/2,tree);
        nans *= (-1);
        RMQ_update_point(-1 * max(nans,ind),N-i-1,tree);
        lis.push_back(max(nans,ind));
    }

    reverse(lis.begin(),lis.end());

    int ans = 0;
    vector<int> dp(N+1,0);
    dp[0] = 1;

    rep(i,0,N){

        dp[i+1] += dp[i];
        dp[lis[i]] += dp[i];

        dp[i] %= mod;
        dp[lis[i]] %= mod;
    }

    cout << dp[N] % mod << endl; 
}

