  vm dp(N + 1);
  dp[0] = 1;

  auto f=[](int a,int b){return max(a,b);};
  ST<int,decltype(f)> memo(N , f , 0);
  memo.update(N - 1 , N - 1);
  repr(i , N){
    auto it = lower_bound(all(a) , P(a[i].fi+a[i].se, -1));
    int nya = it - a.begin();
    memo.update(i , i);
    if(nya != i) memo.update(i , memo.query(i , nya) );
  }
