#define rep(i, n) for(UL i = 0; i < (n); i++)

struct RMQ {
	UL N;
	vector<UL> V;
	void init(UL n) {
		N = 1; while (N < n) N *= 2;
		V.resize(N * 2 - 1);
	}
	void update(UL p, UL v) {
		UL i = N - 1 + p;
		V[i] = v;
		while (i != 0) {
			i = (i - 1) >> 1;
			V[i] = max(V[(i << 1) + 1], V[(i << 1) + 2]);
		}
	}
	UL query(UL l, UL r, UL a = -1, UL b = -1, UL i = -1) {
		if (i == -1) { a = i = 0; b = N; }
		if (l <= a && b <= r) return V[i];
		if (r <= a || b <= l) return 0;
		return max(
			query(l, r, a, (a + b) >> 1, (i << 1) + 1),
			query(l, r, (a + b) >> 1, b, (i << 1) + 2)
		);
	}
};

struct Problem {

	static const ULL M = 998244353;

	void Solve() {
		UL N; cin >> N;
		vector<pair<UL, UL>> X(N);
		rep(i, N) {
			int x, d; cin >> x >> d;
			UL ux = x + 1000000000, ud = d;
			X[i] = { ux, ux + ud };
		}
		sort(X.begin(), X.end());

		vector<UL> To(N + 1); To[N] = N;
		{
			set<pair<UL, UL>> Q;
			RMQ T; T.init(N + 1); T.update(N, N - 1);
			rep(i, N) Q.insert({ X[i].first, i });
			Q.insert({ -1, N });
			for (int i = N - 1; i >= 0; i--) {
				To[i] = Q.lower_bound({ X[i].second, 0 })->second;
				T.update(i, To[i]);
				To[i] = T.query(i, To[i]);
				T.update(i, To[i]);
			}
		}

		vector<ULL> dp(N + 1); dp[N] = 1;
		for (int i = N - 1; i >= 0; i--) {
			dp[i] = (dp[i + 1] + dp[To[i]]) % M;
		}
		/*
		cout << endl;
		rep(i, N) cout << X[i].first << " " << X[i].second << endl;
		cout << endl;
		rep(i, N) cout << To[i] << " "; cout << endl;
		rep(i, N + 1) cout << dp[i] << " "; cout << endl;
		cout << endl;
		*/
		cout << dp[0] << endl;
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
