template<class T>
class SegTree
{
public:
    T Max[N << 2];
    inline void pushup(int rt)
    {
        Max[rt] = max(Max[lson], Max[rson]);
    }

    void update(int rt, int l, int r,int pos, T val)
    {
        if(l == r)
        {
            Max[rt] = val;
            return;
        }
        int mid = l + r >> 1;
        if(pos <= mid) update(lson, l, mid, pos, val);
        else          update(rson, mid + 1, r, pos, val);
        pushup(rt);
        return;
    }

    T query(int rt, int l, int r, int L, int R)
    {
        if(L <= l && r <= R) return Max[rt];
        int mid = l + r >> 1;
        T ans = 0;
        if(L <= mid) ans = max(ans, query(lson, l, mid, L, R));
        if(R > mid)  ans = max(ans, query(rson, mid + 1, r, L, R));
        return ans;
    }
};
