int find(int x) { return x == uf[x] ? x : uf[x] = find(uf[x]); }
void merge(int a, int b) {
  a = find(a); b = find(b);
  if (a > b) swap(a, b); 
  uf[a] = b;
}

ll dp[N];

pair<int, int> t[2*N];
void upd(int x, int v, int i) {
  t[N+x] = {v, i};
  for (x += N, x /= 2; x; x /= 2) {
    t[x] = max(t[2*x], t[2*x+1]);
  }
}
pair<int, int> query(int l, int r) {
  pair<int, int> ans = {-INF, -1};
  for (l += N, r += N+1; l < r; l /= 2, r /= 2) {
    if (l%2) ans = max(ans, t[l++]);
    if (r%2) ans = max(ans, t[--r]);
  }
  return ans;
}

