void modify(int p,int x,int id = 1,int l = 0,int r = n){
	s[id] = max(s[id],x);
	if(r - l < 2){	//	l = r - 1 = p
		return ;
	}
	int mid = (l + r)/2;
	if(p < mid)
		modify(p, x, id * 2, l, mid);
	else
		modify(p, x, id * 2 + 1, mid, r);
}

int query(int x,int y,int id = 1,int l = 0,int r = n){
	if(x >= r or l >= y)	return 0;
	if(x <= l && r <= y)	return s[id];
	int mid = (l+r)/2;
	return max(query(x, y, id * 2, l, mid) ,
	       query(x, y, id * 2 + 1, mid, r));
}

int add(int x , int y){
    int ret = x + y;
    if(ret >= MOD)ret -= MOD;
    return ret;
}

int solve(int idx){
    if(idx == n)return 1;
    int &ret = dp[idx];
    if(~ret)return ret;
    ret = solve(idx + 1);
    ret = add(ret , solve(nxt[idx]));
    return ret;
}

