ModInt<> solve() {
  auto fun = [](int l, int r) { return max(l, r); };
  seg = SegmentTree<int>(n + 1, fun, 0);
  for(int i = 0; i <= n; ++i) seg.update(i, i);
  for(int i = n - 1; i >= 0; --i) {
    long long lim = v[i].x + v[i].d;
    auto it = lower_bound(x.begin(), x.end(), lim);
    int id = it - x.begin();
    seg.update(i, seg.query(i, id));
  }
  dp.assign(n + 1, 0);
  dp[n] = 1;
  for(int i = n - 1; i >= 0; --i) {
    // not use
    dp[i] = dp[i + 1];
    // use
    dp[i] += dp[seg.query(i, i + 1) + 1];
  }
  return dp[0];
}

