  sort(ALL(xd));
  set<pair<long long, int>> s;//現時点で根である頂点たちを格納。(x座標, 頂点のインデックスi)
  for(int i = n - 1; i >= 0; i--){
    long long tx = xd[i].first;
    long long td = xd[i].second;
    while(s.size() > 0 && s.begin() -> first < tx + td){
      G[i].push_back(s.begin() -> second);
      s.erase(s.begin());
    }
    s.insert(make_pair(tx, i));
  }

  long long ans = 1;
  for(auto xi: s){
    int i = xi.second;
    ans *= dfs(i);
    ans = mod(ans);
  }
  cout<<ans<<endl;
  return 0;
}

