vector<pair<int, int>> input;
vector<int> x, r; //r[i] is the last robot that you can influence with the ith robot
vector<int> memo;

struct segtree{
    int i, j, val;
    segtree *l, *r;
    segtree(vector<int> &ar, int _i, int _j) : i(_i), j(_j){
        if (i == j){
            val = ar[i];
            l = r = nullptr;
        }
        else{
            int k = (i+j)/2;
            l = new segtree(ar, i, k);
            r = new segtree(ar, k+1, j);
            val = max(l->val, r->val);
        }
    }
    void update(int _i, int _val){
        if (_i <= i and j <= _i){
            val = _val;
        }
        else if(_i < i or j < _i){
            //nothing
        }
        else{
            l->update(_i, _val);
            r->update(_i, _val);
            val = max(l->val, r->val);
        }
    }
    int query(int _i, int _j){
        if (_i <= i and j <= _j){
            return val;
        }
        else if (_j < i or j < _i){
            return 0;
        }
        else{
            return max(l->query(_i, _j), r->query(_i, _j));
        }
    }
};

int main(){
