    }
    sort(input.begin(), input.end());
    sort(x.begin(), x.end());

    r.resize(n);
    r[n - 1] = n - 1;
    segtree * seg = new segtree(r, 0, n - 1);
    for (int i = n-2; i >= 0; --i){
        int pos = lower_bound(x.begin(), x.end(), input[i].first + input[i].second) - x.begin() - 1; 
        seg->update(i, pos);

        r[i] = seg->query(i, pos);

        seg->update(i, r[i]);
    }
    memo.resize(n+100);
    memo[n] = 1;
    for (int i = n-1; i >= 0; --i){
        memo[i] = (memo[r[i] + 1] + memo[i + 1]) % MOD;
    }
    cout << memo[0] << endl;
}

