const long long MOD = 998244353;
template<typename T>
vector<T> build_segtree(function<T(T,T)>f,T unit,const vector<T> &v){
    long n=1;
    while(n<v.size()){n<<=1;}
    vector<T> tree(n<<1,unit);
    for(size_t i=0;i<v.size();++i)tree[n+i]=v[i];
    if(n>0)for(size_t i=n-1;i;--i){
        tree[i]=f(tree[i*2],tree[i*2+1]);
    }
    return tree;
}
template <typename T>
class segtree{
    using F = function<T(T,T)>;
    long n;
    F f;
    T unit;
    vector<T> tree;
    public:
    segtree(F f,T unit,const vector<T> &v):f(f),unit(unit),tree(){
        tree=build_segtree(f,unit,v);
        n = tree.size()/2;
    }
    segtree(F f,T unit,size_t n_):segtree(f,unit,vector<T>(n_,unit)){
    }
    void build(const vector<T> &v){
        for(size_t i=0;i<v.size();++i)tree[n+i]=v[i];
        if(n>0)for(size_t i=n-1;i;--i){
            tree[i]=f(tree[i*2],tree[i*2+1]);
        }
    }
    void set_val(size_t k,T x){
        if(k>n){
            cerr<<"out of size"<<endl;
            exit(1);
        }
        tree[k+=n]=x;
        while(k>>=1){
            tree[k]=f(tree[k*2],tree[k*2+1]);
        }
    }
    void add_val(size_t k,T x){
        if(k>n){
            cerr<<"out of size"<<endl;
            exit(1);
        }
        k+=n;
        tree[k]=f(tree[k],x);
        while(k>>=1){
            tree[k]=f(tree[k*2],tree[k*2+1]);
        }
    }
    T query(size_t a,size_t b){
      if(b>=n){
        b=n;
      }
        T vl=unit,vr=unit;
        for(int l=a+n,r=b+n;l<r;l/=2,r/=2){
            if(l&1)vl=f(vl,tree[l++]);
            if(r&1)vr=f(tree[--r],vr);
        }
        return f(vl,vr);
    }
};
void solve(long long N, std::vector<long long> X, std::vector<long long> D){
  vector<pll> XD(N);
  REP(N){
    XD[i]=make_pair(X[i],D[i]);
  }
  sort(XD.begin(),XD.end());
  dump(XD);
  REP(N){
    X[i]=XD[i].first;
    D[i]=XD[i].second;
  }
  auto f=[](ll a,ll b){return max(a,b);};
  segtree<ll> delright(f,LLONG_MIN,N);
  delright.set_val(N-1,N);
  Rev(i,N-1){
    ll j=lower_bound(X.begin(),X.end(),X[i]+D[i])-X.begin();
    if(i+1==j){
      delright.set_val(i,j);
    }else{
      ll tmp=delright.query(i,j);
      while(tmp>j){
        j=tmp;
        tmp=delright.query(i,j);
      }
      delright.set_val(i,j);
    }
  }
  REP(N){
    cerr<<delright.query(i,i+1)<<" ,";
  }
  cerr<<endl;
  vector<ll> dp(N+1);
  dp[N-1]=2;
  dp[N]=1;
  Rev(i,N-1){
    ll tmp=delright.query(i,i+1);
    dp[i]=dp[i+1]+dp[tmp];
  }
  cout<<dp[0]<<endl;
}

