    y.at(i) = x.at(i).first;
  }

  sort(x.begin(), x.end());
  map<int, int> mp = compress(y);

  SegmentTree st(n);
  for (int i = 0; i < n; i++) st.update(i, i);
  for (int i = n - 2; i >= 0; i--) {
    int keep = x.at(i).first + x.at(i).second;
    int l = i, r = n;
    while (r - l > 1) {
      int mid = (l + r) / 2;
      if (x.at(mid).first < keep) l = mid;
      else r = mid;
    }
    st.update(i, st.query(i, r));
  }

  vector<ll> dp(n);
  dp[n - 1] = 2;
  for (int i = n - 2; i >= 0; i--) {
    if (st.query(i, i + 1) + 1 < n) dp[i] = dp[i + 1] + dp[st.query(i, i + 1) + 1];
    else dp[i] = dp[i + 1] + 1;
    dp[i] %= MOD;
  }

  cout << dp[0] << '\n';
}

