    ll n;
    cin >> n;
    vector<pair<ll,ll>> xd(n);
    for(auto &t: xd) cin >> t.first >> t.second;
    sort(xd.begin(), xd.end());

    SegmentTree<ll> st(n+1, [&](ll a, ll b){return max(a, b);}, 0);

    vector<vector<ll>> dp(n+1, vector<ll>(2));
    dp[n][0] = 1;
    dp[n-1][0] = 1;
    dp[n-1][1] = 1;
    st.update(n-1, n);
    for(ll i=n-2; i>=0; i--) {
        ll j = lower_bound(xd.begin(), xd.end(), make_pair(xd[i].first + xd[i].second, (ll)-1e9)) - xd.begin();
        ll k = max(st.query(i, j), j);
        st.update(i, k);

        dp[i][1] = (dp[k][1] + dp[k][0]) % MOD;
        dp[i][0] = (dp[i+1][1] + dp[i+1][0]) % MOD;
    }

    cout << (dp[0][0] + dp[0][1]) % MOD << endl;
}

