int Maxi(int l, int r, int I)
{
    if (l <= L[I] && R[I] <= r)
    {
        return M[I];
    }
    else if ((L[I] <= l && l <= R[I]) || (L[I] <= r && r <= R[I]))
    {
        return max(Maxi(l, r, 2*I), Maxi(l, r, 2*I+1));
    }
    else
    {
        return 0;
    }
}

void Update(int I, int a)
{
    I += t-1;
    M[I] = a;
    I /= 2;
    while (I >= 1)
    {
        M[I] = max(M[2*I], M[2*I+1]);
        I /= 2;
    }
}

