template<class M=int> struct segmax {
    int n;
    vector<M> seg;/*@formatter:on*/
    const M e = MIN(M);
    M f(M a, M b) { return a > b ? a : b; }
    segmax(int len, M init_value) : e(init_value) {
        n = 1;
        int asz = len;
        while (n <= asz)n <<= 1;
        seg.assign((n << 1) - 1, e);
        rep(i, asz) seg[i + n - 1] = e;
        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);
        debu();
    }
    segmax(vector<M> &dat, M init_value) : e(init_value) {
        n = 1;
        int asz = dat.size();
        while (n <= asz)n <<= 1;
        seg.assign((n << 1) - 1, e);
        rep(i, asz) seg[i + n - 1] = dat[i];
        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);
        debu();
    }
    void update(int k, M v, bool debug = true) {
        int tk = k;
        seg[k + n - 1] = v;
        k += n - 1;
        while (k) {
            k = (k - 1) >> 1;
            seg[k] = f(seg[(k << 1) | 1], seg[(k << 1) + 2]);
        }
        if (debug)debup(tk, v);
    }
    M query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l)return e;
        else if (a <= l && r <= b)return seg[k];
        else {
            M sl = query(a, b, (k << 1) | 1, l, (l + r) >> 1);
            M sr = query(a, b, (k << 1) + 2, (l + r) >> 1, r);
            return f(sl, sr);
        }
    }/*    M get(int a = 0, int b = -1) { return query(a, b == -1 ? n : b, 0, 0, n); }*/
    M query_bottomup(int l, int r, bool debug = true) {
        advance();
        int tl = l, tr = r;
        M retl = e;
        M retr = e;
        l += n - 1;
        r += n - 1;
        while (l < r) {            /*右なら、次に右上へ移動してしまうので*/            if (!(l & 1)) { retl = f(retl, seg[l]); }            /*右なら、左を取らないと機会を逃す*/            if (!(r & 1)) { retr = f(seg[r - 1], retr); }
            l >>= 1;
            r = (r - 1) >> 1;
        }
        M ret = f(retl, retr);
        if (debug)debge(tl, tr, ret);
        return ret;
    }
    void advance() {        /*iが複数回更新されている場合最後だけみればいいが         * そのような使い方はしないため前からみる*/        while (!q.empty()) {
            int i;
            M v;
            tie(i, v) = q.front();
            q.pop();
            if (seg[i + n - 1] != v) { update(i, seg[i + n - 1]); }
        }
    }
    template<typename C> int find_subtree(int a, const C &check, M &m, bool type) {
        while (a < n) {
            M nxt = type ? f(seg[2 * a + type - 1], m) : f(m, seg[2 * a + type - 1]);
            if (check(nxt)) a = 2 * a + type; else m = nxt, a = 2 * a + 1 - type;
        }
        return a - n;
    }
public:
    void del(int k) {
        advance();
        update(k, e);
    }
    void add(int k, int v, bool debug = true) {
        advance();
        update(k, v + seg[k + n - 1], debug);
    }
    M get(int a, int b, bool debug = true) { return query_bottomup(a, min(b, n), debug); }
    M get(int b = inf, bool debug = true) { return query_bottomup(0, min(b, n), debug); }
    M operator()(int b = inf) { return get(0, b); }
    M operator()(int a, int b) { return get(a, b); }
    queue<pair<int, M>> q;
    M &operator[](int k) {
        q.push(mp(k, seg[k + n - 1]));
        return seg[k + n - 1];
    }
    /*[a x+1)でcheckを満たす最も左のxを返す*/
    template<typename C> int find_first(int a, const C &check) {
        M L = e;
        if (a <= 0) {
            if (check(f(L, seg[1 - 1]))) return find_subtree(1, check, L, false);
            return -1;
        }
        int b = n;
        for (a += n, b += n; a < b; a >>= 1, b >>= 1) {
            if (a & 1) {
                M nxt = f(L, seg[a - 1]);
                if (check(nxt)) return find_subtree(a, check, L, false);
                L = nxt;
                ++a;
            }
        }
        return -1;
    }
    /*[x b)でcheckを満たす最も右のxを返す*/
    template<typename C> int find_last(int b, const C &check) {
        M R = e;
        if (b >= n) {
            if (check(f(seg[1 - 1], R))) return find_subtree(1, check, R, true);
            return -1;
        }
        int a = n;
        for (b += n; a < b; a >>= 1, b >>= 1) {
            if (b & 1) {
                M nxt = f(seg[--b - 1], R);
                if (check(nxt)) return find_subtree(b, check, R, true);
                R = nxt;
            }
        }
        return -1;
    }
    //r)でv以上を満たす最右のindexを返す
    int most_r(int r, M v) {
        M d = get(0, r, false);
        if (get(0, r, false) < v) {
            err("most_r : ", r, ")  >= ", v, " :  ", -1);
            debu();
            return -1;
        }
        int l = 0;
        while (r - l > 1) {
            int m = (l + r) >> 1;
            if (get(m, r, false) >= v) { l = m; } else { r = m; }
        }
        err("most_r : ", r, ")  >= ", v, " :  ", l);
        debu();
        return l;
    }
    int most_r(M v) { return most_r(n, v); }
    //[lで v以上を満たす最左のindexを返す
    int most_l(int l, M v) {
        if (get(l, n, false) < v) {
            err("most_l : ", "[ ", l, ">=", v, "  :  ", -1);
            debu();
            return -1;
        }
        int r = n;
        while (r - l > 1) {
            int m = (l + r) >> 1;
            if (get(l, m, false) >= v) { r = m; } else { l = m; }
        }
        err("most_l : ", "[ ", l, ">=", v, "  :  ", l);
        debu();
        return l;
    }
    int most_l(M v) { return most_l(0, v); }
#ifdef _DEBUG
/*@formatter:on*/
    void debu() {
        rep(i, min(n, 30ll)) {
            int v = seg[i + n - 1];
            if (v == MIN(ll) || v == MAX(ll)) { cerr << "e "; } else { cerr << v << " "; }
        }
        cerr << "" << endl << endl;
    }
    void debup(int k, int v) {
        cerr << "upd : [" << k << "] = " << v << endl;
        debu();
    }
    void debge(int l, int r, M v) {
        cerr << "get : [" << l << ", " << r << ") = " << v << endl;
        debu();
    }
#else
    void debu(){;}    void debup(int k,int v){;}    void debge(int l,int r,M v){;}/*@formatter:on*/
#endif
};
template<typename T> struct segumax {/*@formatter:off*/
    int n, height;
    T fvv(T a, T b) {return a > b ? a : b;}
    T fvl(int len, T x) {return x;}
    T ve = MIN(T); //演算における単位元
    T le = MAX(T);//作用素に対しての単位元
    vector<T> dat;
    vector<T> laz;
    vi len;
    segumax(vector<T> a) {        n = 1;        int n_ = a.size();        height = 0;        while (n <= n_) n <<= 1, height++;        dat.assign(n << 1, ve);        laz.assign(n << 1, le);        len.assign(n << 1, 0);        int l = 1, v = n;        rep(i, 1, n << 1) {            if ((l << 1) == i) {                l <<= 1;                v >>= 1;            }            len[i] = v;        }        for (int i = 0; i < n_; i++) dat[n + i] = a[i];        for (int i = n - 1; i; i--)            dat[i] = fvv(dat[(i << 1) | 0], dat[(i << 1) | 1]);    }
    //おそらく1-indexed
    T reflect(int k) {        return laz[k] == le ? dat[k] : fvl(len[k], laz[k]);    }
    void eval(int k) {        if (laz[k] == le) return;        laz[(k << 1)] = laz[k];        laz[(k << 1) | 1] = laz[k];        dat[k] = reflect(k);        laz[k] = le;    }
    void thrust(int k) {for (int i = height; i; i--) eval(k >> i);}
    void recalc(int k) {        while (k >>= 1)dat[k] = fvv(reflect((k << 1) | 0), reflect((k << 1) | 1));    }
    void update(int a, int b, T x) {        thrust(a += n);        thrust(b += n - 1);        for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {            if (l & 1) laz[l] = x, l++;            if (r & 1) --r, laz[r] = x;        }        recalc(a);        recalc(b);    }
//    void set_val(int a, T x) {        thrust(a += n);        dat[a] = x;        laz[a] = le;        recalc(a);    }
    T get(int a, int b) {        thrust(a += n);        thrust(b += n - 1);        T vl = ve, vr = ve;        for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {            if (l & 1) vl = fvv(vl, reflect(l++));            if (r & 1) vr = fvv(reflect(--r), vr);        }        return fvv(vl, vr);    }
    T get(int b){return get(0,b);}
    void debu() {        rep(i, min(n, 10ll)) {            cerr << get(i, i + 1) << " ";        }        cerr << "" << endl;    }/*@formatter:on*/
};

void solve() {
    in(N);
    dna2(X, D, N);
    sortp(X, D);
    //回区間でどこまで消えるか
    segumax<int> S(vi(N, -1));
    S.update(N - 1, N, N);
    rer(i, N - 2) {
        int ri = lowerIndex(X, X[i] + D[i]);
        S.update(i, i + 1, max(i + 1, S.get(i, ri)));
    }
    S.debu();
    vm dp(N + 1);
    dp[N] = 1;
    rer(i, N - 1) {
        dp[i] = dp[i + 1] + dp[S.get(i,i+1)];
    }
    deb(dp);
    out(dp[0]);
}

