segment_tree<llong> st;

llong solve(llong idx) {
  if (idx == N) return 1;
  if (dp[idx] != -1) return dp[idx];

  llong ret = (solve(idx + 1) + solve(bombed[idx] + 1)) % mod;

  return dp[idx] = ret;
}

