    F f; T default_value;
  public:
    SegTree(int n, T default_value, F f) : default_value(default_value), f(f) {
      size = 1;
      while (size < n) size *= 2;
      v.resize(2 * size - 1, default_value);
    }
    void update(int index, T val) {
      index = index + size - 1;
      v[index] = val;
      while (index > 0) {
        index = (index - 1) / 2;
        v[index] = f(v[2 * index + 1], v[2 * index + 2]);
      }
    }
    T query(int l, int r) { return query(l, r, 0, size, 0); }
    T query(int l, int r, int cur_l, int cur_r, int index) {
      // [l, r)に対するクエリ
      if (cur_r <= l || r <= cur_l) return default_value;
      if (l <= cur_l && cur_r <= r) return v[index];

      int mid = (cur_l + cur_r) / 2;
      return f(query(l, r, cur_l, mid, 2 * index + 1), query(l, r, mid, cur_r, 2 * index + 2));
    }
};


int main() {

  int N; cin >> N;

  vector<pii> robot(N+1);
  rep(i, N) {
    cin >> robot[i].first >> robot[i].second;
  }
  robot[N].first = 2e9+1;
  robot[N].second = 1;
  all(sort, robot);

  vector<mint> dp(N+1, 0); // dp[i] = ロボットiのスイッチを入れたときの場合の数
  vector<mint> dp2(N+1, 0); // dp[i] = ロボットiのスイッチを入れないときの場合の数
  vector<int> right(N+1, 0); // right[i] = ロボットiのスイッチを入れたときに動くもっとも右にある要素のインデックス

  SegTree<int> T(N, 0, [](int a, int b){return max(a, b);});

  dp[N] = 1;
  dp2[N] = 0;
  right[N] = 0;
  rrep(i, N-1) {
    // robot[i].first + robot[i].second以上になるものを探したい
    auto it = all(lower_bound, robot, pii(robot[i].first + robot[i].second, 0));
    int j = it - robot.begin(); // iが接触しないロボットのうち左端のもの
    if (j == i+1) {
      right[i] = i;
      dp[i] = dp[i+1] + dp2[i+1];
    } else {
      right[i] = T.query(i+1, j);
      dp[i] = dp[right[i]+1] + dp2[right[i]+1];
    }
    T.update(i, right[i]);

    dp2[i] = dp[i+1] + dp2[i+1];
  }
  cout << dp[0] + dp2[0] << endl;

  return 0;
}

#include <bits/stdc++.h>
#include <boost/dynamic_bitset.hpp>
using namespace std;
using u32 = uint32_t;
using s64 = int64_t;
using u64 = uint64_t;

void gen_tree(vector<vector<u32>>& tree,
	boost::dynamic_bitset<>& regs,
	const vector<pair<s64, s64>>& xd,
	const u32 v) {

	for(u32 i=v+1; i<regs.size(); i++) {
		if(xd[i].first < xd[v].second) break;

		if(~regs[i]) {
			regs[i] = 1;
			tree[v].push_back(i);
			gen_tree(tree, regs, xd, i);
		}
	}
}

int main() {
	u32 N;
	cin >> N;

	vector<pair<s64, s64>> XD(N);

	for(u32 i=0; i<N; i++) {
		s64 X, D;
		cin >> X >> D;
		XD[i] = make_pair(X, X+D);
	}

	sort(XD.begin(), XD.end());

	vector<vector<u32>> tree(N, vector<u32>());
	boost::dynamic_bitset<> regs(N); // 0;root, 1:not root

	for(u32 i=0; i<N; i++) {
		if(~regs[i]) {
			gen_tree(tree, regs, XD, i);
			// for(u32 s=0; s<tree[i].size(); s++) cout << tree[i][s] << " ";
			// cout << endl;
		}
	}

	vector<u64> dp(N);
	u64 ans = 1;
	u64 mod = 998244353;

	for(u32 i=N; i>0; i--) {
		u32 c = i - 1;
		dp[c] = 1;

		for(u32 s=0; s<tree[c].size(); s++) {
			dp[c] = (dp[c] * dp[tree[c][s]]) % mod;
		}

		dp[c]++; // 起動した場合

		if(~regs[c]) { // root 
			ans = (ans * dp[c]) % mod;
		}
	}

	cout << ans;
	return 0;
}

