template<typename T>
struct ST{
  using F = function<T(T, T)>;
  int size_ = 1, n_; vector<T> node; T initial; F query_, update_;
  ST(int n, T initial, F query, F update){
    while(size_ < n) size_ *= 2;
    node.resize(2*size_-1, initial);
    n_ = n;
    query_ = query;
    update_ = update;
  }
  void printnodes(){
    rep(i, node.size()) cout << node[i] << endl;
    return;
  }
  void build(vector<T> v){
    rep(i, v.size()) node[i+size_-1] = v[i];
    rrep(i, size_ - 1) node[i] = query_(node[2*i+1], node[2*i+2]);
    return;
  }
  void update(int j, T x){
    j += size_-1;
    node[j] = update_(node[j], x);
    while(j > 0){
      j = (j-1)/2;
      node[j] = query_(node[2*j+1], node[2*j+2]);
    }
    return;
  }
  T query(int l, int r){
    l += size_-1;
    r += size_-1;
    T ql = node[l], qr = node[r];
    while(l < r-1){
      if(l % 2 == 1) ql = query_(ql, node[l+1]);
      if(r % 2 == 0) qr = query_(node[r-1], qr);
      l = (l-1)/2;
      r = (r-1)/2;
    }
    return query_(ql, qr);
  }
  T entire(){
    return node[0];
  }
  int lb(T x){
    int tmp = 0;
    while(tmp < size_-1){
      if(x <= node[tmp*2+1]) tmp = tmp*2+1;
      else tmp = tmp*2+2;
    }
    if(node[tmp] < x) ++tmp;
    return min(tmp+1-size_, n_);
  }
  int ub(T x){
    int tmp = 0;
    while(tmp < size_-1){
      if(x < node[tmp*2+1]) tmp = tmp*2+1;
      else tmp = tmp*2+2;
    }
    if(node[tmp] <= x) ++tmp;
    return min(tmp+1-size_, n_);
  }
};

int main() {
  lint n;
  cin >> n;
  vector<pli> v(n); vector<lint> x(n), r(n), s(n+1); s[n] = 1;
  rep(i, n) cin >> v[i].fi >> v[i].se;
  auto f = [](lint a, lint b){return max(a, b);};
  ST<lint> st(n, -1*1e9, f, f);
  sort(v.begin(), v.end());
  rep(i, n) x[i] = v[i].fi;
  rrep(i, n) st.update(i, v[i].fi+v[i].se);
  rrep(i, n){
      int j = lower_bound(x.begin(), x.end(), v[i].fi+v[i].se)-x.begin()-1;
      r[i] = st.query(i, min(j, (int)n-1));
  }
  rep(i, n) r[i] = lower_bound(x.begin(), x.end(), r[i]) - x.begin();
  rep(i, n){
    s[n-i-1] = s[n-i] + s[r[n-i-1]];
    s[n-i-1] %= mod2;
  }
  cout << s[0] << endl;
  return 0;
}

