int dp[200001];
void update(int x,int st,int ed,int pos,int ind)
{
	if(st==ed)
	{
		t[x]=ind;
		return;
	}
	int mid=(st+ed)/2;
	if(pos<=mid)update(x*2,st,mid,pos,ind);
	else update(x*2+1,mid+1,ed,pos,ind);
	t[x]=max(t[x*2],t[x*2+1]);
}
int query(int x,int st,int ed,int l,int r)
{
	if(st>=l&&ed<=r) return t[x];
	if(st>r||ed<l) return 0;
	int mid=(st+ed)/2;
	return max(query(x*2,st,mid,l,r),query(x*2+1,mid+1,ed,l,r));
}

