class SegmentTree{
private:
	static const int siz = 262144;
	int dat[siz << 1];
public:
	inline int size(){ return siz; }
	inline void init(){ memset(dat, -1, sizeof(dat)); return; }
	inline void update(int x, int l, int r, int y, int k){
		if(l == r){
			dat[x] = k;
			return;
		}
		int md = l + r >> 1;
		if(y <= md)
			update(x << 1, l, md, y, k);
		else
			update(x << 1 | 1, md + 1, r, y, k);
		dat[x] = max(dat[x << 1], dat[x << 1 | 1]);
		return;
	}
	inline int query(int x, int l, int r, int s, int t){
		if(l >= s && r <= t){
			return dat[x];
		}
		int md = l + r >> 1;
		if(t <= md)
			return query(x << 1, l, md, s, t);
		else if(s > md)
			return query(x << 1 | 1, md + 1, r, s, t);
		return max(query(x << 1, l, md, s, t), query(x << 1 | 1, md + 1, r, s, t));
	}
}seg;

