template<typename T = long long>
class SegmentTree {
public:
    std::vector<T> ary;
    int n;
    const T default_value = -1 * (1 << 30);
    SegmentTree(int n) {
        this->n = 1;
        while (this->n < n) this->n *= 2;
        ary.resize(this->n * 2 - 1, default_value); // sum -> 0, min -> INF, 0?
    }
    T ope(T l, T r) {
        return std::max(l, r);
    }
    void update(int k, T d) {
        k += n - 1;
        ary[k] = d;
        while (k > 0) {
            k = (k - 1) / 2;
            ary[k] = ope(ary[2 * k + 1], ary[2 * k + 2]);
        }
    }
    T query(int a, int b) {
        return query(a, b, 0, n, 0);
    }
    T query(int a, int b, int l, int r, int i) {
        if (a <= l && b >= r) return ary[i];
        //if (a >= r || b <= l) return 0; // sum
        if (a >= r || b <= l) return default_value; // min
        int m = (l + r) / 2;
        T vl = query(a, b, l, m, 2 * i + 1);
        T vr = query(a, b, m, r, 2 * i + 2);
        return ope(vl, vr);
    }
};

void solve() {
    int n;
    cin >> n;

    vector<S> ss(n);
    REP(i,0,n) cin >> ss[i].x >> ss[i].d;
    sort(all(ss), [](auto &l, auto &r) {return l.x < r.x;});

    SegmentTree<int> sg(n);
    REP(i,0,n) sg.update(i,ss[i].x + ss[i].d);

    vector<mint> dp(n), ru(n+1);
    ru[n] = 1;
    RREP(i,0,n) {
        S tmps;
        tmps.x = ss[i].x + ss[i].d - 1;

        int prevd = -1, d;
        auto it = upper_bound(all(ss), tmps, [](auto &l, auto &r) {return l.x < r.x;});
        prevd = distance(ss.begin(), it);
        //if (i == 0) dump(prevd);
        for (;;) {
            int mv = sg.query(i, prevd);
            //if (i == 0) dump(mv);
            tmps.x = mv - 1;        
            auto it = upper_bound(all(ss), tmps, [](auto &l, auto &r) {return l.x < r.x;});
            d = distance(ss.begin(), it);
            if (d == prevd) break;
            prevd = d;
        }
        sg.update(i, ss[prevd].x - 1);

        dp[i] = ru[d];
        ru[i] = ru[i+1] + dp[i];
    }
    cout << ru[0]() << endl;

    return;

    REP(i,0,n) {
        cout << dp[i]() << " ";
    }
    cout << endl;
    REP(i,0,n+1) {
        cout << ru[i]() << " ";
    }
    cout << endl;
}

signed main() {
    solve();

    return 0;
}

