//1点更新,区間最大
class SegmentTree {
public:
    SegmentTree(int64_t n, int64_t value) {
        n_ = (int64_t)pow(2, ceil(log2(n)));
        nodes_.resize(2 * n_ - 1, value);
    }
    void update(int64_t x, int64_t v) {
        nodes_[x + n_ - 1] = v;
        for (int64_t i = (x + n_ - 2) / 2; ; i = (i - 1) / 2) {
            nodes_[i] = max(nodes_[2 * i + 1], nodes_[2 * i + 2]);
            if (i == 0) {
                break;
            }
        }
    }

    int64_t getMax(int64_t a, int64_t b, int64_t k = 0, int64_t l = 0, int64_t r = -1) {
        if (r < 0) {
            r = n_;
        }
        if (r <= a || b <= l) {
            return INT_MIN;
        }
        if (a <= l && r <= b) {
            return nodes_[k];
        }
        int64_t lv = getMax(a, b, 2 * k + 1, l, (l + r) / 2);
        int64_t rv = getMax(a, b, 2 * k + 2, (l + r) / 2, r);
        return max(lv, rv);
    }

private:
    //2のべき乗
    int64_t n_;
    vector<int64_t> nodes_;
};

struct Robot {
    int64_t X, D;
};

int main() {
    int64_t N;
    cin >> N;
    vector<Robot> robots(N);
    for (Robot& r : robots) {
        cin >> r.X >> r.D;
    }

    sort(robots.begin(), robots.end(), [&](Robot& lhs, Robot& rhs){
        return (lhs.X == rhs.X ? lhs.D < rhs.D : lhs.X < rhs.X);
    });

    //remove_index[i] := iを起動した場合にどこまで消えるか
    vector<int64_t> remove_index(N);
    SegmentTree st(N, 0);
    iota(remove_index.begin(), remove_index.end(), 0);
    for (int64_t i = 0; i < N; i++) {
        st.update(i, i);
    }
    for (int64_t i = N - 2; i >= 0; i--) {
        auto itr = lower_bound(robots.begin(), robots.end(), robots[i].X + robots[i].D, [&](Robot& lhs, int64_t x){
            return lhs.X < x;
        });
        int64_t index = itr - robots.begin();
        remove_index[i] = remove_index[st.getMax(0, index)];
        st.update(i, remove_index[i]);
    }

    constexpr int64_t MOD = 998244353;
    vector<int64_t> dp(N + 1, 0);
    dp[0] = 1;
    for (int64_t i = 0; i < N; i++) {
        (dp[i + 1] += dp[i]) %= MOD;
        (dp[remove_index[i] + 1] += dp[i]) %= MOD;
    }

    cout << dp[N] << endl;
}

