const ll mod=998344353;

int main(){
    ll n;
    cin >> n;
    priority_queue<PLL> que;
    rp(i,n){
        ll x,d;
        cin >> x >> d;
        que.push(mp(x,d));
    }
    stack<PLL> scts;
    ll ans=1;
    scts.push(mp(INF,1ll));
    while(!que.empty()){
        PLL p=que.top(); que.pop();
        if(scts.top().first>=p.first+p.second){
            scts.push(mp(p.first,2ll));
            continue;
        }
        ll integrate=1ll;
        while(scts.top().first<p.first+p.second){
            PLL pp=scts.top(); scts.pop();
            integrate *= pp.second;
            integrate %= mod;
        }
        integrate += 1ll;
        scts.push(mp(p.first,integrate));
    }
    while(!scts.empty()){
        ans *= scts.top().second;
        ans %= mod;
        scts.pop();
    }
    print(ans);
    return 0;
}

