    vi d(n);
    for(int i=0;i<n;i++)
        d[i]=p[i].first;
    int dp[n+1];
    dp[n]=1;
    int ind[n+1];
    for(int i=0;i<n;i++)
        update(0,0,n-1,i,i);
    for(int i=n-1;i>=0;i--)
    {
        int dx=p[i].first+p[i].second;
