vector<vector<ll>> tree; // adjacency list of tree. It may not be connected. It may have multiple connected components.

mint dfs(int v) {
  mint res(1);
  for (int nv : tree[v]) {
    res *= dfs(nv);
  }
  return res + 1; // erase .. 1, not erase .. res
}

