//const ll mod=1e9+7;
const ll mod=998244353;
const ll inf=5e15;

struct query{
  ll type;//0=empty, 1=add-sum ,2=set-max
  ll value;
  query(ll a=0,ll b=0):type(a),value(b) {}
};

ll INF=(1LL<<60);

struct segtree{
  ll SIZE;
  vector<query> s;
  vector<ll> t;// sum-add
  vector<ll> u;// max-set

  segtree(ll n=1){
    SIZE=1;
    while(SIZE<n)SIZE*=2;
    s.clear();
    t.clear();
    u.clear();
    s.resize(SIZE*2, query());
    t.resize(SIZE*2, 0);
    u.resize(SIZE*2, 0);
  }

  void func(ll k,ll l,ll r,query q){
    if(q.type==1){
      if(s[k].type==0)s[k]=q;
      else s[k].value+=q.value;
      t[k]+=q.value*(r-l);
      u[k]+=q.value;
    }
    if(q.type==2){
      s[k]=q;
      t[k]=q.value*(r-l);
      u[k]=q.value;
    }
  }

  void compute(ll k,ll l,ll r){
    query q=s[k];
    s[k]=query();
    if(q.type==0||r-l==1)return;
    ll m=(l+r)/2;
    func(k*2+1,l,m,q);
    func(k*2+2,m,r,q);
  }

  void Update(ll a,ll b,query x,ll k,ll l,ll r){
    if(b<=l || r<=a)return;
    compute(k,l,r);
    if(a<=l && r<=b){
      func(k,l,r,x);
    }else{
      ll m=(l+r)/2;
      Update(a,b,x,k*2+1,l,m);
      Update(a,b,x,k*2+2,m,r);
      t[k]=t[k*2+1]+t[k*2+2];
      u[k]=max(u[k*2+1],u[k*2+2]);
    }
  }

  ll Dfs(ll type,ll a,ll b,ll k,ll l,ll r){
    if(b<=l || r<=a){
      if(type==1)return 0; //add
      if(type==2)return -inf; // max
    }
    compute(k,l,r);
    if(a<=l && r<=b){
      if(type==1)return t[k];
      if(type==2)return u[k];
    }else{
      ll m=(l+r)/2;
      ll lv=Dfs(type,a,b,k*2+1,l,m);
      ll rv=Dfs(type,a,b,k*2+2,m,r);
      if(type==1)return lv+rv; // add
      if(type==2)return max(lv,rv); // max
    }
  }

  void Add(ll a,ll b,ll x){
    Update(a,b,query(1,x), 0,0,SIZE);
  }
  void Set(ll a,ll b,ll x){
    Update(a,b,query(2,x), 0,0,SIZE);
  }
  ll Getsum(ll a,ll b){
    return Dfs(1,a,b, 0,0,SIZE);
  }

  ll Getmax(ll a,ll b){
    return Dfs(2,a,b, 0,0,SIZE);
  }

};

int main() {
  ll n;
  cin >> n;
  vector<pll> a(n);
  for(ll i=0;i<n;i++) {
    ll x,d;
    cin >> x >> d;
    a[i]={x,d};
  }
  sort(a.begin(),a.end());
  segtree d(n+10);
  d.Set(0,n+1,-inf);
  vec dp(n+1);
  dp[0]=1;
  for(ll i=0;i<n;i++) {
    ll x=a[n-i-1].first+a[n-i-1].second;
    ll it=upper_bound(a.begin(),a.end(),pll(x,0))-a.begin();
    d.Set(n-i-1,n-i,it);
    d.Set(n-i-1,n-i,d.Getmax(n-i-1,it));
    ll id=n-d.Getmax(n-i-1,n-i);
    (dp[i+1]=dp[i]+dp[id])%=mod;
  }
  cout << dp[n] << endl;
}

#include<bits/stdc++.h>
template <class Seg, class SegPtr>
struct segment_tree_entry;

template <class Seg, class SegPtr, class Pointer, class Reference>
struct segment_tree_iterator;

template <typename Value, typename BinaryOp>
class segment_tree {
public:
    using value_type = Value;
    using this_type = segment_tree<Value, BinaryOp>;
    using entry_type = segment_tree_entry<this_type, this_type*>;
    using const_entry_type = segment_tree_entry<this_type, this_type const*>;
    using iterator = segment_tree_iterator<this_type, this_type*, value_type*, value_type&>;
    using const_iterator = segment_tree_iterator<this_type, this_type const*, value_type const*, value_type const&>;

friend class segment_tree_entry<this_type, this_type*>;
friend class segment_tree_entry<this_type, this_type const*>;

private:
    int                                    sz, n, N;
    BinaryOp                         op;
    Value                                id;
    std::vector< Value > table;

    auto& op_assign(Value& x, Value y) const
        { return x = op(x, y); }
    void merge(int u)
        { table.at(u) = op(table.at(2 * u), table.at(2 * u + 1)); }

public:
    segment_tree(int sz, BinaryOp op, Value id):
        sz(sz), n(std::pow(2, int(std::log2(2*sz-1)))), N(n * 2), op(op), id(id), table (N, id) {}

    iterator begin()
        { return iterator(this, 0); }

    iterator end()
        { return iterator(this, sz); }

    const_iterator begin() const
        { return const_iterator(this, 0); }

    const_iterator end() const
        { return const_iterator(this, sz); }

    auto at(std::size_t i)
        { return entry_type(this, i); }

    auto at(std::size_t i) const
        { return table.at(n + i); }

    auto& lazy_at(std::size_t i)
        { return table.at(n + i); }

    auto& lazy_at(std::size_t i) const
        { return table.at(n + i); }

    auto collect() const {
        auto ret = std::vector<Value>(sz);
        for (auto i = 0; i < sz; i++)
            { ret.at(i) = at(i); }
        return ret;
    }

    auto query(int l, int r) const {
        auto const dfs = [&](auto&& f, int l, int r, int k, int L, int R) -> Value {
            return l <= L && R <= r ? table.at(k)
                : R <= l || r <= L ? id
                : op(f(f, l, r, 2*k, L, (L+R)/2), f(f, l, r, 2*k+1, (L+R)/2, R));
        };
        return dfs(dfs, l, r, 1, 0, n);
    }

    void build()
        { for (auto i = n - 1; i > 0; i--) merge(i); }
};

template <class Seg, class SegPtr>
class segment_tree_entry {
    using value_type = typename Seg::value_type;
    SegPtr seg;
    std::size_t i;

    auto& get() {
        return seg->table.at(seg->n+i);
    }

    void build_oneline() {
        for (int j=(i+seg->n)/2; j>0; j/=2) {
            seg->merge(j);
        }
    }

public:
    segment_tree_entry(SegPtr seg, std::size_t i) : seg(seg), i(i) {}

    operator value_type() {
        return seg->table.at(seg->n + i);
    }
    void operator=(value_type x) {
        get() = x;
        build_oneline();
    }
    void operator++() {
        get()++;
        build_oneline();
    }
    void operator--() {
        get()--;
        build_oneline();
    }
    void operator+=(value_type x) {
        get() += x;
        build_oneline();
    }
    void operator-=(value_type x) {
        get() -= x;
        build_oneline();
    }
    void operator*=(value_type x) {
        get() *= x;
        build_oneline();
    }
    void operator/=(value_type x) {
        get() /= x;
        build_oneline();
    }
};

template <class Seg, class SegPtr, class Pointer, class Reference>
class segment_tree_iterator {
    using this_type = segment_tree_iterator<Seg, SegPtr, Pointer, Reference>;
    using value_type = typename Seg::value_type;
    using pointer = Pointer;
    using reference = Reference;

    template <class Seg_, class SegPtr_, class Pointer_, class Reference_>
    friend bool operator!=(segment_tree_iterator<Seg_, SegPtr_, Pointer_, Reference_>, segment_tree_iterator<Seg_, SegPtr_, Pointer_, Reference_>);

    SegPtr seg;
    std::size_t i;

public:
    segment_tree_iterator(SegPtr seg, std::size_t i) : seg(seg), i(i) {}

    this_type& operator++(){ i++; return *this; }
    this_type    operator++(int){ auto old = *this; ++i; return old; }
    pointer operator->(){ return &seg->at(i); }
    value_type operator*(){ return seg->at(i); }
};

template <class Seg, class SegPtr, class Pointer, class Reference>
bool operator!=(segment_tree_iterator<Seg, SegPtr, Pointer, Reference> a, segment_tree_iterator<Seg, SegPtr, Pointer, Reference> b) {
    return a.i != b.i;
}

template<typename Value, typename BinaryOp>
auto make_segment_tree(int sz, BinaryOp const& op, Value id)
    { return segment_tree<Value, BinaryOp>(sz, op, id); }

template <class T>
T inverse(T a, T m) {
    T u=0,v=1;
    while(a!=0){
        T t=m/a;
        m-=t*a;std::swap(a,m);
        u-=t*v;std::swap(u,v);
    }
    assert(m==1);
    return u;
}
template <class T>
class modular {
    public:
        int value;
        constexpr modular() = default;
        constexpr modular(const modular&) = default;
        constexpr modular(modular&&) = default;
        modular& operator=(const modular&) = default;
        modular& operator=(modular&&) = default;
        template <class U>modular (const U& x) {value = normalize(x);}

        template <class U>
        static int normalize(const U& x) {
            int v=static_cast<int>(-mod()<=x&&x<mod()?x:x%mod());
            if(v<0)v+=mod();
            return v;
        }

        template <class U> explicit operator U()const{return static_cast<U>(value);}
        constexpr static auto mod(){return T::value;}

        auto&operator+=(const modular&other) {if((value+=other.value)>=mod())value-=mod();return *this;}
        auto&operator-=(const modular& other){if ((value-=other.value)<0)value+=mod();return *this;}
        template <class U>auto& operator+=(const U& other){return*this+=modular(other);}
        template <class U>auto& operator-=(const U& other){return*this-=modular(other);}
        auto operator-()const{return modular(-value);}
        auto&operator++(){return*this+=1;}
        auto&operator--(){return*this-=1;}
        auto operator++(int){modular result(*this);operator++();return result;}
        auto operator--(int){modular result(*this);operator--();return result;}

        template <class U = T>
        auto&operator*=(const modular&rhs){value=normalize(static_cast<std::int64_t>(value)*static_cast<std::int64_t>(rhs.value));return *this;}
        auto&operator/=(const modular&rhs){return*this*=modular(inverse(rhs.value, mod()));}
};
