const int N = 200'009;

int t[4 * N];

void put(int x, int l, int r, int p, int v) {
  if (l == r) {
    t[x] = v;
    return;
  }
  int s = (l + r) / 2;
  if (p <= s) {
    put(2 * x, l, s, p, v);
  } else {
    put(2 * x + 1, s + 1, r, p, v);
  }
  t[x] = max(t[2 * x], t[2 * x + 1]);
}

int get(int x, int l, int r, int ql, int qr) {
  if (l > qr || r < ql) {
    return -1;
  }
  if (l >= ql && r <= qr) {
    return t[x];
  }
  int s = (l + r) / 2;
  return max(get(2 * x, l, s, ql, qr), get(2 * x + 1, s + 1, r, ql, qr));
}

