  });
  const int mod = 998244353;
  f[n] = 1;
  for (int i = n - 1; i >= 0; --i) {
    int l = i, r = n;
    while (r - l > 1) {
      int s = (l + r) / 2;
      if (x[o[i]] + d[o[i]] - 1 >= x[o[s]]) {
