    int n;
    cin >> n;
    vector<pair<long long, long long>> pairs(n);
    for (int i = 0; i < n; i++)
    {
        cin >> pairs[i].first >> pairs[i].second;
    }
    sort(pairs.begin(), pairs.end());
    vector<long long> dp(n + 1), next(n);
    stack<pair<long long, long long>> s;
    stack<long long> idx;
    for (int i = 0; i < n; i++)
    {
        while (!s.empty())
        {
            pair<long long, long long> curr = s.top();
            if (curr.first + curr.second > pairs[i].first)
            {
                break;
            }
            next[idx.top()] = i;
            idx.pop();
            s.pop();
        }
        s.push(pairs[i]);
        idx.push(i);
    }
    while (!s.empty())
    {
        pair<long long, long long> curr = s.top();
        next[idx.top()] = n;
        idx.pop();
        s.pop();
    }
    dp[n] = 1;
    for (int i = n - 1; i >= 0; i--)
    {
        dp[i] = dp[i + 1] + dp[next[i]];
    }
    cout << dp[0] << '\n';
    return 0;
}

