bool cmp(pair<long long, long long>a, pair<long long, long long>b){
	if (a.first<b.first) return true;
	if (a.first>b.first) return false;
	return a.second<b.second;
}

void build(long long l, long long r, long long v){
	if (l==r) tree[v]=farthest[l];
	else{
		long long mid=(l+r)/2;
		build(l,mid,v*2);
		build(mid+1,r,v*2+1);
		tree[v]=max(tree[v*2],tree[v*2+1]);
	}
}

long long query(long long l, long long r, long long lb, long long rb, long long v){
	if (r<lb || l>rb) return -1e9;
	if (l>=lb && r<=rb) return tree[v];
	long long mid=(l+r)/2;
	return max(query(l,mid,lb,rb,v*2),query(mid+1,r,lb,rb,v*2+1));
}

void update(long long l, long long r, long long v, long long target){
	if (l==r) tree[v]=farthest[l];
	else{
		long long mid=(l+r)/2;
		if (target<=mid) update(l,mid,v*2,target);
		else update(mid+1,r,v*2+1,target);
		tree[v]=max(tree[v*2],tree[v*2+1]);
	} 
}

void init(){
	for (int i=0;i<n;i++) farthest[i]=i;
	build(0,n-1,1);
}

