struct SegT
{
	int sum[M*4],se[M*4];
	void pull(int o,int ls,int rs)
	{
		sum[o]=add(sum[ls],sum[rs]);
	}
	void push(int o,int ls,int rs)
	{
		if(se[o])
		{
			se[ls]=se[rs]=1;
			sum[ls]=sum[rs]=0;
			se[o]=0;
		}
	}
	int L,R;
	void upd_set(int o,int l,int r)
	{
		if(L<=l&&r<=R)
		{
			se[o]=1;
			sum[o]=0;
			return;
		}
		int mid=(l+r)>>1;
		int ls=o+1,rs=o+((mid-l+1)<<1);
		push(o,ls,rs);
		if(L<=mid) upd_set(ls,l,mid);
		if(mid<R) upd_set(rs,mid+1,r);
		pull(o,ls,rs);
	}
	int V;
	void upd_add(int o,int l,int r)
	{
		if(l==r)
		{
			sum[o]=V;
			return;
		}
		int mid=(l+r)>>1;
		int ls=o+1,rs=o+((mid-l+1)<<1);
		push(o,ls,rs);
		if(L<=mid) upd_add(ls,l,mid);
		else upd_add(rs,mid+1,r);
		pull(o,ls,rs);
	}
	int query(int o,int l,int r)
	{
		if(L<=l&&r<=R)
			return sum[o];
		int mid=(l+r)>>1;
		int ls=o+1,rs=o+((mid-l+1)<<1);
		push(o,ls,rs);
		int ans=0;
		if(L<=mid) addv(ans,query(ls,l,mid));
		if(mid<R) addv(ans,query(rs,mid+1,r));
		pull(o,ls,rs);
		return ans;
	}
}segt;

