int count(int index, int triggered = -1000000001) 
{
    if (index == N-1) {
        if (triggered <= XD[index].first) {
            return 2;  //! { N-1 }, {}
        } else {
            return 1;  //! {}
        }
    } else {
        pair<int,int> key = {index, triggered};
        int ret = dp[key];
        if (!ret) {
            if (triggered <= XD[index].first) {
                ret = (count(index+1, triggered) /*this one remains*/ + count(index+1, max(triggered, XD[index].first+XD[index].second)) /*this one goes*/) % MOD;
