using namespace std;

template <class T>
class SegmentTree {
 private:
  using Eval = std::function<T(T, T)>;
  using Update = std::function<T(T, T)>;

  std::vector<T> seg_;
  int sz_;
  T init_;
  Eval eval_;
  Update update_;

  T query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
      return init_;
    }
    if (a <= l && r <= b) {
      return seg_[k];
    } else {
      return eval_(query(a, b, 2 * k + 1, l, (l + r) / 2),
                   query(a, b, 2 * k + 2, (l + r) / 2, r));
    }
  }

 public:
  SegmentTree(int sz, const T& init, const Eval& eval,
              const Update& update = [](T s, T v) {return v;})
      : init_(init), eval_(eval), update_(update) {
    sz_ = 1;
    while (sz_ < sz) {
      sz_ <<= 1;
    }
    seg_.assign(2 * sz_ - 1, init);
  }

  void set(int id, const T& v) {
    seg_[id + sz_ - 1] = update_(seg_[id + sz_ - 1], v);
  }

  void build() {
    for (int id = sz_ - 2; id >= 0; --id) {
      seg_[id] = eval_(seg_[2 * id + 1], seg_[2 * id + 2]);
    }
  }

  void update(int id, const T& v) {
    id += sz_ - 1;
    seg_[id] = update_(seg_[id], v);
    while (id > 0) {
      id = (id - 1) / 2;
      seg_[id] = eval_(seg_[id * 2 + 1], seg_[id * 2 + 2]);
    }
  }

  T find(int a, int b) {
    return query(a, b, 0, 0, sz_);
  }

  T at(int id) {
    return seg_[id + sz_ - 1];
  }
};

