    auto rd = r[i].first + r[i].second;
    auto next = i + 1;
    while (next < n && r[next].first < rd) {
      next++;
    }
    if (next == i + 1) {
      st.update(i, i);
    } else {
      st.update(i, st.find(i + 1, next));
    }
  }

  constexpr uint64_t c = 998244353;
  int dp[200001] = {};
  dp[n] = 1;
  for (int i = n - 1; i >= 0; --i) {
