int ar[2000000];

void up(int r, int l1, int l2, int q, int v){
	if(q<l1||q>l2)return;
	if(l1==l2){
		ar[r] = v;
		return;
	}
	int m = (l1+l2)/2;
	up(r<<1,l1,m,q,v);
	up((r<<1)+1,m+1,l2,q,v);
	ar[r] = max(ar[r<<1],ar[(r<<1)+1]);
}

int qu(int r, int l1, int l2, int q1, int q2){
	if(q1>l2||q2<l1)return -1;
	if(q1<=l1&&q2>=l2)return ar[r];
	int m = (l1+l2)/2;
	return max(qu(r<<1,l1,m,q1,q2), qu((r<<1)+1,m+1,l2,q1,q2));
}

