struct segtree{
    int n;
    vector<int> d;
    function<int(int, int)> f;
    segtree(int mx, int mode){
        n = 1;
        while(n < mx) n <<= 1;
        d = vector<int>(n << 1);
        switch (mode){
            case 0:
                f = [](int a, int b){return a + b;};
                break;
            case 1:
                f = [](int a, int b){return (a >= b? a : b);};
                break;
            case 2:
                f = [](int a, int b){return (a <= b? a : b);};
                break;
        }
    }
    int query(int a, int b, int i = 1, int l = 0, int r = -1){
        if(r == -1) r = n;
        if(a <= l && r <= b) return d[i];
        int res = 0;
        int c = (l + r) >> 1;
        if(a < c) res = f(res, query(a, b, i << 1, l, c));
        if(c < b) res = f(res, query(a, b, i << 1 | 1, c, r));
        return res;
    }
    void update(int i, int x){
        i += n;
        d[i] = x;
        while(i){
            i >>= 1;
            d[i] = f(d[2 * i], d[2 * i + 1]);
        }
    }
};

