    for(int i = 0; i < n; i++){
        // 選ぶ場合
        int nex = st.query(i, i+1);
        dp[nex] = dp[nex] + dp[i];
        // 選ばない場合
        dp[i+1] = dp[i+1] + dp[i];
    }
