template <typename F>
struct FixPoint : F{
  explicit constexpr FixPoint(F &&f) noexcept : F(std::forward<F>(f)){}

  template <typename... Args>
  constexpr decltype(auto) operator()(Args &&... args) const {
    return F::operator()(*this, std::forward<Args>(args)...);
  }
};

template <typename F>
static inline constexpr decltype(auto) make_fix_point(F &&f){
  return FixPoint<F>(std::forward<F>(f));
}




int main(){
  int N;

  while(cin >> N){
    vector<i64> X(N), D(N);
    REP(i,N) cin >> X[i] >> D[i];

    sort_all::run([&](int i, int j){return X[i] < X[j];}, N, X, D);

    DualSegmentTree<UpdateMonoid<i64>> seg(N);
    seg.init(-1);


    REP(i,N){
      int r = lower_bound(ALL(X), X[i] + D[i]) - X.begin();

      seg.update(i+1, r, i);
    }


    Graph<int> g(N);
    REP(i,N){
      int p = *seg.get(i);

      if(p != -1){
        add_edge(g, p, i, 1);
      }
    }

    vector<bool> visit(N);

    auto dfs =
      make_fix_point([&](auto &&dfs, int cur) -> mint {
                       visit[cur] = true;

                       mint ret = 1;

                       for(auto &e : g[cur]){
                         ret *= dfs(e.to);
                       }

                       ret += 1;

                       return ret;
                     });


    mint ans = 1;

    REP(i,N){
      if(not visit[i]){
        ans *= dfs(i);
      }
    }


    puts_all(ans);
  }



  return 0;
}

