    a[i]=l[i];


    function<void(ll,ll,ll)>build_sgt=[&](ll ss,ll se,ll si){
        if(ss==se){
            st[si]=a[ss];
            return;
        }

        ll mid=(ss+se)/2;
        build_sgt(ss,mid,2*si+1);
        build_sgt(mid+1,se,2*si+2);
        st[si]=max(st[2*si+1],st[2*si+2]);
    };

    function<void(ll,ll,ll,ll,ll)>update=[&](ll ss,ll se,ll si,ll id,ll val){
      if(ss==se&&ss==id){
          st[si]=val;
          return;
      }

      if(id>se||id<ss)
      return;

      ll mid=(ss+se)/2;

      update(ss,mid,2*si+1,id,val);
      update(mid+1,se,2*si+2,id,val);

      st[si]=max(st[2*si+1],st[2*si+2]);
    };


    function<ll(ll,ll,ll,ll,ll)>get_min=[&](ll ss,ll se,ll si,ll l,ll r){

        if(l>r)

        return -INF;


        if(r<ss||se<l)
        return -INF;

        if(ss>=l&&se<=r)
        return st[si];

        ll mid=(ss+se)/2;

        return max(get_min(ss,mid,2*si+1,max(l,ss),min(mid,r)),get_min(mid+1,se,2*si+2,max(l,mid+1),min(se,r)));
    };

    build_sgt(0,n-1,0);
    ll dp[n+1];

    dp[n]=1;

    for(ll i=n-1;i>=0;i--){
        ll res=get_min(0,n-1,0,i,a[i]);
        a[i]=res;
        update(0,n-1,0,i,a[i]); 
    }
    for(ll i=n-1;i>=0;i--)
    dp[i]=(dp[i+1]+dp[a[i]+1])%mod;

