	for(int i=1;i<=n;i++)
	{
		cin>>xz[i].ff>>xz[i].ss;
		xz[i].ss = xz[i].ff + xz[i].ss - 1;
	}	
	sort(xz+1, xz+n+1, [](PLL A, PLL B){ return ((A.ff < B.ff) || ((A.ff == B.ff) && (A.ss < B.ss))); });
	iota(ar, ar+n+1, 0);
	memset(memo, -1, sizeof(memo));
	segtree D;
	D.build(1, 1, n);
	D.update(1, 1, n, n, n);
	for(int i=n;i>0;i--)
	{
		int ft = bs2(i, n);
		ar[i] = D.query(1, 1, n, i, ft);
		D.update(1, 1, n, i, ar[i]);
	}	
	int ans = xd(1, n)%MOD;
	cout<<ans<<"\n";
	return;
}

