ll cal(ll k,ll l,ll r,ll l1,ll r1)
{
	ll m=(l+r)/2;
	if(l1<=l&&r<=r1)
	{
		return tree[k];
	}
	else if(r<l1||r1<l)
	{
		return -10000000000;
	}
	else
	{
		return max(cal(k*2+1,l,m,l1,r1),cal(k*2+2,m+1,r,l1,r1));
	}
}
