    for(int i=0; i<N; i++) st.update(i, i);
    for(int i=N-1; i>=0; i--){
        long long l = i;
        long long r = lower_bound(XD.begin(), XD.end(), make_pair(XD[i].first+XD[i].second, 0LL)) - XD.begin();
        st.update(i, st.query(l, r));
    }
    vector<int> R(N);
    REP(i, N)
        R[i] = st.at(i);

    vector<long long> dp(N+1);
    dp[N] = 1;
    dp[N-1] = 2;
    for(int i=N-2; i>=0; i--){
        dp[i] = (dp[i+1] + dp[R[i]+1]) % MOD;
    }
