void upd(int x, int L, int R, int ind, int v)
{
    //printf("%d\n", x);
    if (L == R && L == ind) {
        tr[x] = v;
        return;
    }
    int mid = L + R >> 1;
    if (ind <= mid)
        upd(x << 1, L, mid, ind, v);
    else
        upd(x << 1 | 1, mid + 1, R, ind, v);
    tr[x] = max(tr[x << 1], tr[x << 1 | 1]);
}
int query(int x, int L, int R, int l, int r)
{
    if (l >= r)
        return l;
    if (l <= L && R <= r)
        return tr[x];
    int mid = L + R >> 1, res = l;
    if (l <= mid)
        res = max(res, query(x << 1, L, mid, l, mid));
    if (r > mid)
        res = max(res, query(x << 1 | 1, mid + 1, R, mid + 1, r));
    return res;
}
