int main() {
    ll n;
    std::cin >> n;
    vec<pll> xd(n);
    for (ll i = 0; i < n; i++) {
        ll x, d;
        std::cin >> x >> d;
        xd[i] = pll(x, d);
    }

    std::sort(ALL(xd));
    vec<ll> init_v(n + 10), xv(n + 1, inf);
    for (ll i = 0; i < n; i++) {
        ll x, d;
        std::tie(x, d) = xd[i];
        init_v[i] = x + d;
        xv[i] = x;
    }

    vec<mint> dp(n + 1, 0);
    dp.back() = 1;
    segtree::SegmentTree<ll> seg(vec<ll>(n + 10, -inf), [](ll a, ll b) { return std::max(a, b); }, -inf);
    seg.update_query(n, n);
    for (ll i = n - 1; 0 <= i; i--) {
        ll x, d;
        std::tie(x, d) = xd[i];
        auto ite = std::lower_bound(ALL(xv), x + d) - 1;
        ll idx = std::distance(xv.begin(), ite);
        if (idx == i) {
            seg.update_query(i, i);
            dp[i] = dp[i + 1] * 2;
        } else {
            ll maxv = seg.get_query(i + 1, idx + 1);
            seg.update_query(i, maxv);
            dp[i] += dp[maxv + 1];
            dp[i] += dp[i + 1];
        }
    }

    std::cout << dp[0].value() << '\n';
    return 0;
}

