#define ALL(v) (v).begin(),(v).end()
typedef long long LL;

const LL MOD = 998244353;

struct segtree{
	vector<int> dat;
	int m;
	segtree(int n){
		for(m = 1; m < n; m *= 2);
		dat.assign(m * 2 - 1, -1);
	}
	void update(int k, int v){
		k += m - 1;
		dat[k] = v;
		while(k){
			k = (k - 1) / 2;
			dat[k] = max(dat[k], v);
		}
	}
	int query(int a, int b){
		return query(a, b, 0, 0, m);
	}
	int query(int a, int b, int k, int l, int r){
		if(b <= l || r <= a){ return -1; }
		if(a <= l && r <= b){ return dat[k]; }
		int md = (l + r) >> 1;
		int x = query(a, b, k * 2 + 1, l, md);
		int y = query(a, b, k * 2 + 2, md, r);
		return max(x, y);
	}
};

int main(){
	int n;
	scanf("%d", &n);
	vector<LL> xs(n), ds(n);
	vector<LL> ps;
	for(int i = 0; i < n; ++i){
		scanf("%lld%lld", &xs[i], &ds[i]);
		ps.push_back(xs[i]);
		ps.push_back(xs[i] + ds[i]);
	}
	ps.push_back(LLONG_MAX);
	sort(ALL(ps));
	ps.erase(unique(ALL(ps)), ps.end());

	int sz = ps.size();
	vector<int> to(sz, -1);
	for(int i = 0; i < n; ++i){
		int k = lower_bound(ALL(ps), xs[i]) - ps.begin();
		int l = lower_bound(ALL(ps), xs[i] + ds[i]) - ps.begin();
		to[k] = l;
	}

	segtree st(sz);
	vector<LL> dp(sz);
	dp[sz - 1] = 1;
	for(int i = sz - 2; i >= 0; --i){
		LL &r = dp[i];
		r = dp[i + 1];
		if(to[i] >= 0){
			int a = st.query(i, to[i]);
			if(a < 0){ a = i + 1; }
			r += dp[a];
			st.update(i, a);
		}
		r %= MOD;
	}
	printf("%lld\n", dp[0]);
}

