template<typename T>
struct SegmentTree{
    using F=function<T(T,T)>;

    int n;
    vector<T> dat;
    F f;
    T ti;

    SegmentTree(int n_ ,F f ,T ti) :f(f),ti(ti){
        n=1;
        while(n<n_) n*=2;
        dat.assign(2*n-1,ti);
    }

    SegmentTree(int n_ ,vector<T> &v ,F f,T ti) :f(f),ti(ti){
        n=1;
        while(n<n_) n*=2;
        dat.assign(2*n-1,ti);

        for(int i=n-1;i-(n-1)<v.size();i++) dat[i]=v[i-(n-1)];

        for(int i=n-2;i>=0;i--) dat[i]=f(dat[i*2+1],dat[i*2+2]);
    }

    void update(int k,T x){
        k+=n-1;
        dat[k]=x;

        while(k){
            k=(k-1)/2;
            dat[k]=f(dat[k*2+1],dat[k*2+2]);
        }
    }

    void set(int k,T x){
        dat[n-1+k]=x;
    }

    void built(){
        for(int i=n-2;i>=0;i--) dat[i]=f(dat[i*2+1],dat[i*2+2]);
    }

    T query_(int a,int b,int k,int l,int r){
        if(r<=a||b<=l) return ti;
        if(a<=l&&r<=b) return dat[k];
        else{
            T vl=query_(a,b,2*k+1,l,(l+r)/2);
            T vr=query_(a,b,2*k+2,(l+r)/2,r);
            return f(vl,vr);
        }
    }

    T query(int a,int b){
        return query_(a,b,0,0,n);
    }

    T get(int k){
        return dat[k+n-1];
    }

};

