void build(int node , int st , int en)
{
    if (st==en)
    {
        seg[node] = {v[st].f+v[st].s-1 , st};
        return;
    }
    int mid = (st+en)/2;
    build(2*node , st , mid);
    build(2*node+1 , mid+1 , en);
    seg[node] = max(seg[2*node] , seg[2*node+1]);
}

pair<ll,ll> query(int node , int st , int en , int l , int r)
{
    if (st > r || en < l) return {0,0};

    if (st >= l && en <= r)
        return seg[node];

    int mid = (st+en)/2;
    return max(query(2*node , st , mid , l , r) , query(2*node+1 , mid+1 , en , l , r));
}

ll solve(int i)
{
    if (i==n+1)
        return dp[i] = i;

    if (dp[i] != -1)
        return dp[i];

    ll ans = i+1 , up , idx , tmp , l , r;
    up = upper_bound(v.begin() , v.end() , make_pair(v[i].f+v[i].s-1 , (ll)3e9)) - v.begin();
    if (up == v.size() || up == i+1) ans = up;
    else
    {
        l = i+1 , r = up-1;
        idx = query(1,1,n,l,r).s;
        if (idx > i) ans = max(ans , solve(idx));
    }
    return dp[i] = ans;
}

ll solve2(int i)
{
