            c=(l+r)/2;
            if(dat[i].first+dat[i].second<=dat[c].first)
            r=c;
            else
            l=c+1;
        }
        update(i,query(i,l,0,0,N));
        dp[i]=(dp[i+1]+dp[v[i+N-1]+1])%mod;
    }
    cout<<(dp[0]+mod)%mod<<endl;
}

