VV G;

mint dfs(int u) {
  mint res = 1;
  for (int v : G[u]) {
    res *= dfs(v);
  }
  res += 1;
  return res;
}


int main() {
  ll n; cin >> n;
  vector<P> xd;
  rep(i, n) {
    int x, d; cin >> x >> d;
    xd.emplace_back(x, x+d);
  }
  sort(all(xd));

  stack<P> st;
  V roots;
  G.assign(n, V());

  rep(i, n) {
    while (!st.empty() && st.top().second <= xd[i].first) st.pop();
    if (st.empty()) roots.push_back(i);
    else G[st.top().first].push_back(i);
    st.emplace(i, xd[i].second);
  }

  mint ans = 1;
  for (auto r : roots) {
    ans *= dfs(r);
  }

  cout << ans << "\n";
  return 0;
}

