template<typename Monoid,typename F>
class SegmentTree{
private:
    int sz;
    vector<Monoid> seg;
    const F op;//演算
    const Monoid e;//単位元
public:
    SegmentTree(int n,const F op,const Monoid &e):op(op),e(e){
        sz = 1;
        while(sz<=n) sz <<= 1;
        seg.assign(2*sz,e);
    }
    void set(int k, const Monoid &x){
        seg[k+sz] = x;
    }
    void build(){
        for(int i=sz-1;i>0;i--){
            seg[i] = op(seg[2*i],seg[2*i+1]);
        }
    }
    void update(int k,const Monoid &x){
        k += sz;
        seg[k] = x;
        while(k>>=1){
            seg[k] = op(seg[2*k],seg[2*k+1]);
        }
    }
    Monoid query(int l,int r){
        Monoid L = e,R = e;
        for(l+=sz,r+=sz;l<r;l>>=1,r>>=1){
            if(l&1) L = op(L,seg[l++]);
            if(r&1) R = op(seg[--r],R);
        }
        return op(L,R);
    }
    Monoid operator[](const int &k)const{
        return seg[k+sz];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vec<Pa<int,int>> I;
    for(int i=0;i<N;i++){
        int x,d;
        cin >> x >> d;
        I.emplace_back(x,x+d);
    }
    sort(I.begin(),I.end());
    int inf = 2e9+1;
    I.emplace_back(inf,inf);
    auto op = [](int a,int b){return max(a,b);};
    SegmentTree<int,decltype(op)> seg(N+1,op,-inf);
    vec<int> R(N+1,-1);
    R[N] = inf;
    seg.set(N,R[N]);
    seg.build();
    for(int i=N-1;i>=0;i--){
        int id = lower_bound(I.begin(),I.end(),make_pair(I[i].second,-inf))-I.begin();
        R[i] = max(I[i].second,seg.query(i,id));
        seg.update(i,R[i]);
    }

    vec<mint> dp(N+1,0);
    dp[0] = 1;
    for(int i=0;i<N;i++){
        dp[i+1] += dp[i];
        int id = lower_bound(I.begin(),I.end(),make_pair(R[i],-inf))-I.begin();
        dp[id] += dp[i];
    }
    cout << dp[N] << "\n";
}

