using robot = tuple<ll, ll>;
using info = tuple<ll, int>;

int main()
{
  int N;
  cin >> N;
  vector<robot> V(N);
  for (auto i = 0; i < N; ++i)
  {
    ll X, D;
    cin >> X >> D;
    V[i] = robot(X, X + D);
  }
  sort(V.rbegin(), V.rend());
  // make I part
  vector<int> I(N);
  SegTree<int> tree{N, unit, func, _update};
  set<info> S;
  S.insert(info(infty, -1));
  for (auto i = 0; i < N; ++i)
  {
    int l, r;
    tie(l, r) = V[i];
    S.insert(info(l, i));
    auto finish{get<1>(*S.lower_bound(info(r, -1)))};
    auto mini{tree.find(finish + 1, i)};
    ch_min(mini, i);
    I[i] = mini;
#if DEBUG == 1
    cerr << "l = " << l << ", r = " << r << ", finish = " << finish << endl;
    cerr << "I[" << i << "] = " << mini << endl;
#endif
    tree.update(i, mini);
  }
  // DP part
  vector<mint> DP(N + 1);
  DP[0] = 1;
  for (auto i = 0; i < N; ++i)
  {
    DP[i + 1] = DP[i] + DP[I[i]];
  }
  cout << DP[N] << endl;
}

