#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
const int N = 2e5;
typedef pair <int,int> pii;
const ll MOD = 998244353;

ll dmod(ll x){
	return x%MOD;
}

int n;

pii li[N+5];
int ST[4*N+5];

void update(int node, int l, int r, int pos, int val){
	if(pos > r || pos < l) return;
	if(l == r){
		ST[node] = val;
		return;
	}
	int mid = (l+r)/2;
	update(node*2,l,mid,pos,val);
	update(node*2+1,mid+1,r,pos,val);
	ST[node] = max(ST[node*2], ST[node*2+1]);
	return;
}

int query(int node, int l, int r, int ql, int qr){
	if(l > qr || r < ql) return 0;
	if(l >= ql && r <= qr) return ST[node];
	int mid = (l+r)/2;
	return max(query(node*2,l,mid,ql,qr),query(node*2+1,mid+1,r,ql,qr));
}

void build(int node, int l, int r){
	if(l == r){
		ST[node] = l;
		return;
	}
	int mid = (l+r)/2;
	build(node*2,l,mid);
	build(node*2+1,mid+1,r);
	ST[node] = max(ST[node*2],ST[node*2+1]);
	return;
}

int cari(int x, int id){
	int ret = id;
	int l = id+1;
	int r = n;
	while(l<=r){
		int mid = (l+r)/2;
		if(li[mid].first <= x){
			l = mid + 1;
			ret = mid;
		} else {
			r = mid - 1;
		}
	}
	return ret;
}

ll fe(ll x, ll p){
	if(p==0) return 1ll;
	ll ret = fe(x,p/2);
	ret = dmod(ret*ret);
	if(p&1) ret = dmod(ret*x);
	return ret;
}

ll p2[N+5];

ll memo[N+5];
int kanan[N+5];

ll dp(int x){
	if(x > n) return 1;
	ll &ret = memo[x];
	if(ret != -1) return ret;
	ret = dp(x+1);
	ret = dmod(ret+dp(kanan[x]+1));
	return ret;
}

int main(){
	memset(memo,-1,sizeof(memo));
	p2[0] = 1;
	for(int i=1;i<=N;i++){
		p2[i] = dmod(p2[i-1]*2ll);
	}
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%d %d",&li[i].first,&li[i].second);
	}
	sort(li+1,li+n+1);
	build(1,1,n);
	for(int i=n;i>=1;i--){
		int smpe = li[i].first + li[i].second - 1;
		int id = cari(smpe,i);
		int ujung = query(1,1,n,i,id);
		update(1,1,n,i,ujung);
		kanan[i] = ujung;
	}
	ll ans = dp(1);
//	ans = dmod(ans*fe(p2[n],MOD-2));
	printf("%lld\n",ans);
	return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
using large = long long;
constexpr int N_max = 200'000;
constexpr int mod = 998'244'353;

struct Robot {
    int x, d;
    struct Removal {
        Robot *begin;
        Robot *end; // one-past-last
    } removal;
};

static large solve(const Robot *const robots, const Robot *const end) {
    if (robots == end) {
        return 1;
    }

    large ans = 0;

    // activate (and remove)
    {
        large c = solve(robots->removal.end, end);
        ans += c;
        if (ans >= mod)
            ans -= mod;
    }
    // not activate
    {
        large c = solve(robots + 1, end);
        ans += c;
        if (ans >= mod)
            ans -= mod;
    }

    return ans;
}

int main() {
    int n;
    cin >> n;
    auto robots = vector<Robot>(n);
    for (int i = 0; i < n; i++) {
        cin >> robots[i].x >> robots[i].d;
    }
    sort(robots.begin(), robots.end(), [](auto &a, auto &b) { return a.x < b.x; });
    robots.push_back(Robot());
    robots[n].x = 2'100'000'000;
    robots[n - 1].removal.begin = &robots[n - 1];
    robots[n - 1].removal.end = &robots[n - 1] + 1;

    for (int i = n - 2; i >= 0; i--) {
        auto *r1 = &robots[i];
        r1->removal.begin = r1;
        r1->removal.end = r1 + 1;

        int x_limit = r1->x + r1->d;

        // check chain reactions
        auto *r2 = r1 + 1;
        while (r2->x < x_limit) {
            robots[i].removal.end = r2->removal.end;
            r2 = r2->removal.end - 1;
            x_limit = max(x_limit, r2->x + r2->d);
            r2++;
        }
    }

    cout << solve(robots.data(), robots.data() + n);
    return 0;
}

