struct ufind
{
  struct node
  {
    int par, rank, size;
    void init(int i)
    {
      par = i;
      rank = 0;
      size = 1;
    }
  };
  vector<node> nodes;
  ufind(int n)
  {
    nodes.resize(n);
    rep(i, n) nodes[i].init(i);
  }
  int find(int x)
  {
    return nodes[x].par == x ? x : (nodes[x].par = find(nodes[x].par));
  }
  void unite(int x, int y)
  {
    x = find(x);
    y = find(y);
    if (x == y)
      return;
    if (nodes[x].rank < nodes[y].rank)
    {
      nodes[x].par = y;
      nodes[y].size += nodes[x].size;
    }
    else
    {
      nodes[y].par = x;
      if (nodes[x].rank == nodes[y].rank)
        nodes[x].rank++;
      nodes[x].size += nodes[y].size;
    }
  }
  bool same(int x, int y) { return find(x) == find(y); }
  int size(int x) { return nodes[find(x)].size; }
};
template <class T>
class segtree
{
public:
  lli n;
  vector<T> dat;
  function<T(T, T)> func;
  T dummy;
  segtree<T>(lli n, T ini, function<T(T, T)> f, T dummy) : func(f), dummy(dummy), n(n)
  {
    lli _n = 1;
    while (_n < n)
    {
      _n = _n * 2;
    }
    n = _n;
    dat.assign(2 * _n - 1, ini);
  }
  void update(lli k, T a)
  {
    k += n - 1;
    dat[k] = a;
    while (k > 0)
    {
      k = (k - 1) / 2;
      dat[k] = func(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  T query(int a, int b)
  {
    return query(a, b, 0, 0, n);
  }
  // [a,b)の何かを求める.
  T query(int a, int b, int k, int l, int r)
  {
    //交差しないときはダミー
    if (r <= a || b <= l)
      return dummy;
    if (a <= l && r <= b)
      return dat[k];
    else
    {
      T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
      T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return func(vl, vr);
    }
  }
  T get(int a)
  {
    return query(a, a + 1, 0, 0, n);
  }
};

