  rep(i, N) X[i] = y[i].first, D[i] = y[i].second;
  vector<int> par(N);
  vector<pair<int, int>> Y;
  stack<pair<int, int>> st;
  rep(i, N)
  {
    auto last = lower_bound(X.begin(), X.end(), D[i] + X[i]) - X.begin();
    int pp = -1;
    //cout << i << " " << last << endl;
    while (!st.empty())
    {
      if (st.top().first > i)
      {
        pp = st.top().second;
        break;
      }
      else
      {
        st.pop();
      }
    }
    st.push(make_pair(last, i));

    par[i] = pp;
  }
  e.resize(N);
  rep(i, N)
  {
    if (par[i] != -1)
    {
      e[i].push_back(par[i]);
      e[par[i]].push_back(i);
    }
  }
