struct MPoly {
    vector<int_m> c;
    int sz() const { return c.size(); }
    int deg() const { return sz() - 1; }
    MPoly operator+(const MPoly &p) const {
        MPoly x;
        int N = sz(), M = p.sz();
        for(int i = max(N, M) - 1; i >= 0; i--) {
            int_m tmp = 0;
            if(i < N) tmp += c[i];
            if(i < M) tmp += p.c[i];
            if(tmp != 0) {
                if(x.c.empty()) x.c.resize(i + 1);
                x.c[i] = tmp;
            } else {
                if(!x.c.empty()) x.c[i] = 0;
            }
        }
        return x;
    }
    MPoly operator*(int_m t) const {
        MPoly x;
        x.c.resize(sz());
        for(int i = 0; i < sz(); i++) x.c[i] = c[i] * t;
        return x;
    }
    MPoly operator-() {
        return (*this) * int_m(-1);
    }
    MPoly operator-(const MPoly &p) {
        return (*this) + (p * (int_m)(-1));
    }
    MPoly operator*(const MPoly &p) const {
        MPoly x;
        x.c.resize(p.sz() + sz() - 1);
        for(int i = 0; i < x.sz(); i++) {
            int_m tmp = 0;
            // TODO: Implement Fast Fourier Transformation
            for(int j = 0; j < p.sz(); j++) {
                tmp += p.c[j] * c[i - j];
            }
            x.c[i] = tmp;
        }
        return x;
    }
    MPoly operator*(const int_m &t) {
        MPoly x;
        x.c.resize(sz());
        for(int i = 0; i < sz(); i++) {
            x.c[i] = t * c[i];
        }
        return x;
    }
};


struct Robot {
    int X, D;
    bool operator<(const Robot &rhs) {
        if(X < rhs.X) return true;
        else if(X == rhs.X) return D < rhs.D;
        return false;
    }
};

int main() {
    int_m::m = 998244353;
    int N;
    cin >> N;
    // (X, D) |-> 座標XにD進むロボットがいる
    vector<Robot> R(N);
    // 誘爆されないロボット
    vector<int> root;
    // 誘爆の木
    vector2d<int> edge(N);

    for(Robot &r : R) {
        cin >> r.X >> r.D;
    }
    sort(REV_WHOLE(R));
    {
        vector<bool> is_child(N, false);
        stack<int> st;
        for(int i = 0; i < N; i++) {
            while(st.size() && R[st.top()].X < R[i].X + R[i].D) {
                edge[i].push_back(st.top());
                is_child[st.top()] = true;
                st.pop();
            }
            st.push(i);
        }
        for(int i = 0; i < N; i++) if(!is_child[i]) root.push_back(i);
    }
    vector<int_m> B(N, 1);
    for(int i = 0; i < N; i++) {
        int_m tmp = 1;
        for(int j : edge[i]) {
            tmp *= B[j];
        }
        B[i] += tmp;
    }
    int_m ans = 1;
    for(int i : root) ans *= B[i];
    cout << ans << endl;
    return 0;
}

