template <typename Monoid>
struct SegmentTree {
	using F = function<Monoid(Monoid, Monoid)>;

	int sz;
	vector<Monoid> seg;
	const F f;
	const Monoid M1;

	SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
		sz = 1;
		while (sz < n) sz <<= 1;
		seg.assign(2 * sz, M1);
	}

	void set(int k, const Monoid &x) { seg[k + sz] = x; }

	void build() {
		for (int k = sz - 1; k > 0; k--) {
			seg[k] = f(seg[2 * k], seg[2 * k + 1]);
		}
	}

	void update(int k, const Monoid &x) {
		k += sz;
		seg[k] = x;
		while (k >>= 1) {
			seg[k] = f(seg[2 * k], seg[2 * k + 1]);
		}
	}

	Monoid query(int a, int b) {
		Monoid L = M1, R = M1;
		for (a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
			if (a & 1) L = f(L, seg[a++]);
			if (b & 1) R = f(seg[--b], R);
		}
		return f(L, R);
	}

	Monoid operator[](const int &k) const { return seg[k + sz]; }
};

ll dp[200001];

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	int N;
	cin >> N;
	SegmentTree<int> seg(N, [](int a, int b) {return max(a, b); }, 0);
	vector<P> robot;
	for (int i = 0; i < N; i++) {
		int X, D;
		cin >> X >> D;
		robot.emplace_back(X, D);
	}
	sort(begin(robot), end(robot));
	seg.update(N - 1, N - 1);
	for (int i = N - 2; i >= 0; i--) {
		int idx = lower_bound(begin(robot), end(robot), P(robot[i].first + robot[i].second, -1)) - begin(robot);
		int x = seg.query(i, idx);
		seg.update(i, max(i, x));
	}
	dp[0] = 1;
	for (int i = 0; i < N; i++) {
		(dp[i + 1] += dp[i]) %= MOD;
		int m = seg[i];
		(dp[m + 1] += dp[i]) %= MOD;
	}
	cout << dp[N] << endl;
}

