int const MAXN = 2e5;
int64_t MOD = 998244353;

std::pair<int, int> XD[MAXN];
int N;

int64_t tmp[MAXN];

int64_t calc(int i, int c) {
  if(tmp[c] >= 0) return tmp[c];
  if(c==0) return 1;
  if(c==1) return 2;
  int64_t res = calc(i, c-1);
  int last_pos = -1e9-1, d = 0;
  for(int j = i-c+1; j <= i; ++j) {
    last_pos = std::max(last_pos, XD[j].first+XD[j].second);
    ++d;
    if(last_pos <= XD[j+1].first) break;
  }
  res += calc(i, c-d);
  return tmp[c] = res;
}

int main() {
  std::cin >> N;
  for(int i = 0; i < N; ++i) std::cin >> XD[i].first >> XD[i].second;
  std::sort(XD, XD+N);
  int64_t ans = 1, count = 0;
  int last_pos = -1e9-1;
  for(int i = 0; i < N-1; ++i) {
    ++count;
    last_pos = std::max(last_pos, XD[i].first + XD[i].second);
    if(last_pos <= XD[i+1].first) {
      std::fill_n(tmp, count+1, -1);
      (ans *= calc(i, count)) %= MOD;
      count = 0;
    }
  }
  std::fill_n(tmp, count+2, -1);
  (ans *= calc(N-1, count+1)) %= MOD;
  std::cout << ans << std::endl;
  return 0;
}

