    SegmentTree<ll> seg(N, [](ll a, ll b){return max(a, b);}, -(1ll<<60));
    for(int i=N-1;i>=0;i--){
    	ll pos = lower_bound(X.begin(), X.end(), X[i]+D[i]) - X.begin();
    	ll ma = pos-1;
    	ll ma2 = seg.query(i+1, pos);
    	seg.update(i, max(ma, ma2));
    }

    /*
