class Segment_Tree{
private:
    vector<int> seg;
    int n;
public:
    Segment_Tree(int n){
        this->n=n;
        seg.resize(4*n,0);
    }
    void update(int idx, int l, int r, int f, int g){
        if(l>f || r<f) return;
        seg[idx]=max(seg[idx],g);
        if(l==r) return;
        int m=(l+r)/2;
        update(2*idx,l,m,f,g);
        update(2*idx+1,m+1,r,f,g);
    }
    int find(int idx, int l, int r, int fl, int fr){
        if(fr<l || r<fl) return 0;
        if(fl<=l && r<=fr) return seg[idx];
        int m=(l+r)/2;
        return max(find(2*idx,l,m,fl,fr),find(2*idx+1,m+1,r,fl,fr));
    }
};
ll mypow(ll x, int y){
    ll res=1;
    while(y){
        if(y%2) res=(res*x)%MD;
        x=(x*x)%MD;
        y/=2;
    }
    return res;
}
