void change(ll k, ll x)
{
  ll cur = k;
  D[cur] = x;
  cur = (cur-1)/2;
  bool flag = false;
  while(1)
  {
    D[cur] = max(D[2*cur+1], D[2*cur+2]);
    cur = (cur-1)/2;
    if(flag) break;
    if(cur==0) flag = true;
  }
}

void init()
{
  rep(2*k-1) D.emplace_back(-INF);
}

// query to the i-the node whose interval is [l,r)
// what is the value of [a,b)?
ll query_body(ll i, ll a, ll b, ll l, ll r)
{
  if(b <= l || r <= a) return -INF; // I don't know
  if(a <= l && r <= b) return D[i]; // I know

  // My children know
  ll c1 = query_body(2*i+1, a, b, l, (l+r)/2);
  ll c2 = query_body(2*i+2, a, b, (l+r)/2, r);
  return max(c1, c2);
}

ll query(ll l, ll r)
{
  return query_body(0, l, r, 0, k);
}

