class Solution {
public:
    int solve(vector<int>& X, vector<int>& D) {
        const int MOD = 998244353;

        int n = X.size();
        vector<pair<int,int>> P;
        for (int i = 0; i < n; ++i) {
            P.emplace_back(X[i], D[i]);
        }
        sort(P.begin(), P.end());

        vector<int> next(n, n);
        vector<int> que;
        for (int i = n - 1; i >= 0; --i) {
            int d = P[i].first + P[i].second;
            while (!que.empty()) {
                int x = que.back();
                int j = que.back();

                if (P[x].first < d) {
                    que.pop_back();
                } else {
                    break;
                }
            }
            if (que.empty()) {
                next[i] = n;
            } else {
                next[i] = que.back();
            }
            que.push_back(i);
        }


        vector<long long> dp(n + 2, 0);
        dp[0] = 1;

        for (int i = 0; i < n; ++i) {
            int j = next[i];
            dp[j] += dp[i];
            if (dp[j] >= MOD) {
                dp[j] -= MOD;
            }
            dp[i + 1] += dp[i];
            if (dp[i + 1] >= MOD) {
                dp[i + 1] -= MOD;
            }
        }

        return dp[n];
    }
};

