class SegmTree{
public:

    SegmTree(int n)
        : tree(4 * n)
        , n(n)
    {
    }

    void upd(int v, int l, int r, int indx, int value) {
        if (indx < l || indx > r) {
            return;
        }
        if (l == r) {
            tree[v] = value;
            return;
        }

        int md = (l + r) / 2;
        upd(v * 2, l, md, indx, value);
        upd(v * 2 + 1, md + 1, r, indx, value);
        tree[v] = max(tree[v * 2], tree[v * 2 + 1]);
    }

    int get(int v, int l, int r, int tl, int tr) {
        if (l > tr || tl > r) {
            return INT_MIN;
        } 
        if (tl <= l && r <= tr) {
            return tree[v];
        }

        int md = (l + r) / 2;
        int t1 = get(v * 2, l, md, tl, tr);
        int t2 = get(v * 2 + 1, md + 1, r, tl, tr);
        return max(t1, t2);
    }

    void upd(int indx, int value) {
        upd(1, 0, n - 1, indx, value);
    }

    int get(int l, int r) {
        return get(1, 0, n - 1, l, r);
    }

private:
    int n;
    vector<int> tree;
};


template <int mod>
struct Modular {
    int val;

    Modular(long long _val = 0) {
        if (_val < 0 || _val >= mod) {
            val = _val % mod;
            if (val < 0) {
                val += mod;
            }
        } else {
            val = _val;
        }
    }

    Modular operator +(const Modular& ot) const {
        int res = val + ot.val;
        if (res >= mod) {
            res -= mod;
        }
        return {res};
    }

    Modular operator -(const Modular& ot) const {
        int res = val - ot.val;
        if (res < 0) {
            res += mod;
        }
        return {res};
    }

    Modular operator *(const Modular& ot) const {
        return {1ll * val * ot.val};
    }

    Modular& operator ++() {
        val += 1;
        if (val == mod) {
            val = 0;
        }
        return *this;
    }

    Modular operator ++(int) {
        Modular tmp(*this);
        operator ++();
        return tmp;
    }

    void operator +=(const Modular& ot) {
        val += ot.val;
        if (val >= mod) {
            val -= mod;
        }
    }

    void operator -=(const Modular& ot) {
        val -= ot.val;
        if (val < 0) {
            val += mod;
        }
    }

    void operator *=(const Modular& ot) {
        val = 1ll * val * ot.val % mod;
    }

    bool operator ==(const Modular& ot) const {
        return val == ot.val;
    }

    bool operator !=(const Modular& ot) const {
        return val != ot.val;
    }
};

template <int mod>
ostream& operator <<(ostream& ostr, const Modular<mod>& x) {
    return ostr << x.val;
} 
