// O(lgN)
int query(int L, int R) {
  if (L > R) return -1;
  auto N = R - L + 1;
  int i = 0;
  while ((1 << i) <= N) i++;
  i--;
  return max(table[L][i], table[R - (1 << i) + 1][i]);
}

