            if (i + j == n) { break; }
        }
    }

    vi dp(n, 0);
    dp[n - 1] = 2;

    rrep(i, 0, n - 1) {
        // Stop.
        dp[i] += dp[i + 1];

        // Run.
        if (i + robots[i] == n - 1) {
            dp[i] += 1;
        } else {
            dp[i] += dp[i + robots[i] + 1];
        }
    }

    cout << dp[0] % MOD << endl;

    return 0;
}

