int st[800000];

int rightMost(int p, int l, int r, int range) {
    if (l == r)
        return l;

    int m = (l + r) / 2;
    if (st[2*p+1] < range)
        return rightMost(2*p+1, m+1, r, range);
    return rightMost(2*p, l, m, range);
}

int query(int p, int l, int r, int i, int j, int range) {
    if (i > r || j < l)
        return -1;
    if (i <= l && r <= j) {
        if (st[p] >= range)
            return -1;
        return rightMost(p, l, r, range);
    }

    int m = (l + r) / 2, ret = query(2*p+1, m+1, r, i, j, range);
    if (ret == -1)
        ret = query(2*p, l, m, i, j, range);
    return ret;
}

void update(int p, int l, int r, int idx, int val) {
    if (l == r) {
        st[p] = val;
        return;
    }

    int m = (l + r) / 2;
    if (idx <= m)
        update(2*p, l, m, idx, val);
    else
        update(2*p+1, m+1, r, idx, val);
    st[p] = min(st[2*p], st[2*p+1]);
}

