void dfs(int i, int n, std::vector< std::pair<int, int> >& robo, std::vector<int>& to) {
  int j = to[i] = i + 1;
  while(j < n && robo.at(j).first < robo.at(i).second)
    if(to[j]) j++; else {
      dfs(j, n, robo, to);
      j = to[i] = to[j];
    }
}

