  dp[n-1] = 2; dp[n] = 1;
  for(int i = n-2; i >= 0; i--)
    dp.at(i) = (dp.at(i+1) + dp.at(to[i])) % 998244353;

  std::cout << dp.at(0) << '\n';

  return 0;
}

