const ll N=500010;

ll sgt[4*N];

void update(ll st,ll en,ll pos,ll idx,ll val)
{
    if(st==en)
    {
        sgt[pos]=val;
        return;
    }
    ll mid=(st+en)/2;
    if(idx>=st&&idx<=mid){update(st,mid,2*pos+1,idx,val);}
    else{update(mid+1,en,2*pos+2,idx,val);}
    sgt[pos]=max(sgt[2*pos+1],sgt[2*pos+2]);
}

ll range(ll st,ll en,ll pos,ll l,ll r)
{
    if(st>r||en<l){return INT_MIN;}
    if(st>=l&&en<=r){return sgt[pos];}
    ll mid=(st+en)/2;
    return max(range(st,mid,2*pos+1,l,r),range(mid+1,en,2*pos+2,l,r));
}

