struct SegmentTree {
    struct Node {
        Node operator*(const Node& o) const {
            return { max(v, o.v) };
        }
        int v;
    };
    SegmentTree(int n) : e({ -1 }), n(n) {
        for (m = 2; m < n; m *= 2);
        t = vector<Node>(m + n + n % 2, e);
    }
    Node& operator[](int i) {
        return t[m + i];
    }
    const Node& root() const {
        return t[1];
    }
    void build() {
        for (int i = (n - 1 + m) / 2; i > 0; i--) t[i] = t[i * 2] * t[i * 2 + 1];
    }
    void update(int i, const Node& o) {
        for (t[i += m] = o; i /= 2, i > 0;) t[i] = t[i * 2] * t[i * 2 + 1];
    }
    Node query(int l, int r) {
        Node o[2] = { e, e };
        for (l += m, r += m; l < r; l /= 2, r /= 2) {
            if (r & 1) o[1] = t[--r] * o[1];
            if (l & 1) o[0] = o[0] * t[l++];
        }
        return o[0] * o[1];
    }
    void print() {
        for (int j = 1; j <= m; j *= 2) {
            int k = min(j * 2, m + n);
            for (int i = j; i < k; i++) {
                cout << t[i].v << " \n"[i == k - 1];
            }
        }
    }
    vector<Node> t;
    const Node e;
    int n, m;
};

struct R {
    bool operator<(const R& r) const {
        return x < r.x;
    }
    int x, d;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<R> r(n);
    for (int i = 0; i < n; i++) {
        int x, d;
        cin >> x >> d;
        r[i] = { x, d };
    }
    sort(r.begin(), r.end());

    SegmentTree st(n);
    vector<int> dp(n + 1);
    dp[n] = 1;

    for (int i = n - 1; i >= 0; i--) {
        int j = lower_bound(r.begin() + i + 1, r.end(), R{ r[i].x + r[i].d , 0 }) - r.begin();
        st.update(i, { j = max(j, st.query(i + 1, j).v) });
        dp[i] = dp[j] + dp[i + 1];
        if (dp[i] >= P) dp[i] -= P;
    }

    cout << dp[0] << endl;

    return 0;
}

