int t[N * 4];

void build(int v, int l, int r) {
  if (l + 1 == r) {
    t[v] = r;
  } else {
    int mid = (l + r) / 2;
    build(v * 2 + 1, l, mid);
    build(v * 2 + 2, mid, r);
    t[v] = max(t[v * 2 + 1], t[v * 2 + 2]);
  }
}

void update(int v, int l, int r, int pos, int val) {
  if (l + 1 == r) {
    t[v] = val;
  } else {
    int mid = (l + r) / 2;
    if (pos < mid) {
      update(v * 2 + 1, l, mid, pos, val);
    } else {
      update(v * 2 + 2, mid, r, pos, val);
    }
    t[v] = max(t[v * 2 + 1], t[v * 2 + 2]);
  }
}

int get(int v, int l, int r, int ql, int qr) {
  if (l == ql && r == qr) {
    return t[v];
  }
  int mid = (l + r) / 2;
  if (qr <= mid) {
    return get(v * 2 + 1, l, mid, ql, qr);
  }
  if (ql >= mid) {
    return get(v * 2 + 2, mid, r, ql, qr);
  }
  return max(get(v * 2 + 1, l, mid, ql, mid), get(v * 2 + 2, mid, r, mid, qr));
}

