template<class T> class segtree {
	int n, mode;
	vector<T> data;
	T id;
public:
	segtree(int _n, int _mode) {
		n = 1;
		mode = _mode;
		while (n < _n + 2) n <<= 1;
		if (mode == 1) id = 0;
		else if (mode == 2) id = -INF;
		else if (mode == 3) id = INF;
		data = vector<T>(2 * n, id);
	}
	T operation(T a, T b) {
		if (mode == 1) return a + b;
		else if (mode == 2) return max(a, b);
		else if (mode == 3) return min(a, b);
	}
	void change(int i, T x) {
		i += n;
		data[i] = x;
		while (i > 1) {
			i >>= 1;
			data[i] = operation(data[i << 1], data[i << 1 | 1]);
		}
	}
	void add(int i, T x) { change(i, data[i + n] + x); }
	T get(int a, int b) {
		T left = id; T right = id;
		a += n; b += n;
		while (a < b) {
			if (a & 1) left = operation(left, data[a++]);
			if (b & 1) right = operation(data[--b], right);
			a >>= 1; b >>= 1;
		}
		return operation(left, right);
	}
	T get_all() { return data[1]; }
	T operator[](int i) { return data[i + n]; }
};
