ModInt<> solve() {
  auto fun = [](pair<long long, long long> l,
                pair<long long, long long> r) {
    return max(l, r);
  };
  seg = SegmentTree<pair<long long, long long>>(n + 1, fun,
                                                {0, 0});
  for(int i = 0; i <= n; ++i)
    seg.update(i, make_pair(1, i));
  for(int i = n - 1; i >= 0; --i) {
    long long lim = v[i].x + v[i].d;
    auto it = lower_bound(x.begin(), x.end(), lim);
    int id = it - x.begin();
    pair<long long, long long> now = seg.query(i, id);
    seg.update(i, make_pair(max(now.first + now.second - i,
                                (long long)id - i),
                            i));
  }
  dp.assign(n + 1, 0);
  dp[n] = 1;
  for(int i = n - 1; i >= 0; --i) {
    // not use
    dp[i] = dp[i + 1];
    // use
    dp[i] += dp[i + seg.query(i, i + 1).first];
  }
  return dp[0];
}

