int find_right(int start, int right_most_i) {
    if (start >= n) {
        return n;
    }
    if (robots[start].x >= robots[right_most_i].y) {
        return start;
    }
    if (robots[right_most_i].y < robots[start].y) {
        right_most_i = start;
    }
    return find_right(start + 1, right_most_i);
}

int rmi[MAXN];  // right most i, that x[rmi[i]] >= max{y[j], i<=j<rmi[i]}

int find_right2(int start) {
    int ans = robots[start].y;
    int ans_i = start;
    rep(i, start + 1, n) {
        if (robots[i].x >= ans) {
            break;
        }
        if (robots[rmi[i]].y > ans) {
            ans = robots[rmi[i]].y;
            ans_i = rmi[i];
        } else if (robots[rmi[i]].y == ans) {
            ans_i = max(ans_i, rmi[i]);
        }
    }
    return ans_i;
}

// split find_right2 into 2 steps.
int find_right3(int start) {
    // 1. find right most i with x<y[start]
    int max_x = robots[start].y;
    int max_y = -INF;
    int max_y_i = -INF;
    rep(i, start + 1, n) {
        if (robots[i].x >= max_x) {
            break;
        }
        if (robots[rmi[i]].y > max_y) {
            max_y = robots[rmi[i]].y;
            max_y_i = rmi[i];
        } else if (robots[rmi[i]].y == max_y) {
            max_y_i = max(max_y_i, rmi[i]);
        }
    }
    // 2. figure out right most i for start
    if (max_y < robots[start].y) {
        max_y_i = start;
    } else if (max_y == robots[start].y) {
        max_y_i = max(start, max_y_i);
    }
    return max_y_i;
}

