struct SegmentTree {
	vi t, A;
	int n;
	void build(int v, int tl, int tr) {
		if (tl == tr)
			t[v] = tl;
		else {
			int tm = (tl + tr) / 2;
			build(v * 2, tl, tm);
			build(v * 2 + 1, tm + 1, tr);
			int valL = t[v * 2], valR = t[v * 2 + 1];
			t[v] = max(valL, valR);
		}
	}
	int query(int v, int tl, int tr, int l, int r) {
		if (l > r)
			return 0;
		if (l == tl && r == tr)
			return t[v];
		int tm = (tl + tr) / 2;
		int valL = query(2 * v, tl, tm, l, min(r, tm));
		int valR = query(2 * v + 1, tm + 1, tr, max(l, tm + 1), r);
		return max(valL, valR);
	}
	void update(int v, int tl, int tr, int idx, int newVal) {
		if (tl == tr)
			t[v] = newVal;
		else {
			int tm = (tl + tr) / 2;
	        if (idx <= tm)
	            update(v * 2, tl, tm, idx, newVal);
	        else
	            update(v * 2 + 1, tm+1, tr, idx, newVal);
			int valL = t[v * 2], valR = t[v * 2 + 1];
			t[v] = max(valL, valR);
		}
	}
	void init(int _n) {
		n = _n;
		t.assign(4 * n, 0);
		build(1, 0, n - 1);
	}
	SegmentTree(int _n) {
		init(_n);
	}
	SegmentTree(const vi& _A) : A(_A) {
		init(sz(A));
	}
	int query(int i, int j) {
		return query(1, 0, n - 1, i, j);
	}
	void update(int idx, int newVal) {
		update(1, 0, n - 1, idx, newVal);
	}
};


