struct Interval
{
	int64_t start;
	int64_t end;

	Interval() = default;
	Interval(int64_t s, int64_t e) : start(s), end(e) {};

	bool operator<(const Interval &other) const
	{
		return start < other.start;
	}
};

struct TreeNode
{
	Interval interval;
	int64_t max_end;
	int index;
	int R;

	TreeNode *left;
	TreeNode *right;

	TreeNode() = default;
	TreeNode(const Interval &inter, int in_index)
		: index(in_index)
		, R(in_index)
		, left(nullptr)
		, right(nullptr)
	{
		interval = inter;
		max_end = inter.end;
	}

	~TreeNode()
	{
		if (left != nullptr)
		{
			delete left;
		}

		if (right != nullptr)
		{
			delete right;
		}
	}
};

int FindSegTree(TreeNode *root, int64_t val, int index)
{
	while(root != nullptr && root->index < index)
	{
		root = root->right;
	}

	if(root == nullptr)
	{
		return -1;
	}

	if (root->interval.start < val)
	{
		if (root->max_end <= val)
		{
			return root->R;
		}
		else
		{
			if (root->interval.end == root->max_end)
			{
				return root->R;
			}
			else if (root->left != nullptr && root->left->max_end == root->max_end)
			{
				int result = FindSegTree(root->left, root->max_end, index);
				return result != -1 ? result : root->R;
			}
			else
			{
				val = std::max(val, root->interval.end);
				if (root->left != nullptr)
				{
					auto node = root->left;
					while (node != nullptr && node->index < index)
					{
						node = node->right;
					}

					if (node != nullptr)
					{
						val = std::max(val, node->max_end);
					}
				}
				int result = FindSegTree(root->right, val, index);
				return result != -1 ? result : root->R;
			}
		}
	}
	else
	{
		if (root->left != nullptr)
		{
			return FindSegTree(root->left, val, index);
		}
	}

	return -1;
}

TreeNode* BuildTree(const std::vector<Interval> &intervals, std::vector<TreeNode*> &indexTreeNodeMap, int start, int end)
{
	if (start >= end)
	{
		return nullptr;
	}

	int middle = (start + end) / 2;
	auto root = new TreeNode(intervals[middle], middle);
	indexTreeNodeMap[middle] = root;

	root->left = BuildTree(intervals, indexTreeNodeMap, start, middle);
	root->right = BuildTree(intervals, indexTreeNodeMap, middle + 1, end);

	if (root->left != nullptr)
	{
		root->max_end = std::max(root->max_end, root->left->max_end);
	}

	if (root->right != nullptr)
	{
		root->max_end = std::max(root->max_end, root->right->max_end);
	}

	return root;
}

void GenerateHelpArray(const std::vector<Interval> &intervals, std::vector<int64_t> &R)
{
	int N = intervals.size();
	std::vector<TreeNode*> indexTreeNodeMap(N, nullptr);
	auto root = BuildTree(intervals, indexTreeNodeMap, 0, N);
	for (int i = N - 1; i >= 0; --i)
	{
		R[i] = FindSegTree(root, intervals[i].end, i);
		indexTreeNodeMap[i]->R = R[i];
	}
}

