template<class T> class segtree {
	using F1 = function<T(T, T)>;
	using F2 = function<void(T&, T)>;
	T unit;
	F1 f1;
	F2 f2;

	int n = 1;
	vector<T> dat;
public:
	segtree() {}
	segtree(const int& _n, const F1& _f1, const F2& _f2, const T _unit = 0)
		: f1(_f1), f2(_f2), unit(_unit) {
		while (n < _n)n <<= 1;
		dat.resize(n << 1, unit);
	}
	segtree(const vector<T>& _dat, const F1& _f1, const F2& _f2, const T _unit = 0)
		: f1(_f1), f2(_f2), unit(_unit) {
		int _n = _dat.size();
		while (n < _n)n <<= 1;
		dat.resize(n << 1, unit);
		FOR(i, 0, _n)dat[i + n] = _dat[i];
		rFOR(i, 1, n)dat[i] = f1(dat[i << 1], dat[i << 1 | 1]);
	}
	void update(int i, T a) {
		i += n;
		f2(dat[i], a);
		while (1 < i) {
			i >>= 1;
			dat[i] = f1(dat[i << 1], dat[i << 1 | 1]);
		}
	}
	T value(int l, int r) {
		T ret = unit;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1)ret = f1(ret, dat[l++]);
			if (r & 1)ret = f1(ret, dat[--r]);
		}
		return ret;
	}
	T operator[](int i) { return dat[i + n]; }
};

int main() {
    init();

	int n; cin >> n;
	vector<pair<int, int>> xd(n); cin >> xd;
    SORT(xd);

	segtree<int> arr(VI(n, -1),
		[](int a, int b) {return max(a, b); },
		[](int& a, int b) {a = b; }, -1);
	arr.update(n - 1, n);
	rFOR(i, 0, n - 1) {
		int reach = xd[i].first + xd[i].second;
		int l = i, r = n;
		while (r - l > 1) {
			int mid = l + r >> 1;
			if (xd[mid].first < reach)l = mid;
			else r = mid;
		}
		if (l == i)arr.update(i, i + 1);
		else arr.update(i, arr.value(i + 1, r));
	}

    VL dp(n + 1);
    dp[0] = 1;
    FOR(i, 0, n) {
        dp[i + 1] = (dp[i] + dp[i + 1]) % MOD;
		int to = arr[i];
        dp[to] = (dp[i] + dp[to]) % MOD;
    }

    cout << dp[n] << "\n";
}

