struct SegmentTree
{
    vector<ll> _data;
    ll N;
    bool minimum;
    SegmentTree(bool minimum):minimum(minimum){}
    void init_0(ll _N){
        N=1;
        while (N < _N)N*=2;
        _data = vector<ll>(N*2-1, 0);
    }

    void init_MAX(ll _N){
        N=1;
        while (N < _N)N*=2;
        if(minimum)
            _data = vector<ll>(N*2-1, INT64_MAX);
        else
            _data = vector<ll>(N*2-1, INT64_MIN);
    }
    void update(ll i, ll value){
        i += N-1;
        _data[i] = value;
        while (i)
        {
            i = (i-1)/2;
            if (minimum) _data[i] = min(_data[i*2+1], _data[i*2+2]);
            else _data[i] = max(_data[i*2+1], _data[i*2+2]);
        }
    }

    void initVector(vector<ll> v){
        for (ll i = 0; i < v.size(); i++)
            update(i, v[i]);
    }

    ll getMax(ll left, ll right, ll l = 0, ll r = -1, ll k = 0){
        if(r == -1)r=N;
        if(r<=left||right<=l)return INT64_MIN;
        if(left<=l&&right>=r)return _data[k];
        ll v1=getMax(left,right,l,(l+r)/2,k*2+1);
        ll v2=getMax(left,right,(l+r)/2,r,k*2+2);
        return max(v1,v2);
    }

};

