        XD.push_back(make_pair(x, d));
    }
    sort(XD.begin(), XD.end());
    vector<ll> be_moved_robots;
    for (vector<pair<ll, ll>>::iterator itr = XD.begin(); itr < XD.end(); itr++){
        vector<pair<ll, ll>>::iterator itr_last = lower_bound(itr, XD.end(), make_pair((*itr).first+(*itr).second, -MAX));
        be_moved_robots.push_back(itr_last - XD.begin());
    }
    SegmentTree seg = SegmentTree(false);
    seg.init_MAX(N);
    seg.initVector(be_moved_robots);
    for (int i = N-2; i >= 0; i--)
    {
        be_moved_robots[i] = seg.getMax(i, be_moved_robots[i]);
        seg.update(i, be_moved_robots[i]);
    }

    vector<ll> combination(N+1, 0);
    combination[0] = 1;
    for (ll i = 1; i <= N; i++){
        combination[i] += combination[i-1] + combination[N - be_moved_robots[N-i]];
        combination[i] %= MOD;
    }
    cout << combination[N] << endl;
}

