template<typename T>
constexpr T inf = static_cast<T>(pow(10, static_cast<int>(log10(numeric_limits<T>::max())))) + 7;
constexpr llong mod = 998244353;

template<typename T>
struct segment_tree {
  int n;
  T op;
  vector<T> node;
  function<T(T,T)> fnc;

  segment_tree() = default;
  segment_tree(int n, T init, function<T(T,T)> fnc, T op = T()) :
    n(n),
    op(op),
    node(n*2, init),
    fnc(fnc)
  {}
  segment_tree(vector<T> v, function<T(T,T)> f, T o = T()) {
    n = v.size();
    op = o;
    fnc = f;
    node.resize(n*2);

    for (int i = 0; i < n; i++)
      node[i+n] = v[i];
    for (int i = n-1; i >= 1; i--)
      node[i] = fnc(node[2*i], node[2*i+1]);
  }

  void set(int x, T val) {
    x += n;
    node[x] = val;
    while (x >>= 1)
      node[x] = fnc(node[x*2], node[x*2 + 1]);
  }

  void update(int x, T val) {
    x += n;
    node[x] = fnc(node[x], val);
    while (x >>= 1)
      node[x] = fnc(node[x*2], node[x*2 + 1]);
  }

  T get(int x, int y) {
    T val = op;
    for (x += n, y += n-1; x <= y; x >>= 1, y >>= 1) {
      if (x&1)
        val = fnc(val, node[x++]);
      if (y&1^1)
        val = fnc(val, node[y--]);
    }

    return val;
  }
};

llong N; 
vector<lpair> XD;
vector<llong> X, B, dp;
segment_tree<llong> st;

llong solve(llong idx) {
  if (idx == N) return 1;
  if (dp[idx] != -1) return dp[idx];

  llong ret = solve(idx + 1) % mod;

  llong right = B[idx];
  llong next = --(lower_bound(ALL(X), right)) - X.begin();
  while (st.get(idx, next) > right) {
    right = st.get(idx, next);
    next = --(lower_bound(ALL(X), right)) - X.begin();
  }
  ret = (ret + solve(next + 1));


  return dp[idx] = ret;
}

int main() {
  cin >> N;
  XD.resize(N);
  for (auto &in: XD) {
    cin >> in.first >> in.second;
  }
  sort(ALL(XD));

  for (auto xd: XD) {
    X.push_back(xd.first);
    B.push_back(xd.first + xd.second);
  }
  st = segment_tree<llong>(B, [](llong a, llong b){return max(a, b);}, -inf<llong>);

  dp.resize(N, -1);
  cout << solve(0) << endl;

  return 0;
}

