template <class T, class E> struct LazySegmentTree{
	using F = function<T(T, T)>;
	using G = function<T(T, E)>;
	using H = function<E(E, E)>;
	ll n=1, height=0;
	F f; //!< データ同士の合成関数
	G g; //!< 作用関数
	H h; //!< 作用素同士の合成関数
	T ti; //!< データの単位元 実際の単位元をセットしないとだめ
	E ei; //!< 作用素の単位元 if文で「何もしない」を実現するため、使わない値なら何でもOK
	vector<T> dat;
	vector<E> laz;
	LazySegmentTree() {}
	LazySegmentTree(vector<T> &v, F f, G g, H h, T ti, E ei) { Init(v, f, g, h, ti, ei); }
	void Init(vector<T> &v, F f, G g, H h, T ti, E ei){
		this->f=f; this->g=g; this->h=h; this->ti=ti; this->ei=ei;
		while (n<(ll)v.size()) n<<=1, height++;
		dat.assign(2*n, ti);
		laz.assign(2*n, ei);
		REP(i, (ll)v.size()) dat[n+i]=v[i];
		DEPS(i, 1, n-1) dat[i]=f(dat[(i<<1)|0], dat[(i<<1)|1]);
	}
	inline T reflect(ll k){ return (laz[k]==ei) ? dat[k] : g(dat[k], laz[k]); }
	inline void eval(ll k){
		if (laz[k]==ei) return;
		laz[(k<<1)|0]=h(laz[(k<<1)|0], laz[k]);
		laz[(k<<1)|1]=h(laz[(k<<1)|1], laz[k]);
		dat[k]=reflect(k);
		laz[k]=ei;
	}
	inline void thrust(ll k){ DEPS(i, 1, height) eval(k>>i); }
	inline void recalc(ll k){
		while (k>>=1)
			dat[k]=f(reflect((k<<1)|0), reflect((k<<1)|1));
	}
	void Update(ll a, ll b, E x){ //区間[a,b)を更新
		thrust(a+=n);
		thrust(b+=n-1);
		for (ll l=a, r=b+1; l<r; l>>=1, r>>=1){
			if (l&1) laz[l]=h(laz[l], x), l++;
			if (r&1) --r, laz[r]=h(laz[r], x);
		}
		recalc(a);
		recalc(b);
	}
	void Set(ll a, T x){ //配列[a]にxをセット aは0-origin
		thrust(a+=n);
		dat[a]=x; laz[a]=ei;
		recalc(a);
	}
	T Range(ll a, ll b){ //区間[a,b)の値を得る
		thrust(a+=n);
		thrust(b+=n-1);
		T vl=ti, vr=ti;
		for (ll l=a, r=b+1; l<r; l>>=1, r>>=1) {
			if (l&1) vl=f(vl, reflect(l++));
			if (r&1) vr=f(reflect(--r), vr);
		}
		return f(vl, vr);
	}
	void Dump(ll w=5){
		REP(i, n) for (ll k=i+n, m=0, p=0; k>0; p=m, m+=k%2, k/=2){
			if (!m) cerr << ((k<n)  ?" ┬ ":"");
			else    cerr << ((m&&!p)?" ┘ ":"");
			if (!m) cerr << setw(w) << dat[k] << " /" << setw(w) << laz[k];
			if (k==1) cerr << '\n';
		}
	}
};


void solve()
{
	ll N; cin>>N;
	auto XD = cinv2(N);
	EACH(e, XD){
		ll X, D; tie(X, D) = e;
		X = -X;
		e.first = X-D;
		e.second = X;
	}

	map<ll, ll> za;
	EACH(e, XD){
		ll l, r; tie(l, r) = e;
		za[l] = 0;
		za[r] = 0;
	}
	ll count=1;
	EACH(e, za){
		e.second = count;
		count++;
	}
	ll NN = count;

	EACH(e, XD){
		ll l, r; tie(l, r) = e;
		ll lIdx = za[l];
		ll rIdx = za[r];
		e.first = lIdx;
		e.second = rIdx;
	}

	sort(XD.begin(), XD.end(),
		[](auto &a, auto &b) {return a.second < b.second; }
	);

	using pmll = pair<mll, ll>;

	vector<pmll> initv(NN);
	initv[0].first = 1;
	initv[0].second = 1;

	LazySegmentTree<pmll, ll>sgt(
		initv,
		[](pmll x, pmll y){ return pmll(x.first+y.first, x.second+y.second); },//データ同士の合成関数
		[](pmll x, ll y){ return pmll(x.second*y, x.second); },//データxに作用素yを作用させる関数
		[](ll x, ll y){ return y; },//作用素の合成関数
		pmll(0, 0), //データの単位元 実際の単位元をセットしないとだめ
		-1); //作用素の単位元 実際の単位元ではなくても、使わない値ならOK

	EACH(e, XD){
		ll l, r; tie(l, r) = e;

		pmll sum = sgt.Range(0, r);
		sgt.Set(r, pmll(sum.first,1));
		sgt.Update(l+1, r, 0);
	}
	pmll ans = sgt.Range(0, NN);
	cout << ans.first << '\n';
}


int main(){
	solve();
	return 0;
}

