    rep(i, n)
    {
        cin >> r[i].first >> r[i].second;
    }
    sort(r, r + n);
    vector<_LL> pos;
    rep(i, n) pos.push_back(r[i].first);
    // i番目の位置にあるロボットが動くと、何番目のロボットまでが連動して動くか
    int *ai = new int[n];
    SegTree<int> st(n);

    rep(i, n)
    {
        int index = n - 1 - i;
        int next = upper_bound(pos.begin(), pos.end(), r[index].first + r[index].second - 1) - pos.begin();
        if( index + 1 < next )
        {
            st.set(index, st.getmax(index + 1, next)); 
        }
        else
        {
            st.set(index, index + 1);
        }
//        cout << index << ": " << st.get(index) << endl;
    }

    int *dp = new int[n + 1];
    rep(i, n + 1) dp[i] = 0;
    dp[0] = 1;
    rep(i, n)
    {
        dp[i + 1] = (dp[i + 1] + dp[i]) % BN_;
        dp[ min(n, st.get(i)) ] = (dp[ min(n, st.get(i)) ] + dp[i]) % BN_;
    }

    cout << dp[n];
}

