lint mod = 998244353;

lint pow(lint a, lint n){
    lint ans = 1;
    lint base = a;
    while(n>0){
        if (n%2) ans = ans*base%mod;
        n = n/2;
        base = base*base%mod;
    }
    return ans;
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(NULL);
    cout.tie(NULL);



    lint n; cin>>n;
    vector<pll> rt(n);
    for (int i=0; i<n; ++i) cin>>rt[i].first>>rt[i].second;
    sort(rt.begin(), rt.end());

    vl last(n);
    stack<pll>  seg;

    last[n-1] = n-1;
    seg.push({n-1, n-1});
    for (int id = n-2; id >=0; --id){
        lint r = rt[id].first + rt[id].second;
        while(!seg.empty()){
            pll left = seg.top();
            if (r > rt[left.first].first){
                seg.pop();
            } else {
                break;
            }
        }
        lint rid = n-1;
        if (!seg.empty()){
            rid = seg.top().first - 1;
        }
        seg.push({id, rid});
        last[id] = rid;

    }

    vl ans(n+1, -1);
    ans[n] = 1;
    for (int i= n-1; i>=0; --i){
        ans[i] = ans[last[i]+1];
        ans[i] = (ans[i+1] + ans[i])%mod;
    }
    cout<<ans[0];

}

