// aのp乗を求める関数
ll mpow(ll a, ll b){
	if(b==0){
		return 1;
	}else if(b%2==0){
		ll memo = mpow(a,b/2);
		return memo*memo%MOD;
	}else{
		return mpow(a,b-1)*a%MOD;
	}
}

ll modulo(ll a, ll b, ll n){
	 long long x=1, y=a;
	 while (b > 0) {
			 if (b%2 == 1) {
					 x = (x*y) % n; // multiplying with base
			 }
			 y = (y*y) % n; // squaring the base
			 b /= 2;
	 }
	 return x % n;
}

