constexpr int sz = 1 << 18, defv = -2e9;
int stree[sz * 2];
void Init() {
	for (int i = 0; i < sz * 2; i++)
		stree[i] = defv;
}
int f(int a, int b) {
	return max(a, b);
}
int query(int l, int r, int low = 0, int upp = sz, int x = 0) {
	if (r <= low || upp <= l)
		return defv;
	if (l <= low && upp <= r)
		return stree[x];
	int cen = (low + upp) / 2;
	int lv = query(l, r, low, cen, x * 2 + 1);
	int rv = query(l, r, cen, upp, x * 2 + 2);
	return f(lv, rv);
}
void upd(int x, int v) {
	x += sz - 1;
	stree[x] = v;
	while (x != 0) {
		x = (x - 1) / 2;
		stree[x] = f(stree[x * 2 + 1], stree[x * 2 + 2]);
	}
}

int g(int v) {
	return lower_bound(x, x + n, v) - x;
}

int main() {
	Init();
	scanf("%d", &n);
	for (int i = 0; i < n; i++)
		scanf("%d %d", x + i, d + i);

	for (int i = 0; i < n; i++)
		s[i] = pii(x[i], d[i]);
