struct intvl
{
    int l;
    int r;
};

template <typename M>
struct seg_tree
{
    int n;
    using T = typename M::T;

private:
    vector<T> data;

    vector<intvl> intvl_s;

    // ノードの端点を得る
    intvl intvl_of_node(int i)
    {
        return intvl_s[i];
    }

    // (2ベキでないときに出てくる)不要なノードならfalse
    bool is_valid_node(int i)
    {
        intvl lr = intvl_of_node(i);
        return lr.l < lr.r;
    }

    // ノードから区間の端点への対応を前計算
    void init_intvl_s()
    {
        rep(i, n)
        {
            intvl_s[n + i] = {i, i + 1};
        }
        for (int i = n - 1; i >= 1; i--)
        {
            intvl_s[i] = {intvl_s[2 * i].l, intvl_s[2 * i + 1].r};
        }
    }

public:
    // idで初期化
    seg_tree(int size)
        : n(size), data(2 * size, M::id), intvl_s(2 * size)
    {
        init_intvl_s();
    }

    // a_sで初期化
    seg_tree(int size, vector<T> a_s)
        : n(size), data(2 * size), intvl_s(2 * size)
    {
        rep(i, n)
        {
            data[n + i] = a_s[i];
        }
        for (int i = n - 1; i >= 1; i--)
        {
            if (not is_valid_node(i))
            {
                continue;
            }
            data[i] = M::op(data[2 * i], data[2 * i + 1]);
        }

        init_intvl_s();
    }

    // i番目をaに変更
    void update(int i, int a)
    {
        i += n;
        data[i] = a;
        while (i > 1)
        {
            i /= 2;
            if (not is_valid_node(i))
            {
                break;
            }
            data[i] = M::op(data[2 * i], data[2 * i + 1]);
        }
    }

    // [l,r) の取得
    T sum(intvl lr)
    {
        int l = lr.l, r = lr.r;
        l += n;
        r += n;
        T retl = M::id, retr = M::id;
        while (l < r)
        {
            if (l & 1)
            {
                retl = M::op(retl, data[l]);
                ++l;
            }
            if (r & 1)
            {
                --r;
                retr = M::op(data[r], retr);
            }
            l /= 2;
            r /= 2;
        }
        return M::op(retl, retr);
    }

    // iの取得
    T at(int i)
    {
        return data[i + n];
    }
};

