int main() {
  int DIV = 998244353;
  int N; cin >> N;
  pair<int, int> R[N+1]; int x, d;
  for (int i = 0; i < N; i++) {
    cin >> x >> d;
    R[i] = make_pair(x, d);
  }
  R[N] = make_pair((int)2e+9 + 1, 1);
  sort(R, R+N, [](auto &a, auto &b) {
    return a.first < b.first;
  });
  int num[N], res[N+1];
  vector<int> childs[N+1]; childs[0].push_back(0);
  stack<pair<int, int>> st;
  st.push(make_pair(0, R[0].first + R[0].second));
  for (int i = 1; i <= N; i++) {
    pair<int, int> e;
    while (!st.empty() && (e = st.top()).second <= R[i].first) {
      st.pop();
      num[e.first] = i - e.first;
    }
    if (i < N) {
      if (st.empty()) {
        childs[0].push_back(i);
      } else {
        childs[e.first + 1].push_back(i);
      }
    }
    st.push(make_pair(i, R[i].first + R[i].second));
  }
  for (int i = N; i >= 0; i--) {
    long r = 1;
    vector<int> v = childs[i];
    for (auto it = v.begin(); it != v.end(); it++) {
      r *= res[*it + 1]; r %= DIV;
    }
    r++;
    res[i] = r;
  }
  cout << res[0] - 1 << endl;
}

