template<class _Tp>
struct segment {
	int size;
	vector<_Tp> v, lazy;
	const vector<_Tp> &input;
	void init(int left, int right, int idx) {
		if(left == right) {
			v[idx] = input[left];
			return;
		}
		int mid = (left+right)/2;
		init(left, mid, idx*2);
		init(mid+1, right, idx*2+1);
		v[idx] = max(v[idx*2], v[idx*2+1]); // <- changeable
	}
	_Tp query(int qleft, int qright, int left, int right, int idx) {
		update_lazy(left, right, idx);
		if(qleft <= left && right <= qright) return v[idx];
		if(qright < left || right < qleft) return -100000000000000000ll; // <- changeable
		int mid = (left+right)/2;
		_Tp retl = query(qleft, qright, left, mid, idx*2);
		_Tp retr = query(qleft, qright, mid+1, right, idx*2+1);
		return max(retl, retr); // <- changeable
	}
	void update(int uleft, int uright, int left, int right, int idx, _Tp vv) {
		update_lazy(left, right, idx);
		if(uleft <= left && right <= uright) {
			v[idx] += vv; // <- changeable
			if(left != right) {
				lazy[idx*2] += vv;
				lazy[idx*2+1] += vv;
			}
			return;
		}
		if(uright < left || right < uleft) return;
		int mid = (left+right)/2;
		update(uleft, uright, left, mid, idx*2, vv);
		update(uleft, uright, mid+1, right, idx*2+1, vv);
		v[idx] = max(v[idx*2], v[idx*2+1]); // <- changeable
		return;
	}
	void update_lazy(int left, int right, int idx) {
		if(lazy[idx] != 0) {
			v[idx] += lazy[idx]; // <- changeable
			if(left != right) {
				lazy[idx*2] += lazy[idx];
				lazy[idx*2+1] += lazy[idx];
			}
			lazy[idx] = 0;
		}
	}
	public:
	segment(vector<_Tp>& input_) : input(input_) {
		size = input.size();
		int capa = 1;
		while(capa < size) capa *= 2;
		v.resize(capa*2);
		lazy.assign(capa*2, 0);
		init(0, size-1, 1);
	}
	_Tp query(int left, int right) {
		return query(left, right, 0, size-1, 1);
	}
	void update(int left, int right, _Tp vv) {
		return update(left, right, 0, size-1, 1, vv);
	}
};

int main() {
	fastio;
	int n; cin >> n;
	vii xd(n);
	forn(i, n) cin >> xd[i].first >> xd[i].second;
	sort(all(xd));
	ll m = 998244353;
	vll dp(n+1); // dp[i] = now, we are at i. activate or not? 
	vll dp2(n+1); // if you activate i, then you can choose starting point at dp2[i]
	segment<ll> rmq(dp2);
	for(int i=n;~i;i--) {
		auto &D = dp[i];
		auto &D2 = dp2[i];
		if(i == n) {
			D = 1;
			D2 = n;
			rmq.update(i, i, D2);
			continue;
		}
		ii t = {xd[i].first+xd[i].second-1, 2*inf};
		int idx = upper_bound(all(xd), t) - xd.begin();
		if(idx == i+1) D2 = i+1;
		else D2 = rmq.query(i+1, idx-1);
		rmq.update(i, i, D2);
		D = dp[i+1] + dp[D2]; D %= m;
	}
	cout << dp[0];
}

