        v.push_back(a);
        mp[a] = b;
    }
    v.push_back(INF);
    sort(ALL(v));

    //セグメント木でiを触ったときに最終的にどのロボットまで動作してしまうかを管理する
    RMQ<int> rmq(N);
    REP(i, N)
    {
        int t = v[i];
        int d = distance(v.begin(), lower_bound(v.begin(), v.end(), t + mp[t] - 1));
        if (v[d] == t + mp[t] - 1) //ピッタリ
        {
            d = d;
        }
        else //一個前まで
        {
            d = d - 1;
        }
        rmq.update(i, i + 1, -d);
    }

    ruiseki[N] = 0;
    REP(i, N)
    {
        int t = v[N - 1 - i]; //後ろから見ていく

        int a = N - 1 - i;
        int b = a;
        int tmp = a + 1;
        while (tmp != b) //
        {
            tmp = b;
            b = rmq.query(a, b + 1);
            b = -b;
        }
        ruiseki[N - 1 - i] = (1 + ruiseki[b + 1]) + ruiseki[N - i];
        ruiseki[N - 1 - i] %= MOD;
    }
    cout << ruiseki[0] + 1 << endl;

    return 0;
}

