template<typename T> struct SegmentTree{
private:
    using F = function<T(T, T)>;

    int n;
    vector<T> node;
    F op;
    T id;
    T get(int a, int b, int k, int l, int r){
        if(b <= l || r <= a) { return id; }
        if(a <= l && r <= b) {
            return node[k];
        } else {
            return op(
                get(a, b, 2 * k + 1, l, (l + r) / 2),
                get(a, b, 2 * k + 2, (l + r) / 2, r));
        }
    }
public:
    SegmentTree(int sz, F op, T id): op(op), id(id) {
        n = 1;
        while (n < sz) { n *= 2; }
        node.resize(2 * n - 1, id);
    }
    void update(int i, T x){
        i += n - 1;
        node[i] = x;
        while(i > 0) {
            i = (i - 1) / 2;
            node[i] = op(node[2 * i + 1], node[2 * i + 2]);
        }
    }
    T get(int i){
        return node[i + n - 1];
    }
    T get(int a, int b){
        return get(a, b, 0, 0, n);
    }
};

int main() {
    int n;
    cin >> n;

    vector<pair<int, int>> xd(n);
    rep(i, 0, n) {
        int x, d;
        cin >> x >> d;
        xd[i] = make_pair(x, d);
    }
    sort(xd.begin(), xd.end());

    SegmentTree<int> tree(n, [](int a,int b)->int{ return max(a,b); }, -INF);

    rrep(i, 0, n) {
        int upper_bound = lower_bound(
            xd.begin(), xd.end(), make_pair(xd[i].first + xd[i].second, -INF)
            ) - xd.begin();

        if (upper_bound != i + 1) {
            upper_bound = max(upper_bound, tree.get(i + 1, upper_bound));
        }
        tree.update(i, upper_bound);
    }

    vi dp(n + 1, 0);
    dp[n] = 1;

    rrep(i, 0, n) {
        // Stop + Run.
        dp[i] = (dp[i+1] + dp[tree.get(i)]) % MOD;
    }
    cout << dp[0] << endl;

    return 0;
}

