template<class T, class F>
struct SegTree {
  size_t n;
  vector<T> a;
  F f;
  T zero;

  template<class U>
  static U ceil2(U x) {
    U y = 1;
    for (; y < x; y <<= 1);
    return y;
  }
  SegTree(size_t n, T zero, F f) 
    : n(ceil2(n)), a(2 * ceil2(n), zero), f(f), zero(zero) {}
  void set(size_t i, T x) {
    i += n;
    a[i] = x;
    while (i >>= 1) a[i] = f(a[2 * i], a[2 * i + 1]);
  }
  // [l, r)
  T seg(size_t l, size_t r) const {
    T x = zero, y = zero;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) {
        x = f(x, a[l]);
        ++l;
      }
      if (r & 1) {
        --r;
        y = f(a[r], y);
      }
    }
    return f(x, y);
  }
  T operator[](size_t i) const { return a[n + i]; }
};

