    SegTree<int, decltype(cmax)> st(n + 1, 0, cmax);
    for (int i = n - 1; i >= 0; --i) {
        int j = lower_bound(begin(x), end(x), x[i] + r[i].d) - begin(x);
        int k = max(st.seg(i, j), j);
        dp[i] = dp[i + 1] + dp[k];
        dp[i] %= mod;
        st.set(i, k);
