void solve(long long N, std::vector<long long> X, std::vector<long long> D)
{
  vector<PII> data;
  for (int i = 0; i < N; i++)
    data.push_back(PII(X[i], D[i]));
  sort(data.begin(), data.end());

  mint<> ans = 1;
  mint<> cnt = 0;
  //priority_queue<PII, vector<PII>, greater<PII>> sta;
  stack<PII> sta;
  for (auto xd : data)
  {
    LL x = xd.first;
    LL d = xd.second;

    while (!sta.empty())
    {
      LL y = x + d;
      auto val = sta.top();
      if (x >= val.first)
      {
        // /cout << x << " " << val.second << endl;
        ans += val.second;
        sta.pop();
      }
      else
      {
        break;
      }
    }
    sta.push(PII(x + d, ans.get_val()));
  }
  while (!sta.empty())
  {
    //cout << sta.top().second << endl;
    ans += sta.top().second;
    sta.pop();
  }
  cout << ans << endl;
}

