class Bit {
	std::vector<int> vec;
public:
	Bit(int size) : vec(size, INT_MIN) {};
	int get(int position) const {
		int result = INT_MIN;
		while (position >= 0) {
			result = std::max(result, vec[position]);
			position -= ~position & (position + 1);
		}
		return result;
	}
	void increase(int position, int value) {
		while (position < vec.size()) {
			vec[position] = std::max(vec[position], value);
			position += ~position & (position + 1);
		}
	}
};
int main() {
	int n; std::cin >> n;
	std::vector<Robot> robots(n);
	for (auto& r : robots) std::cin >> r.position >> r.distance;
	std::sort(robots.begin(), robots.end(), [](const Robot a, const Robot b) {return a.position < b.position; });
	std::vector<int> next(n);
	Bit bit(n + 1); bit.increase(n, n);
	for (int i = n - 1; i >= 0; --i) {
		const auto right = std::lower_bound(robots.begin(), robots.end(), robots[i].right(), [](const Robot a, int position) {return a.position < position; });
		next[i] = std::max(i + 1, bit.get(std::distance(robots.begin(), right) - 1));
		bit.increase(i, next[i]);
	}
	std::vector<long long int> dp(n + 1, 1);
	for (int i = n - 1; i >= 0; --i) {
		dp[i] = (dp[i + 1] + dp[next[i]]) % MOD;
	}
	std::cout << dp.front() << '\n';
}

