int tree[4*maxn];

ll dp[maxn];

void update(int uind, int uval, int li=0, int ri=n-1, int index=1) {
	if(li == ri) tree[index] = uval;
	else {
		int mid = (li + ri) / 2;

		if(uind <= mid) update(uind, uval , li, mid, 2*index);
		else update(uind, uval, mid+1, ri, 2*index+1);

		tree[index] = max(tree[2*index], tree[2*index+1]);
	}
}

int query(int ql, int qr, int li=0, int ri=n-1, int index=1) {
	if(li > qr || ri < ql) return 0;
	if(li >= ql && ri <= qr) return tree[index];
	else {
		int mid = (li + ri) / 2;
		return max(query(ql, qr, li, mid, 2*index), query(ql, qr, mid+1, ri, 2*index+1));
	}
}

