	const LL inf = -1; //为lazy不用修改的值
	LL tree[maxn << 2], lazy[maxn << 2];
	void build(int root, int left, int right) {
		lazy[root] = inf;
		if (left == right) {
			tree[root] = tmp[left];
			return;
		}
		int mid = (left + right) >> 1;
		build(root << 1, left, mid);
		build(root << 1 | 1, mid + 1, right);
		tree[root] = max(tree[root << 1], tree[root << 1 | 1]);
		//operation，可更改
