		//operation，均要修改！！！！！！！！！！
		if (lazy[root] == inf)
			return;
		int mid = (left + right) >> 1;
		tree[root << 1] = max(tree[root << 1], lazy[root]);
		tree[root << 1 | 1] = max(tree[root < 1 | 1], lazy[root]);
		lazy[root << 1] = max(lazy[root << 1], lazy[root]);
		lazy[root << 1 | 1] = max(lazy[root << 1 | 1], lazy[root]);
		lazy[root] = inf;
	}
	void add(int root, int left, int right, int stdl, int stdr, LL val) {
		if (left >= stdl && right <= stdr) {
			tree[root] = max(tree[root], val);
			lazy[root] = max(lazy[root], val); //operation，可更改
			return;
		}
		pushdown(root, left, right);
		int mid = (left + right) >> 1;
		if (stdl <= mid)
			add(root << 1, left, mid, stdl, stdr, val);
		if (stdr > mid)
			add(root << 1 | 1, mid + 1, right, stdl, stdr, val);
		tree[root] = max(tree[root << 1], tree[root << 1 | 1]);
		//operation，可更改
	}
	LL query(int root, int left, int right, int stdl, int stdr) {
		if (left >= stdl && right <= stdr)
			return tree[root];
		pushdown(root, left, right);
		int mid = (left + right) >> 1;
		LL res = inf;
		if (stdl <= mid)
			res = max(res, query(root << 1, left, mid, stdl, stdr));
		if (stdr > mid)
			res = max(res, query(root << 1 | 1, mid + 1, right, stdl, stdr));
		//operation，可更改
		return res;
	}
}
