void st(int i, int l, int r, int k, int v) {
    if (r == l+1) {
        mx[i] = v;
        return;
    }
    int m = (l+r)/2;
    if (k < m)
        st(2*i+1, l, m, k, v);
    else
        st(2*i+2, m, r, k, v);
    mx[i] = MAX(mx[2*i+1], mx[2*i+2]);
}

int gt(int i, int l, int r, int f, int t) {
    if (l >= f && r <= t)
        return mx[i];
    if (l >= t || r <= f)
        return 0;
    int m = (l+r)/2;
    int m1 = gt(2*i+1, l, m, f, t);
    int m2 = gt(2*i+2, m, r, f, t);
    return MAX(m1, m2);
}

