void update(ll a,ll b){
    a+=m;seg[a]=b;
    while(a){
        a=(a-1)/2;
        seg[a]=max(seg[2*a+1],seg[2*a+2]);
    }
}
ll ans(ll a,ll b){
    ll ret=a;a+=m;b+=m;
    while(1){
        if(a==b){
            ret=max(ret,seg[a]);
            break;
        }
        if(b==a+1){
            ret=max(ret,seg[a]);
            ret=max(ret,seg[b]);
            break;
        }
        if(a%2)a/=2;
        else{
            ret=max(ret,seg[a]);
            a/=2;
        }
        if(b%2){
            ret=max(ret,seg[b]);
            b/=2;b--;
        }
        else{b/=2;b--;}
    }
    return ret;
}

