mint dfs(int v, vector<vector<int>> &graph, vector<bool> &seen){
    if (seen[v]) return 1;
    seen[v] = true;
    mint v_num = 1;
    mint child_num = 1;
    for (int next_v : graph[v]){
        child_num *= dfs(next_v, graph, seen);
    }
    return v_num + child_num;
}

