    Rep(i,N){
        id[a[i].first] = i;
    }

    auto f = []( int a, int b ){ return max(a,b); };
    SegmentTree<int> tom( f,0 );
    vi to(N,N-1);
    Rep(i,N){
        auto it = --id.upper_bound(a[i].first+a[i].second-1);
        if( it == id.end() ) continue;
        to[i] = it->second;
    }

    tom.build( to );

    RRep(i,N){
        // max([i,to[i]]) > to[i] => to[i] = max
        int from = i;
        int toa = tom.query(i,to[from]+1);
        while( from < toa ){
            from = toa;
            to[i] = toa;
            toa = tom.query(i,to[from]);
