const int Z = 1 << 18;
int T[Z * 2];

void push(int x, int j)
{
	x += Z;
	while (x){
		T[x] = max(T[x], j);
		x /= 2;
	}
}

int pop(int x, int y)
{
	int r = 0;
	x += Z; y += Z;
	while (x < y){
		if (x & 1) r = max(r, T[x++]);
		if (y & 1) r = max(r, T[--y]);
		x /= 2; y /= 2;
	}
	return r;
}

