	for (int i = 0; i < N; i++) {
		auto &v = dat[i];
		int pos = lower_bound(begin(dat), end(dat), Pl(v.first + v.second, -LLINF)) - begin(dat);
		G.update(i, pos);
	}
	for (int i = N-1; i >= 0; i--) {
		int pos = G.query(i, i+1);
		int npos = G.query(i, pos);
		G.update(i, npos);
	}

	vint dp(N+1, 0);
	dp[0] = 1;
	for (int i = 0; i < N; i++) {
		(dp[i+1] += dp[i]) %= mod;
		(dp[G.query(i, i+1)] += dp[i]) %= mod;
	}
	cout << dp[N] << endl;
}

