struct UnionFind {

  vector<int> par;
  vector<int> siz;

  UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
    for(int i = 0; i < N; i++) par[i] = i;
    siz = Vi(N,1);
  }

  int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  void unite(int x, int y) { // xとyの木を併合
    int rx = root(x);
    int ry = root(y);
    if (rx == ry) return;
    if (siz[rx] < siz[ry]) swap(rx, ry);
    siz[rx] += siz[ry];
    par[ry] = rx;
  }

  bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }

  int size(int x) { // 素集合のサイズ
    return siz[root(x)];
  }
};
int leaf(int n) {
  int a=1;
  while(a<n) a *= 2;
  return a;
}


struct RMQ {

  /*　使い方まとめ　*/

  /*

  RMQ myvec(n) // 宣言 nは必要な要素数
  myvec.update(i,k) // 配列のi番目に要素kを格納
  myvec.at(i) // 配列のi番目にアクセス(0-index)
  myvec.rmin(i,j) // 配列の[i,j]の範囲の最小値を返す(0-index)

  */

  vector<int> value;

  RMQ(int n) : value(0) {
    int ct = leaf(n)*2-1;
    rep(i,0,ct) value.pb(INF); // 全部INF
  }

  void update(int i, int x) { // i 番目の葉の値を x に変える
    int N = (value.size()+1)/2;
    i += N - 1; // i 番目の葉のノード番号
    value[i] = x;
    while (i > 0) {
      i = (i - 1) / 2; // ノード i の親ノードの番号に変える
      value[i] = min(value[i * 2 + 1], value[i * 2 + 2]); // 左右の子のminを計算しなおす
    }
    return;
  }

  int at(int i) { //i番目の要素にアクセス
    int N = (value.size()+1)/2;
    return value[i-1+N];
  }

  int RMQ2(int a, int b, int k, int l, int r) {
    // [a, b) の区間に対するクエリについて
    // ノード k （区間 [l, r) 担当）が答える
    if (r <= a || b <= l) return INF; // 区間が被らない場合は INF を返す
    if (a <= l && r <= b)
      return value[k]; // ノード k の担当範囲がクエリ区間 [a, b)に完全に含まれる
    else {
      int c1 = RMQ2(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
      int c2 = RMQ2(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子に値を聞く
      return min(c1, c2); // 左右の子の値の min を取る
    }
  }

  int rmin(int a,int b) {
    int N = (value.size()+1)/2;
    return RMQ2(a,b+1,0,0,N);
  }
};

