const int MAXN = 2e5 + 1;

int n;
pii a[MAXN];
int t[4 * MAXN];

void build(int v, int l, int r) {
    if (l + 1 == r) {
        t[v] = a[l].second;
        return;
    }
    int m = (l + r) / 2;
    build(2 * v + 1, l, m);
    build(2 * v + 2, m, r);
    t[v] = max(t[2 * v + 1], t[2 * v + 1]);
}

void update(int v, int l, int r, int pos, int val) {
    if (l + 1 == r) {
        t[v] = val;
        return;
    }
    int m = (l + r) / 2;
    if (pos < m) update(2 * v + 1, l, m, pos, val);
    else update(2 * v + 2, m, r, pos, val);
    t[v] = max(t[2 * v + 1], t[2 * v + 2]);
}

int get(int v, int l, int r, int askl, int askr) {
    if (l >= askr || r <= askl) return 0;
    if (l >= askl && r <= askr) return t[v];
    int m = (l + r) / 2;
    return max(get(2 * v + 1, l, m, askl, askr), get(2 * v + 2, m, r, askl, askr));
}

int ind(int i) {
    int l = i, r = n, mid;
    while (r - l > 1) {
        mid = (l + r) / 2;
        if (a[mid].first < a[i].first + a[i].second) l = mid;
        else r = mid;
    }
    return l;
}

