    A[N] = pll(INF, INF);
    memset(dp, 0, sizeof(dp));
    SegmentTree<ll> seg([](ll a, ll b) { return std::max(a, b); }, 0);
    seg.init(N + 1);
    dp[N] = 1;
    mi[N] = N;
    seg.set(N, N);

    ll ans = 1;
    for (ll i = N - 1; i >= 0; --i) {
        //! 右からi番目を起動
        pll a = A[i];
        ll t = 0;
        ll ok = N + 1, ng = i;
        while (abs(ok - ng) > 1) {
            ll mid = (ok + ng) / 2;
            if (A[mid].first >= a.first + a.second)
                ok = mid;
