int xp[N];
int find(int l, int r, int x){
    int mid;
    while(l <= r){
        mid = (l + r) >> 1;
        if(xp[mid] < x) l = mid + 1;
        else r = mid - 1;
    }
    return r;
}

ll f[N];
int tree[N];
void update(int l, int r, int x, int y, int pp) {
  if (l == r) {
    //printf("%d -> %d\n",pp,y);
    tree[pp] = y; return;
  }
  int mid = (l + r) / 2, lp = pp * 2, rp = pp * 2 + 1;
  if (x <= mid) update(l, mid, x, y, lp);
  else update(mid+1, r, x, y, rp);
  tree[pp] = max(tree[lp], tree[rp]);
}
int query(int l, int r, int a, int b, int pp) {
  //printf("qry(%d,%d,%d)\n",l,r,pp);
  if(l == a && r == b) {
    return tree[pp];
  }
  int mid = (l + r) / 2, lp = pp * 2, rp = pp * 2 + 1;
  if (b <= mid) return query(l, mid, a, b, lp);
  else if (a > mid) return query(mid+1, r, a, b, rp);
  else {
    return max(query(l, mid, a, mid, lp), query(mid+1, r, mid+1, b, rp));
  }  
}
