		while (S.size() && S.begin()->first < x+d) {
			to[i].push_back(S.begin()->second);
			S.erase(S.begin());
		}
		S.emplace(x, i);
	}
	mint ans = 1;
	for (auto x:S) {
		int v = x.second;
		ans *= dfs(v);
	}

	return 0;
}

