const int mod = 998244353;
int GM(int x){
    return x >= mod? x-mod : x;
}

int main()
{
    int n;;
    scanf("%d",&n);
    vector <pair<int ,int>> robs(n);
    for(auto&r : robs)
        scanf("%d%d",&r.first,&r.second);
    sort(robs.begin() ,robs.end());

    vector <int> to(n); to[n-1] = n;
    deque <int> dq{n-1};
    for(int i=n-2; ~i; i--){
        int rch = lower_bound(robs.begin() ,robs.end() ,make_pair(robs[i].first+robs[i].second ,-1))-robs.begin()-1;
        to[i] = rch+1;
        if(i < rch)
            to[i] = max(to[i] ,to[*prev(upper_bound(dq.begin() ,dq.end() ,rch))]);
        while(!dq.empty() && to[dq.front()] <= to[i])
            dq.pop_front();
        dq.push_front(i);
    }

    vector <int> dp(n+1); dp[n] = 1;
    for(int i=n-1; ~i; i--)
        dp[i] = GM(dp[i+1]+dp[to[i]]);
    printf("%d\n",dp[0]);
}

