template <typename Mod_t> class modint {
    constexpr static auto mod() { return Mod_t::value; }
public:
    Type value;
    constexpr modint() : value(){}
    constexpr modint(const Type &x) noexcept {if (-mod() <= x && x < mod()) value = static_cast<Type>(x); else value = static_cast<Type>(x % mod());if (value < 0) value += mod();}
    const Type &operator()() const { return value; }
    template<typename U> explicit operator U() const { return static_cast<U>(value); }
    constexpr modint operator+(const modint rhs) const noexcept {return modint(*this) += rhs;}
    constexpr modint operator-(const modint rhs) const noexcept {return modint(*this) -= rhs;}
    constexpr modint operator*(const modint rhs) const noexcept {return modint(*this) *= rhs;}
    constexpr modint operator/(const modint rhs) const noexcept {return modint(*this) /= rhs;}
    constexpr modint &operator+=(const modint rhs) noexcept {        value += rhs.value;        if (value >= mod()) {            value -= mod();        }        return *this;    }
    constexpr modint &operator-=(const modint rhs) noexcept {        if (value < rhs.value) {            value += mod();        }        value -= rhs.value;        return *this;}
    constexpr modint &operator*=(const modint rhs) noexcept {value = value * rhs.value % mod();return *this;}
    constexpr modint &operator/=(const modint& rhs) noexcept {return operator*=(minv(rhs.value));}
    modint &operator++() { return *this += 1; }
    modint &operator--() { return *this -= 1; }
    modint operator++(signed) {modint result(*this);*this += 1;return result;}
    modint operator--(signed) {modint result(*this);*this -= 1;return result;}
    modint operator-() const { return modint(-value); }
    template<typename U> friend bool operator==(const modint<U> &lhs, const modint<U> &rhs);
    template<typename U> friend bool operator<(const modint<U> &lhs, const modint<U> &rhs);
    template<typename U> friend std::istream &operator>>(std::istream &stream, modint<U> &number);
    operator int() { return value; }
};
