int get_nxt(int i){
	int &ret=nxt[i];
	if(~ret) return ret;
	if(i>=n-1) return ret=n;
	ll myr=p[i].f+p[i].s;
	for(int j=i+1;j<n;j++){
		ll adj=p[j].f;
		if(adj>=myr){
			ret=max(ret,j);
			break;
		}
		ret=max(ret,get_nxt(j));
	}
	return ret;
}

ll solve(int i){
	ll &ret=dp[i];
	if(~ret) return ret;
	if(i>=n) return ret=1;
	ret=solve(i+1);
	ret=add(ret,solve(nxt[i]));
	return ret;
}

