int build(int idx, int l, int r) {
    if (l == r) return tree[idx] = -INF;
    return tree[idx] = max(build(idx * 2, l, mid), build(idx * 2 + 1, mid + 1, r));
}
int modify(int idx, int l, int r, int i, int val) {
    if (l == r) return tree[idx] = val;
    if (i <= mid) return tree[idx] = max(tree[idx], modify(idx * 2, l, mid, i, val));
    else return tree[idx] = max(tree[idx], modify(idx * 2 + 1, mid + 1, r, i, val));
}
int query(int idx, int l, int r, int x, int y) {
    int res = -INF;
    if (x <= l && y >= r) return tree[idx];
    if (x <= mid) res = max(res, query(idx * 2, l, mid, x, y));
    if (y > mid) res = max(res, query(idx * 2 + 1, mid + 1, r, x, y));
    return res;
}

