struct segtree {
	vector<int>node; int n;
	void init(int N) {
		n = 1;
		while (n < N) {
			n *= 2;
		}
		node.resize(2 * n, -inf);
	}
	void upd(int a, int x) {
		a += n - 1;
		node[a] = x;
		while (a > 0) {
			a = (a - 1) / 2;
			node[a] = max(node[2 * a + 1], node[2 * a + 2]);
		}
	}
	int calc(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)return -inf;
		if (a <= l&&r <= b)return node[k];
		int vl = calc(a, b, k * 2 + 1, l, (l + r) / 2);
		int vr = calc(a, b, k * 2 + 2, (l + r) / 2, r);
		return max(vl, vr);
	}
	int get(int a, int b) {
		return calc(a, b, 0, 0, n);
	}
};

