        seg.resize(4*n,0);
    }
    void update(int idx, int l, int r, int f, int g){
        if(l>f || r<f) return;
        seg[idx]=max(seg[idx],g);
        if(l==r) return;
        int m=(l+r)/2;
        update(2*idx,l,m,f,g);
