    int m = std::lower_bound(rag(xs), ps[v].first + ps[v].second) - std::begin(xs);

    int res = v + 1;

    for (int i = v + 1; i < m; ++i)
    {
        res = std::max(res, dfs(i));
    }

    return next[v] = res;
}

int main()
{
    int n;

    std::cin >> n;

    ps.resize(n);
    xs.resize(n + 1);

    rep(i, n)
    {
        std::cin >>
            ps[i].first >> ps[i].second;
        xs[i] = ps[i].first;
    }
    xs[n] = INF;
    std::sort(rag(xs));
    std::sort(rag(ps));

    dp[n] = 1;

    for (int i = n - 1; i >= 0; --i)
    {
        dp[i] = dp[dfs(i)] + dp[i + 1];
        //std::cerr << dp[i] << std::endl;
    }

    std::cout << dp[0] << std::endl;

    return 0;
}

