seg segs[MX];

int solve(int l, int r) {
	if (r < l)
		return 1;
	int cur = 1;
	int ind = l + 1;
	while (ind <= r) {
		cur = cur * solve(ind, segs[ind].r) % MOD;
		ind = segs[ind].r + 1;
	}
	cur = (cur + 1) % MOD;
	return cur;
}

