        T[idx]=min(T[k],T[k+1]);
    }
}

int get(int idx, int l, int r, int u, int v) {
    if(r<u||l>v) return 1e9+7;
    if(u<=l&&r<=v) return T[idx];
    else {
        int k=2*idx, mid=(l+r)>>1;
        return min(get(k,l,mid,u,v),get(k+1,mid+1,r,u,v));
    }
}

int pos(int p, int x) {
