void inc(int x, int v) {
    t[x += n] = v;
    for (x >>= 1; x; x >>= 1) t[x] = max(t[x << 1], t[x << 1 | 1]);
}

int que(int l, int r) {
    int z = 0;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
        if (l & 1) z = max(z, t[l++]);
        if (r & 1) z = max(z, t[--r]);
    }
    return z;
}

