  }
  sort(ps.begin(), ps.end());
  for (int i = 0; i < n; i++) {
    mp[ps[i].first] = 0;
    mp[ps[i].first + ps[i].second] = 0;
  }
  int c = 0;
  vector<ll> inv;
  for (auto &it  : mp) {
    it.second = c++;
    inv.push_back(it.first);
  }
  inv.push_back(10000000000000LL);
  tRMQ<ll> r = maxrmq(c);
  for (int i = 0; i < c; i++)r.update(i, i);
