struct Robot;
struct RobotParam {
    int begin;
    int end;
    std::shared_ptr<Robot> robot{nullptr};
};
std::istream& operator>>(std::istream& is, RobotParam& robot)
{
    is >> robot.begin >> robot.end;
    robot.end += robot.begin;

    return is;
}

struct Robot : std::enable_shared_from_this<Robot> {
    std::shared_ptr<Robot> parent;
    int rank;
    long cases = 1;

private:
    Robot()
        : parent{nullptr}, rank{0}
    {
    }

    explicit Robot(std::shared_ptr<Robot> const& _parent)
        : parent{_parent}, rank{_parent->rank + 1}
    {
    }

public:
    static std::shared_ptr<Robot> base;

    static std::shared_ptr<Robot> create(std::shared_ptr<Robot> const& parent)
    {
        return std::shared_ptr<Robot>{new Robot{parent}};
    }
};
std::shared_ptr<Robot> Robot::base = std::shared_ptr<Robot>{new Robot};

int main()
{
    int N;
    std::cin >> N;

    std::vector<std::shared_ptr<Robot>> robots;
    robots.reserve(N);

    {
        std::vector<RobotParam> params;
        params.reserve(N);

        std::copy(std::istream_iterator<RobotParam>{std::cin}, std::istream_iterator<RobotParam>{},
            std::back_inserter(params));

        std::sort(params.begin(), params.end(), [](auto const& lhs, auto const& rhs) {
            return lhs.begin < rhs.begin;
        });

        std::vector<RobotParam> movement;
        movement.reserve(N);

        for (auto& param : params) {
            // std::cout << "thinking about: [" << param.begin << ", " << param.end << ')' << std::endl;

            while (!movement.empty() && movement.back().end <= param.begin) {
                // std::cout << "\t\trobot won't reach: [" << movement.back().begin << ", " << movement.back().end << ')' << std::endl;
                movement.pop_back();
            }

            std::shared_ptr<Robot> new_robot;
            if (movement.empty()) {
                // std::cout << "\tno robots reach" << std::endl;
                new_robot = Robot::create(Robot::base);
            } else {
                // std::cout << "\trobot reach: [" << movement.back().begin << ", " << movement.back().end << ')' << std::endl;
                new_robot = Robot::create(movement.back().robot);
            }

            param.robot = new_robot;
            robots.push_back(new_robot);
            movement.push_back(param);
        }
    }

    std::sort(robots.begin(), robots.end(),
        [](auto const& lhs, auto const& rhs) {
            return lhs->rank > rhs->rank;
        });

    for (auto const& robot : robots) {
        robot->parent->cases *= robot->cases + 1;
        robot->parent->cases %= 998244353;
    }

    std::cout << Robot::base->cases;

    return 0;
}

