static constexpr char nl='\n';
template <typename T1,typename T2> static inline const T1 &pe0(const std::pair<T1,T2> &p) { return p.first; }
template <typename T1,typename T2> static inline const T2 &pe1(const std::pair<T1,T2> &p) { return p.second; }
template <typename T1,typename T2> static inline T1 &pe0(std::pair<T1,T2> &p) { return p.first; }
template <typename T1,typename T2> static inline T2 &pe1(std::pair<T1,T2> &p) { return p.second; }
template <typename Tf> static inline void rep(int n, Tf f) { for ( int i=0; i<n; i++ ) { f(i); } }
template <typename Tf> static inline void repr(int n, Tf f) { for ( int i=n-1; i>=0; i-- ) { f(i); } }
template <typename T> static inline int blen(T n) {
  int i=0;
  while ( n>0 ) { i++; n>>=1; }
  return i;
}
template <typename Te,typename Tc> class segtree {
private:
  const int _n,_n2;
  const Tc _f;
  const Te _e;
  vec<Te> _ctn;
public:
  segtree(int n,Tc f,Te e): _n(n),_n2(1<<(1+blen(n))),_f(f),_e(e) {
    _ctn.assign(_n2-1,e);
  }
  const Te &operator[](int p) const {
    return _ctn[p];
  }
  void set(int p,Te val) {
    _ctn[p]=val;
    for ( int pprev=p,prdist=_n2-p,pnext; (prdist&1)==0&&prdist>2; pprev=pnext ) {
      prdist>>=1;
      pnext=_n2-prdist;
      _ctn[pnext]=val=_f(val,_ctn[pprev+1]);
    }
  }
  Te get(int ib,int ie) {
    int w=1<<(blen(ib^ie)-1);
    int rm=(ib&ie&~(w-1))|w;
    Te ret=_e;
    for ( int rt=rm,wt=w; ib<rt; wt>>=1 ) {
      if ( rt-wt<ib ) continue;
      ret=_f(ret,_ctn[_n2-(_n2-rt)/wt-1]);
      rt-=wt;
    }
    for ( int rt=rm,wt=w; rt<ie; wt>>=1 ) {
      if ( ie<rt+wt ) continue;
      ret=_f(ret,_ctn[_n2-(_n2-rt)/wt]);
      rt+=wt;
    }
    return ret;
  }
};
int solve(int n,vec<intp> xds) {
  constexpr int M=998244353;
  std::sort(xds.begin(),xds.end());
  vec<int> ys(n);
  rep(n,[&](int i){
    intp bound(pe0(xds[i])+pe1(xds[i]),0); // 0: dummy
    auto ib=xds.begin(),ie=xds.end();
    auto lb=std::lower_bound(ib,ie,bound);
    ys[i]=lb==ie ? n : lb-ib;
  });
  auto fmax=[](int a,int b)->int{ return a>b ? a : b; };
  segtree<int,decltype(fmax)> sgt(n,fmax,-1);
  repr(n,[&](int i){
    sgt.set(i,ys[i]==i+1 ? i+1 : sgt.get(i+1,ys[i]));
  });
  vec<int> cs(n+1,0);
  cs[0]=1;
  rep(n,[&](int i){
    cs[i+1]=(cs[i+1]+cs[i])%M;
    cs[sgt[i]]=(cs[sgt[i]]+cs[i])%M;
  });
  return cs[n];
}

void doit(std::istream &sin, std::ostream &sout) {
  int n;
  sin >> n;
  vec<intp> xds(n);
  rep(n,[&](int i){
    sin >> pe0(xds[i]) >> pe1(xds[i]);
  });
  int ans=solve(n,xds);
  sout << ans << nl;
}
int main(void) {
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(nullptr);
  doit(std::cin,std::cout);
}

