int update( int k , ll x){// upsege with a point
        // [a,b) is target interval
        // x is the value added on interval
        // k is node id
        // [l,r) is current interval
        k += n-1;//first n-2 node is not leaf,last n nodes are leaf,adjust target position
        seg[k]  = x; // upsege the very point
        while( k > 0 ){// upsege to the root , root == 0
                k = (k - 1 ) /2;//find the father id
                seg[k] = max(seg[k*2+1] , seg[k*2+2] );//upsege the sum of father node
        }
        return 0;
}
ll query_max( int a , int b , int k , int l , int r ){// query sum of value with a span [a,b) , k is  node  index ,  node range [l,r)
        if( b <= l || r <= a ){// no overlap part
                return 0;
        }
        else if( a <= l && r <= b ){// wholely overlap
                return seg[k];//current node value
        }
        else{//partly overlap [l,r)
                ll res = 0;
                res =  query_max( a , b , k * 2 + 1 , l , (l+r)/2 ); //search left child 
                res = max( res , query_max( a , b , k * 2 + 2 , (l+r)/2 , r ));//search right child
                return res;
        }
}

