    m[-INF] = -INF;
    for (int i = n-1; i >= 0; --i) {
        int x, d;
        tie(x, d) = a[i];
        auto it = prev(m.lower_bound(x+d));
        int v = max(x+d, it->second);
        m[x] = v;
        a[i].second = v;
    }

    vector<pair<int, int>> evt;
    for (auto &e: a) {
        evt.emplace_back(e.first, 1);
        evt.emplace_back(e.second, 0);
    }
    sort(evt.begin(), evt.end());

    stack<mint> st;
    st.push(1);
    for (auto &e: evt) {
        if (e.second == 1) {
            st.push(1);
        } else if (e.second == 0) {
            mint t = st.top();
            st.pop();
            st.top() *= (t+1);
        }
    }

    cout << st.top() << endl;

    return 0;
