LL __uw;
void update(int l,int r,int rt){
    if(l==r){
        mx[rt]=__uw;
        return;
    }
    int mid=(l+r)>>1;
    if(__ul<=mid) update(lson);
    else update(rson);
    mx[rt]=max(mx[ls],mx[rs]);
}

int __ql,__qr;
int query(int l,int r,int rt){
    if(__ql<=l&&r<=__qr){
        return mx[rt];
    }
    int mid=(l+r)>>1;
    if(__qr<=mid) return query(lson);
    else if(__ql>mid) return query(rson);
    else return max(query(lson),query(rson));
}
