using namespace std;
#define  ll long long
#define ld long double
#define f first
#define s second
const int N = 2e5+5;

ll n , dp[N] , dp2[N] , mod = 998244353;
pair<ll,ll> seg[4*N];
vector< pair<ll,ll> > v;

void build(int node , int st , int en)
{
    if (st==en)
    {
        seg[node] = {v[st].f+v[st].s-1 , st};
        return;
    }
    int mid = (st+en)/2;
    build(2*node , st , mid);
    build(2*node+1 , mid+1 , en);
    seg[node] = max(seg[2*node] , seg[2*node+1]);
}

pair<ll,ll> query(int node , int st , int en , int l , int r)
{
    if (st > r || en < l) return {-2e9,-2e9};

    if (st >= l && en <= r)
        return seg[node];

    int mid = (st+en)/2;
    return max(query(2*node , st , mid , l , r) , query(2*node+1 , mid+1 , en , l , r));
}

ll solve(int i)
{
    if (i==n+1)
        return dp[i] = i;

    if (dp[i] != -1)
        return dp[i];

    ll ans = i+1 , up , idx , tmp , l , r;
    up = upper_bound(v.begin() , v.end() , make_pair(v[i].f+v[i].s-1 , (ll)3e9)) - v.begin();
    if (up == v.size() || up == i+1) ans = up;
    else
    {
        l = i+1 , r = up-1;
        idx = query(1,1,n,l,r).s;
        ans = max(ans , up);
        if (idx > i) ans = max(ans , solve(idx));
    }
    return dp[i] = ans;
}

ll solve2(int i)
{
    if (i > n)
        return 1;

    if (dp2[i] != -1)
        return dp2[i];

    ll ans = solve2(i+1);

    ans += solve2(dp[i]);
    ans %= mod;

    return dp2[i] = ans;
}

int main()
{
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

    cin >> n;
    for(int i=1; i<=n; i++)
    {
        ll x,d;
        cin >> x >> d;
        v.push_back({x,d});
    }
    v.push_back({-3e9,-3e9});
    sort(v.begin() , v.end());
    build(1,1,n);

    memset(dp , -1 , sizeof(dp));
    memset(dp2 , -1 , sizeof(dp2));

    for(int i=1; i<=n; i++)
    {
        solve(i);
    }

    cout << solve2(1) << "\n";

    return 0;
}

