struct Bit {
    inline int lowbit(int i) { return i & (-i); }

    T dat[N];

    void clear(int n) {
        memset(dat, 0, sizeof(T) * (n + 1));
    }

    inline void add(int i, T x) {
        ++i;
        for (; i<N; i+=lowbit(i))
            dat[i] = (dat[i] + x) % MOD;
    }

    inline T sum(int i) {
