void solver::run(){
    if(!input()) return;
    sort(ALL(XD));
    SegmentTree<int> max_next(N, [](int a, int b){return max(a, b);}, -INF);
    for (int i = N - 1; i >= 0; --i) {
        size_t lb = lower_bound(ALL(XD), tuple<int, int>{get<0>(XD[i])+get<1>(XD[i]), -1}) - XD.begin();
        max_next.update(i, max(i, max_next.query(i, lb)));
    } // end i

    auto dp = VEC(N, 0_mod);
    dp[0] = 1;
    dp[max_next[0]] += 1;
    for (int i = 1; i < N; ++i) {
        dp[i] += dp[i-1];
        dp[max_next[i]] += dp[i-1];
    } // end i
    os << dp.back() << endl;
}

