ll mod = 998244353;
ll d[200001];
ll dp[200001][2];
ll tree[800001];
ll n;
void Update(int node, int x, int y, int i, int val) {
	if (x > i || y < i)return;
	if (x == y) {
		tree[node] = val;
	}
	else {
		int mid = (x + y) / 2;
		Update(node * 2, x, mid, i, val);
		Update(node * 2 + 1, mid + 1, y, i, val);
		tree[node] = max(tree[node * 2], tree[node * 2 + 1]);
	}
}
int Quary(int node, int x, int y, int i, int j) {
	if (x > j || y < i)return 0;
	if (i <= x && y <= j)return tree[node];
	int mid = (x + y) / 2;
	return max(Quary(node * 2, x, mid, i, j), Quary(node * 2 + 1, mid + 1, y, i, j));
}
ll go(int x, int y) {
	if (x == n) {
		if (y == 1)return 1;
		return 0;
	}
	if (dp[x][y] != -1)return dp[x][y];
	ll &ret = dp[x][y];
	ret = 0;
	if (y == 0) {
		ret += go(x + 1, 0); ret %= mod;
		ret += go(x + 1, 1); ret %= mod;
	}
	else {
		ret += go(d[x] + 1, 0); ret %= mod;
		ret += go(d[x] + 1, 1); ret %= mod;
	}
	return ret;
}

