struct Graph{
    struct Edge{
        int from;
        int to;
        ll cost;
        Edge(int a, ll b) : to(a), cost(b) {}
        Edge(int a, int b, ll c) : from(a), to(b), cost(c) {}
    };

    int N;  //頂点数
    vector<vector<Edge>> edges;   //隣接リスト
    vector<ll> dist;   //ノードの深さ
    ll diam;            //木の直径
    vector<int> deg;    //入次数
    vector<int> cycle;  //サイクル

    Graph(int n) : N(n), edges(n), dist(n, INF), diam(INF), deg(n, 0){}

    void connect(int a, int b, ll c){   //辺を追加
        edges[a].emplace_back(Edge(a, b, c));
        deg[b]++;
    }

    bool visited(int v){
        return dist[v] < INF;
    }

    void resetDist(){
        for(int i=0; i<N; i++){
            dist[i] = INF;
        }
    }

    ll dfs(int p, int v){    //深さ優先探索
        if(visited(v)) return 0;

        dist[v] = 1;

        ll res = 1;

        /*
        if(edges[v].size() == 0){
            return 1;
        }else if(edges[v].size() == 1){
            return dfs(v, edges[v][0].to) + 1;
        }
        */

        for(auto e : edges[v]){
            if(e.to == p) continue;
            ll r = dfs(v, e.to) + 1;
            res *= r;
            res %= MOD;
        }

        if(p == -1) res++;
        return res;
    }
};


