      ll tmp=(l+r)>1;
      if(a[tmp].first>v) {
        r=tmp;
      }
      else {
        l=tmp;
      }
    }
    dp.Set(i,i+1,l);
    dp.Set(i,i+1,dp.Getmin(l,i+1));
    ans[i+1]=(ans[i]+ans[dp.Getmin(i,i+1)])%mod;
  }
  cout << ans[n] << endl;
}

