template<class T>
class SegmentTree {
public:
    SegmentTree(int n_ = 0) :firstNum(std::numeric_limits<T>::min()) {
        n = 1;
        while (n < n_) n *= 2;
        data.resize(2 * n);
        std::fill(data.begin(), data.end(), firstNum);
    }
    void resize(int n_) { *this = { n_ }; }
    T comp(T a, T b) { return std::max(a, b); }
    // d[k] = a
    void update(int k, int a) {
        k += n - 1;
        data[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            data[k] = comp(data[k * 2 + 1], data[k * 2 + 2]);
        }
    }
    // comp() [a,b)
    // a, b, k = 0, l = 0, r = st.n
    T query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return firstNum;
        if (a <= l && r <= b) return data[k];
        else {
            T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return comp(vl, vr);
        }
    }

    int n;
private:
    const T firstNum;
    std::vector<T> data;
};

