struct segtree{
	vector<int> dat;
	int m;
	segtree(int n){
		for(m = 1; m < n; m *= 2);
		dat.assign(m * 2 - 1, -1);
	}
	void update(int k, int v){
		k += m - 1;
		dat[k] = v;
		while(k){
			k = (k - 1) / 2;
			dat[k] = max(dat[k], v);
		}
	}
	int query(int a, int b){
		return query(a, b, 0, 0, m);
	}
	int query(int a, int b, int k, int l, int r){
		if(b <= l || r <= a){ return -1; }
		if(a <= l && r <= b){ return dat[k]; }
		int md = (l + r) >> 1;
		int x = query(a, b, k * 2 + 1, l, md);
		int y = query(a, b, k * 2 + 2, md, r);
		return max(x, y);
	}
};

