const ll RAW = 998244353;

class R {
public:
  ll x;
  ll d;
  ll c;
};

ll getA (vector<R>& A, int N, size_t i) {
  if (i >= N) {
    return (ll)1;
  }
  if (A[i].c != -1) {
    return A[i].c;
  }

  auto bound = A[i].x + A[i].d;
  size_t up_i = i + 1;
  for (; up_i < N; ++up_i) {
    if (A[up_i].x < bound) {
      bound = max(bound, A[up_i].x + A[up_i].d);
    }
    if (A[up_i].x >= bound) {
      break;
    }
  }
  size_t down_i = i + 1;

  ll up, down;
  if (up_i < N) {
    if (A[up_i].c == -1) {
      A[up_i].c = getA(A, N, up_i);
    }
    up = A[up_i].c;
  } else {
    up = 1;
  }
  if (down_i < N) {
    if (A[down_i].c == -1) {
      A[down_i].c = getA(A, N, down_i);
    }
    down = A[down_i].c;
  } else {
    down = 1;
  }

  return (A[i].c = ((up + down) % RAW));
};

