    for (li i = n - 1; i >= 0; --i) {
        li pos = lower_bound(xd + i + 1, xd + n, xd[i].F + xd[i].S, [](const PI & a, const li b) {
            return a.F < b;
        }) - xd;
        segtree.update(i, max(pos, segtree.query(i + 1, pos)));
