void buildma(ll v, ll tl, ll tr) 
{
    if (tl == tr) 
        t[v] = tl;
    else 
    {
        ll tm = (tl + tr) / 2;
        buildma(v*2, tl, tm);
        buildma(v*2+1, tm+1, tr);
        t[v] = max(t[2*v],t[(2*v)+1]);
    }
}

ll ma(ll v, ll tl, ll tr, ll l, ll r) 
{
    if (l > r) 
        return -C;
    if (l == tl && r == tr) 
        return t[v];
    ll tm = (tl + tr) / 2;
    return max(ma(v*2, tl, tm, l, min(r, tm)),ma(v*2+1, tm+1, tr, max(l, tm+1), r));
}

void updatema(ll v, ll tl, ll tr, ll pos, ll new_val) 
{
    if (tl == tr) 
        t[v] = max(new_val,t[v]);
    else 
    {
        ll tm = (tl + tr) / 2;
        if (pos <= tm)
            updatema(v*2, tl, tm, pos, new_val);
        else
            updatema(v*2+1, tm+1, tr, pos, new_val);
        t[v] = max(t[v*2],t[v*2+1]);
    }
}

