    build(1,0,n-1);
    sort(p,p+n);
    a[n-1] = n-1;
    update(1,0,n-1,n-1,n-1);
    for(ll i=n-2;i>=0;i--)
    {
        a[i] = i;
        pll range = {p[i].ff + p[i].ss,-1};
        ll temp = lower_bound(p,p+n,range) - p;
        ll maxi = sum(1,0,n-1,i+1,temp-1);
        a[i] = max(a[i],maxi);
        update(1,0,n-1,i,a[i]);
    }
    memset(dp,-1,sizeof(dp));
    ll ans1 = solve1(0);
    cout<<ans1;
}

