void dfs(ll i)
{
	dp[i]=1;
	ll k=vec[i].size();
	for(ll j=0;j<k;j++)
	{
		dfs(vec[i][j]);
		dp[i]=(dp[i]*dp[vec[i][j]])%mod;
	}
	dp[i] = (dp[i]+1)%mod;
}
