int N;
int tmp[SIZEN];
int cnt = 0;
int mx[SIZEN << 2] = {0};
void change(int rt,int l,int r,int x,int y){
	if(l == r){
		mx[rt] = y;
		return;
	}
	int mid = (l+r)>>1;
	if(x <= mid)change(rt<<1,l,mid,x,y);
	else change(rt<<1|1,mid+1,r,x,y);
	mx[rt] = max(mx[rt<<1],mx[rt<<1|1]);
}
int query(int rt,int l,int r,int x,int y){
	if(x <= l && y >= r){
		return mx[rt];
	}
	int mid = (l+r)>>1;
	if(y <= mid)return query(rt<<1,l,mid,x,y);
	if(x >  mid)return query(rt<<1|1,mid+1,r,x,y);
	return max(query(rt<<1,l,mid,x,y),query(rt<<1|1,mid+1,r,x,y));

}
bool cmp(const Robot &A,const Robot &B){
	return A.x < B.x;
}
