			MID = (L + R) >> 1;
			if(s[i].x + s[i].d > s[MID].x){
				tmp = MID;
				L = MID + 1;
			}
			else R = MID - 1;
		}
		mr[i] = max(i,query(1,1,n,i + 1,tmp)); modify(1,1,n,i,i,mr[i]);
		if(mr[i] == n) dp[i] = 1;
		else dp[i] = (suf[mr[i] + 1] + 1) % N;
		suf[i] = (suf[i + 1] + dp[i]) % N;
		ans = (ans + dp[i]) % N;
