template<typename Monoid>
class SegTree {

//半開区間!!!!!!!!!!!!!!!
public:
    int p = 2;
    vector<Monoid> node;
    using Func = function<Monoid(Monoid,Monoid)>;
    Func pick; Monoid init;//操作と単位元

    SegTree(vector<Monoid> A, string type, Monoid m) {
        if (type == "min") {
            pick = [](Monoid a, Monoid b){return min(a,b);};
        } else if (type == "max") {
            pick = [](Monoid a, Monoid b){return max(a,b);};
        } else if (type == "sum") {
            pick = [](Monoid a, Monoid b){return a + b;};
        }

        init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    SegTree(vector<Monoid> A, Func f, Monoid m) {
        pick = f; init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    //1点更新
    void update(int i, Monoid v) {
        for (node[(i+=p)-1] = v; i >>= 1;) {
            node[i-1] = pick(node[i*2-1], node[i*2]);
        }
    }

    //1点加算
    void add(int i, Monoid v) {
        update(i, this[i] + v);
    }

    Monoid getval(int start,int end,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = p;
        if (r <= start || end <= l) {return init;}
        if (start <= l && r <= end) {return node[k];}
        Monoid L,R;
        L = getval(start,end,k*2+1,l,(l+r)/2);
        R = getval(start,end,k*2+2,(l+r)/2,r);
        return {pick(L,R)};
    }

    inline Monoid operator [] (int i) {
        return node[i+p-1];
    }
};

int dp[200005];

void solve() {
    mod = 998244353;
    int n; cin >> n;
    vector<pair<int, int>> xd(n); rep (i, n) cin >> xd[i].first >> xd[i].second,xd[i].second+=xd[i].first;
    sort(all(xd));
    vector<int> st(n); rep (i, n) st[i] = xd[i].first;
    vector<int> fis(n); iota(all(fis), 0);
    SegTree<int> seg(fis, "max", -INF);
    dp[n] = 1;
    for (int i = n-1; i>=0; i--) {
        int pos = lower_bound(all(st), xd[i].second) - st.begin();
        seg.update(i, max(i, seg.getval(i, pos)));
        dp[i] = dp[i+1] + dp[seg[i]+1] % mod;
    }
    cout << dp[0] << endl;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

