void init(vector<int> &stree,int N){
    FOR(i,0,4*N) stree[i] = -1;
};
void update(vector<int> &stree,int N,int i, int x){
    i+= N - 1;
    stree[i] = x;
    while(i>0){
      i = (i-1)/2;
      stree[i] = max(stree[2*i+1], stree[2*i+2]);
    }
};
int query(vector<int> &stree,int N,int a, int b, int k, int l, int r){
    if(r<=a || b <= l) return -1;
    if(a<=l && r<=b) return stree[k];
    else{
      int vl = query(stree,N,a,b,k*2+1,l,(l+r)/2);
      int vr = query(stree,N,a,b,k*2+2,(l+r)/2,r);
      return max(vl,vr);
    }
};

