int kai(int x, int y) {
	int res = 1;
	for (int i = x - y + 1; i <= x; i++) {
		res *= i; res %= mod;
	}
	return res;
}
int mod_pow(int x, int y, int m) {
	int res = 1;
	while (y > 0) {
		if (y & 1) {
			res = res * x % m;
		}
		x = x * x % m;
		y >>= 1;
	}
	return res;
}

int comb(int x, int y) {
	if (y > x)return 0;
	return kai(x, y) * mod_pow(kai(y, y), mod - 2, mod) % mod;
}

int s = 1;
vector<int> dat;
void init(int n_) {
	while (s < n_)s *= 2;
	dat.resize(2 * s - 1);
	for (int i = s - 1; i <= n_ + s - 2; i++)dat[i] = i - (s - 2);
	for (int i = s - 2; i >= 0; i--)dat[i] = max(dat[2 * i + 1], dat[2 * i + 2]);
 }

void add(int k, int x) {
	k += s - 2;
	dat[k] = x;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = max(dat[2 * k + 1], dat[2 * k + 2]);
	}
}

int query(int a, int b, int k = 0, int l = 0, int r = s) {
	if (r <= a || b <= l)return 0;
	if (a <= l && r <= b)return dat[k];
	int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
	int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
	return max(vl, vr);
}

