void add2(int k, int x) {
	while (k <= n) {
		BIT[k] = (BIT[k] + x) % mod;
		k += k & -k;
	}
}

int sum(int k) {
	int res = 0;
	while (k > 0) {
		res = (res + BIT[k]) % mod;
		k -= k & -k;
	}
	return res;
}

