int head[maxn],fa[maxn],a[maxn],lz[maxn<<2],sgt[maxn<<2];
struct EDGE{
	int to,nxt;
}edge[maxn<<1];
void addedge(int u,int v){
	static int sz=0;edge[++sz].to=v;
	edge[sz].nxt=head[u];head[u]=sz;
}

void change(int id,int w){
	sgt[id]=w;
	lz[id]=w;
}

void pushdown(int id){
	if(lz[id]){
		change(lson(id),lz[id]);
		change(rson(id),lz[id]);
		lz[id]=0;
	}
}

int query(int id,int l,int r,int pos){
//	printf("Q %d %d %d %d\n",id,l,r,pos);
	if(l==r) return sgt[id];
	int mid=(l+r)/2;
	pushdown(id);
	if(pos<=mid)return query(lson(id),l,mid,pos);
	else return query(rson(id),mid+1,r,pos);
}

void update(int id,int l,int r,int L,int R,int w){
//	printf("U %d %d %d %d %d %d\n",id,l,r,L,R,w);
	if(l>=L&&r<=R){
		change(id,w);
		return ;
	}
	if(l>R||L>r) return ;
	int mid=(l+r)/2;
	pushdown(id);
	update(lson(id),l,mid,L,R,w);
	update(rson(id),mid+1,r,L,R,w);
}

