    vector<int> rights(N+1, -1);
    rrep(i,0,N) {
        auto itr = lower_bound(all(robots), make_pair(robots[i].first + robots[i].second, 0LL));
        int value;
        if (itr == robots.end()) {
            value =  N;
            st.update(i, value);
        } else {
            int j = distance(robots.begin(), itr);
            value = j != i+1 ? st.get(i+1, j) : i+1;
            st.update(i, value);
        }
        rights[i] = value;
    }
    dp[N-1][1] = 1;
    dp[N-1][0] = 1;
    rrep(i,0,N-1) {
        dp[i][1] = dp[i+1][1] + dp[i+1][0];
        if (rights[i] == N) {
            dp[i][0] = 1;
        } else {
            dp[i][0] = dp[rights[i]][0] + dp[rights[i]][1];
        }
        dp[i][1] %= MOD;
        dp[i][0] %= MOD;
    }
    cout << (dp[0][0] + dp[0][1]) % MOD << endl;
}

signed main(){
    long long N;
    scanf("%lld",&N);
    std::vector<long long> X(N);
    std::vector<long long> D(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&X[i]);
        scanf("%lld",&D[i]);
    }
    solve(N, std::move(X), std::move(D));
    return 0;
}

