struct dor {
	dor *l, *r;
	int sd;
} *rt;

const int LN = -1e9 - 5, NR = 2e9 + 5, mod = 998244353;

int M(long long l, long long r) {
	int m = (l + r) / 2;
	if(m == r) --m;
	return m;
}

int si, vl;
void rgnk(int l, int r, dor *&t) {
	if(t == NULL)
		t = new dor();
	if(l == r)
		t->sd = vl;
	else if((l + r) / 2 >= si)
		rgnk(l, M(l, r), t->l);
	else
		rgnk(M(l, r) + 1, r, t->r);
}

void gnk(int Si, int Vl) {
	si = Si, vl = Vl;
	rgnk(LN, NR, rt);
}

int sl, sr;
int rsgm(int l, int r, dor *&t) {
	if(l > sr || r < sl || t == NULL)
		return LN;
	if(l >= sl && r <= sr)
		return t->sd;
	return max(rsgm(l, M(l, r), t->l), rsgm(M(l, r) + 1, r, t->r));
}

int sgm(int l, int r) {
	sl = l, sr = r;
	return rsgm(LN, NR, rt);
}

