        while(siz<N)siz*=2;
        dat.resize(siz*2-1,-INF);
    }
    void update(int k,int x){
        k+=siz-1;
        dat[k]=x;
        while(k>0){
            k=(k-1)/2;
            dat[k]=max(dat[k*2+1],dat[k*2+2]);
