/**
 * 1-D Segment Tree data structure. Supports element updates and binary
 * associative operations over range like (addition, max, min) in logarithmic
 * time. Space usage is linear in n. Works with numeric data types like
 * 32/64 bit integers and doubles.
 */
template<class T>
class SegmentTree
{
public:
    SegmentTree(int _n, T _initial, const function<T(T, T)> _op)
    {
        n = _n;
        op = _op;
        initial = _initial;
        tree.clear();
        tree.resize(4 * n + 5, initial);
    }

    /** Updates a single element at index x to newval. */
    void update(int x, T newval)
    {
        stack<int> pathToX;
        int i = 0, l = 0, r = n - 1;
        while (l < x || r > x) {
            pathToX.push(i);
            int m = (l + r) / 2;
            if (x > m) {
                l = m + 1;
                i = 2 * i + 2;
            } else {
                r = m;
                i = 2 * i + 1;
            }
        }

        tree[i] = newval;

        // move back upto the root, updating all the nodes in the path.
        while (!pathToX.empty()) {
            int i = pathToX.top();
            pathToX.pop();
            tree[i] = op(tree[2 * i + 1], tree[2 * i + 2]);
        }
    }

    T rangeQuery(int x, int y)
    {
        return rangeQuery(x, y, 0, 0, n - 1);
    }
private:
    /** Returns the result of the operator performed over the entire 
      range specified by [x, y], both ends inclusive. */
    T rangeQuery(int x, int y, int i, int l, int r)
    {
        if (x > y)
            return initial;

        if (x <= l && y >= r)
            return tree[i];

        int m = (l + r) / 2;
        if (y <= m)
            return rangeQuery(x, y, 2 * i + 1, l, m);
        else if (x > m)
            return rangeQuery(x, y, 2 * i + 2, m + 1, r);

        T half1 = rangeQuery(x, m, 2 * i + 1, l, m);
        T half2 = rangeQuery(m + 1, y, 2 * i + 2, m + 1, r);
        return op(half1, half2);
    }

    int n;
    T initial;
    function<T(T, T)> op;
    vector<T> tree;
};
