template <class Monoid>
struct SegTree {
    using Func = function<Monoid(Monoid, Monoid)>;
    const Func F;
    const Monoid UNITY;
    int SIZE_R;
    vector<Monoid> dat;

    SegTree(int n, const Func f, const Monoid &unity) : F(f), UNITY(unity) { init(n); }
    void init(int n) {
        SIZE_R = 1;
        while (SIZE_R < n) SIZE_R *= 2;
        dat.assign(SIZE_R * 2, UNITY);
    }

    /* set, a is 0-indexed */
    void set(int a, const Monoid &v) { dat[a + SIZE_R] = v; }
    void build() {
        for (int k = SIZE_R - 1; k > 0; --k)
            dat[k] = F(dat[k * 2], dat[k * 2 + 1]);
    }

    /* update a, a is 0-indexed */
    void update(int a, const Monoid &v) {
        int k = a + SIZE_R;
        dat[k] = v;
        while (k >>= 1) dat[k] = F(dat[k * 2], dat[k * 2 + 1]);
    }

    /* get [a, b), a and b are 0-indexed */
    Monoid get(int a, int b) {
        Monoid vleft = UNITY, vright = UNITY;
        for (int left = a + SIZE_R, right = b + SIZE_R; left < right; left >>= 1, right >>= 1) {
            if (left & 1) vleft = F(vleft, dat[left++]);
            if (right & 1) vright = F(dat[--right], vright);
        }
        return F(vleft, vright);
    }
    inline Monoid operator[](int a) { return dat[a + SIZE_R]; }

    /* debug */
    void print() {
        for (int i = 0; i < SIZE_R; ++i) {
            cout << (*this)[i];
            if (i != SIZE_R - 1) cout << ",";
        }
        cout << endl;
    }
};

void solve(long long N, std::vector<long long> X, std::vector<long long> D) {

    vector<pair<int, int>> vp(N);
    rep(i, N) {
        vp[i].first = X[i];
        vp[i].second = X[i] + D[i];
    }
    sort(all(vp));

    vi dp(N + 1, 0);
    dp[N] = 1;
    SegTree<int> seg(N, [](int a, int b) { return max(a, b); }, 0);
    rrep(i, N) {
        dp[i] = dp[i + 1];

        int ri = lower_bound(all(vp), make_pair(vp[i].second, 0LL)) - vp.begin();
        ri = max(i + 1, seg.get(i, ri));
        dp[i] += dp[ri];
        dp[i] %= mod;

        seg.update(i, ri);
    }

    cout << dp[0] << endl;
}

