  all(sort, robot);

  vector<mint> dp(N+1, 0); // dp[i] = ロボットiのスイッチを入れたときの場合の数
  vector<mint> dp2(N+1, 0); // dp[i] = ロボットiのスイッチを入れないときの場合の数
  vector<int> right(N+1, 0); // right[i] = ロボットiのスイッチを入れたときに動くもっとも右にある要素のインデックス

  SegTree<int> T(N, 0, [](int a, int b){return max(a, b);});

  dp[N] = 1;
  dp2[N] = 0;
  right[N] = 0;
  rrep(i, N-1) {
    // robot[i].first + robot[i].second以上になるものを探したい
    auto it = all(lower_bound, robot, pii(robot[i].first + robot[i].second, 0));
    int j = it - robot.begin(); // iが接触しないロボットのうち左端のもの
    if (j == i+1) {
      right[i] = i;
      dp[i] = dp[i+1] + dp2[i+1];
    } else {
      right[i] = T.query(i+1, j);
      dp[i] = dp[right[i]+1] + dp2[right[i]+1];
    }
    T.update(i, right[i]);

    dp2[i] = dp[i+1] + dp2[i+1];
  }
  cout << dp[0] + dp2[0] << endl;

  return 0;
}

