int mxn11 = (int) (2e5 + 1);
vector<ll> t(4 * mxn11 + 1, 0);
vector<ll> tAdd(4 * mxn11 + 1, 0);

void build(int v, int vl, int vr) {
    if (vl == vr) {
        t[v] = vl;
    } else {
        int tmp = (vl + vr) >> 1;
        build(2 * v, vl, tmp);
        build(2 * v + 1, tmp + 1, vr);
        t[v] = max(t[2 * v], t[2 * v + 1]);
    }
}

/* void push(int v) {
     tAdd[2 * v] += tAdd[v];
     tAdd[2 * v + 1] += tAdd[v];
     t[v] += tAdd[v];
     tAdd[v] = 0;
 }*/

int get(int v, int vl, int vr, int l, int r) {
    if (l > r) return 0;
    if (vl == l && vr == r) {
        return t[v] + tAdd[v];
    }
    int tmp = (vl + vr) >> 1;
    // push(v);
    ll a = get(2 * v, vl, tmp, l, min(tmp, r));
    ll b = get(2 * v + 1, tmp + 1, vr, max(tmp + 1, l), r);
    return max(a, b);
}

void update(int v, int vl, int vr, int pos, int cnt) {
    if (vl == vr) {
        t[v] = cnt;
        return;
    }
    int tmp = (vl + vr) >> 1;
    //push(v);
    if (pos <= tmp) {
        update(2 * v, vl, tmp, pos, cnt);
    } else {
        update(2 * v + 1, tmp + 1, vr, pos, cnt);
    }
    t[v] = max(t[2 * v], t[2 * v + 1]);
}

