void update(int node , int st , int en , int idx , int val)
{
    if (st == en)
    {
        seg[node] = val;
        return;
    }
    int mid = (st+en)/2;
    if (idx >= st && idx <= mid) update(2*node , st , mid , idx , val);
    else update(2*node+1 , mid+1 , en , idx , val);
    seg[node] = max(seg[2*node] , seg[2*node+1]);
}

ll query(int node , int st , int en , int l , int r)
{
    if (st > r || en < l) return -2e9;

    if (st >= l && en <= r)
        return seg[node];

    int mid = (st+en)/2;
    return max(query(2*node , st , mid , l , r) , query(2*node+1 , mid+1 , en , l , r));
}

ll solve(int i)
{
    if (i > n)
        return 1;

    if (dp[i] != -1)
        return dp[i];

    ll ans = solve(i+1);

    ans += solve(nxt[i]);
    ans %= mod;

    return dp[i] = ans;
}

int UP(ll val)
{
    int up = upper_bound(v.begin() , v.end() , make_pair(val , (ll)3e9)) - v.begin();
    up--;
    return up;
}

