using namespace std;

class Node {
public:
	int start;
	int end;
	int mv;
	Node* left;
	Node* right;
	Node(int s, int e, int m = -1, Node* l = nullptr, Node* r = nullptr) : start(s), end(e), mv(m), left(l), right(r) {}
};

class Tree {
public:
	Node *root;
	Tree() {
		root = nullptr;
	}

	Node* buildTree(int start, int end, vector<int> &v) {
		if (start == end) {
			return new Node(start, end, v[start]);
		}
		int mid = (start + end) / 2;
		Node* res = new Node(start, end);
		res->left = buildTree(start, mid, v);
		res->right = buildTree(mid+1, end, v);
		res->mv = max(res->left->mv, res->right->mv);
		return res;
	}

	void updateNode(int index, int value, Node* node) {
		if (index < node->start || index > node->end) return;
		if (index == node->start && index == node->end) {
			node->mv = value;
			return;
		}
		updateNode(index, value, node->left);
		updateNode(index, value, node->right);
		node->mv = max(node->left->mv, node->right->mv);
	}

	int searchMax(int s, int e, Node* node) {
		if (s == node->start && e == node->end) {
			return node->mv;
		}
		if (s >= node->right->start) {
			return searchMax(s, e, node->right);
		}
		if (e <= node->left->end) {
			return searchMax(s, e, node->left);
		}
		return max(searchMax(s, node->left->end, node->left), searchMax(node->right->start, e, node->right));
	}
};

int main() {
	ios_base::sync_with_stdio(false);
	const int M = 998244353;
	int n;
	cin>>n;
	map<int, int> v;
	for (int i = 0; i < n; i++) {
		int x, d;
		cin>>x>>d;
		v[x] = x + d;
	}

	vector<int> pos, reach;
	for (auto &i : v) {
		pos.push_back(i.first);
		reach.push_back(i.second);
	}

	vector<int> dp(n);
	iota(dp.begin(), dp.end(), 0);

	vector<int64_t> DP(n);
	DP[n-1] = 2;

	Tree T = Tree();
	T.root = T.buildTree(0, n-1, dp);

	for (int i = n-2; i>=0; i--) {
		int index = lower_bound(pos.begin(), pos.end(), reach[i]) - pos.begin() - 1;
		int r = T.searchMax(i, index, T.root);
		T.updateNode(i, r, T.root);
		dp[i] = r;
		if (r == n-1) {
			DP[i] = (DP[i+1] + 1) % M;
		} else {
			DP[i] = (DP[i+1] + DP[r+1]) % M;
		}
	}

	cout<<DP[0]<<endl;
	return 0;
}

