	int s,e,m,v;
	node *l, *r;
	node(int _s, int _e):s(_s), e(_e){
		m=(s+e)/2;v=0;
		if (s!=e){l=new node(s,m);r=new node(m+1,e);}
	}
	void up(int x, int val){
		if (s==e){v=max(v,val);return;}
		if (x<=m)l->up(x,val);
		else r->up(x,val);
		v=max(l->v,r->v);
