template <typename T> static inline int blen(T n) {
  if ( n<=0 ) { return 0; }
  int md=std::numeric_limits<T>::digits;
  if ( n>=1<<(md-1) ) { return md; }
  int i=1;
  for ( T b=1; b<n; b<<=1 ) { i++; }
  return i;
}
template <typename Te,typename Tc> class segtree {
private:
  int _n,_n2;
  Tc _f;
  Te _e;
  vec<Te> _ctn;
public:
  segtree(int n,Tc f,Te e): _n(n),_f(f),_e(e) {
    int b=blen(n);
    _n2=1<<(b+1);
    _ctn.assign(_n2,e);
  }
  const Te &operator[](int p) const {
    return _ctn[p];
  }
  void set(int p,Te val) {
    _ctn[p]=val;
    if ( (p&1)!=0 ) return;
    for ( int i=p>>1,n2t=_n2>>1,pprev=p,pnext;
          (i&1)==0&&n2t>1;
          i>>=1,n2t>>=1,pnext=pprev ) {
      val=_f(val,_ctn[pprev+1]);
      pnext=_n2-n2t+i;
      _ctn[pnext]=val;
    }
  }
  Te get(int ib,int ie) {
    int w=1<<blen(ib^ie)-1;
    int rm=ib&ie&~(w-1)|w;
    Te ret;
    bool notset=true;
    for ( int rt=rm,wt=w; ib<rt; wt>>=1 ) {
      if ( rt-wt<ib ) continue;
      if ( notset ) {
        ret=_ctn[_n2-(_n2-rt)/wt-1];
        notset=false;
      }
      else {
        ret=_f(ret,_ctn[_n2-(_n2-rt)/wt-1]);
      }
      rt-=wt;
    }
    for ( int rt=rm,wt=w; rt<ie; wt>>=1 ) {
      if ( ie<rt+wt ) continue;
      if ( notset ) {
        ret=_ctn[_n2-(_n2-rt)/wt];
        notset=false;
      }
      else {
        ret=_f(ret,_ctn[_n2-(_n2-rt)/wt]);
      }
      rt+=wt;
    }
    return ret;
  }
};

int solve(int n,vec<intp> xds) {
  constexpr int M=998244353;
  std::sort(xds.begin(),xds.end());
  vec<int> ys(n);
  rep(n,[&](int i){
    intp bound(pe0(xds[i])+pe1(xds[i]),0); // 0: dummy
    auto ib=xds.begin(),ie=xds.end();
    auto lb=std::lower_bound(ib,ie,bound);
    ys[i]=lb==ie ? n : lb-ib;
  });
  auto fmax=[](int a,int b)->int{ return a>b ? a : b; };
  segtree<int,decltype(fmax)> sgt(n,fmax,n);
  repr(n,[&](int i){
    sgt.set(i,ys[i]==i+1 ? i+1 : sgt.get(i+1,ys[i]));
  });
  vec<int> cs(n+1,0);
  cs[0]=1;
  rep(n,[&](int i){
    cs[i+1]=(cs[i+1]+cs[i])%M;
    cs[sgt[i]]=(cs[sgt[i]]+cs[i])%M;
  });
  return cs[n];
}

void doit(std::istream &sin, std::ostream &sout) {
  int n;
  sin >> n;
  vec<intp> xds(n);
  rep(n,[&](int i){
    sin >> pe0(xds[i]) >> pe1(xds[i]);
  });
  int ans=solve(n,xds);
  sout << ans << nl;
}
