		it = lower_bound(xx.begin(), xx.end(), xd);
		ct = it - xx.begin();

		dp[i] = dp[i + 1];		// don't activate this one
		dp[i] = (dp[i] + dp[ct]) % MOD;	// activate this one
	}

	ans = dp[0];
