using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;

const ll MOD = 998244353;
const ll INF = 10000000000000;

ll modpow(ll x, ll n){
    ll res = 1, r = x;
    while(n){
        if(n % 2) res = res * r % MOD;
        r = r * r % MOD;
        n /= 2;
    }
    return res;
}

template<typename Monoid>
struct SegmentTree {
    using F = function<Monoid(Monoid, Monoid)>;

    int sz;
    vector<Monoid> seg;

    const F f;
    const Monoid M1;

    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
        sz = 1;
        while(sz < n) sz <<= 1;
        seg.assign(2 * sz, M1);
    }

    void set(int k, const Monoid &x) {
        seg[k + sz] = x;
    }

    void build() {
        for(int k = sz - 1; k > 0; k--) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    void update(int k, const Monoid &x) {
        k += sz;
        seg[k] = x;
        while(k >>= 1) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    Monoid query(int a, int b) {
        Monoid L = M1, R = M1;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
            if(a & 1) L = f(L, seg[a++]);
            if(b & 1) R = f(seg[--b], R);
        }
        return f(L, R);
    }

    Monoid operator[](const int &k) const {
        return seg[k + sz];
    }
};

int main()
{
    int n;
    cin >> n;
    P p[200005];
    for(int i = 0; i < n; i++){
        ll x, d;
        cin >> x >> d;
        p[i] = P(x, d);
    }
    sort(p, p + n);
    p[n] = P(INF, INF);
    ll dp[200005];
    int right[200005];
    SegmentTree<int> seg(n + 1, [](int a, int b){return max(a, b);}, 0);
    dp[n] = 1;
    right[n] = n;
    seg.update(n, n);
    for(int i = n - 1; i >= 0; i--){
        int k = lower_bound(p, p + n + 1, P(p[i].first + p[i].second, 0)) - p - 1;
        if(k == i) right[i] = i + 1;
        else right[i] = seg.query(i, k + 1);
        seg.update(i, right[i]);
        dp[i] = (dp[i + 1] + dp[right[i]]) % MOD;
    }
