int dfs(int i, const vii& tree) noexcept {
    if (tree[i].empty()) {
        return 2;
    } else {
        ll ans = 1;
        for (auto item : tree[i]) {
            ans *= dfs(item, tree);
            ans %= MOD;
        }
        return ans + 1;
    }
}

void solve(long long N, std::vector<long long> X, std::vector<long long> D) {
    using pll=pair<ll, ll>;
    using vpl=vector<pll>;
    vpl V(N);
    for (int i = 0; i < N; i++) {
        V[i] = make_pair(X[i], D[i]);
    }

    sort(V.begin(), V.end());
    sort(X.begin(), X.end());

    vii tree(N);
    set<pll> s;
    for (ll i = N - 1; i >= 0; i--) {
        int x = V[i].first, d = V[i].second;
        while (!s.empty() && s.begin()->first < x + d) {
            tree[i].push_back(s.begin()->second);
            s.erase(s.begin());
        }
        s.emplace(x, i);
    }

    ll ans = 1;
    for (auto&& root : s) {
        ans *= dfs(root.second, tree);
        ans %= MOD;
    }
    cout << ans << endl;
}

