class segtree {
  vector<int> t;
  int n;

  void update(int to, int from) {
    to += n - 1;
    t.at(to) = from;
    while (to) {
      to = (to - 1) / 2;
      t.at(to) = max(t.at(2 * to + 1), t.at(2 * to + 2));
    }
  }

  int query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return -inf;
    if (a <= l && r <= b) return t.at(k);
    return max(query(a, b, 2 * k + 1, l, (l + r) / 2), query(a, b, 2 * k + 2, (l + r) / 2, r));
  }

  public:
  segtree(vector<int> a) {
    n = 1;
    while (n < a.size()) n *= 2;
    for (int i = 0; i < n - 1; i++) t.push_back(-inf);
    for (int i = 0; i < a.size(); i++) t.push_back(a.at(i));
    for (int i = a.size(); i < n; i++) t.push_back(-inf);
    for (int i = n - 2; i >= 0; i--) t.at(i) = max(t.at(2 * i + 1), t.at(2 * i + 2));
  }

  void edit(int k, int to) {
    update(k, to);
  }

  int find(int l, int r) {
    return query(l, r, 0, 0, n);
  }
};

