int main() {
    int N;
    scanf("%d", &N);
    vector<pii> robots;
    for (int i = 0; i < N; i++) {
        int X, D;
        scanf("%d %d", &X, &D);
        robots.push_back(make_pair(X, D));
    }
    map<int, int> dp;
    set<pii> st;
    dp[INF] = 1;
    sort(robots.rbegin(), robots.rend());
    for (int i = 0; i < (int)robots.size(); i++) {
        int X = robots[i].first, D = robots[i].second;
        if (!i) {
            dp[X] = 2;
            st.insert(make_pair(X, X + D));
        } else {
            int dis = X + D;
            while (!st.empty() && st.begin()->first < dis) {
                dis = max(st.begin()->second, dis);
                st.erase(st.begin());
            }
            st.insert(make_pair(X, dis));
            //printf("X = %d dis = %d\n", X, dis);
            int touch = dp.lower_bound(dis)->first;
            dp[X] = (dp[touch] + dp[robots[i - 1].first]) % MOD;
        }
        //printf("X = %d dp = %d\n", X, dp[X]);
    }
    printf("%d\n", dp.begin()->second);
    return 0;
}

