int getMax(int p, int q, int pocz, int kon, int ind = 1) {
	// printf("getMax: %d, %d, %d ,%d,%d\n", p,q,pocz,kon,ind);
	if (p == pocz && q == kon) {
		return bi[ind];
	}
	int sr = (pocz + kon) / 2;
	if (q <= sr) return getMax(p,q,pocz,sr,2*ind);
	else if (p > sr) return getMax(p, q, sr + 1, kon, 2*ind + 1);
	return max(getMax(p,sr,pocz,sr, 2*ind), getMax(sr+1,q,sr+1,kon,2*ind + 1));
};

