int main() {

    int N;
    Scd(N);
    vii a(N);
    map<int,int> id;
    Rep(i,N){
        Scd2(a[i].first,a[i].second);
    }

    sort(a.begin(),a.end());

    Rep(i,N){
        id[a[i].first] = i;
    }

    auto f = []( int a, int b ){ return max(a,b); };
    SegmentTree<int> tom( f,0 );
    vi to(N,N-1);
    Rep(i,N){
        auto it = --id.upper_bound(a[i].first+a[i].second-1);
        if( it == id.end() ) continue;
        to[i] = it->second;
    }

    tom.build( to );

    RRep(i,N){
        // max([i,toa]) > to[i] => to[i] = max
        int from = i;
        int toa = tom.query(from,to[from]+1);
        while( toa > from ){
            from = toa;
            toa = tom.query(from,to[from]+1);
        }
        tom.upda(i,toa);
        to[i] = toa;
    }

//     Rep(i,N){
