//     }
//
    vector<modint> dp(N+1,0);
    dp[0] = 1;
    Rep(i,N){
        dp[i+1] += dp[i];
        dp[to[i]+1] += dp[i];
    }

    printf ("%lld\n", dp[N] );

    return 0;
}

