		else if(p == i) dp2[i] = (dp1[i + 1] + dp2[i + 1]) % MOD;
		else dp2[i] = (dp1[p + 1] + dp2[p + 1]) % MOD;
		dp1[i] = (dp1[i + 1] + dp2[i + 1]) % MOD;
	}
