inline void build(int now,int l,int r)
{
	t[now].l=l; t[now].r=r;
	if(l==r) {t[now].w=l; return;}
	int mid=(l+r)>>1;
	build(now<<1,l,mid); build(now<<1|1,mid+1,r); upd(now);
}

inline void add(int now,int x,int w)
{
	t[now].w=max(t[now].w,w);
	if(t[now].l==x&&t[now].r==x) {t[now].w=w; return;}
	int mid=(t[now].l+t[now].r)>>1;
	if(x<=mid) add(now<<1,x,w); else add(now<<1|1,x,w);
}

inline int q(int now,int l,int r)
{
	if(t[now].l==l&&t[now].r==r) return t[now].w;
	int mid=(t[now].l+t[now].r)>>1;
	if(l>=mid+1) return q(now<<1|1,l,r);
	else if(r<=mid) return q(now<<1,l,r);
	return max(q(now<<1,l,mid),q(now<<1|1,mid+1,r));
}

