using namespace std;
using ll = long long;

int n;

const ll MOD = 998244353;

vector<pair<int, int>> ds;

ll dp[200005];

class Seg{
public:
    int seg[200005*4];

    void update(int targ, int val, int l=0, int r=200005, int idx=1){
        if(targ<l||targ>r) return;
        if(l==r){
            seg[idx] = val;
            return;
        }
        int mid = (l+r)/2;
        update(targ, val, l, mid, idx*2);
        update(targ,val, mid+1, r, idx*2+1);
        seg[idx] = max(seg[idx*2], seg[idx*2+1]);
    }

    int query(int x, int y, int l=0, int r=200005, int idx=1){
        if(x>r || y<l) return 0;
        if(x<=l && r<=y) return seg[idx];
        int mid = (l+r)/2;
        return max(query(x,y,l,mid, idx*2), query(x,y,mid+1,r,idx*2+1));
    }
} seg;

ll dp_dfs(int a){
    if(a>=n) return 1;
    if(dp[a]!=-1) return dp[a];
    int val = seg.query(a,a);
    dp[a] = (dp_dfs(val) + dp_dfs(a+1))%MOD;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin>>n;
    for(int i=0;i<n;i++){
        int x, d;
        cin>>x>>d;
        ds.emplace_back(x, d);
    }
    sort(ds.begin(), ds.end());
    memset(dp, -1, sizeof(dp));
    for(int i=n-1;i>=0;i--){
        auto p = ds[i];
        pair<int, int> q = {p.first+p.second, 0};
        int lb = lower_bound(ds.begin(), ds.end(), q) - ds.begin();
        if(lb==i+1){
            seg.update(i, i+1);
        }else{
            int val = seg.query(i+1, lb-1);
            seg.update(i, val);
        }
    }
    ll ans = dp_dfs(0);
    cout<<ans;
    return 0;
}

