	inc(i, n) { X[i] = v[i].FI; }
	dec(i, n) {
		LL x = v[i].FI;
		LL d = v[i].SE;
		p[i] = LB(X, x + d);
		z[i] = max(st.fold_ID(i, p[i]), i + 1LL);
		LL zz = z[i];
		st.apply(i, AP(A = zz));
	}

	vector<MI> dp(n + 1);
	dp[n] = 1;
	dec(i, n) { dp[i] += dp[i + 1] + dp[z[i]]; }

	OUT(dp[0]);
}

