  vector<pair<int, int>> arr (n); // <pos, range>
  for (int i = 0; i < n; i++) {
    cin >> arr[i].first >> arr[i].second;
  }

  sort(arr.begin(), arr.end());

  SegTree seg (n + 5);
  for (int i = n - 1; i >= 0; i--) {
    seg.set(i, i);

    int ans = i;
    for (int k = 1 << 25; k != 0; k /= 2) {
      if (ans + k < n && arr[ans + k].first < arr[i].first + arr[i].second) {
        ans += k;
      }
    }

    int mx = seg.query(i, ans);
    seg.set(i, mx);
  }

  vector<pair<int, int>> stk;
  vector<int> roots;
  for (int i = 0; i < n; i++) {
    pair<int, int> cur = make_pair(i, seg.query(i, i));
    while (!stk.empty() && stk.back().second < cur.first) {
      stk.pop_back();
    }

    if (stk.empty()) {
      roots.push_back(cur.first);
    } else {
      adj[stk.back().first].push_back(cur.first);
    }

    stk.push_back(cur);
  }

  Modint ans (1);
  for (int u : roots) {
    dfs(u);
