            cout << (*this)[i];
            if (i != SIZE_R - 1) cout << ",";
        }
        cout << endl;
    }
};

void solve(long long N, std::vector<long long> X, std::vector<long long> D) {

    vector<pair<int, int>> vp(N);
    rep(i, N) {
        vp[i].first = X[i];
        vp[i].second = D[i];
    }
    sort(all(vp));

    vi dp(N + 1, 0);
    dp[N] = 1;
    SegTree<int> seg(N, [](int a, int b) { return max(a, b); }, 0);
    rrep(i, N) {
        int ri = lower_bound(all(vp), make_pair(vp[i].first + vp[i].second, 0LL)) - vp.begin();
        ri = max(i + 1, seg.get(i + 1, ri));
        dp[i] = (dp[i + 1] + dp[ri]) % mod;
        seg.update(i, ri);
    }

    cout << dp[0] << endl;
}

