typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;

void solve(){
    bool okay = false;
    string S, T, U;
    ll A, B, C, D, N, M, H, W, K, x, y, Q, idx, cnt, num, answer;
