int power(int a,int n)
{
    a %= mod;
    if(n == 1)return a;
    if(n == 0)return 1;
    if(n%2)return (a*(power((a*a)%mod,n/2)%mod))%mod;
    return power((a*a)%mod,n/2)%mod;
}

const int inf = (int) 1e18;

int inverse(int x){
    return power(x,mod-2)%mod;//little fermat....
}

int tree[4*maxn],n,dp1[maxn],dp2[maxn];
vector<pii>v(maxn);

void build(int no, int st, int la)
{
    if(st == la){
        tree[no] = st;
        return ;
    }
    int mid = (st+la)/2;
    build(2*no,st,mid);
    build(2*no+1,mid+1,la);
    if(v[tree[2*no]].se >= v[tree[2*no+1]].se){
        tree[no] = tree[2*no];
    }
    else tree[no] = tree[2*no+1]; 
}

int query(int no,int st,int la,int l,int r){

    if(l <= st && r >= la)return tree[no];
    if(l > la || r < st)return 0;
    int mid = (st+la)/2;
    int l1 = query(2*no,st,mid,l,r);
    int l2 = query(2*no+1,mid+1,la,l,r);
    if(v[l1].se >= v[l2].se)return l1;
    return l2;
}   

void solve(){
    cin >> n;
    FOR(i,1,n+1){cin >> v[i].f >> v[i].se;v[i].se += v[i].f-1;}
    sort(v.begin()+1,v.begin()+n+1);
    build(1,1,n);
    v[0].se = -inf;
    dp1[n+1] = 1;
    RFOR(i,n,0){
        pii p = {v[i].se+1,-inf};
        int j = lower_bound(v.begin()+i,v.begin()+n+1,p)-v.begin()-1;
        int max_in = query(1,1,n,i,j);
        if(v[max_in].se <= v[i].se)dp2[i] = dp1[j+1]%mod;
        else dp2[i] = dp2[max_in]%mod;
        dp1[i] = (dp1[i+1]+dp2[i])%mod;
    }
    cout << dp1[1] << "\n";
}

