using namespace std;
typedef long long ll;
int const N = 1002020;
struct Node {
  int x, d;
  friend bool operator<(Node a, Node b) {
    return a.x < b.x;
  }
} p[N];

int xp[N];
int find(int l, int r, int x){
    int mid;
    while(l <= r){
        mid = (l + r) >> 1;
        if(xp[mid] < x) l = mid + 1;
        else r = mid - 1;
    }
    return r;
}

ll f[N];
int tree[N];
void update(int l, int r, int x, int y, int pp) {
  if (l == r) {
    //printf("%d -> %d\n",pp,y);
    tree[pp] = y; return;
  }
  int mid = (l + r) / 2, lp = pp * 2, rp = pp * 2 + 1;
  if (x <= mid) update(l, mid, x, y, lp);
  else update(mid+1, r, x, y, rp);
  tree[pp] = max(tree[lp], tree[rp]);
}
int query(int l, int r, int a, int b, int pp) {
  //printf("qry(%d,%d,%d)\n",l,r,pp);
  if(l == a && r == b) {
    return tree[pp];
  }
  int mid = (l + r) / 2, lp = pp * 2, rp = pp * 2 + 1;
  if (b <= mid) return query(l, mid, a, b, lp);
  else if (a > mid) return query(mid+1, r, a, b, rp);
  else {
    return max(query(l, mid, a, mid, lp), query(mid+1, r, mid+1, b, rp));
  }  
}
int main() {
  int n; scanf("%d", &n);
  Rep(i, n) {
    scanf("%d%d", &p[i].x, &p[i].d);
  }  
  sort(p + 1, p + n + 1);
  Rep(i, n) xp[i] = p[i].x;
  f[n + 1] = 1;
  for (int i = n; i >= 1; --i) {
    int pos = find(i, n, p[i].x + p[i].d);
    if (pos >= n) pos = n;
    update(1, n, i, pos, 1);
    f[i] = f[i + 1];
    int qry = query(1, n, i, pos, 1);
    update(1, n, i, qry, 1);
    //cout<<pos<<endl;
    f[i] += f[qry + 1];

  } 
  cout << f[1] << endl;
  return 0;
}

