    }

    vector<int> ids(n);
    iota(ids.begin(), ids.end(), 0);
    sort(ids.begin(), ids.end(), [&](int i1, int i2){
        return x[i1] > x[i2];
    });

    stack<int> st;
    vector<mint> dp(n, 1);
    for (int i : ids) {
        while (!st.empty() && x[st.top()] < x[i] + d[i]) {
            dp[i] *= dp[st.top()];
            st.pop();
        }
        st.push(i);
        ++dp[i];
    }

    mint ans = 1;
    while (!st.empty()) {
        ans *= dp[st.top()];
        st.pop();
    }
    cout << ans << newl;

    return 0;
