const int mod = 998244353;
const int MAXN = 2 * 105000;

class SegmentTree {
private: 
  const long long INF = 1e18;
  vector<long long> tree;
  int n;
public:
  void init(int sz) {
    n = 1;
    while (n < sz) {
      n *= 2;
    }
    tree.assign(2 * n, -INF);
  }

  // l, r are in [0, n - 1]
  long long getMax(int l, int r) {
    l = n + l; r = n + r;
    long long res = -INF;

    while (l <= r) {
      if (l & 1) {
        res = max(res, tree[l]);
        l++;
      }
      if (r % 2 == 0) {
        res = max(res, tree[r]);
        r--;
      }
      l /= 2; r /= 2;
    }

    return res;
  }

  // pos is in [0, n - 1]
  void update(int pos, long long val) {
    pos = n + pos;
    tree[pos] = val;
    pos /= 2;
    while (pos >= 1) {
      tree[pos] = max(tree[pos * 2], tree[pos * 2 + 1]);
      pos /= 2;
    }
  }
};

