template <typename E>
mint dfs(GraphL<E> &graph) {
  mint ret = 1;
  vector<bool> visited(graph.n, false);
  auto dfs_in = [&](auto &Self, int node) -> void {
    visited[node] = true;
    for (auto &&e : graph.adj[node]) {
      if (!visited[e.to]) {
        Self(Self, e.to);
        dp[node] *= dp[e.to] + 1;
      }
    }
    dump(node, dp[node]);
  };
  for (int i = 0; i < graph.n; i++) {
    if (!visited[i]) {
      dfs_in(dfs_in, i);
      ret *= dp[i] + 1;
      dump(i, ret);
    }
  }
  return ret;
}


template <typename T, typename E, typename F, typename G, typename H, typename P>
struct LazySegmentTree {
  int N;
  T T_identity;
  E E_identity;
  F merge;      // (T, T) -> T
  G operate;    // (T, E) -> T
  H merge_op;   // (E, E) -> E
  P operate_ex; // (E, int) -> E
  vector<T> node;
  vector<T> lazy;
  LazySegmentTree(F mg, G op, H m_op, P op_ex, T tid, E eid,
      const vector<T> &vec = vector<T>())
      : T_identity(tid), E_identity(eid), merge(mg), operate(op),
        merge_op(m_op), operate_ex(op_ex) {
    build(vec);
  }
  void build(const vector<T> &vec) {
    int sz = vec.size();
    N = 1;
    while (N < sz) {
      N <<= 1;
    }
    node.resize(2 * N - 1, T_identity);
    lazy.resize(2 * N - 1, E_identity);
    for (int i = 0; i < sz; i++) {
      node[i + N - 1] = vec[i];
    }
    for (int i = N - 2; i >= 0; i--) {
      node[i] = merge(node[2 * i + 1], node[2 * i + 2]);
    }
  }
  inline void eval(int len, int k) {
    if (lazy[k] == E_identity) {
      return;
    }
    if (k * 2 + 1 < N * 2 - 1) {
      lazy[k * 2 + 1] = merge_op(lazy[k * 2 + 1], lazy[k]);
      lazy[k * 2 + 2] = merge_op(lazy[k * 2 + 2], lazy[k]);
    }
    node[k] = operate(node[k], operate_ex(lazy[k], len));
    lazy[k] = E_identity;
  }
  T update(int a, int b, E x, int k, int l, int r) {
    eval(r - l, k);
    if (r <= a || b <= l) {
      return node[k];
    }
    if (a <= l && r <= b) {
      lazy[k] = merge_op(lazy[k], x);
      return operate(node[k], operate_ex(lazy[k], r - l));
    }
    return node[k] = merge(update(a, b, x, k * 2 + 1, l, (l + r) / 2),
                           update(a, b, x, k * 2 + 2, (l + r) / 2, r));
  }
  T update(int a, int b, E x) {
    return update(a, b, x, 0, 0, N);
  }
  T query(int a, int b, int k, int l, int r) {
    eval(r - l, k);
    if (r <= a || b <= l) {
      return T_identity;
    }
    if (a <= l && r <= b) {
      return node[k];
    }
    T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
    T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
    return merge(vl, vr);
  }
  T query(int a, int b) {
    return query(a, b, 0, 0, N);
  }
  T operator[](const int idx) {
    return query(idx, idx+1, 0, 0, N);
  }
};

