    for(int i=N-1;i>=0;i--){
        ll x = vp[i].first;
        ll d = vp[i].second;
        auto S = st.lower_bound({x, i});
        auto E = st.lower_bound({x + d, i});
        mint res = 1;
        while(S != E){
            ll idx = S -> second;
            res *= dp[idx];
            S = st.erase(S);
        }
        dp[i] = res + 1;
        st.insert({x, i});
    }
    mint ans = 1;
    for(auto x : st) ans *= dp[x.second];
    cout << ans << endl;
}
