template <typename T>
struct SegmentTree{
	using F = function<T(T, T)>;
	T N, d;
	F f;
	Vec1<T> data;

	SegmentTree(T n, T d, F f) : f(f), d(d){
		init(n);
	}

	void init(T n){
		N = 1;
		while(N < n) N <<= 1;
		data.assign(N*2, d);
	}

	void build(Vec1<T> v){
		rep(i, v.size()) data[N+i] = v[i];
		repnr(i, N-1) data[i] = f(data[i*2], data[i*2+1]);
	}

	void update(T k, const T x){
		k += N;
		data[k] = x;
		while(k > 1){
			k >>= 1;
			data[k] = f(data[k*2], data[k*2+1]);
		}
	}

	void add(T k, const T x){
		k += N;
		data[k] += x;
		while(k > 1){
			k >>= 1;
			data[k] = f(data[k*2], data[k*2+1]);
		}
	}

	T query(T a, T b){return query(a, b, 1, 0, N);}
	T query(T a, T b, T k, T l, T r){
		if(r <= a || b <= l) return d;
		if(a <= l && r <= b) return data[k];
		T m = (l+r)/2;
		return f(query(a, b, k*2, l, m), query(a, b, k*2+1, m, r));
	}
};

int main(void){
	ll n;
	cin >> n;
	VecP r(n);
	rep(i, n) cin >> r[i].fs >> r[i].sc;
	sort(all(r));
	Vec x(n), d(n);
	rep(i, n){
		x[i] = r[i].fs;
		d[i] = r[i].sc;
	}
	SegmentTree<ll> st(n, LINF, [](ll a, ll b){return min(a, b);});

	Vec dp1(n), dp2(n);
	dp1[n - 1] = 1, dp2[n - 1] = 1;
	repr(i, n - 1){
		ll p = lower_bound(all(x), x[i] + d[i]) - x.begin();
		if(p == n) dp2[i] = 1;
		else if(p == i + 1) dp2[i] = dp1[i + 1] + dp2[i + 1];
		else dp2[i] = st.query(i + 1, p);
		dp1[i] = dp1[i + 1] + dp2[i + 1];
		st.update(i, dp2[i]);
	}
	//co(dp1);
	//co(dp2);
	co(dp1[0] + dp2[0]);

	return 0;
}

