using namespace std;
typedef long long ll;

const ll RAW = 998244353;

class R {
public:
  ll x;
  ll d;
  ll c;
  ll bound_idx;
};

ll getA (vector<R>& A, int N, size_t i) {
  if (i >= N) {
    return (ll)1;
  }
  if (A[i].c != -1) {
    return A[i].c;
  }

  ll up_i = N;
  if (A[i].bound_idx != -1) {
    up_i = A[i].bound_idx;
  } else {
    auto bound = A[i].x + A[i].d;
    vector<int> idxs;

    for (int j = i + 1; j < N; ++j) {
      if (A[j].x < bound) {
        if (bound <= A[j].x + A[j].d) {
          bound = A[j].x + A[j].d;
          idxs.push_back(j);
        }
      }
      if (A[j].x >= bound) {
        up_i = j;
        break;
      }
    }

    for (auto idx : idxs) {
      A[idx].bound_idx = up_i;
    }
  }

  size_t down_i = i + 1;

  ll up, down;
  if (up_i < N) {
    if (A[up_i].c == -1) {
      A[up_i].c = getA(A, N, up_i);
    }
    up = A[up_i].c;
  } else {
    up = 1;
  }
  if (down_i < N) {
    if (A[down_i].c == -1) {
      A[down_i].c = getA(A, N, down_i);
    }
    down = A[down_i].c;
  } else {
    down = 1;
  }

  return (A[i].c = ((up + down) % RAW));
};

int main() {
  int N;
  cin >> N;

  vector<R> A(N);

  for (int i = 0; i < N; ++i) {
    int x, d;
    cin >> x >> d;
    A[i] = {x, d, -1, -1};

  }

  sort(A.begin(), A.end(), [](const R& l, const R& r) {
    return l.x < r.x;
  });

  A[N-1].c = 2;
  cout << getA(A, N, 0) << endl;

  return 0;
}

