  vector<pll> a(n);
  for(ll i=0;i<n;i++) {
    ll x,d;
    cin >> x >> d;
    x+=1e9+1;
    a[i]={-x,-d};
  }
  sort(a.begin(),a.end());
  segtree dp(n);
  dp.Set(0,n+1,inf);
  vec ans(n+1);
  ans[0]=1;
  for(ll i=0;i<n;i++) {
    ll x=a[i].first;
    ll d=a[i].second;
    pll tmp={x+d,-1};
    ll it=lower_bound(a.begin(),a.end(),tmp)-a.begin();
    dp.Set(i,i+1,it);
    dp.Set(i,i+1,dp.Getmin(it,i+1));
    ans[i+1]=(ans[i]+ans[dp.Getmin(i,i+1)])%mod;
  }
  cout << ans[n] << endl;
}

