//firstで初期化された、葉がn要素を超えるように2のべき乗個用意されたリストを返す
vector<int> make_ST(int n,int first){

    int i = 0;
    vector<int> ret(0,0);

    while ((1<<(i-1)) < n){

        for (int j = 0 ; j < (1<<i) ; j++){
            ret.push_back(first);
        }

        i++;

    }

    return ret;
}

void RMQ_update_point(int num,int point,vector<int>& tree){

    int i = (tree.size()-1)/2 + point;
    tree[i] = num;
    while (i > 0){
        i = (i-1)/2;
        tree[i] = min(tree[i*2+2] , tree[i*2+1]);
    }
    return ;
}

int RMQ_query(int a,int b,int k,int l,int r,vector<int>& tree){

    if ((r <= a) || (b <= l)) return INT_MAX;
    if ((a <= l) && (r <= b)) return tree[k];

    int c1 = RMQ_query(a,b,2*k+1,l,(l+r)/2,tree);
    int c2 = RMQ_query(a,b,2*k+2,(l+r)/2,r,tree);

    return min(c1,c2);
}


int main(){

    int N,X,D;
    cin >> N;
    vector<vector<int>> XD(N,vector<int>(2,0));
    vector<int> Xlis(N,0);

    rep(i,0,N){
        cin >> X >> D;
        XD[i][0] = X;
        XD[i][1] = D;
        Xlis[i] = X;
    }

    sort(XD.begin(),XD.end());
    sort(Xlis.begin(),Xlis.end());

    vector<int> tree = make_ST(N,0);
    vector<int> lis(0);

    rep(i,0,N){
        X = XD[N-1-i][0];
        D = XD[N-1-i][1];
        int ind = distance(Xlis.begin(),lower_bound(Xlis.begin(), Xlis.end(), X+D));

        int nans = RMQ_query(N-i-1,ind,0,0,(tree.size()+1)/2,tree);
        nans *= (-1);
        RMQ_update_point(-1 * max(nans,ind),N-i-1,tree);
        lis.push_back(max(nans,ind));
    }

    reverse(lis.begin(),lis.end());

    vector<ll> dp(N+1,0);
    dp[0] = 1;

    rep(i,0,N){

        dp[i+1] += dp[i];
        dp[lis[i]] += dp[i];

        dp[i] %= mod;
        dp[i+1] %= mod;
        dp[lis[i]] %= mod;
    }

    cout << dp[N] % mod << endl; 
}

