struct Segtree {
	int size = 1;
	vector<int> dat, lazy;
	Segtree(int x) {
		while (size < x)
			size *= 2;
		dat.resize(size * 2 - 1, -inf);
		lazy.resize(size * 2 - 1, -inf);
	}
	void eval(int k, int l, int r) {
		chmax(dat[k], lazy[k]);
		if (r - l > 1) {
			chmax(lazy[k * 2 + 1], lazy[k]);
			chmax(lazy[k * 2 + 2], lazy[k]);
		}
		lazy[k] = -inf;
	}
	void update(int a, int b, int x, int k = 0, int l = 0, int r = -1) {
		if (r == -1)
			r = size;
		eval(k, l, r);
		if (r <= a || b <= l)
			return;
		if (a <= l && r <= b) {
			chmax(lazy[k], x);
			eval(k, l, r);
			return;
		}
		update(a, b, x, k * 2 + 1, l, (l + r) / 2);
		update(a, b, x, k * 2 + 2, (l + r) / 2, r);
		dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
	int query(int a, int b,int k = 0, int l = 0, int r = -1) {
		if (r == -1)
			r = size;
		eval(k, l, r);
		if(r<=a||b<=l)return -inf;
		if(a<=l&&r<=b)return dat[k];
		int lv=query(a,b,k*2+1,l,(l+r)/2),rv=query(a,b,k*2+2,(l+r)/2,r);
		return max(lv,rv);
	}
};

