void adde(int x,int y)
{
	to[++cnt]=y;
	nxt[cnt]=head[x];
	head[x]=cnt;
}
void work(int u)
{
	tot[u]=1;
	long long sum=1;
	for(int i=head[u];i;i=nxt[i])
	{
		int v=to[i];
		if(!v)
		{
			continue;
		}
		work(v);
		sum=(sum*tot[v])%mod;
	}
	tot[u]+=sum;
}
