using namespace std;

ll N;
pair<ll, ll> R[200001];
ll indexes[200001];
ll dp[200001][2]; // 0 means not activated, 1 means activated

ll thunder(ll currInd){
    if(currInd==N){
        return 1;
    }
    //If activated
    if(dp[currInd][1] == -1){
        dp[currInd][1] = thunder(indexes[currInd]+1)%mod;
    }
    //If deactivated
    if(dp[currInd][0] == -1){
        dp[currInd][0] = thunder(currInd+1)%mod;
    }
    return (dp[currInd][1]+dp[currInd][0])%mod;
}

ll findIndex(ll ind, ll currDist){
    if(ind==N || R[ind].first >= currDist){
        return -1;
    }
    if(indexes[ind]!= -1) return indexes[ind];
    ll tmp = findIndex(ind+1, max(currDist, R[ind].first+R[ind].second));
    return (tmp==-1) ? ind : tmp;
}

signed main(){
    cin>>N;
    for(ll i=0; i<N; i++){
        cin>>R[i].first>>R[i].second;
    }
    sort(R, R+N);
    memset(indexes, -1, sizeof(indexes));
    memset(dp, -1, sizeof(dp));
    for(ll i=0; i<N; i++){
        if(indexes[i] == -1){
            indexes[i] = findIndex(i, R[i].first+R[i].second);
        }
    }
    cout<<thunder(0)<<endl;
    return 0;
}

