void addedge(int st, int ed, ll co) {
    edge e;
    e.to = ed;
    e.cost = co;
    G[st].push_back(e);
}

vector<ll> par;
vector<ll> num;

void leafToRoot(vector<ll> &parentVector, ll root) {
    queue<ll> que;
    num = vector<ll>(V, 1);
    vector<ll> used(parentVector.size());
    fill(used.begin(), used.end(), 0);
    REP(i, 0, parentVector.size()) {
        if (parentVector[i] != -1 && G[i].size() == 1) {
            que.push(i);
            used[i] = 1;
        }
    }
    while (!que.empty()) {
        ll node = que.front();
        que.pop();

        //rootも含めて子だけのときに何かやりたいときはここに書く
        num[node] = modadd(num[node], 1);

        if (parentVector[node] == -1) {
            break;
        }
        ll parent = parentVector[node];
        used[parent]++;

        //ここに書く
        num[parent] = multiply(num[parent], num[node]);

        if ((parentVector[parent] == -1 && used[parent] == (ll)G[parent].size()) ||
            (parentVector[parent] != -1 && used[parent] == (ll)G[parent].size() - 1)) {
            que.push(parent);
        }
    }
}

