int FindClosest(const std::vector<std::pair<int, int>> &points, int limit)
{
    int res = -1;
    int pow = (1 << 20);

    while (pow > 0) {
        int next_res = res + pow;
        pow >>= 1;

        if (next_res < (int)points.size() && points[next_res].first < limit) {
            res = next_res;
        }
    }
    return res;
}

int main()
{
    int n;
    std::cin >> n;

    std::vector<std::pair<int, int>> points(n);
    for (auto &p : points) {
        std::cin >> p.first >> p.second;
    }
    std::sort(points.begin(), points.end());

    constexpr int kMod = 998244353;
    std::vector<int> ways(n, 0);
    std::vector<int> reach(n, -1);

    for (int i = 0; i < n; i += 1) {
        reach[i] = i + 1;
    }
    for (int i = n - 2; i >= 0; i -= 1) {
        int right = FindClosest(points, points[i].first + points[i].second);
        right = reach[right];
        if (points[i + 1].first < points[i].first + points[i].second) {
            right = std::max(right, reach[i + 1]);
        }
        reach[i] = right;
    }

    ways[n - 1] = 2;
    for (int i = n - 2; i >= 0; i -= 1) {
        ways[i] = ways[i + 1];
        if (reach[i] < n) {
            ways[i] = (1LL * ways[i] + ways[reach[i]]) % kMod;
        } else {
            ways[i] = (1LL * ways[i] + 1) % kMod;
        }
    }

    std::cout << ways[0] << "\n";
    return 0;
}

