using namespace std;

const long long MOD = 998244353;

vector<int> tree;

void update(int node, int nl, int nr, int id, int val) {
	if (nl == nr) {
		tree[node] = val;
		return;	
	}
	int mid = nl + nr >> 1;
	if (id <= mid) {
		update(2 * node, nl, mid, id, val);
	} else {
		update(2 * node + 1, mid + 1, nr, id, val);
	}
	tree[node] = max(tree[2 * node], tree[2 * node + 1]);
	return;
}

int query(int node, int nl, int nr, int l, int r) {
	if (nr < l || r < nl) {
		return -1;
	}
	if (l <= nl && nr <= r) {
		return tree[node];
	}
	int mid = nl + nr >> 1;
	return max(query(2 * node, nl, mid, l, r), query(2 * node + 1, mid + 1, nr, l, r));
}

