const int MOD = 998244353;

struct SegTree {
    int siz;
    vector<int> node;

    SegTree(int n) : siz(1) {
        while (siz < n)
            siz *= 2;
        node.resize(2 * siz - 1, INT_MIN);
    }

    void update(int k, int x) {
        k += siz - 1;
        node[k] = x;
        while (k > 0) {
            k = (k - 1) >> 1;
            node[k] = max(node[2 * k + 1], node[2 * k + 2]);
        }
    }

    int query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0)
            r = siz;

        if (r <= a || b <= l)
            return INT_MIN;
        if (a <= l && r <= b)
            return node[k];
        int vl = query(a, b, 2 * k + 1, l, (l + r) >> 1);
        int vr = query(a, b, 2 * k + 2, (l + r) >> 1, r);
        return max(vl, vr);
    }
};

int main() {
