struct robodata {
	int x;
	int d;
	long long tori;
	int parent;
	vector<int> children;
};


const long long C = 998244353;


int main() {
	int n;
	cin >> n;

	vector<robodata> data(n);
	int* index_top = new int[n];
	int index_max = -1;

	for (int i = 0; i < n; ++i) {
		int x;
		int d;
		cin >> x >> d;
		data[i] = robodata{ x, d, -1, -1 };
		index_top[i] = -1;
	}

	std::sort(data.begin(), data.end(), [&](const robodata& a, const robodata& b) { return a.x < b.x; });


	for (int i = 0; i < n; ++i) {
		if (data[i].parent == -1) {

			index_max++;
			index_top[index_max] = i;

			vector<int> node_stack;
			int max_index = i + 1;

			node_stack.push_back(i);

			while (!node_stack.empty()) {
				int k = node_stack.back();

				int max_range = data[k].x + data[k].d;
				bool none_child = true;

				for (int j = max_index; j < n && data[j].x < max_range; ++j) {
					if (data[j].parent == -1) {

						data[k].children.push_back(j);
						data[j].parent = k;
						node_stack.push_back(j);
						none_child = false;
						max_index = j;
						break;
					}
				}

				if (none_child) {
					node_stack.pop_back();
				}
			}
		}
	}

	unsigned long long ret = 1;

	for (int i = data.size() - 1; i >= 0; --i) {
		if (data[i].children.empty()) {
			data[i].tori = 2;
		}
		else {
			long long x = 1;
			for (int i : data[i].children) {
				x *= data[i].tori;
				x %= C;

				if (data[i].tori == -1) { cout << "ERR" << endl; }
			}
			data[i].tori = x + 1;
		}
	}

	for (int i = 0; i <= index_max; ++i) {
		ret *= data[index_top[i]].tori;
		ret %= C;
	}


	cout << ret << endl;

	delete[] index_top;

	return 0;
}

