#define rep(i,min,sup) for(int i=min;i<sup;i++)
#define per(i,min,sup) for(int i=(sup-1);i>=min;i--)
#define swap(a,b) {a+=b;b=a-b;a-=b;}
#define ll long long

void quickid_sort(int* id,ll* X,int left,int right){
  if(right-left<4){
    rep(i,left,right)rep(j,i+1,right)if(X[id[i]]>X[id[j]])swap(id[i],id[j]);
  }else{
    int i=left,j=right-1;
    ll pivot=X[id[i]]+(X[id[j]]-X[id[i]])/2;
    while(1){
      while(X[id[i]]<pivot)i++;
      while(X[id[j]]>pivot)j--;
      if(i>=j)break;
      swap(id[i],id[j]);
      i++;j--;
    }
    quickid_sort(id,X,left,i);
    quickid_sort(id,X,j+1,right);
  }
}
void quickid(int* id,ll* X,int N){
  /*  sort X[0~N-1]
   *  X[id[i]]=ith minimum X
   */
  rep(i,0,N)id[i]=i;
  quickid_sort(id,X,0,N);
}

