using namespace std;
typedef long long ll;

const ll MOD = 998244353;
const int MAX_N = 200010;

struct Robot {
  int id;
  int x;
  int d;

  Robot(int id = -1, int x = -1, int d = -1) {
    this->id = id;
    this->x = x;
    this->d = d;
  }

  int range() {
    return x + d;
  }

  bool operator<(const Robot &n) const {
    return x < n.x;
  }
};

vector<Robot> robots;
vector<vector<int>> G(MAX_N);
ll cache[MAX_N];

ll dfs(int v) {
  if (cache[v] != -1) return cache[v];
  ll res = 1;

  for (int i = 0; i < G[v].size(); ++i) {
    int u = G[v][i];
    res = (res * dfs(u)) % MOD;
  }

  return cache[v] = res + 1;
}

int main() {
  memset(cache, -1, sizeof(cache));

  int N;
  cin >> N;

  int x, d;
  for (int i = 0; i < N; ++i) {
    cin >> x >> d;
    robots.push_back(Robot(i, x, d));
  }

  sort(robots.begin(), robots.end());
  stack<Robot> stk;
  vector<int> vs;

  for (int i = 0; i < N; ++i) {
    Robot robot = robots[i];

    while (!stk.empty() && stk.top().range() <= robot.x) {
      stk.pop();
    }

    if (stk.empty()) {
      vs.push_back(robot.id);
    } else {
      vs.push_back(stk.top().id);
      G[stk.top().id].push_back(robot.id);
    }

    stk.push(robot);
  }

  ll ans = 1;

  for (int v : vs) {
    if (cache[v] != -1) continue;

    ans = (ans * dfs(v)) % MOD;
  }

  cout << ans << endl;

  return 0;
}

