vector<int> G[200020];
int visited[200020];
mint dfs(int u) {
  visited[u] = 1;
  mint cur = 1;
  for(int v : G[u]) {
    cur *= dfs(v);
  }
  return cur + 1;
}
void answer() {
  int n;
  cin >> n;
  vector<P> robots(n); // x, d
  rep(i, n) {
    int x, d;
    cin >> x >> d;
    robots[i] = (P(x, d));
  }
  sort(RALL(robots));
  set<P> s; // x, i
  rep(i, robots.size()) {
    int x, d;
    tie(x, d) = robots[i];
    auto itr = s.lower_bound(P(x, -1));
    for(; itr != s.end(); s.erase(prev(++itr))) {
      int y, j;
      tie(y, j) = (*itr);
      if(x + d <= y) break;
      G[i].push_back(j);
    }
    s.insert(P(x, i));
  }
  mint ans = 1;
  REPCM(i, n-1, 0) if(!visited[i]) {
    ans *= dfs(i);
  }
  cout << ans << '\n';
}
