class UF{       // UnionFind
public:
    int n;      // the number of nodes
    vector<int> par;        // the parents of nodes. (the body of UnionFindTree)

    UF(){
        n = 1;
        par.assign(n, -1);      // parents of root nodes are negative
    }

    UF(int N){
        n = N;
        par.assign(n, -1);      // parents of root nodes are negative
    }

    // find the root of x
    int root(int x) {
        if (par[x] < 0) {
            return x;
        } else {
            return par[x] = root(par[x]);
        }
    }

    // merge set of x and set of y
    bool merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y)
            return false;
        if (par[x] > par[y])
            swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    // x and y belong the same set or not
    bool same(int x, int y) {
        return root(x) == root(y);
    }

    // size of set of x
    int size(int x)
    {
        return -par[root(x)];
    }
};

void mktr(vector<P> bot, vector<int> &par, int N, int x)
{
    int y = x + 1;

    while(y < N && bot[y].first < bot[x].first + bot[x].second) {
        par[y] = x;
        y++;
    }
}

ll rec(vector<int> par, vector<vector<int>> sib, int x) {
    ll ret = 1;
    if (sib[x].size() > 0) {
        rep(i, sib[x].size()) {
            ret = ret * rec(par, sib, sib[x][i]) % MOD;
        }
        return ret + 1 % MOD;
    } else {
        return 2;
    }

}

