}

int seg[400009], N;

void upd(int p, int v)
{
	p = p + N / 2;
	seg[p] = v;
	p /= 2;
	while (p) {
		seg[p] = max(seg[p], v);
		p /= 2;
	}
}

int query(int a, int b, int l, int r, int p)
{
	if (r <= a || b <= l) return -1e9;
	if (l == r) return -1e9;
	if (a <= l && r <= b) return seg[p];
	int ret = query(a, b, l, (l + r) / 2, 2 * p);
	ret = max(ret, query(a, b, (l + r) / 2, r, 2 * p + 1));
	return ret;
}

