template <typename N> class seg {
    vector<N> t;
    void upd(int a, N n, int p, int l, int r) {
        if(a < l || r <= a)
            return;
        t[p] = op(t[p], n);
        if(r - l < 2)
            return;
        int m = l + r >> 1;
        upd(a, n, p + 1, l, m), upd(a, n, p + (r - l & -2), m, r);
    }
    N get(int a, int b, int p, int l, int r) const {
        if(b <= l || r <= a)
            return e();
        if(a <= l && r <= b)
            return t[p];
        int m = l + r >> 1;
        return op(get(a, b, p + 1, l, m), get(a, b, p + (r - l & -2), m, r));
    }

  public:
    const int s;
    seg(int s) : s(s), t(s + s, e()) {}
    void upd(int a, N n) { upd(a, n, 0, 0, s); }
    N get(int a, int b) const { return get(a, b, 0, 0, s); }

    static N e() { return -1e9; }
    static N op(N x, N y) { return max(x, y); }
};

