struct sg{
    vector<int> rangeMax;
    int n;
    sg(vector<int>& arr){
        n = arr.size();
        rangeMax.resize(4 * n);
        init(arr, 0, n-1, 1);
    }
    int init(vector<int>& arr, int arrLeft, int arrRight, int nodeIndex){
        if(arrLeft == arrRight){
            return rangeMax[nodeIndex] = arrLeft;
        }
        int mid = (arrLeft + arrRight) / 2;
        int left = init(arr, arrLeft, mid, nodeIndex * 2);
        int right = init(arr, mid+1, arrRight, nodeIndex * 2 + 1);
        return rangeMax[nodeIndex] = max(left, right);
    }

    int query(int arrLeft, int arrRight, int nodeLeft, int nodeRight, int nodeIndex){
        if(arrLeft <= nodeLeft && nodeRight <= arrRight){
            return rangeMax[nodeIndex];
        }
        if(arrLeft > nodeRight || arrRight < nodeLeft){
            return INT_MIN;
        }
        int mid = (nodeLeft + nodeRight) / 2;
        int left = query(arrLeft, arrRight, nodeLeft, mid, nodeIndex * 2);
        int right = query(arrLeft, arrRight, mid+1, nodeRight, nodeIndex * 2 + 1);
        return max(left, right);
    }

    int query(int arrLeft, int arrRight){
        return query(arrLeft, arrRight, 0, n-1, 1);
    }

    int update(int arrIndex, int val, int nodeLeft, int nodeRight, int nodeIndex){
        if(arrIndex < nodeLeft || arrIndex > nodeRight){
            return rangeMax[nodeIndex];
        }
        if(nodeLeft == nodeRight){
            return rangeMax[nodeIndex] = val;
        }
        int mid = (nodeLeft + nodeRight) / 2;
        int left = update(arrIndex, val, nodeLeft, mid, nodeIndex*2);
        int right = update(arrIndex, val, mid+1, nodeRight, nodeIndex*2+1);
        return rangeMax[nodeIndex] = max(left, right);
    }

    int update(int arrIndex, int val){
        return update(arrIndex, val, 0, n-1, 1);
    }
};

