        upd(2 * v, tl, tm, p);
        upd(2 * v + 1, tm + 1, tr, p);
        t[v] = max(t[2 * v], t[2 * v + 1]);
}

int get(int v, int tl, int tr, int l, int r) {
        if (tr < l || r < tl)
                return 0;
        if (l <= tl && tr <= r)
                return t[v];
        int tm = (tl + tr) / 2;
        return max(get(2 * v, tl, tm, l, r), get(2 * v + 1, tm + 1, tr, l, r));
}

int main() {
        ios::sync_with_stdio(false);
        cin.tie(0);
        cin >> n;
        for (int i = 1; i <= n; i++)
                cin >> a[i].x >> a[i].d;
        sort(a + 1, a + n + 1);
        for (int i = n; i >= 1; i--) {
                pos[i] = i;
                if (i + 1 <= n && a[i + 1].x <= a[i].x + a[i].d - 1) {
                        pos[i] = max(pos[i], pos[i + 1]);
                        int l = i, r = n;
                        while (l <= r) {
                                int m = (l + r) / 2;
                                if (a[m].x <= a[i].x + a[i].d - 1) {
                                        pos[i] = max(pos[i], m);
                                        l = m + 1;
                                } else
                                        r = m - 1;
                        }
                        pos[i] = max(pos[i], get(1, 1, n, i, pos[i]));
                        upd(1, 1, n, i);
                }
        }
        for (int i = 1; i <= n; i++)
                g[pos[i]].push_back(i - 1);
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
                dp[i] = dp[i - 1];
                for (auto &j : g[i])
                        dp[i] = add(dp[i], dp[j]);
        }
        cout << dp[n] << "\n";
        return 0;
}

