  sort(ALL(XD));
  REP(i, N) {
    X[i] = XD[i].first;
    D[i] = XD[i].second;
  }
  vector<modint> dp(N + 1);
  dp[N] = 1;
  SegmentTree<ll> seg(
      N, [](ll l, ll r) { return max(l, r); }, 0LL);
  REP(i, N) seg.update(i, i);
  for (int i = N - 1; i >= 0; --i) {
    auto itr = lower_bound(ALL(X), X[i] + D[i]);
    int aff = itr - X.begin();
    ll mx = seg.query(i, aff);
    dp[i] = dp[i + 1] + dp[mx + 1];
    seg.update(i, mx);
  }
  io.writeln(dp[0].x);
  return 0;
}

