#define MOD 998244353

ll doit(VPLL& robots) {
  int n = sz(robots);
  VL dp(n + 1, 0);
  VL reach(n, 0);
  int B = 500;
  VL block_max(n / B + 1, -1E9-5);
  dp[n] = 1;
  FORR(i,n-1,0){
    // not choose myself.
    dp[i] = dp[i+1];
    // choose myself, then a lot will be killed.
    // Search for largest j, s.t. robots[j].FI < robots[i].FI + robots[i].SE.
    int lo = i;
    int hi = n - 1;
    while (lo < hi) {
      int mi = hi - (hi - lo) / 2;
      if (robots[mi].FI < robots[i].FI + robots[i].SE) {
        lo = mi;
      } else {
        hi = mi - 1;
      }
    }
    int j = lo;
    ll curr_reach = robots[i].FI + robots[i].SE-1;
    for (int k = (i + 1) / B; k * B + B <= j; ++k) {
      curr_reach = max(curr_reach, block_max[k]);
    }
    for (int k = max(i+1, j - j % B); k <= j; ++k) {
      curr_reach = max(curr_reach, reach[k]);
    }
    reach[i] = curr_reach;
    lo = i;
    hi = n - 1;
    while (lo < hi) {
      int mi = hi - (hi - lo) / 2;
      if (robots[mi].FI <= curr_reach) {
        lo = mi;
      } else {
        hi = mi - 1;
      }
    }
    ++lo;
    dp[i] += dp[lo];
    dp[i] %= MOD;
    block_max[i/B] = max(block_max[i/B],curr_reach);
  }
  return dp[0];
}

