    GO();
    cin>>n;
    for(int i=0;i<n;i++){
        int a,b;
        cin>>a>>b;
        v.pb(mp(a,b));
    }
    sort(all(v));

    for(int i=n-1;i>=0;i--){
        ll aa=v[i].first;
        ll d=v[i].second;
        d--;
        auto it=upper_bound(all(v),mp(aa+d,100000000000),cmp);
        it--;
        if((*it).first==aa){
            update(i,aa+d);
            arr[i]=aa+d;
            continue;
        }
        int idx=it-v.begin();
        int res=query(i,idx);
        update(i,res);
        arr[i]=res;
    }
  //  for(int i=0;i<n;i++) cout<<arr[i]<<endl;
    clr(mem,-1);
    cout<<solve(0)<<"\n";
}

