    pair<int,int> p[n];
    rep(i,n){
        int x,d;
        cin>>x>>d;
        p[i]={x,x+d};
    }
    sort(p,p+n);
    auto op=[](int a,int b)->int{
        return max(a,b);
    };
    SegmentTree<int> seg(n,op,-inf);
    for(int i=n-1;i>=0;--i){
        int r=p[i].second;
        int mx=lower_bound(p,p+n,make_pair(r,-inf))-p;
        if(mx!=i+1){
            mx=max(mx,seg.get(i+1,mx));
        }
        seg.update(i,mx);
    }
    ll dp[n+1];
    dp[n]=1;
    for(int i=n-1;i>=0;--i){
        dp[i]=(dp[i+1]+dp[seg.get(i)])%mod;
    }
    cout<<dp[0]<<endl;
}

