struct Segment_tree {
	int maxj[800010];
	Segment_tree() {memset(maxj, 0, sizeof(maxj));}
	void Update(int now, int l, int r, int pos, int x) {
		if (l == r) {
			maxj[now] = max(maxj[now], x);
			return ;
		}
		int mid = l + r >> 1;
		if (pos <= mid) Update(now << 1, l, mid, pos, x);
		else Update(now << 1 | 1, mid + 1, r, pos, x);
		maxj[now] = max(maxj[now << 1], maxj[now << 1 | 1]);
	}
	int Query(int now, int l, int r, int L, int R) {
		if (l == L && r == R) return maxj[now];
		int mid = l + r >> 1;
		if (R <= mid) return Query(now << 1, l, mid, L, R);
		if (L > mid) return Query(now << 1 | 1, mid + 1, r, L, R);
		return max(Query(now << 1, l, mid, L, mid), Query(now << 1 | 1, mid + 1, r, mid + 1, R));
	}
}seg;

