	dp[n] = 1;
	for (int i = n - 1; i >= 0; i--) {
		int pos = lower_bound(a, a + n, mp(a[i].fi + a[i].se - 1, 0x3f3f3f3f)) - a;
		nxt[i] = max(i, seg.Query(1, 0, n - 1, i, pos - 1));
		seg.Update(1, 0, n - 1, i, nxt[i]);
		dp[i] = dp[nxt[i] + 1] + dp[i + 1];
		if (dp[i] >= mod) dp[i] -= mod;
	}
	printf("%d\n", dp[0]);
	return 0;
}

