int query(int t, int nl, int nr, int l, int r) {
	if (nl > r || nr < l) {
		return -inf;
	}
	if (nl >= l && nr <= r) {
		return tree[t];
	}
	int mid = nl + (nr - nl) / 2;
	return max(query(2 * t, nl, mid, l, r), query(2 * t + 1, mid + 1, nr, l, r));
}
void update(int t, int nl, int nr, int ind, int val) {
	if (nl > ind || nr < ind) {
		return;
	}
	if (nl == nr) {
		tree[t] = val;
		return;
	}
	int mid = nl + (nr - nl) / 2;
	update(2 * t, nl, mid, ind, val);
	update(2 * t + 1, mid + 1, nr, ind, val);
	tree[t] = max(tree[2 * t], tree[2 * t + 1]);
}
