        int next_ind = lower_bound(x.begin(), x.end(), x[i] + d[i]) - x.begin();
        next[i] = next_ind;
    }

    dp[0] = 1;

    for(int i = 0; i < n; i++){
        // 選ぶ場合
        dp[next[i]] = add(dp[next[i]], dp[i]);
        // 選ばない場合
        dp[i+1] = add(dp[i+1], dp[i]);
    }
    cout << dp[n] << endl;

    return 0;
}

