const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, dp[2][MAX_N];
vpl bs;

void solve(){
    bs = vpl(n); UnionFind uf(n + 1);
    rep(i, n){
        ll x, d; in2(x, d);
        bs[i] = {x, x + d};
    }

    rep(i, n + 1) dp[0][i] = dp[1][i] = 0;
    dp[0][0] = 1;
    sort(all(bs));
    vl xs(n); SegmentTree st(n + 1, false);
    rep(i, n) xs[i] = bs[i].e1;

    uf.unite(n, n - 1); st.update(n, n);
    For(i, 1, n + 1){
        // xs[lb - 1] < xi + di <= xs[lb]
        ll lb = lower_bound(all(xs), bs[n - i].e2) - xs.begin();
        ll pre = uf.root_find(lb - 1);
        st.update(n - i, pre);
        if (!uf.is_same(lb - 1, n - i)) uf.unite(lb - 1, n - i);
        if (n - i <= lb - 1) pre = st.query(n - i, lb - 1);

        dp[0][i] = (dp[0][i - 1] + dp[1][i - 1]) % MOD;
        if (pre == n) dp[1][i] = 1;
        else if (n - pre < i) dp[1][i] = dp[1][n - pre];
        else dp[1][i] = dp[0][i];
    }

    prl(dp[0][n] + dp[1][n]);
}

int main(void){
    in1(n);
    // assert(k <= 100000);
    solve();
    return 0;
}

