using namespace std;

struct robodata {
	int x;
	int d;
	long long tori;
	int parent;
	int rank;
	vector<int> children;
};

const long long C = 998244353;
int n;

void f(vector<robodata>& data, int i) {
	int max_range = data[i].x + data[i].d;

	for (int j = i + 1; j < n && data[j].x < max_range; ++j) {
		if (data[j].parent == -1) {

			data[i].children.push_back(j);
			data[j].parent = i;
			data[j].rank = data[i].rank + 1;
			f(data, j);
		}
	}
}


int main() {
	cin >> n;

	vector<robodata> data(n);
	int* index_top = new int[n];
	int index_max = -1;

	for (int i = 0; i < n; ++i) {
		int x;
		int d;
		cin >> x >> d;
		data[i] = robodata{ x, d, -1, -1, -1 };
		index_top[i] = -1;
	}

	std::sort(data.begin(), data.end(), [&](const robodata& a, const robodata& b) { return a.x < b.x; });

	for (int i = 0; i < n; ++i) {
		if (data[i].parent == -1) {
			index_max++;
			index_top[index_max] = i;
			data[i].rank = 0;
			f(data, i);
		}
	}

	unsigned long long ret = 1;

	for (int i = data.size() - 1; i >= 0; --i) {
		if (data[i].children.empty()) {
			data[i].tori = 2;
		}
		else {
			long long x = 1;
			for (int i : data[i].children) {
				x *= data[i].tori;
				x %= C;

				if (data[i].tori == -1) { cout << "ERR" << endl; }
			}
			data[i].tori = x + 1;
		}
	}

	for (int i = 0; i <= index_max; ++i) {
		ret *= data[index_top[i]].tori;
		ret %= C;
	}


	cout << ret << endl;

	delete[] index_top;

	return 0;
}

