void GO(){ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);}
const int N=200000+9,mod=998244353;
ll n,tree[4*N];
ll mem[N],arr[N];
vector< pair<ll,ll> > v;
bool cmp(pair<ll,ll> a,pair<ll,ll> b){

  if(a.first!=b.first) return (a.first<b.first);
  if(a.second!=b.second) return (a.second<b.second);
  return 0;
}
ll solve(int id){

  if(id>=n) return 1;
  ll &ret=mem[id];
  if(ret!=-1) return ret;
  ll ans=0;
  ans+=solve(id+1);
  if(ans>=mod) ans-=mod;

  auto it=upper_bound(all(v),mp(arr[id],100000000000),cmp);
  int idx=it-v.begin();
  ans+=solve(idx);
  if(ans>=mod) ans-=mod;
  return ret=ans;
}
void update(int pos,int val,int s=0,int e=n-1,int p=1){

   if(s==e){
     tree[p]=val;
     return ;
   }
   int m=(s+e)/2;
   if(pos<=m)
   update(pos,val,s,m,p*2);
   else{
    update(pos,val,m+1,e,p*2+1);
   }
   tree[p]=max(tree[p*2],tree[p*2+1]);
}
ll query(int a,int b,int s=0,int e=n-1,int p=1){

   if(b<s||a>e) return -100000000000;
   if(s>=a&&e<=b){
      return tree[p];
   }
   int m=(s+e)/2;
   return max(query(a,b,s,m,p*2),query(a,b,m+1,e,p*2+1));
}
