        modint res = 1;
        for (int next : tree[now]) {
            res *= dfs(next);
        }
        return res + 1;
    };
    modint ans = 1;
    for (auto temp : root) {
        ans *= dfs(temp.second);
    }
    cout << ans << endl;
}

