ll dp[N];

ll recur(ll pos) {
  if (pos == n + 1)
    return 1;
  ll &ans = dp[pos];
  if (ans != -1)
    return ans;

  ans = recur(pos + 1);
  ans += recur(nxt[pos] + 1);

  if (ans >= mod)
    ans -= mod;
  return ans;
}

