#include <bits/stdc++.h>
using namespace std;

long long kMod = 998244353;

class Robot {
  public:
    long long x;
    long long d;
    Robot() {}
};

class Node {
  public:
    vector<Node*> children;
    Node* parent;
    long long p;
    long long x;
    Node(const Robot& robot) {
      parent = nullptr;
      p = -1;
      x = robot.x + robot.d;
    }
    void calc_p() {
      p = 1;
      for (auto ptr : children) {
        ptr->calc_p();
        p *= ptr->p;
        p %= kMod;
      }
      p += 1;
      p %= kMod;
    }
};

bool has_smaller_x(const Robot& a, const Robot& b)
{
  return a.x < b.x;
}

int main()
{
  long long n;
  cin >> n;
  vector<Robot> v(n);
  for (int i = 0; i < n; i++) {
    cin >> v.at(i).x >> v.at(i).d;
  }
  sort(v.begin(), v.end(), has_smaller_x);
  long long res = 1;
  long long largest_x = LLONG_MIN;
  Node* root = nullptr;
  Node* cur = nullptr;
  for (const auto& robot : v) {
    if (largest_x <= robot.x) {
      if (root) {
        root->calc_p();
        res *= root->p;
        res %= kMod;
      }
      root = new Node(robot);
      cur = root;
      largest_x = robot.x + robot.d;
    } else {
      while (cur->x <= robot.x) {
        cur = cur->parent;
        assert(cur != nullptr);
      }
      Node* n = new Node(robot);
      n->parent = cur;
      cur->children.push_back(n);
      cur = n;
      largest_x = max(largest_x, n->x);
    }
  }
  if (root) {
    root->calc_p();
    res *= root->p;
    res %= kMod;
  }
  cout << res << '\n';
  return 0;
}

