        while (x <= y)longest = max(longest, backets[x / bs]), x += bs;
        longests[i] = longest, backets[i / bs] = max(backets[i / bs], longest);

        int index = lower_bound(pos.begin(), pos.end(), longest) - pos.begin();
        move[i] = (move[index] + stop[index]) % MOD;
        stop[i] = (move[i + 1] + stop[i + 1]) % MOD;
    }

