/**
 * 1D Segment tree: Suppports point update and range queries.
 * f is an associative function. f can be non-commutative.
 * @warning: When f is non-commutative, ensure correct ordering of children!
 * @note: For query function, bounds are inclusive to left and exclusive to right
 */
template <typename T>
struct seg_tree {
	static constexpr T unit = -1;
	vector<T> tree;
	int N;

	inline T f(T a, T b) { return max(a, b); }
	seg_tree(int _N = 0, T def = unit) : tree(2 * _N, def), N(_N) {}
	void update(int pos, T value) {
		for (tree[pos += N] = value; pos > 1; pos >>= 1)
			tree[pos >> 1] = f(tree[pos], tree[pos ^ 1]);
	}
	T query(int l, int r) {
		T ra = unit, rb = unit;
		for (l += N, r += N; l < r; l /= 2, r /= 2) {
			if (l & 1) ra = f(ra, tree[l++]);
			if (r & 1) rb = f(tree[--r], rb);
		}
		return f(ra, rb);
	}
};

