const int MAX_N = 200005;
int N;
struct Node {
  Node(int X = 0, int D = 0) : X(X), D(X) {}
  int X, D;
  void input() {
    cin >> X >> D;
  }

  bool operator < (const Node& node) const {
    return X < node.X;
  }

  vector<int> nextNodeIndexList;
};

Node nodes[MAX_N];

bool buildTree(int pos, int& nodesIndex)
{
  if(N <= nodesIndex) {
    return true;
  }

  int nextNodeIndex = nodesIndex;
  // 範囲内なら追加
  if(nodes[pos].X <= nodes[nodesIndex].X && nodes[nodesIndex].X < nodes[pos].X + nodes[pos].D) {
    nodes[pos].nextNodeIndexList.push_back(nodesIndex);
    nodesIndex++;
    while(!buildTree(nextNodeIndex, nodesIndex)) {
      if (nodes[pos].X <= nodes[nodesIndex].X && nodes[nodesIndex].X < nodes[pos].X + nodes[pos].D) {
        nextNodeIndex = nodesIndex;
        nodes[pos].nextNodeIndexList.push_back(nodesIndex);
        nodesIndex++;
      } else {
        return false;
      }
    }
    return true;
  } else { // 範囲外なら先祖に追加してもらう
    return false;
  }
}

int solve(int pos = 0)
{
  int ret = 1;
  for(int next : nodes[pos].nextNodeIndexList) {
    ret *= solve(next);
    ret %= MOD9;
  }
  return (ret + 1) % MOD9;
}

