void update(int low,int high,int index,int idx,int val){
	if(low>high or idx>high or idx<low)return;
	if(low==high){
		seg[index]=val;
		return;
	}
	int mid=(low+high)/2;
	update(low,mid,index*2+1,idx,val);
	update(mid+1,high,index*2+2,idx,val);
	seg[index]=max(seg[index*2+1],seg[index*2+2]);
}

int query(int low,int high,int index,int l,int r){
	if(l>r or low>high or l>high or low>r)return 0;
	if(low>=l and high<=r)return seg[index];
	int mid=(low+high)/2;
	return max(query(low,mid,index*2+1,l,r),query(mid+1,high,index*2+2,l,r));
}

