using namespace std;

using ll = long long;

const ll MOD = 998244353;

ll modpow(ll x, ll n, ll mod = MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

ll calc(int cur, const vector< vector<int> >& g, vector<int>& visited) {
    visited[cur] = true;
    ll res = 1;
    for (int nex : g[cur]) {
        if (visited[nex]) continue;
        (res *= calc(nex, g, visited)) %= MOD;
    }
    res = (res + 1) % MOD;
    return res;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<ll> x(n), d(n);
    map<ll, int> xtoi;
    for (int i = 0; i < n; ++i) {
        cin >> x[i] >> d[i];
        xtoi[x[i]] = i;
    }

    vector<int> ids(n);
    iota(ids.begin(), ids.end(), 0);
    sort(ids.begin(), ids.end(), [&](int i1, int i2){
        return x[i1] > x[i2];
    });

    vector< vector<int> > g(n);
    for (int i : ids) {
        if (xtoi.find(x[i]) == xtoi.end()) {
            cerr << i << " " << x[i] << " " << d[i] << endl;
            return 0;
        }
        auto it = next(xtoi.find(x[i]));
        while (it != xtoi.end() && it->first < x[i] + d[i]) {
            g[i].push_back(it->second);
            //cerr << i << " -> " << it->second << ": " << cnt[i] << ", " << cnt[it->second] << "\n";
            it = xtoi.erase(it);
        }
    }
    reverse(ids.begin(), ids.end());

    vector<int> visited(n, false);
    ll ans = 1;
    for (int i : ids) {
        if (visited[i]) continue;
        (ans *= calc(i, g, visited)) %= MOD;
    }
    cout << ans << "\n";
    return 0;
}

