template<class M=int> struct seg_base {
    int n;
    vector<M> seg;
    const M e;
    virtual M f(M a, M b) {return a + b;};
    seg_base(int len, M init_value) : e(init_value) {        n = 1;        int asz = len;        while (n <= asz)n <<= 1;        seg.assign((n << 1) - 1, e);        rep(i, asz) seg[i + n - 1] = e;        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);        debu();    }
    seg_base(vector<M> &dat, M init_value) : e(init_value) {        n = 1;        int asz = dat.size();        while (n <= asz)n <<= 1;        seg.assign((n << 1) - 1, e);        rep(i, asz) seg[i + n - 1] = dat[i];        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);        debu();    }
    void update(int k, M v, bool debug = true) {        int tk = k;        seg[k + n - 1] = v;        k += n - 1;        while (k) {            k = (k - 1) >> 1;            seg[k] = f(seg[(k << 1) | 1], seg[(k << 1) + 2]);        }        if (debug)debup(tk, v);    }
private:
    M query_bottomup(int l, int r, bool debug = true) {        int tl = l, tr = r;        M retl = e;        M retr = e;        l += n - 1;        r += n - 1;        while (l < r) {            /*右なら、次に右上へ移動してしまうので*/            if (!(l & 1)) { retl = f(retl, seg[l]); }            /*右なら、左を取らないと機会を逃す*/            if (!(r & 1)) { retr = f(seg[r - 1], retr); }            l >>= 1;            r = (r - 1) >> 1;        }        M ret = f(retl, retr);        if (debug)debge(tl, tr, ret);        return ret;    }
    template<typename C> int find_subtree(int a, const C &check, M &m, bool type) {while (a < n) {M nxt = type ? f(seg[2 * a + type - 1], m) : f(m, seg[2 * a + type - 1]);if (check(nxt)) a = 2 * a + type; else m = nxt, a = 2 * a + 1 - type;}return a - n;}
public:
    void del(int k) {update(k, e);}
    void add(int k, int v, bool debug = true) {update(k, v + seg[k + n - 1], debug);}
    M get(int a, int b, bool debug = true) { return query_bottomup(a, min(b, n), debug); }
    M get(int b = inf, bool debug = true) { return query_bottomup(0, min(b, n), debug); }
    M operator()(int b = inf) { return get(0, b); }
    M operator()(int a, int b) { return get(a, b); }
    M operator[](int k) { return seg[k + n - 1]; }
    /*[a x+1)でcheckを満たす最も左のxを返す*/
    template<typename C> int find_first(int a, const C &check) {        M L = e;        if (a <= 0) {            if (check(f(L, seg[1 - 1]))) return find_subtree(1, check, L, false);            return -1;        }        int b = n;        for (a += n, b += n; a < b; a >>= 1, b >>= 1) {            if (a & 1) {                M nxt = f(L, seg[a - 1]);                if (check(nxt)) return find_subtree(a, check, L, false);                L = nxt;                ++a;            }        }        return -1;    }
    /*[x b)でcheckを満たす最も右のxを返す*/
    template<typename C> int find_last(int b, const C &check) {        M R = e;        if (b >= n) {            if (check(f(seg[1 - 1], R))) return find_subtree(1, check, R, true);            return -1;        }        int a = n;        for (b += n; a < b; a >>= 1, b >>= 1) {            if (b & 1) {                M nxt = f(seg[--b - 1], R);                if (check(nxt)) return find_subtree(b, check, R, true);                R = nxt;            }        }        return -1;    }
    //r)でv以上を満たす最右のindexを返す
    int most_r(int r, M v) {        M d = get(0, r, false);        if (get(0, r, false) < v) {            err("most_r : ", r, ")  >= ", v, " :  ", -1);            debu();            return -1;        }        int l = 0;        while (r - l > 1) {            int m = (l + r) >> 1;            if (get(m, r, false) >= v) { l = m; } else { r = m; }        }        err("most_r : ", r, ")  >= ", v, " :  ", l);        debu();        return l;    }
    int most_r(M v) { return most_r(n, v); }
    //[lで v以上を満たす最左のindexを返す
    int most_l(int l, M v) {        if (get(l, n, false) < v) {            err("most_l : ", "[ ", l, ">=", v, "  :  ", -1);            debu();            return -1;        }        int r = n;        while (r - l > 1) {            int m = (l + r) >> 1;            if (get(l, m, false) >= v) { r = m; } else { l = m; }        }        err("most_l : ", "[ ", l, ">=", v, "  :  ", l);        debu();        return l;    }
    int most_l(M v) { return most_l(0, v); }
#ifdef _DEBUG
    void debu() {        rep(i, min(n, 10ll)) {            int v = seg[i + n - 1];            if (v == MIN(ll) || v == MAX(ll)) { cerr << "e "; } else { cerr << v << " "; }        }        cerr << "" << endl << endl;    }
    void debup(int k, int v) {cerr << "upd : [" << k << "] = " << v << endl;debu();}
    void debge(int l, int r, M v) {cerr << "get : [" << l << ", " << r << ") = " << v << endl;debu();}
#else
    void debu(){;}    void debup(int k,int v){;}    void debge(int l,int r,M v){;}/*@formatter:on*/
#endif
};
