void build(int rt,int l,int r){
    t[rt].l=l,t[rt].r=r;
    t[rt].maxx=-2e9-1;
    if(l==r)return;
    int mid=(t[rt].l+t[rt].r)>>1;
    build(rt<<1,l,mid);
