using namespace std;
using large = long long;
constexpr int N_max = 200'000;
constexpr int mod = 998'244'353;

static large memo[N_max + 1];

struct Robot {
    int x, d;
    struct Removal {
        Robot *begin;
        Robot *end; // one-past-last
    } removal;
};

static large solve(const Robot *const robots, const Robot *const end) {
    if (robots == end) {
        return 1;
    }
    auto cnt = end - robots;
    if (memo[cnt] >= 0)
        return memo[cnt];

    large ans = 0;

    // activate (and remove)
    {
        large c = solve(robots->removal.end, end);
        ans += c;
        if (ans >= mod)
            ans -= mod;
    }
    // not activate
    {
        large c = solve(robots + 1, end);
        ans += c;
        if (ans >= mod)
            ans -= mod;
    }

    memo[cnt] = ans;
    return ans;
}

int main() {
    for (auto &m : memo)
        m = -1;

    int n;
    cin >> n;
    auto robots = vector<Robot>(n);
    for (int i = 0; i < n; i++) {
        cin >> robots[i].x >> robots[i].d;
    }
    sort(robots.begin(), robots.end(), [](auto &a, auto &b) { return a.x < b.x; });
    robots.push_back(Robot());
    robots[n].x = 2'100'000'000;
    robots[n - 1].removal.begin = &robots[n - 1];
    robots[n - 1].removal.end = &robots[n - 1] + 1;

    for (int i = n - 2; i >= 0; i--) {
        auto *r1 = &robots[i];
        r1->removal.begin = r1;
        r1->removal.end = r1 + 1;

        int x_limit = r1->x + r1->d;

        // check chain reactions
        auto *r2 = r1 + 1;
        while (r2->x < x_limit) {
            robots[i].removal.end = r2->removal.end;
            r2 = r2->removal.end - 1;
            x_limit = max(x_limit, r2->x + r2->d);
            r2++;
        }
    }

    cout << solve(robots.data(), robots.data() + n);
    return 0;
}

