template<class T>
class SegmentTree {
    using Func = std::function<T(T, T)>;
    private:
        const Func F;
        const T DEF;
        int N;
        std::vector<T> dat;
    public:
        SegmentTree(int n, const Func f, const T def) : F(f), DEF(def) {
            N = 1;
            while (N < n) N *= 2;
            dat.assign(2*N, DEF);
        }
        // a is 0-indexed
        void set(int a, const T v) { dat[a+N] = v; }
        void build() { for (int i=N-1; i>0; --i) dat[i] = F(dat[2*i], dat[2*i+1]); }
        // a is 0-indexed
        void update(int a, const T v) {
            int cur = a + N;
            dat[cur] = v;
            while ((cur /= 2) > 0) dat[cur] = F(dat[2*cur], dat[2*cur+1]);
        }
        // return value of [a, b)
        // a and b are 0-indexed
        T get(int a, int b) const { return get(a, b, 1, 0, N); }
        T get(int a, int b, int k, int l, int r) const {
            if (b <= l || r <= a) return DEF;
            if (a <= l && r <= b) return dat[k];
            T vleft = get(a, b, 2*k, l, (l+r)/2);
            T vright = get(a, b, 2*k+1, (l+r)/2, r);
            return F(vleft, vright);
        }
        // a is 0-indexed
        T at(int a) const { return dat.at(a+N); }
};

void solve() {
    int N;
    cin >> N;
    vector<pair<int, int>> robots(N);
    for (int i=0; i<N; ++i) cin >> robots[i].first >> robots[i].second;

    sort(robots.begin(), robots.end());
    SegmentTree<int> st(N, [](int a, int b){return max(a, b);}, 0);
    for (int i=0; i<N; ++i) st.set(i, i+1);
    st.build();
    for (int i=N-2; i>=0; --i) {
        int p = lower_bound(robots.begin(), robots.end(), make_pair(robots[i].first+robots[i].second, 0)) - robots.begin();
        st.update(i, st.get(i, p));
    }
    vector<MInt> dp(N+1);
    dp[N] = 1;
    for (int i=N-1; i>=0; --i) dp[i] = dp[i+1] + dp[st.at(i)];
    cout << dp[0] << '\n';
}

