template<class T>
struct SegTree
{
	lint n;
	vector<T> t;
	T neutral;

	SegTree(lint _n, const T& _neutral) : neutral(_neutral)
	{
		n = 1;
		while (n < _n)
		{
			n *= 2;
		}
		rep(i, n)
		{
			t.resize(2 * n, neutral);
		}
	}

	using funcT = T(T val1, T val2);
	funcT* un;

	void update(lint i, const T& val)
	{
		i += n - 1;
		t[i] = val;
		while (i > 0)
		{
			i = (i - 1) / 2;
			t[i] = un(t[i * 2 + 1], t[i * 2 + 2]);
		}
	}

	T query_impl(lint a, lint b, lint k, lint l, lint r)
	{
		if (r <= a || b <= l)
			return neutral;
		if (a <= l && r <= b)
			return t[k];
		else
		{
			const T c1 = query_impl(a, b, 2 * k + 1, l, (l + r) / 2);
			const T c2 = query_impl(a, b, 2 * k + 2, (l + r) / 2, r);
			return un(c1, c2);
		}
	}

	T query(lint l, lint r)
	{
		return query_impl(l, r, 0, 0, n);
	}

};


struct mint
{
	lint n;
	mint()
	{
		n = 0;
	}
	mint(lint a)
	{
		n = a % mod;
	}
	mint& operator+=(mint a)
	{
		n += a.n;
		n %= mod;
		return *this;
	}
	mint& operator-=(mint a)
	{
		n += mod;
		n -= a.n;
		n %= mod;
		return *this;
	}
	mint& operator*=(mint a)
	{
		n *= a.n;
		n %= mod;
		return *this;
	}
	mint& operator%=(mint a)
	{
		n %= a.n;
		return *this;
	}
	mint& operator++()
	{
		n++;
		n %= mod;
		return *this;
	}
	mint& operator--()
	{
		n += mod;
		n--;
		n %= mod;
		return *this;
	}
};

