struct Robot
{
    ll X,D;
    bool operator<(const Robot& o)const&
    {
        return X < o.X;
    }
};
void solve(long long N, std::vector<long long> X, std::vector<long long> D){
    vector<Robot> dat;
    for(int i=0;i<N;++i)
    {
        dat.push_back({X[i],D[i]});
    }
    sort(dat.begin(),dat.end());
    vector<int> ActiveDis(N);
    ActiveDis[N-1] = N-1;
    stack<int> s;
    s.push(N-1);
    for(int i=N-2;i>=0;--i)
    {
        int res = i;
        while(!s.empty() && dat[i].X + dat[i].D > dat[s.top()].X)
        {
            res = ActiveDis[s.top()];
            s.pop();
        }
        ActiveDis[i] = res;
        s.push(i);
    }
    vector<ll> dp(N+1,0);
    dp[N] = 1;
    for(int i=N-1;i>=0;--i)
    {
        dp[i] += dp[i+1];
        dp[i] += dp[ActiveDis[i]+1];
        dp[i] %= MOD;
    }
    cout<<dp[0]<<endl;
}

