void update(int pos,int val,int s=0,int e=n-1,int p=1){

   if(s==e){
     tree[p]=val;
     return ;
   }
   int m=(s+e)/2;
   if(pos<=m)
   update(pos,val,s,m,p*2);
   else{
    update(pos,val,m+1,e,p*2+1);
   }
   tree[p]=max(tree[p*2],tree[p*2+1]);
}
ll query(int a,int b,int s=0,int e=n-1,int p=1){

   if(b<s||a>e) return 0;
   if(s>=a&&e<=b){
      return tree[p];
   }
   int m=(s+e)/2;
   return max(query(a,b,s,m,p*2),query(a,b,m+1,e,p*2+1));
}
