template <typename T>
class Segment {
    using u32 = uint_fast32_t;
    u32 n;
    vector<T> node;
    T e;                  // 単位元∧初期値
    function<T(T, T)> f;  // 更新
    function<T(T, T)> g;  // 取得

   public:
    Segment(u32 N, T e, function<T(T, T)> f, function<T(T, T)> g, vector<T> v = vector<T>())
        : e(e), f(f), g(g) {
        n = 1;
        while (n < N) n *= 2;
        node.assign(2 * n - 1, e);
        if (N == (u32)v.size()) {
            for (int i = 0; i < N; i++) node[i + n - 1] = v[i];
            for (int i = n - 2; i >= 0; i--) {
                node[i] = g(node[2 * i + 1], node[2 * i + 2]);
            }
        }
    }

    // k番目をaで更新
    void update(u32 k, T a) {
        k += n - 1;
        node[k] = f(node[k], a);
        while (k > 0) {
            k = (k - 1) / 2;
            node[k] = g(node[2 * k + 1], node[2 * k + 2]);
        }
    }

    // [a,b)の区間取得
    T get(u32 a, u32 b, u32 k, u32 l, u32 r) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return e;  // 含まない
        if (a <= l && r <= b)            // 完全に含む
            return node[k];
        else {
            T vl = get(a, b, 2 * k + 1, l, (l + r) / 2);
            T vr = get(a, b, 2 * k + 2, (l + r) / 2, r);
            return g(vl, vr);
        }
    }
    T get(u32 a, u32 b) { return get(a, b, 0, 0, n); }

    T operator[](u32 i) { return node[i + n - 1]; }
};

