#define     F       first
#define     S       second
typedef pair<int, int>  pi;
typedef long long       ll;

const int MAX=2e5+9;
const int MOD=998244353;
int n, lst[MAX];
ll dp[MAX];
vector<pi> v;
bool can[MAX];
int tree[(MAX<<2)], idx, l, r, val;

void upd(int low, int high, int pos) {
    if (low==high) {
        tree[pos]=val;
        return;
    }

    int mid=((low+high)>>1);
    if (idx<=mid) {
        upd(low, mid, (pos<<1|1));
    }
    else {
        upd(mid+1, high, (pos<<1)+2);
    }

    tree[pos]=max(tree[(pos<<1|1)], tree[(pos<<1)+2]);
}

int qwr(int low, int high, int pos) {
    if (l>high || r<low) {
        return 0;
    }

    if (l<=low && r>=high) {
        return tree[pos];
    }

    int mid=((low+high)>>1);
    return max(qwr(low, mid, (pos<<1|1)), qwr(mid+1, high, (pos<<1)+2));
}

int BSFindLast(int low, int high, int val) {
    int res=low;
    while (low<=high) {
        int mid=((low+high)>>1);

        if (v[mid].F<=val) {
            res=mid;
            low=mid+1;
        }
        else {
            high=mid-1;
        }
    }

    return res;
}

