struct Interval
{
	int64_t start;
	int64_t end;

	Interval() = default;
	Interval(int64_t s, int64_t e) : start(s), end(e) {};

	bool operator<(const Interval &other) const
	{
		return start < other.start;
	}
};

struct TreeNode
{
	Interval interval;
	int64_t max_end;
	int index;

	TreeNode *left;
	TreeNode *right;

	TreeNode() = default;
	TreeNode(const Interval &inter, int in_index)
		: index(in_index)
		, left(nullptr)
		, right(nullptr)
	{
		interval = inter;
		max_end = inter.end;
	}

	~TreeNode()
	{
		if (left != nullptr)
		{
			delete left;
		}

		if (right != nullptr)
		{
			delete right;
		}
	}
};

int FindSegTree(TreeNode *root, int64_t val, int index)
{
	if (root->interval.start < val && root->interval.end > val)
	{
		return root->index;
	}

	if (root->left != nullptr)
	{
		if (root->left->max_end > val)
		{
			return FindSegTree(root->left, val, index);
		}
	}

	if (root->right != nullptr)
	{
		return FindSegTree(root->right, val, index);
	}

	return root->index;
}

TreeNode* BuildTree(const std::vector<Interval> &intervals, int start, int end)
{
	if (start >= end)
	{
		return nullptr;
	}

	int middle = (start + end) / 2;
	auto root = new TreeNode(intervals[middle], middle);

	root->left = BuildTree(intervals, start, middle);
	root->right = BuildTree(intervals, middle + 1, end);

	if (root->left != nullptr)
	{
		root->max_end = std::max(root->max_end, root->left->max_end);
	}

	if (root->right != nullptr)
	{
		root->max_end = std::max(root->max_end, root->right->max_end);
	}

	return root;
}

void GenerateHelpArray(const std::vector<Interval> &intervals, std::vector<int64_t> &R)
{
	int N = intervals.size();
	for (int i = N - 1; i >= 0; --i)
	{
		auto root = BuildTree(intervals, i, N);
		R[i] = i;
		int64_t val = intervals[i].end;

		bool find = false;
		do
		{
			find = false;
			int index = FindSegTree(root, val, i);
			if (intervals[index].start < val && intervals[index].end > val)
			{
				find = true;
				R[i] = std::max(R[i], R[index]);
				val = intervals[index].end;
			}
		} while (find);

		delete root;
	}
}

int main()
{
	int N;
	std::cin >> N;

	std::vector<Interval> intervals;
	intervals.reserve(N);

	int64_t X, D;
	for (int i = 0; i < N; ++i)
	{
		std::cin >> X >> D;
		intervals.emplace_back(X, X + D);
	}

	std::sort(intervals.begin(), intervals.end());

	std::vector<int64_t> R(N, 0);
	GenerateHelpArray(intervals, R);

	std::vector<int64_t> dp(N + 1, 0);
	dp[N] = 1;
	for (int i = N - 1; i >= 0; --i)
	{
		dp[i] = (dp[i + 1] + dp[R[i] + 1]) % 998244353;
	}

	std::cout << dp[0] << std::endl;

	return 0;
}

