        ll r = mp.lower_bound(x+d)->second;
        ll ma = -seg.find(i+1,r);
        if(ma==-INF) ma=i+1;
        dp[i]=(dp[i+1]+dp[ma])%MOD;
        seg.update(i,-ma);
    }
