using namespace std;
struct node{
    int l,r;
    long long mx = 0;
};
node tree[200005*4+5];
vector<pair<int,int>>robot;
void build(int cur, int l, int r){
    tree[cur].l = l;
    tree[cur].r = r;
    if(l == r){
        tree[cur].mx = robot[l].first+robot[l].second;
    }
    else{
        int mid = (l+r)/2;
        build(cur*2,l,mid);
        build(cur*2+1,mid+1,r);
        tree[cur].mx = max(tree[cur*2].mx,tree[cur*2+1].mx);
    }
}
void update(int cur,long long goal, long long num){
    if(tree[cur].l == tree[cur].r &&tree[cur].l == goal){
        tree[cur].mx = num;
    }
    else{
        int mid = (tree[cur].l+tree[cur].r)/2;
        if(goal <= mid){
            update(cur*2,goal,num);
        }
        else{
            update(cur*2+1,goal,num);
        }
        tree[cur].mx = max(tree[cur*2].mx,tree[cur*2+1].mx);
    }
}
long long fnd(int cur, int l , int r){
    if(tree[cur].l >=l && tree[cur].r <= r){
        return tree[cur].mx;
    }
    else{
        int mid = (tree[cur].l+tree[cur].r)/2;
        long long best;
        bool st = false;
        if(l<=mid ){
            st = true;
            best = fnd(cur*2,l,r);
        }
        if(mid+1 <=r){
            if(st){
                best = max(fnd(cur*2+1,l,r),best);
            }
            else{
                st =true;
                best = fnd(cur*2+1,l,r);
            }
        }
        if(st)
        return best;
        else
        {
            return -10000000000;
        }

    }
}
