void Build(int x,int l,int r)
{
	if(l==r){mx[x]=l;return;}
	int mid=l+r>>1;
	Build(ls,l,mid);
	Build(rs,mid+1,r);
    mx[x]=max(mx[ls],mx[rs]);
}
int getMax(int L,int R,int x,int l,int r)
{
	if(L<=l && r<=R)return mx[x];
	int mid=l+r>>1,res=0;
	if(L<=mid)res=max(res,getMax(L,R,ls,l,mid));
	if(R>mid)res=max(res,getMax(L,R,rs,mid+1,r));
	return res;
}
void Change(int i,int c,int x,int l,int r)
{
	if(l==r){mx[x]=c;return;}
	int mid=l+r>>1;
	if(i<=mid)Change(i,c,ls,l,mid);
	else Change(i,c,rs,mid+1,r);
	mx[x]=max(mx[ls],mx[rs]);
}
