using point = complex<double>;
using ll = long long;
const ll MOD = 998244353;
using md = mod_int<MOD>;

int my_main(int argc, char** argv)
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<pair<ll, ll>> robots;
    for (int i = 0; i < n; i++) {
        ll x, d;
        cin >> x >> d;
        robots.emplace_back(x, d);
    }

    sort(all(robots));

    stack<pair<ll, md>> k;
    for (int i = robots.size() - 1; i >= 0; i--) {
        ll x = robots[i].first;
        ll d = robots[i].second;

        bool has_intersect = false;
        md g = 1;
        while (!k.empty()) {
            if (x + d > k.top().first) {
                has_intersect = true;
                g *= k.top().second;
                k.pop();
            } else {
                break;
            }
        }

        if (has_intersect) {
            md r = g + 1;
            k.push({ x, r });
        } else {
            k.push({ x, 2 });
        }

#ifdef DEBUG
        auto backup = k;
        while (!k.empty()) {
            std::cerr << k.top().first << " " << k.top().second.value() << endl;

            k.pop();
        }
        std::cerr << " ---" << std::endl;
        k = backup;
#endif
    }

    md ret = 1;
    while (!k.empty()) {
        ret *= k.top().second;
        k.pop();
    }

    cout << ret.value() << endl;

    return 0;
}

