const int N = 2e5 + 3;
const int MOD = 998244353;

int n, dp[N];
pair <int, int> x[N];

int main() {
    cin >> n;

    for (int i = 0; i < n; i++) {
        scanf("%d%d", &x[i].first, &x[i].second);
    }

    sort(x, x + n);

    vector <int> next(n, n);
    vector <int> que;

    for (int i = n - 1; i >= 0; i--) {
        int d = x[i].first + x[i].second;
        while (!que.empty()) {
            int v = que.back();
            if (x[v].first < d) {
                que.pop_back();
            } else {
                break;
            }
        }
        if (!que.empty()) {
            next[i] = que.back();
        }
        que.push_back(i);
    }

    dp[0] = 1;

    for (int i = 0; i < n; i++) {
        int j = next[i];
        dp[j] += dp[i];
        if (dp[j] >= MOD) {
