template <typename T>
struct fenwick_tree {
  using F = function<T(T, T)>;
  const F f;
  vector<T> data;
  fenwick_tree(int sz, const F f) : f(f) {
    data.assign(++sz, 0);
  }
  T query(int k) {
    T ret = 0;
    for (++k; k > 0; k -= k & -k) ret = f(ret, data[k]);
    return ret;
  }
  void add(int k, T x) {
    for (++k; k < data.size(); k += k & -k) data[k] = f(data[k], x);
  }
};
