void solve(int n, vi x, vi d) {
  vp xy(n);
  rep(i, n)xy[i] = mp(x[i], x[i] + d[i]);
  SORT(xy);
  vi maxi(n);
  fenwick_tree<int> ft(n, [](int a, int b){ return max(a, b); });
  rrep(i, n) {
    int r = lower_bound(all(xy), mp(xy[i].second, -INF)) - xy.begin();
    maxi[i] = max(i, ft.query(r - 1));
    ft.add(i, maxi[i]);
  }
  vector<mint> dp(n + 1);
  dp[n] = 1;
  rrep(i, n)dp[i] = dp[i + 1] + dp[maxi[i] + 1];
  COUT(dp[0]);
}


