struct SegmentTreeNode 
{
    int res;

    void assignLeaf(int value) 
    {
        res = value;
    }

    void merge(SegmentTreeNode& left, SegmentTreeNode& right) 
    {
        res = max(left.res, right.res);
    }

    int getValue() 
    {
        return res;
    }
};



template<class T, class V>
class SegmentTree
{
    SegmentTreeNode *nodes;
    int N;

public:
    SegmentTree(T arr[], int N)
    {
        this->N = N;
        nodes = new SegmentTreeNode[getSize(N)];
        buildTree(arr, 1, 0, N - 1);
    }

    ~SegmentTree()
    {
        delete []nodes;
    }

    V getValue(int lo, int hi)
    {
        SegmentTreeNode result = getValue(1, 0, N - 1, lo, hi);
        return result.getValue();
    }

    void update(int index, T val)
    {
        update(1, 0, N - 1, index, val);
    }


private:

    void buildTree(T arr[], int stIndex, int lo, int hi)
    {
        if(lo == hi)
        {
            nodes[stIndex].assignLeaf(arr[lo]);
            return;
        }
        int mid = (lo + hi) / 2;
        buildTree(arr, 2*stIndex, lo, mid);
        buildTree(arr, 2*stIndex + 1, mid + 1, hi);
        nodes[stIndex].merge(nodes[2*stIndex], nodes[2*stIndex + 1]);
    }

    SegmentTreeNode getValue(int stIndex, int left, int right, int lo, int hi)
    {
        if(left == lo && right == hi)
            return nodes[stIndex];
        int mid = (left + right) / 2;
        if(lo > mid)
            return getValue(2*stIndex + 1, mid + 1, right, lo, hi);
        if(hi <= mid)
            return getValue(2*stIndex, left, mid, lo, hi);
        SegmentTreeNode leftResult = getValue(2*stIndex, left, mid, lo, mid);
        SegmentTreeNode rightResult = getValue(2*stIndex + 1, mid + 1, right, mid + 1, hi);
        SegmentTreeNode result;
        result.merge(leftResult, rightResult);
        return result;
    }


    void update(int stIndex, int lo, int hi, int index, T value)
    {
        if(lo == hi)
        {
            nodes[stIndex].assignLeaf(value);
            return;
        }
        int mid = (lo + hi) / 2;
        if(index <= mid)
            update(2*stIndex, lo, mid, index, value);
        else
            update(2*stIndex + 1, mid + 1, hi, index, value);
        nodes[stIndex].merge(nodes[2*stIndex], nodes[2*stIndex + 1]);
    }


    int getSize(int n)
    {
		int size = 1;
		for (; size < N; size <<= 1);
		return size << 1;
    }
};

