ll f(ll i) {
  static vector<ll> memo(300000, -1);
  if (i >= N)
    return 1;
  if (memo[i] != -1)
    return memo[i];
  // ノードiを選択しない
  ll res = f(i+1);
  // ノードiを選択する
  res += f(st.get(i)+1);
  return memo[i] = res;
}

