	for (int i=n-1;i>=0;i--){
		long long l=i, r=n-1, tmp, far=robot[i].first+robot[i].second;
		while (l<=r){
			long long mid=(l+r)/2;
			if (robot[mid].first<far){
				tmp=mid;
				l=mid+1;
			}
			else r=mid-1;
		}
		farthest[i]=query(0,n-1,i,tmp,1);
		update(0,n-1,1,i);
	}
//	for (int i=0;i<n;i++) cout << farthest[i] << "\n";
	memset(dp,0,sizeof dp);
	dp[0]=1;
	for (int i=0;i<n;i++){
		dp[i+1]+=dp[i]; // kalau i remain
		dp[i+1]%=mod;
		dp[farthest[i]+1]+=dp[i]; // kalau i tidak remain
		dp[farthest[i]+1]%=mod;
