#define ll long long

ll mod = 998244353;

struct segtree{
    int size;
    vector<ll> dat;
    ll init = -1;

    segtree (int N) {
        size = 1;
        while (size < N) size *= 2;
        dat = vector<ll>(2*size-1, init);
    }

    ll op(ll a, ll b) {
        return max(a, b);
    }

    void update(int i, ll x) { 
        i += size-1;
        dat[i] = x;
        while (i > 0) {
            i = (i-1)/2;
            dat[i] = op(dat[2*i+1], dat[2*i+2]);
        }
        return;
    }

    ll query(int a, int b) {
        return query(a, b, 0, 0, size);
    }

    ll query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return init;
        if (a <= l && r <= b) return dat[k];
        ll lv, rv;
        lv = query(a, b, 2*k+1, l, (l+r)/2);
        rv = query(a, b, 2*k+2, (l+r)/2, r);
        return op(lv, rv);
    }
};

int main() {
    int N;
    cin >> N;
    vector<pair<ll, ll>> robo(N);
    for (int i = 0; i < N; i++) cin >> robo[i].first >> robo[i].second;
    sort(robo.begin(), robo.end());

    segtree st(N+10);

    vector<vector<ll>> dp(N, vector<ll>(2, 0));
    dp[N-1][0] = 1;
    dp[N-1][1] = 1;
    st.update(N-1, N-1);

    for (int i = N-2; i >= 0; i--) {
        dp[i][0] = (dp[i+1][0] + dp[i+1][1])%mod;
        pair<ll, ll> rm = {robo[i].first + robo[i].second, 0};
        auto it = lower_bound(robo.begin(), robo.end(), rm);
        int pos = distance(robo.begin(), it);
        if (pos == i+1) {
            st.update(i, i);
            dp[i][1] = dp[i][0];
        }else {
            ll h = st.query(i+1, pos);
            st.update(i, h);
            dp[i][1] = dp[h][1];
        }
    }
    cout << (dp[0][0] + dp[0][1])%mod << endl;
    return 0;
}

