void Update(ll i, ll x, vi &value) {
	i += (value.size() + 1) / 2;
	value[i] = x;
	while (i > 0) {
		i = (i - 1) / 2;
		value[i] = min(value[i * 2 + 1], value[i * 2 + 2]);
	}
}

ll Query(ll a, ll b, ll k, ll l, ll r, vi &value) {
	if (r <= a || b <= l)return LLMAX;
	if (a <= l && r <= b)
		return value[k];
	else {
		ll c1 = Query(a, b, 2 * k + 1, l, (l + r) / 2, value);
		ll c2 = Query(a, b, 2 * k + 2, (l + r) / 2, r, value);
		return min(c1, c2);
	}
}


int main() {
	cin >> N;

	vi X(N);
	vpii XD(N);

	rep(i, N) {
		ll x, d;
		cin >> x >> d;

		X[i] = -x;
		XD[i] = mp(-x, d);
	}

	sort(all(XD));
	sort(all(X));

	// セグ木
	ll n = 1;
	while (n < N)
		n *= 2;

	vi seg(2 * n - 1, LLMAX);

	vi dp(N + 1, 0);
	dp[0] = 2;
	Update(0, 0, seg);

	for(ll i = 1; i < N; i++){
		ll x = XD[i].first;
		ll xd = x - XD[i].second;

		auto itr = upper_bound(all(X), xd);
		// どこまでさかのぼるか
		ll idx = itr - X.begin();

		Update(i, idx, seg);

		if (idx == i){
			dp[i] = (2 * dp[i - 1]) % MOD;
		}
		else {
			ll min = Query(idx, i + 1, 0, 0, n, seg);
			if (min == 0) {
				dp[i] = (dp[i - 1] + 1) % MOD;
			}
			else {
				dp[i] = (dp[i - 1] + dp[min - 1]) % MOD;
			}
		}
	}

	cout << dp[N - 1] << endl;

	return 0;
}

