typedef long long ll;
const ll MOD = 998244353;
const long double EPS = 1e-8;

class SegmentTree {
    vector<int> nodes_;
    int size_;
    inline static constexpr int INIT = -1;

    int query (const int left, const int right, const int index, const int l, const int r) const {
        if (r <= left || right <= l) return INIT;
        if (left <= l && r <= right) return nodes_[index];

        return max (
                query(left, right, 2 * index + 1, l, (l + r) / 2),
                query(left, right, 2 * index + 2, (l + r) / 2, r)
        );
    }

public:
    SegmentTree(const int maxSize) {
        size_ = 1;
        while (size_ < maxSize) size_ *= 2;
        nodes_ = vector<int> (2 * size_, INIT);
    };

    void update (int index, const int value) {
        index += size_ - 1;
        nodes_[index] = value;
        while (index > 0) {
            index = (index - 1) / 2;
            nodes_[index] = max(nodes_[2 * index + 1], nodes_[2 * index + 2]);
        }
    }

    // get value in [left, right)
    int get (const int left, const int right) const {
        return query(left, right, 0, 0, size_);
    }
};

void solve(long long N, std::vector<long long> X, std::vector<long long> D){
    vector<vector<ll>> dp(N, vector<ll>(2));
    vector<pair<ll, ll>> robots(N);
    rep(i,0,N) robots[i] = {X[i], D[i]};
    sort(all(robots));
    SegmentTree st(N+1);
    vector<int> rights(N+1, -1);
    rrep(i,0,N) {
        auto itr = lower_bound(all(robots), make_pair(robots[i].first + robots[i].second, 0LL));
        int value;
        if (itr == robots.end()) {
            value =  N;
            st.update(i, value);
        } else {
            int j = distance(robots.begin(), itr);
            value = j != i+1 ? st.get(i+1, j) : i+1;
            st.update(i, value);
        }
        rights[i] = value;
    }
    dp[N-1][1] = 1;
    dp[N-1][0] = 1;
    rrep(i,0,N-1) {
        dp[i][1] = dp[i+1][1] + dp[i+1][0];
        if (rights[i] == N) {
            dp[i][0] = 1;
        } else {
            dp[i][0] = dp[rights[i]][0] + dp[rights[i]][1];
        }
        dp[i][1] %= MOD;
        dp[i][0] %= MOD;
    }
    cout << (dp[0][0] + dp[0][1]) % MOD << endl;
}

