#include <functional>
template<typename T>
class SegmentTree{
private:
  const size_t offset;
  const std::function<T(T,T)> f;
  const T unit;
  std::vector<T> tree;
  size_t mlb(size_t N) const{
    N |= (N >> 1);
    N |= (N >> 2);
    N |= (N >> 4);
    N |= (N >> 8);
    N |= (N >> 16);
    N |= (N >> 32);
    return (N - (N >> 1));
  };
public:
  SegmentTree(const size_t N, const std::function<T(T,T)> f_, const T unit_):
    offset((mlb(N) << 1) - 1),
    f(f_),
    unit(unit_),
    tree(std::vector<T>(((offset+1) << 1) - 1))
  {
    std::fill(tree.begin(), tree.end(), unit);
  };

  ~SegmentTree(){
  };
  const T& operator[](const size_t i) const{
    return tree[i+offset];
  }

  void update(const size_t i, const T t){
    size_t index = i + offset;
    tree[index] = t;
    while(index){
      index = (index-1)/2;
      tree[index] = f(tree[2*index + 2], tree[2*index + 1]);
    }
  }

  T query(size_t a, size_t b, const bool first_call = true) const{
    if(first_call){
      a += offset;
      b += offset;
    }
    if(a == b){
      return tree[a];
    }
    else if(a+1 == b){
      return f(tree[a], tree[b]);
    }
    else if(a&1 and !(b&1)){
      return query(a/2, (b-1)/2, false);
    }
    else if(a&1 and b&1){
      return f(query(a/2, (b-2)/2, false), tree[b]);
    }
    else if(!(a&1) and !(b&1)){
      return f(query(a/2, (b-1)/2, false), tree[a]);
    }
    else if(!(a&1) and b&1){
      return f(f(query(a/2, (b-2)/2, false), tree[a]), tree[b]);
    }
    else{
      throw 1;
    }
  }
};

int main(){
  long N;
  std::cin >> N;
  std::vector<long> X(0);
  std::vector<long> D(0);
  SegmentTree<unsigned long> R(N,
                               [](unsigned long a, unsigned long b){
                                 return std::max(a,b);
                               },
                               0ul);
  std::vector<long> d(N+1,0);
  for(long i = 0; i < N; ++i){
    long Xi, Di;
