    auto it = std::upper_bound(X.begin(),X.end(),Xi);
    long index = it - X.begin();
    X.insert(it,Xi);
    D.insert(D.begin() + index, Di);
  }
  R.update(N-1, N-1);
  for(long i = N-2; i >= 0; --i){
    auto it = std::lower_bound(X.begin()+i, X.end(), X[i] + D[i]);
    long index = it - X.begin() - 1;
    R.update(i, std::max((unsigned long)i, R.query(i, index)));
  }
  d[N] = 1;
  d[N-1] = 2;
  for(long i = N-2; i >= 0; --i){
