#define L (nod << 1)
#define R (L | 1)
#define smax(X, Y) ((X) > (Y) ? (X) : (Y))
#define smin(X, Y) ((X) < (Y) ? (X) : (Y))

int arb[4 * N];

void update(int nod, int st, int dr, int idx, int val){
    if (st == dr){
        arb[nod] = val;
        return;
    }
    int mid = (st + dr) >> 1;
    if (idx <= mid) update(L, st, mid, idx, val);
    else update(R, mid+1, dr, idx, val);
    arb[nod] = smax(arb[L], arb[R]);
}

int query(int nod, int st, int dr, int l, int r){
    if (st >= l && dr <= r) return arb[nod];
    int mid = (st + dr) >> 1;
    int to_left = 0, to_right = 0;
    if (l <= mid) to_left = query(L, st, mid, l, r);
    if (r > mid) to_right = query(R, mid+1, dr, l, r);
    return smax(to_left, to_right);
}

