	return (a + b) % MOD;
}

const int N = 2e5 + 7;

int dp[N];
int dg[N];
vector<int> g[N];

int solve(int v) {
	if (dp[v] == -1) {
		int pdp = 1;
		for (auto t : g[v]) {
			pdp = mul(pdp, solve(t));
		}
		dp[v] = add(pdp, 1);
	}
	return dp[v];
}

int n;

