struct SegTree{
  int n;
  vector<int> node;
  int ui=-2000000010;

public:
  SegTree(vector<int> v){
    n=1;
    while((1<<(n-1))<v.size()) n++;
    node.resize((1<<n)-1,ui);
    for(int i=0;i<v.size();i++){
      node[(1<<(n-1))-1+i]=v[i];
    }
    for(int i=(1<<(n-1))-2;0<=i;i--){
      node[i]=max(node[2*i+1], node[2*i+2]);
    }
  }

  int compare(int a,int b){
    return max(a,b);
  }

  int find(int a, int b){
    int l=((1<<(n-1))-1)+a;
    int r=((1<<(n-1))-1)+b;

    return find_(l,r);
  }

  int find_(int l, int r){
    if(l==r || l==r-1) return compare(node[l],node[r]);
    else{
      int ans=ui;
      if(l%2==0){
	ans=compare(ans,node[l]);
      }
      if(r%2==1){
	ans=compare(ans,node[r]);
      }
      ans=compare(ans,find_(l/2,(r-2)/2));
      return ans;
    }
  }

  int get(int p){
    return node[(1<<(n-1))-1+p];
  }

  int set(int p, int val){
    int cur=(1<<(n-1))-1+p;
    node[cur]=val;
    for(int i=0;i<n-1;i++){
      cur=(cur-1)/2;
      node[cur]=compare(node[2*cur+1],node[2*cur+2]);
    }
    return 0;
  }

  int show(){
    int cur=0;
    for(int i=0;i<n;i++){
      for(int j=cur;j<2*cur+1;j++){
	//cout << "(" << j << ")" << node[j];
      }
      cur=2*cur+1;
      //cout << endl;
    }
    return 0;
  }
};


