struct Segtree{
    int siz=1;
    vector<int>dat;
    Segtree(int N){
        while(siz<N)siz*=2;
        dat.resize(siz*2-1,-INF);
        rep(i,N)dat[i+siz-1]=i;
        for(int i=siz-2;i>=0;i--)dat[i]=max(dat[i*2+1],dat[i*2+2]);
    }
    void update(int k,int x){
        k+=siz-1;
        dat[k]=x;
        while(k>0){
            k=(k-1)/2;
            dat[k]=max(dat[k*2+1],dat[k*2+2]);
        }
    }
    int query(int a,int b,int k=0,int l=0,int r=-1){
        if(r==-1)r=siz;
        if(r<=a||b<=l)return -INF;
        if(a<=l&&r<=b)return dat[k];
        int m=(l+r)/2;
        int vl=query(a,b,k*2+1,l,m);
        int vr=query(a,b,k*2+2,m,r);
        return max(vl,vr);
    }
};
