void upd(int l,int r,int val,int pos,int ind)
{
	if(l==r) {seg[ind]=val; return;}
	int s=(l+r)/2;
	if(pos<=s) upd(l,s,val,pos,2*ind);
	else upd(s+1,r,val,pos,2*ind+1);
	seg[ind]=max(seg[2*ind],seg[2*ind+1]);
}
int nmax(int l,int r,int lt,int rt,int ind)
{
	if(lt<=l && rt>=r) return seg[ind];
	if(r<lt || l>rt) return -1000000001;
	int s=(l+r)/2;
	return max(nmax(l,s,lt,rt,2*ind),nmax(s+1,r,lt,rt,2*ind+1));
}
int binarna(int l,int r,int val) 
{
	if(l==r) return l;
	int s=(l+r)/2;
	if(rb[s].x>=val) return binarna(l,s,val);
	return binarna(s+1,r,val);
}
