int lim;

void upd(int idx, int v){
  idx += lim;
  tree[idx] = max(tree[idx],v);
  idx /= 2;
  while(idx > 0){
    tree[idx] = max(tree[idx * 2], tree[idx * 2 + 1]);
    idx /= 2;
  }
}

int qry(int l, int r){
  l += lim;
  r += lim;
  int res = 0;
  while(l <= r){
    if(l % 2 == 1) res = max(res, tree[l ++ ]);
    if(r % 2 == 0) res = max(res, tree[r -- ]);
    l /= 2;
    r /= 2;
  }
  return res;
}

