		x[i] = p[i].first;
		y[i] = p[i].second;
	}
	p.pb(P(INF, INF));
	vector<int> use(n);
	for (int i = 0; i < n; i++) {
		int g = lower_bound(all(x), y[i]) - x.begin();
		use[i] = g - 1;
	}
	lazysegtree<int> dp(n + 2);
	dp.change(n, 1);
	for (int i = n - 1; i >= 0; i--) {
		int sum = dp.get(i + 1, n + 1);
		dp.change(i, sum);
		dp.lazychange(i + 1, use[i] + 1, 0);
	}
	int ans = 0;
	rep(i, n + 1) {
		ans += dp[i];
		ans %= mod;
	}
	cout << ans << endl;
}

