struct mint {
    const int mod = 998244353;
    long long x;

    mint (long long x = 0) : x((x % mod + mod) % mod) {

    }

    mint& operator=(const long long a) {
        x = a % mod;
        return *this;
    }

    mint& operator=(const mint a) {
        x = a.x % mod;
        return *this;
    }

    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint& operator-=(const mint a) {
        if ((x += (mod - a.x)) >= mod) x -= mod;
        return *this;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(long long t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    mint inv() const {
        return pow(mod - 2);
    }

    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }

    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }
};

vector<vector<ll>> g;

mint dfs(ll v, ll p = -1) {
    mint ans = 1;
    for(auto u : g[v]) {
        if (u == p) continue;
        ans *= dfs(u, v);
    }
    return ans + 1;
}

