void updaterange(ll cur,ll st,ll end,ll l,ll r,ll val)
{
  if(lazy[cur]!=0)                                    /* 2-change */
  {
    seg[cur]=0;          /* 3-change */
    if(st!=end)
    {
      lazy[cur<<1]=1;            /* 4-change */
      lazy[(cur<<1)+1]=1;                   /* 5-change */
    }
    lazy[cur]=0;                                    /* 6-change */
  }
  if(st>end||st>r||end<l) return;
  if(l<=st&&end<=r)
  {
    seg[cur]=0;              /* 7-change */
    if(st!=end)
    {
      lazy[(cur<<1)]=1;                           /* 8-change */
      lazy[(cur<<1)+1]=1;                         /* 9-change */
    }
    return;
  }
  ll mid=(st+end)>>1;
  updaterange((cur<<1),st,mid,l,r,val);
  updaterange((cur<<1)+1,mid+1,end,l,r,val);
  seg[cur]=add(seg[cur<<1],seg[(cur<<1)+1]);                  /* 10-change */
}
ll query(ll cur,ll st,ll end,ll l,ll r)
{
  if(st>end||st>r||end<l) return 0;
  if(lazy[cur]!=0)
  {
    seg[cur]=0;                /* 11-change */
    if(st!=end)
    {
      lazy[(cur<<1)]=1;                    /* 12-change */
      lazy[(cur<<1)+1]=1;                  /* 13-change */
    }
    lazy[cur]=0;
  }

  if(st>=l&&end<=r) return seg[cur];
  ll mid=(st+end)>>1;
  ll ans1=query(cur<<1,st,mid,l,r);
  ll ans2=query((cur<<1)+1,mid+1,end,l,r);
  return add(ans1,ans2);                                 /* 14-change */
}
void update(ll cur,ll start,ll end,ll idx,ll val)
{

  // cout<<cur<<' '<<start<<' '<<end<<endl;
