      lazy[(cur<<1)+1]=1;                   /* 5-change */
    }
    lazy[cur]=0;                                    /* 6-change */
  }
  if(start>end||start>idx||end<idx) return;
  if((start == end)&&(idx==start))
    {
      seg[cur] = add(val,seg[cur]);
      return ;
    }
  ll mid = (start + end) >> 1;
  update((cur<<1), start, mid, idx, val);
  update((cur<<1)+1, mid+1, end, idx, val);
  seg[cur] = add(seg[cur<<1] , seg[(cur<<1)+1]);
}
