	int N; cin >> N;
	vector<pair<int, int>> robots(N);
	for (auto& it : robots) { cin >> it.first >> it.second; it.second += it.first; }

	sort(robots.begin(), robots.end());

	for (auto& it : robots) {
		it.second = int(lower_bound(robots.begin(), robots.end(), pair<int, int>(it.second, -1)) - robots.begin());
	}

	const int S = 1 << 18;
	vector<int> seg(2*S);

	vector<num> dp(N+1);
	dp[N] = 1;
	for (int i = N-1; i >= 0; i--) {
		int furthest = robots[i].second;
		for (int a = S+i, b = S+robots[i].second; a < b; a /= 2, b /= 2) {
			if (a & 1) furthest = max(furthest, seg[a++]);
			if (b & 1) furthest = max(furthest, seg[--b]);
		}
		seg[S+i] = furthest;
		for (int a = (S+i)/2; a; a /= 2) {
			seg[a] = max(seg[2*a], seg[2*a+1]);
		}

		dp[i] = dp[i+1] + dp[furthest];
	}
	cout << dp[0] << '\n';

	return 0;
}

