/* constant */

const int MAX_N = 200000;
const int MAX_E2 = 1 << 19; // = 524288
const int MOD = 998244353;

/* typedef */

typedef pair<int,int> pii;

template <typename T, const int MAX_E2>
struct SegTreeMax {
  int e2;
  T nodes[MAX_E2];
  SegTreeMax() {}

  void init(int n) {
    for (e2 = 1; e2 < n; e2 <<= 1);
    //fill(nodes, nodes + MAX_E2, minf);
  }

  T &get(int i) { return nodes[e2 - 1 + i]; }

  void set(int i, T v) {
    int j = e2 - 1 + i;
    nodes[j] = v;
    while (j > 0) {
      j = (j - 1) / 2;
      nodes[j] = max(nodes[j * 2 + 1], nodes[j * 2 + 2]);
    }
  }

  T max_range(int r0, int r1, int k, int i0, int i1) {
    if (r1 <= i0 || i1 <= r0) return 0;
    if (r0 <= i0 && i1 <= r1) return nodes[k];

    int im = (i0 + i1) / 2;
    T v0 = max_range(r0, r1, k * 2 + 1, i0, im);
    T v1 = max_range(r0, r1, k * 2 + 2, im, i1);
    return max(v0, v1);
  }
  T max_range(int r0, int r1) { return max_range(r0, r1, 0, 0, e2); }
};

/* global variables */

pii ps[MAX_N];
SegTreeMax<int,MAX_E2> st;
int dp[MAX_N + 1];

/* subroutines */

/* main */

int main() {
  int n;
  scanf("%d", &n);

  for (int i = 0; i < n; i++)
    scanf("%d%d", &ps[i].first, &ps[i].second);
  sort(ps, ps + n);

  st.init(n);

  for (int i = n - 1; i >= 0; i--) {
    int xi = ps[i].first, yi = xi + ps[i].second;
    int j = lower_bound(ps, ps + n, pii(yi, 0)) - ps;
    int m = st.max_range(i + 1, j);
    st.set(i, max(m, j));
  }

  dp[n] = 1;
  for (int i = n - 1; i >= 0; i--) {
    int j = st.get(i);
    dp[i] = (dp[i + 1] + dp[j]) % MOD;
  }

  printf("%d\n", dp[0]);
  return 0;
}

