#define fastInp cin.tie(0); cout.tie(0); ios_base::sync_with_stdio(0);

const ll SIZE = 2e5 + 10, MOD = 998244353, INF = 1e9 * 1e9;

ll dp[SIZE], lst[SIZE], tree[SIZE * 4];

void upd(int v, int l, int r, int pos) {
	if (l == r - 1) {
		tree[v] = lst[l];
	}
	else {
		int mid = (l + r) / 2;
		if (pos < mid) {
			upd(v * 2 + 1, l, mid, pos);
		}
		else {
			upd(v * 2 + 2, mid, r, pos);
		}
		tree[v] = min(tree[v * 2 + 1], tree[v * 2 + 2]);
	}
}

ll ask(int v, int l, int r, int askl, int askr) {
	if (l >= askr || r <= askl) return INF;

	if (l >= askl && r <= askr) return tree[v];

	int mid = (l + r) / 2;
	return min(ask(v * 2 + 1, l, mid, askl, askr), ask(v * 2 + 2, mid, r, askl, askr));
}

int main() {
	fastInp;

	ll n;
	cin >> n;
	vector<pair<ll, ll>> vec;
	for (int i = 0; i < n; i++) {
		ll x, d;
		cin >> x >> d;
		vec.push_back({ x, d });
	}

	sort(vec.rbegin(), vec.rend());

	vec.insert(vec.begin(), { INF, 0 });
	ll pr = INF, sz = 0, ans = 1;
	dp[0] = 1;
	lst[0] = 0;
	for (int i = 1; i <= n; i++) {
		int l = 0, r = vec.size();
		while (r - l > 1) {
			int mid = (l + r) / 2;
			if (vec[mid].first >= vec[i].first + vec[i].second) {
				l = mid;
			}
			else {
				r = mid;
			}
		}

		lst[i] = i;
		lst[i] = min(lst[i], ask(0, 0, n + 2, l + 1, i));
		upd(0, 0, n + 2, i);

		dp[i] = (dp[lst[i] - 1] + dp[i - 1]) % MOD;
	}

	cout << dp[n];
	return 0;
}

