struct segmentTree
{
	ll tree[N<<2];
	void pushup(int k)
	{
		tree[k]=max(tree[k<<1],tree[k<<1|1]);
	}
	void build(int k,int l,int r)
	{
		if(l==r){
			tree[k]=l;
			return;
		}
		int mid=(l+r)/2;
		build(k<<1,l,mid);
		build(k<<1|1,mid+1,r);
		pushup(k);
	}
	ll query(int k,int l,int r,int x,int y)
	{
		if(x>r||y<l)return -1e9;
		if(x<=l&&r<=y)return tree[k];
		int mid=(l+r)/2;
		ll res=query(k<<1,l,mid,x,y);
		res=max(res,query(k<<1|1,mid+1,r,x,y));
		return res;
	}
	void modify(int k,int l,int r,int i,int x)
	{
		if(l==r){
			tree[k]=x;
			return;
		}
		int mid=(l+r)/2;
		if(i<=mid)modify(k<<1,l,mid,i,x);
		else modify(k<<1|1,mid+1,r,i,x);
		pushup(k);
	}
}t;
