struct BIT{
  vector <int> bit;

  void prepare(int n){
    bit.assign(n + 1, -INF);
  }

  void Update(int p, int val){
    for (; p > 0; p -= p&-p) bit[p] = max(bit[p], val);
  }

  int Get(int p){
    int ans = -INF;
    for (; p <= n; p += p&-p) ans = max(ans, bit[p]);
    return ans;
  }
} cur;


int main()
{
  fastio;
  cin >> n; cur.prepare(n);
  for (int i = 1; i <= n; i++){
    cin >> a[i].first >> a[i].second;
  }
  sort(a + 1, a + 1 + n);
  R[n] = n;
  for (int i = n - 1; i > 0; i--){
    int pos = -1;
    int l = i + 1; int r = n;
    while (l <= r){
      int m = (l + r) / 2;
      if (a[i].first + a[i].second > a[m].first){
        pos = m;
        l = m + 1;
      }
      else r = m - 1;
    }
    if (pos == -1) R[i] = i;
    else R[i] = R[pos];
  }
  dp[0] = 1; psum[0] = 1;  
  for (int i = 1; i <= n; i++){
    int pos = cur.Get(i);
    if (pos == -INF) dp[i] += psum[i - 1];
    else {
      dp[i] += (psum[i - 1] - psum[pos - 1] + MOD) % MOD;
    }
    dp[i] %= MOD; psum[i] = (psum[i - 1] + dp[i]) % MOD;
    cur.Update(R[i], i);
  }
  int res = 0;
  for (int i = 0; i <= n; i++) (res += dp[i]) %= MOD;
  cout << res;
  return 0;
}

