        XD[i] = make_pair(X[i], D[i]);
    }
    sort(XD.begin(), XD.end());
    sort(X.begin(), X.end());

    SegmentTree<int> st(
        N,
        [](int a, int b) { return max(a, b); },
        INT_MIN);
    for (int i = N - 1; i >= 0; i--)
    {
        int x = X[i];
        int d = XD[i].second;
        int r = distance(X.begin(), lower_bound(X.begin(), X.end(), x + d)) - 1;
        st.update(i, max(r, st.query(i, r)));
    }
