int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;
    pii xd[n];
    for (int i = 0; i < n; i++) {
        cin >> xd[i].first >> xd[i].second;
    }
    sort(xd, xd+n);

    int lg2[n+1];
    for (int i = 1; i <= n; i++) {
        lg2[i] = i == 1 ? 0 : lg2[i/2] + 1;
    }

    int st[n+1][LGN];
    for (int k = 0; k < LGN; k++) {
        st[n][k] = n;
    }
    int dp[n+1];
    dp[n] = 1;

    for (int i = n - 1; i >= 0; i--) {
        int j = upper_bound(xd, xd+n, pii(xd[i].first + xd[i].second, -1)) - xd;

        if (j == i + 1) {
            st[i][0] = i + 1;
        } else {
            int lg = lg2[j-i-1];
            st[i][0] = max(st[i+1][lg], st[j-(1<<lg)][lg]);
        }

        dp[i] = (dp[i+1] + dp[st[i][0]]) % Z;

        for (int k = 1; i + (1 << k - 1) <= n; k++) {
            st[i][k] = max(st[i][k-1], st[i+(1<<k-1)][k-1]);
        }
    }

