template <class Mono = ll>
struct SegTree{
    using FuncMonoMono = function<Mono(Mono,Mono)>;
    FuncMonoMono operation; //区間クエリ
    FuncMonoMono setval; //点更新
    int N;
    vector<Mono> dat;
    Mono unitMono; //初期値であり単位元

    SegTree(int n, Mono unitm, FuncMonoMono _operation, FuncMonoMono _setval) : unitMono(unitm), operation(_operation), setval(_setval) {
        N = 1;
        while(N < n) N <<= 1;
        dat.resize(2*N-1, unitMono);
    }

    void update(int i, const Mono &val) { // 0-indexed
        i += (N - 1); //最下段に移動
        dat[i] = setval(dat[i],val);
        while(i > 0) { //上に向かって更新
            i = (i - 1) / 2;
            dat[i] = operation(dat[i*2+1], dat[i*2+2]);
        }
    }

    Mono _query(int a, int b, int k, int l, int r) {
        // [a,b)をみる。現在k,範囲[l,r)。0-indexed。
        if(r <= a or b <= l) return unitMono; //範囲外
        if(a <= l and r <= b) return dat[k]; //被覆
        Mono vl = _query(a, b, 2*k+1, l, (l+r)/2);
        Mono vr = _query(a, b, 2*k+2, (l+r)/2, r);
        return operation(vl, vr);
    }

    Mono query(int a, int b){ //[a,b)
        return _query(a,b,0,0,N);
    }

    inline Mono operator[](int i){
        return dat[i+N-1];
    }

};

