// SegmentTree
template <class DataType>
class SegmentTree
{
public:
    using OpType = std::function<DataType(DataType, DataType)>;
    int N;
    std::vector<DataType> dat;
    DataType e; // identity element
    OpType op;

    SegmentTree(std::vector<DataType>& base,
        DataType e0, OpType op0): e(e0), op(op0)
    {
        N = 1;
        while(N < base.size()) N *= 2;
        dat.resize(2*N-1);
        for(int i=0; i<N; i++)
            dat[i+N-1] = (i<base.size()) ? base[i] : e;
        for(int i=N-2; i>=0; i--) dat[i] = op(dat[2*i+1], dat[2*i+2]);
    }
    void update(int index, DataType value){
        int i = index + N-1;
        dat[i] = value;
        while(i > 0){
            i = (i-1) / 2;
            dat[i] = op(dat[2*i+1], dat[2*i+2]);
        }
    }
    DataType subQuery(int qleft, int qright, int tmp, int sleft, int sright){
        if(qleft <= sleft && sright <= qright) return dat[tmp];
        if(sright <= qleft || qright <= sleft) return e;

        int mid = (sleft + sright) / 2;
        return op(subQuery(qleft, qright, 2*tmp+1, sleft, mid),
            subQuery(qleft, qright, 2*tmp+2, mid, sright));
    }
    DataType query(int left, int right){
        return subQuery(left, right, 0, 0, N);
    }
    void print(){
        for(int i=N-1; i<2*N-1; i++) std::cout << dat[i] << " ";
        std::cout << std::endl;
    }
};

