	}

	sort(Z.begin(), Z.end());

	Z.erase(unique(Z.begin(), Z.end()), Z.end());

	seg.init(Z.size()+2,0, [](int first, int second){ return max(first,second);});

	dp.resize(Z.size()+1);

	dp[0] = 1;

	sort(in.begin(), in.end(), greater<pair<int,int>>());

	for(int i = 0; i < N; i++){
		int a = in[i].first;
		int b = in[i].second;

		in[i].first = lower_bound(Z.begin(), Z.end(), a) - Z.begin();
		in[i].second = lower_bound(Z.begin(), Z.end(), a + b) - Z.begin();
	}


	for(int i = 0; i < N; i++){
		int maximum = seg.query(in[i].first, in[i].second);
		in[i].second = max(in[i].second, maximum);
		seg.update(in[i].first, in[i].second);
	}

	sort(in.begin(), in.end());

	for(int i = 0, j = 0; i < dp.size()-1; i++){
		for(; j < N; j++){
			if(in[j].first == i) {
				dp[in[j].second] += dp[in[j].first];
				dp[in[j].second] %= MOD;
			} else break;
		}
		dp[i+1] += dp[i];
		dp[i+1] %= MOD;
	}

	cout<<dp.back()<<endl;

	return 0;
}

