#include<bits/stdc++.h>
using namespace std;

const int64_t MOD = 998244353;

//Segment Tree改
int INF = -1e9;
int64_t n = 1;

vector<int64_t> value; // ノードの値を持つ配列

void update(int64_t i, int64_t x, int64_t n) { //nは上にあるn(0-indexのはず)
  // i 番目の葉の値を x に変える
  i += n - 1; 
  value[i] = x;
  while (i > 0) {
    i = (i - 1) / 2;
    value[i] = max(value[i * 2 + 1],value[i * 2 + 2]);
  }
}

int64_t query(int64_t a, int64_t b, int64_t k, int64_t l, int64_t r) { //a,b,0,0,n
  if (r <= a || b <= l) return INF; 
  if (a <= l && r <= b)
    return value[k];
  else {
    int64_t c1 = query(a, b, 2 * k + 1, l, (l + r) / 2);
    int64_t c2 = query(a, b, 2 * k + 2, (l + r) / 2, r); 
    return max(c1, c2);
  }
}

void init(int64_t N){
  while(n < N){
    n *=2 ;
  }
  value = vector<int64_t>(2*n - 1, INF);
}

int64_t access(int64_t x, int64_t n){
  return value[x+n-1];
}

int main(){
  int N;
