  for(int i=0; i<N; i++){
    dist[i] = vec[i][0];
  }

  //Segにはiを動かした時に最大どこまで動くかを記録する
  init(N);

  vector<vector<int>> ans(N+1,vector<int>(2));
  //0は存在しない、1は存在する
  ans[N-1][0] = 1;
  ans[N-1][1] = 1;
  ans[N][0] = 1;

  for(int i=0; i<N; i++){
    update(i,i,n);
  }

  vector<int>::iterator pos;
  int idx;

  for(int i=N-2; i>=0; i--){
    int x = vec[i][0];
    int y = vec[i][1];
    pos = lower_bound(dist.begin(),dist.end(),x+y);
    idx = distance(dist.begin(),pos);
    int q = query(i,idx,0,0,n);
    //cout << i << " " << idx << " " << q << endl;
    update(i,access(q,n),n);
    //cout << query(i,idx,0,0,n) << endl;
    ans[i][0] = ans[q+1][0] + ans[q+1][1];
    ans[i][0] %= MOD;
    ans[i][1] = ans[i+1][0] + ans[i+1][1];
    ans[i][1] %= MOD;
  }
  cout << (ans[0][0] + ans[0][1]) %MOD << endl;
}

