const int maxn = 200009;
typedef long long i64;
typedef pair<i64, i64> pi64;
typedef pair<int, int> pi;
const i64 MOD = 119 << 23 | 1;
class {
  public:
    pi a[maxn];
    int n;
    i64 dp[maxn][2], nx[maxn];
    void solve() {
        cin >> n;
        for (int i = 0; i < n; ++i) {
            cin >> a[i].first >> a[i].second;
        }
        sort(a, a + n);
        dp[n][0] = 1;
        build(1, 0, n - 1);
        for (int i = n - 1; i >= 0; --i) {
            int id = lower_bound(a, a + n,
                                 make_pair(a[i].first + a[i].second - 1, 0)) -
                     a;
            if (a[id].first != a[i].first + a[i].second - 1)
                --id;
            nx[i] = query(1, 0, n - 1, i, id);
            upd(1, 0, n - 1, i, nx[i]);
            dp[i][1] = (dp[nx[i] + 1][0] + dp[nx[i] + 1][1]) % MOD;
            dp[i][0] = (dp[i + 1][0] + dp[i + 1][1]) % MOD;
        }
        cout << (dp[0][0] + dp[0][1]) % MOD << '\n';
    }
    int Max[maxn << 2];
    void build(int rt, int l, int r) {
        if (l == r) {
            Max[rt] = l;
            return;
        }
        int mid = l + r >> 1;
        build(rt << 1, l, mid);
        build(rt << 1 | 1, mid + 1, r);
        Max[rt] = max(Max[rt << 1], Max[rt << 1 | 1]);
    }
    void upd(int rt, int l, int r, int p, int v) {
        if (l == r) {
            Max[rt] = v;
            return;
        }
        int mid = l + r >> 1;
        if (p <= mid)
            upd(rt << 1, l, mid, p, v);
        else
            upd(rt << 1 | 1, mid + 1, r, p, v);
        Max[rt] = max(Max[rt << 1], Max[rt << 1 | 1]);
    }
    int query(int rt, int l, int r, int ll, int rr) {
        if (ll <= l && rr >= r) {
            return Max[rt];
        }
        int mid = l + r >> 1;
        int res = -1;
        if (ll <= mid)
            res = max(res, query(rt << 1, l, mid, ll, rr));
        if (rr > mid)
            res = max(res, query(rt << 1 | 1, mid + 1, r, ll, rr));
        return res;
    }
} NSPACE;
