int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> a(n);
    for (auto &e: a) cin >> e.first >> e.second;
    sort(a.rbegin(), a.rend());

    vector<int> dict(2*n);
    for (int i = 0; i < n; ++i) {
        dict[i*2] = a[i].first;
        dict[i*2+1] = a[i].second;
    }
    sort(dict.begin(), dict.end());
    dict.erase(unique(dict.begin(), dict.end()), dict.end());
    auto conv = [&](int x){
        return lower_bound(dict.begin(), dict.end(), x) - dict.begin();
    };

    SegTree<maxmn> seg(dict.size());
    for (auto &e: a) {
        int x, d;
        tie(x, d) = e;
        int nd = max((ll)x+d, seg.range_concat(conv(x), conv(x+d)));
        seg.point_set(conv(x), nd);
        e.second = nd;
    }

    vector<pair<int, int>> evt;
    for (auto &e: a) {
        evt.emplace_back(e.first, 1);
        evt.emplace_back(e.second, 0);
    }
    sort(evt.begin(), evt.end());

    stack<mint> st;
    st.push(1);
    for (auto &e: evt) {
        if (e.second == 1) {
            st.push(1);
        } else if (e.second == 0) {
            mint t = st.top();
            st.pop();
            st.top() *= (t+1);
        }
    }

    cout << st.top() << endl;

    return 0;
}

