    SegmentTree seg( v1 );
    sort(v.begin(), v.end());
    v.pb(P(INF, INF));
    ans_table[n] = 1;
    max_table[n] = -1;
    for(ll i=n-1;i>=0;i--){
        ll ok = i, ng = n;
        while(ng - ok > 1){
            ll mid = (ng + ok) / 2;
            if(v[i].second > v[mid].first){
                ok = mid;
            }else{
