    drep(i,n){
        int ite = lower_bound(x, x+n+1, v[i].first + v[i].second) - x;
        int tmp = query(i,ite,0,0,nn);
        if(tmp > 1234567)tmp = -i;
        update(i, tmp);
    }

    ll dp[n+1] = {};
    dp[0] = 1;
    rep(i,n){
        dp[i+1] += dp[i];
        dp[i+1] %= MOD;
        int tmp = -query(i,i+1,0,0,nn);
        dp[tmp+1] += dp[i];
        dp[tmp+1] %= MOD;
    }

    cout << dp[n] << endl;
    return 0;
}

