int query_in(int a, int b, int k, int l, int r) {
  if(r <= a || b <= l) return -1;
  if(a <= l && r <= b) return dat[k];
  int m = (l+r)/2;
  int vl = query_in(a, b, k*2+1, l, m);
  int vr = query_in(a, b, k*2+2, m, r);
  return std::max(vl, vr);
}

void update(int k, int v) {
  k += NN-1;
  dat[k] = v;
  while(k > 0) {
    k = (k-1)/2;
    dat[k] = std::max(dat[k*2+1], dat[k*2+2]);
  }
}

