vector<int> tree;

int solve(int a,int b,int i,int left,int right){
  if(right<=a||b<=left){
    return 0;
  }
  if(a<=left&&right<=b){
    return tree.at(i);
  }
  int x=solve(a,b,2*i+1,left,(left+right)/2);
  int y=solve(a,b,2*i+2,(left+right)/2,right);
  return max(x,y);
}

