P drange_ika(int a, int b) {    assert(b);    if (a >= 0) {        if (b > 0)return mp(-linf, a / b + 1);        else return mp(-(a / -b), linf + 1);    } else {        if (b > 0)return mp(-linf, -ceil(-a, b) + 1);        else return mp(ceil(-a, -b), linf + 1);    }}

