            if (v == MIN(ll) || v == MAX(ll)) { cerr << "e "; } else { cerr << v << " "; }
        }
        cerr << "" << endl << endl;
    }
    void debup(int k, int v) {
        cerr << "upd : [" << k << "] = " << v << endl;
        debu();
    }
    void debge(int l, int r, M v) {
        cerr << "get : [" << l << ", " << r << ") = " << v << endl;
        debu();
