#include <bits/stdc++.h>
using namespace std;

template<typename T>
struct SegmentTree{
    int n;
    vector <T> node, lazy;
    SegmentTree (int n=0): n(n), node(4*n+5, -(int) 2e9), lazy(4*n+5, -(int) 2e9) {}

    void pushLazy(int l, int r, int id){
        node[id] = max(node[id], lazy[id]);             
        if (l != r)
            lazy[2*id] = max(lazy[2*id], lazy[id]),
            lazy[2*id+1] = max(lazy[2*id+1], lazy[id]);
        lazy[id] = -(int) 2e9;
    }

    void update(int u, int v, T val, int l=0, int r=0, int id = 1){
    	if (!l)	l = 1, r = n;
        pushLazy(l, r, id);
        if (r < u || v < l)     return;
        if (u <= l && r <= v)   { lazy[id] = max(lazy[id], val); pushLazy(l, r, id); return; }
        update(u, v, val, l, (l+r)/2, 2*id);
        update(u, v, val, (l+r)/2+1, r, 2*id + 1);
        node[id] = max(node[2*id], node[2*id+1]);
    }
    T get(int u, int v, int l=0, int r=0, int id = 1){
    	if (u > v)	return -(int) 2e9;
    	if (!l)	l = 1, r = n;
        pushLazy(l, r, id);
        if (r < u || v < l)     return 0;
        if (u <= l && r <= v)   return node[id];
        return max(get(u, v, l, (l+r)/2, 2*id), get(u, v, (l+r)/2+1, r, 2*id + 1));
    }
};

int n;
pair<int,int> robot[200005];
const int mod = (int) 998244353;
int f[200005];
SegmentTree<int> best;

void ngk(){
	cin >> n;
	for(int i=1;i<=n;i++)
		cin >> robot[i].first >> robot[i].second;

	best = SegmentTree<int>(n);
	sort(robot+1, robot+n+1);
	f[n+1] = 1;

	for(int i=n;i>=1;i--){
		int pos = lower_bound(robot+i+1, robot+n+1, pair<int,int>(robot[i].first + robot[i].second, -1)) - robot - 1;
		int z = max(robot[i].first + robot[i].second - 1, best.get(i+1, pos));
		int where = lower_bound(robot+i+1, robot+n+1, pair<int,int>(z+1, -1)) - robot;
		f[i] = (f[i+1] + f[where]) % mod;
		cout << i << ' ' << f[i] << ' ' << where << endl;
		best.update(i, i, z);
	}

	cout << f[1];
}

