#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
typedef pair<LL, LL> PII;

LL MOD = 998244353;
void solve(long long N, std::vector<PII> data)
{
  sort(data.begin(), data.end());
  LL ans = 1;
  stack<PII> sta;
  for (auto xd : data)
  {
    LL x = xd.first;
    LL d = xd.second;

    while (!sta.empty())
    {
      auto val = sta.top();
      if (x >= val.first)
      {
        ans += val.second;
        ans %= MOD;
        sta.pop();
      }
      else
        break;
    }
    sta.push(PII(x + d, ans));
  }
  while (!sta.empty())
  {
    ans += sta.top().second;
    ans %= MOD;
    sta.pop();
  }
  cout << ans << endl;
}

int main()
{
  cout << setprecision(10);
  long long N;
  scanf("%lld", &N);
  std::vector<PII> XD(N);
  for (int i = 0; i < N; i++)
  {
    LL a, b;
    scanf("%lld", &a);
    scanf("%lld", &b);
    XD[i] = PII(a, b);
  }
  solve(N, std::move(XD));
  return 0;
}

