const int N = 2e5 + 6, MOD = 998244353;

int dp[N], t[4 * N];
pi a[N];

void change(int v, int l, int r, int pos, int val) {
    if (l == pos && r == pos) {
        t[v] = val;
        return;
    }
    int m = l + r >> 1;
    if (m >= pos)
        change(2 * v + 1, l, m, pos, val);
    else
        change(2 * v + 2, m + 1, r, pos, val);
    t[v] = max(t[2 * v + 1], t[2 * v + 2]);
}

int ask(int v, int l, int r, int L, int R) {
    if (l > R || r < L)
        return 0;
    if (l >= L && r <= R) 
        return t[v];
    int m = l + r >> 1;
    return max(ask(2 * v + 1, l, m, L, R), ask(2 * v + 2, m + 1, r, L, R));
}

void solve() {
    int n; cin >> n;
    loop(i, n)
        cin >> a[i].F >> a[i].S;
    sort(a, a + n);
    loop(i, n)
        change(0, 0, n - 1, i, i);
    dp[n] = 1;
    for (int i = n - 1; i >= 0; --i) {
        int lef = i, rig = n;
        while (rig - lef > 1) {
            int m = rig + lef >> 1;
            if (a[i].F + a[i].S > a[m].F)
                lef = m;
            else rig = m;
        }
        int x = ask(0, 0, n - 1, i, lef);
        change(0, 0, n - 1, i, x);
        dp[i] = (dp[i + 1] + dp[x + 1]) % MOD;
    }
    cout << dp[0];
}

