	}
}

bool done[225816][2];
ll memo[225816][2];

ll solve(int i, int st){
	int j;
	if(done[i][st]){
		return memo[i][st];
	}
	done[i][st] = true;
	if(i==n-1){
		return memo[i][st] = 1ll;
	}
	if(st){
		j = (int)(lower_bound(v,v+n,P(v[i].second,-INFLL))-v); --j;
		if(i==j){
			memo[i][st] = (solve(i+1,0)+solve(i+1,1))%MOD;
		}else{
