#include <bits/stdc++.h>

using namespace std;

const int N = 2e5+5;
const int mod = 998244353;

long long dp[N][2];
int go[N], sg[4*N];

void upd(int node, int l, int r, int pos, int val) {
	if(r<pos||l>pos) return;
	if(l==r) {
		sg[node] = max(sg[node], val);
		return;
	}
	int mid = (l + r) / 2;
	upd(2*node, l, mid, pos, val);
	upd(2*node+1, mid+1, r, pos, val);
	sg[node] = max(sg[2*node], sg[2*node+1]);
}

int que(int node, int l, int r, int ll, int rr) {
	if(l>rr||r<ll) return -1;
	if(l>=ll&&r<=rr) return sg[node];
	int mid = (l + r) / 2;
	int q1 = que(2*node, l, mid, ll, rr);
	int q2 = que(2*node+1, mid+1, r, ll, rr);
	return max(q1, q2);
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
