	vector<pair<int,int>> v(n);
	vector<int> pos;

	for(int i = 0; i < n; i++) {
		cin >> v[i].first >> v[i].second;
	}

	sort(v.begin(), v.end());

	for(int i = 0; i < n; i++) go[i] = v[i].first + v[i].second - 1;

	dp[n-1][0] = 1;
	dp[n-1][1] = 1;

	auto last_go = [&](int pos) {
		int val = v[pos].first + v[pos].second - 1;
		int l = pos, r = n-1;
		while(r-l>3) {
			int mid = (l+r)/2;
			if(val>=v[mid].first) l=mid;
			else r=mid-1;
		}
		for(int i = r; i >= 0; i--) {
			if(val>=v[i].first) return i;
		}
		return -1;
	};

	auto mx_go = [&](int l, int r) {
		if(l>r) return -1;
		return que(1, 0, n-1, l, r);
	};

	go[n - 1] = n - 1;
	upd(1, 0, n-1, n-1, n-1);

	for(int i = n - 2; i >= 0; i--) {
		go[i] = last_go(i);
		go[i] = max(go[i], mx_go(i+1, go[i]));
		upd(1, 0, n-1, i, go[i]);
	}


	for(int i = n - 2; i >= 0; i--) {
		dp[i][0] = (dp[i+1][0] + dp[i+1][1])%mod;
		if(v[n-1].first < v[i].first + v[i].second) {
			dp[i][1] = 1;
		}
		else {
			int p = go[i];
			if(p==n-1) dp[i][1]=1;
			else dp[i][1] = (dp[p+1][0] + dp[p+1][1])%mod;
		}
	}

	cout << (dp[0][0] + dp[0][1])%mod;

	return 0;
}

