	for (int i=SZ(V)-2;i>=0;--i){
		int l = root->query(V[i].f,V[i].s);
		l = max(l,i);
		lst[i] = l;
		root->up(V[i].f, l);
		AL[V[i].f].pb(V[l].s);
	}

	dp[0] = 1;
	for (int i=1;i<=SZ(des);++i){
		dp[i] += dp[i-1];
		dp[i] %= MOD;
		// cout<<"AL: ";
		for (auto x:AL[i]){
			// cout<<x<<' ';
			dp[x]+=dp[i-1];
			dp[x] %= MOD;
		}
		// cout<<'\n';
	}
	cout<<dp[SZ(des)];
}

