ll n;

const ll MOD = 998244353;

struct robo {
	ll x, d;
	vector<int> child;
};
vector<robo> v;

ll dfs( int node ){
	const robo &r = v[node];

	ll result = 1;
	for ( size_t i = 0; i < r.child.size(); i++ ){
		//cout << node << "->" << r.child[i] << endl;
		result = result * dfs(r.child[i]) % MOD;
	}

	// 組み合わせ = 全ての子ノードの組み合わせ + このノードを起動して全ての子を起動
	//cout << node << ":" << result+1 << endl;
	return  (result+1) % MOD;
}

int main(){
