	v[n].d =  4000000000LL; // root

	sort(v.begin(),v.end(),[](const robo &l, const robo &r){return l.x < r.x;});


	// 起動の順番は結果に影響を与えない
	// ロボットの関係をツリーにする。 Aを起動したときにBが起動するなら、AはBの祖先
	stack<int> s;
	s.push(0);
	for ( int i = 1; i < n+1; i++ ){
		const robo &ri = v[i];
		while ( v[s.top()].x + v[s.top()].d <= ri.x )
			s.pop();
		v[s.top()].child.push_back(i);
		s.push(i);
	}

	ll result = dfs(0) - 1; // rootを起動 の1を引く

	cout << result << endl;

	return 0;
}

