        //cout<<x[i]<<' '<<d[i]<<endl;
    }
    Rrep(i,N){
        auto ite = lower_bound(ALL(x), x[i] + d[i]);
        seg.update(i, seg.Q(i, ite - x.begin()));
    }
    vec num(N), sum(N);
    num[N - 1] = 1;
    sum[N - 1] = 2;
    Rrep(i,N - 1){
