class SegmentTree {
  vector<int> dat;
  int n, def;
public:
  SegmentTree(int num, int x) {
    n = 1;
    while (n < num)
      n <<= 1;
    dat.resize(2 * n - 1, x);
    def = x;
  }
  void update(int i, int x) {
    i += (n - 1);
    dat[i] = x;
    while (i > 0) {
      i = (i - 1) / 2;
      dat[i] = max(dat[2 * i + 1], dat[2 * i + 2]);
    }
  }
  int query(int a, int b, int i = 0, int li = 0, int ri = -1) {
    if (!i) ri = n;
    if (ri <= a || li >= b) return def;
    if (li >= a && ri <= b) return dat[i];
    int vl = query(a, b, 2 * i + 1, li, (li + ri) / 2);
    int vr = query(a, b, 2 * i + 2, (li + ri) / 2, ri);
    return max(vl, vr);
  }
};

