void build(int rt,int l,int r){
    t[rt].l=l,t[rt].r=r;
    t[rt].maxx=-2e9-1;
    if(l==r)return;
    int mid=(t[rt].l+t[rt].r)>>1;
    build(rt<<1,l,mid);
    build(rt<<1|1,mid+1,r);
}
void update(int rt,int p,int val){
    if(t[rt].l==t[rt].r){
        t[rt].maxx=max(t[rt].maxx,val);
        return;
    }
    int mid=(t[rt].l+t[rt].r)>>1;
    if(p<=mid)update(rt<<1,p,val);
    else update(rt<<1|1,p,val);
    t[rt].maxx=max(t[rt<<1].maxx,t[rt<<1|1].maxx);
}
int query(int rt,int l,int r){
    if(l>r)return -2e9-1;
    if(t[rt].l>=l&&t[rt].r<=r)return t[rt].maxx;
    int ans=0;
    int mid=(t[rt].l+t[rt].r)>>1;
    if(l<=mid)ans=max(ans,query(rt<<1,l,r));
    if(r>mid)ans=max(ans,query(rt<<1|1,l,r));
    return ans;
}
