  for (int i = 0; i < n; ++i) cin >> a[i].first >> a[i].second;
  sort(a.begin(), a.end());
  vector<int> skip(n);
  for (int i = 0; i < n; ++i) {
    auto it = lower_bound(a.begin(), a.end(),
        make_pair<ll, ll>(a[i].first + a[i].second, -1));
    skip[i] = it - a.begin() - 1;
  }

  Update(1, 0, n, 2, 2);
  for (int i = n - 1; i >= 0; --i) {
    skip[i] = max(skip[i], Max(1, 0, n, i, skip[i]));
    Update(1, 0, n, i, skip[i]);
  }

  vector<ll> ans(n + 1);
  ans[n] = 1;
  for (int i = n - 1; i >= 0; --i) ans[i] = (ans[i + 1] + ans[skip[i] + 1]) % mod;
  cout << ans[0] << endl;
  return 0;
}

