int main(void) {
    ll n;
    cin >> n;
    vector<PII> v(n);
    REP(i, n) cin >> v[i].first >> v[i].second;
    sort(ALL(v));

    vector<ll> x(n), d(n);
    REP(i, n) x[i] = v[i].first, d[i] = v[i].second;

    vector<ll> r(n);
    REP(i, n) r[i] = lower_bound(ALL(x), x[i]+d[i]) - x.begin() - 1;
    segtree<max_monoid<ll>> seg(n);
    seg.build(r);
    for(ll i=n-1; i>=0; --i) {
        // j \in [i,r[i]] について max(r[j]) 
        r[i] = seg.query(i, r[i]+1);
        seg.update(i, r[i]);
    }

    vector<mint> dp(n+1);
    dp[n] = 1;
    for(ll i=n-1; i>=0; --i) dp[i] = dp[r[i]+1] + dp[i+1];
    cout << dp[0] << endl;

    return 0;
}

