template <class T>
class SegmentTree
{
	int size;
	T def;
	vector<T> data;
	function<T(T, T)> f;

public:
	SegmentTree<T>(int _size, T _def, function<T(T, T)> _f) : f(_f), def(_def), size(1)
	{
		while (size < _size)
			size <<= 1;
		data = vector<T>(size * 2, def);
	}
	//bottom-up implementation
	//query for[l, r)
	T query(int l, int r)
	{
		T L = def, R = def;
		for (l += size, r += size; l < r; l >>= 1, r >>= 1)
		{
			if (l & 1)
				L = f(L, data[l++]);
			if (r & 1)
				R = f(data[--r], R);
		}
		return f(L, R);
	}
	void update(int idx, T val)
	{
		idx += size;
		data[idx] = val;
		while (idx > 1)
		{
			idx >>= 1;
			data[idx] = f(data[2 * idx], data[2 * idx + 1]);
		}
	}
	T operator[](int idx)
	{
		return data[idx + size];
	}
};


class Solution {
public:
	void solve() {
		int n;
		cin >> n;
		vector<pair<int, int>> xd(n);
		for(int i=0; i < n; i++)cin >> xd[i].first >> xd[i].second;
		sort(xd.begin(), xd.end());
		SegmentTree<int> st(n, 0, [](int a, int b){return max(a,b);});
		for(int i=0; i < n; i++)st.update(i, i);
		for(int i=n-2; i >= 0; i--){
			int R = distance(xd.begin(), upper_bound(next(xd.begin(), i), xd.end(), make_pair(xd[i].first+xd[i].second, 0)));
			st.update(i, st.query(i, R));
		}
		vector<mint> dp(n+1);
		dp[n] = 1;
		for(int i=n-1; i >= 0; i--){
			dp[i] = dp[i+1] + dp[st[i]+1];
		}
		cout << dp[0] << "\n";





		return;
	};
};

