typedef long long ll;

const ll M = 998244353;

ll n, base = 1;
pair<ll, ll> a[200005];
ll d[200005];
ll e[200005];
ll s[200005];
ll b[540005];

void f(ll p, ll q)
{
    p += base;
    b[p] = q;
    p /= 2;
    while(p >= 1)
    {
        b[p] = max(b[p * 2], b[p * 2 + 1]);
        p /= 2;
    }
}

ll g(ll p, ll q)
{
    p += base;
    q += base;
    ll re = 0;
    while(p < q)
    {
        if(p % 2 == 1) re = max(re, b[p]), p++;
        if(q % 2 == 0) re = max(re, b[q]), q--;
        p /= 2;
        q /= 2;
    }
    if(p == q) re = max(re, b[p]);
    return re;
}

int main()
{
    scanf("%lld", &n);
    for(ll i = 0; i < n; i++)
    {
        scanf("%lld%lld", &a[i].F, &a[i].S);
    }
    while(base < n) base *= 2;
    sort(a, a + n);
    for(ll i = 0; i < base * 2; i++) b[i] = 0;
    d[n - 1] = 1;
    e[n - 1] = n - 1;
    f(n - 1, n - 1);
    s[n - 1] = 1;
    for(ll i = n - 2; i >= 0; i--)
    {
        ll t = lower_bound(a, a + n, make_pair(a[i].F + a[i].S, (ll)-4e18)) - a;
        t--;
        e[i] = max(i, g(i + 1, t));
        d[i] = s[e[i] + 1] + 1;
        d[i] %= M;
        s[i] = d[i] + s[i + 1];
        s[i] %= M;
        f(i, e[i]);
    }
    s[0]++;
    s[0] %= M;
    cout<<s[0]<<endl;
    return 0;
}

