int find( int x ) {
	int l = 1, r = n, mid;
	while( l <= r ) {
		mid = l + r >> 1;
		if( a[ mid ].first >= x )
			r = mid - 1;
		else
			l = mid + 1;
	}
	return l;
}

void modify( int cur, int l, int r, int x, int k ) {
	int t, mid;
	if( x == l && x == r ) {
		g[ cur ] = k;
		return;
	}
	t = cur << 1;
	mid = l + r >> 1;
	if( x <= mid )
		modify( t, l, mid, x, k );
	else
		modify( t + 1, mid + 1, r, x, k );
	g[ cur ] = max( g[ t ], g[ t + 1 ] );
}

int query( int cur, int l, int r, int x, int y ) {
	int t, mid;
	int retl, retr;
	if( x == l && y == r )
		return g[ cur ];
	t = cur << 1;
	mid = l + r >> 1;
	retl = retr = 0;
	if( x <= mid )
		retl = query( t, l, mid, x, min( y, mid ) );
	if( y > mid )
		retr = query( t + 1, mid + 1, r, max( x, mid + 1 ), y );
	return max( retl, retr );
}

