    vl X(N),D(N);
    REP(i,N){
        X[i]=XD[i].first;
        D[i]=XD[i].second;
    }

    starry_sky_tree seg(N+10);
    REPD2(i,N-1,-1){
        ll idx =lower_bound(ALL(X),X[i]+D[i])-X.begin();
        ll l=i+1;
        ll r=idx;
        ll num=seg.getmax(l,r);
        num=max(num,idx);
        seg.add(i,i+1,num);
    }

    vl dp(N+1,0);
    dp[N]=1;
    REPD2(i,N-1,-1){
        dp[i]=dp[i+1];
        dp[i]+=dp[seg.getmax(i,i+1)];
        dp[i]%=MOD;

    }
    cout<<dp[0]<<endl;

}

