static const long long mod = 998244353;
struct mint {
  ll x;
  mint(ll x = 0) : x(x % mod) {}
  mint& operator+=(const mint a) {
    (x += a.x) %= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    (x += mod - a.x) %= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint ret(*this);
    return ret += a;
  }
  mint operator-(const mint a) const {
    mint ret(*this);
    return ret -= a;
  }
  mint operator*(const mint a) const {
    mint ret(*this);
    return ret *= a;
  }
  mint pow(ll t) const {
    if (t == 0) return mint(1);
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const { return pow(mod - 2); }
  mint& operator/=(const mint a) { return (*this) *= a.inv(); }
  mint operator/(const mint a) const {
    mint ret(*this);
    return ret /= a;
  }
};
class modutils {
  vector<mint> fact, invfact;

 public:
  modutils(int n = 200005) : fact(n + 1), invfact(n + 1) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
    invfact[n] = fact[n].inv();
    for (int i = n; i >= 1; i--) invfact[i - 1] = invfact[i] * i;
  }
  mint pow(mint x, ll n) { return x.pow(n); }
  mint comb(ll n, ll k) {
    if (n < 0 || k < 0 || n < k) return 0;
    return fact[n] * invfact[k] * invfact[n - k];
  }
  mint perm(ll n, ll k) {
    if (n < 0 || k < 0 || n < k) return 0;
    return fact[n] * invfact[n - k];
  }
  mint fac(ll n) { return fact[n]; }
};

set<ll> seen;
mint dfs(ll u, map<ll, vll>& to){
  if (seen.find(u) != seen.end()) return 0;
  seen.insert(u);
  if (to.count(u) == 0) return 2;
  mint tmp = 1;
  for (ll v : to[u]) {
    tmp = tmp*dfs(v, to);
  }
  return tmp + 1;
}

int main() {
  // ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
  cout << fixed << setprecision(15);

  ll n;
  cin >> n;
  vP ps(n);
  rep(i, n) {
    ll d;
    cin >> ps[i].first >> d;
    ps[i].second = ps[i].first + d - 1;
  }
  Sort(ps);

  map<ll, vll> to;
  set<ll> stx;
  set<P> stp;
  rep(i, n) {
    for (auto itr = stp.begin(); itr != stp.end() && (*itr).first < ps[i].first;
         stp.erase(itr++)) {
      stx.erase((*itr).second);
    }
    if (!stx.empty()) to[*stx.rbegin()].push_back(ps[i].first);
    stx.insert(ps[i].first);
    stp.insert(P(ps[i].second, ps[i].first));
  }

  mint ans = 1;
  rep(i, n) {
    if (seen.find(ps[i].first) != seen.end()) {
      continue;
    }
    mint tmp = dfs(ps[i].first, to);
    ans *= tmp;
  }

  cout << ans.x << endl;

  return 0;
}

