using namespace std;
const long long MOD = (long long)998244353;

int n, x, d, to[200009];
pair<int, int> dat[200009];
bool vis[200009];
long long cnt[200009], pos[200009];

long long fun(int cur)
{
	if (cur >= n) return 1;
	if (!vis[cur]) {
		vis[cur] = true;
		int tmp = lower_bound(pos, pos + n, to[cur]) - pos;
		cnt[cur] += fun(tmp);
		cnt[cur] %= MOD;
		cnt[cur] += fun(cur + 1);
		cnt[cur] %= MOD;
	}
	return cnt[cur];
}

int seg[400009], N;

void upd(int p, int v)
{
	p = p + N / 2;
	seg[p] = v;
	p /= 2;
	while (p) {
		seg[p] = max(seg[p], v);
		p /= 2;
	}
}

int query(int a, int b, int l, int r, int p)
{
	if (r <= a || b <= l) return -1e9;
	if (l == r) return -1e9;
	if (a <= l && r <= b) return seg[p];
	int ret = query(a, b, l, (l + r) / 2, 2 * p);
	ret = max(ret, query(a, b, (l + r) / 2, r, 2 * p + 1));
	return ret;
}

int main()
{
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> x >> d;
		dat[i] = { x, d };
	}
	sort(dat, dat + n);
	N = 1;
	while (N < n) {
		N = N << 1;
	}
	N = N << 1;
	for (int i = 0; i < n; i++) pos[i] = dat[i].fi;
	for (int i = 0; i < n; i++) upd(i, dat[i].first + dat[i].second);
	for (int i = 0; i < n; i++)
		to[i] = dat[i].first + dat[i].second;
	upd(n - 1, to[n - 1]);
	for (int i = n - 2; i >= 0; i--) {
		int tmp = lower_bound(pos + i, pos + n, dat[i].first + dat[i].second) - pos;
		to[i] = query(i, tmp, 0, N / 2, 1);
		upd(i, to[i]);
	}
	cout << fun(0) << E;
	//system("pause");
	return 0;
}

