lint dp[214514];

lint start_up(int now){
    if(now == N){
        return 1;
    }else if(dp[now] != -1){
        return dp[now];
    }
    return dp[now] = (start_up(now + 1) + start_up(rightest[now] + 1)) % mod;
}

