template<typename T> struct segment_tree {
	long long n; //vの要素数
	long long m; //葉の数
	std::vector<T> v; //セグ木
	std::function<T(T, T)> op; //二項演算
	T id_e; //単位元

	//コンストラクタ
	segment_tree(std::vector<T> &a, auto f, T b) {
		op = f;
		id_e = b;
		m = 1;
		while (m < a.size()) m *= 2;
		n = 2 * m - 1;
		v.resize(n, id_e);
		for (long long i = 0; i < a.size(); i++) v[m - 1 + i] = a[i];
		for (long long i = m - 2; i >= 0; i--) {
			v[i] = op(v[2 * i + 1], v[2 * i + 2]);
		}
	}

	//1点更新
	void point_update(long long a, T b) {
		a += m - 1;
		v[a] = b;
		while ((a - 1) / 2 != a) {
			a = (a - 1) / 2;
			v[a] = op(v[2 * a + 1], v[2 * a + 2]);
		}
	}

	//遅延なし区間取得の補助関数
	T range_sub(long long a, long long b, long long cur, long long l, long long r) {
		if (a <= l && r <= b) return v[cur];
		if (r < a || b < l) return id_e;
		return op(
			range_sub(a, b, 2 * cur + 1, l, (l + r) / 2),
			range_sub(a, b, 2 * cur + 2, (l + r) / 2 + 1, r)
		);
	}

	//遅延なし区間取得
	T range(long long a, long long b) {return range_sub(a, b, 0, 0, m - 1);}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	//const ll p = 1e9 + 7;
	const ll p = 998244353;

	ll n;
	cin >> n;
	vector<vll> v(n, vll(3, 0));
	for (ll i = 0; i < n; i++) cin >> v[i][0] >> v[i][1];
	sort(all(v));
	for (ll i = 0; i < n; i++) v[i][2] = i;

	vll dp1(n, 0);
	dp1[n - 1] = n - 1;

	auto f = [&] (ll a, ll b) {return max(a, b);};
	segment_tree<ll> sg(dp1, f, 0);

	for (ll i = n - 2; i >= 0; i--) {
		vll z = {v[i][0] + v[i][1], 0, 0};
		auto itr = lower_bound(all(v), z);
		if (itr == v.end()) dp1[i] = n - 1;
		else if ((*itr)[2] == i + 1) dp1[i] = i;
		else dp1[i] = sg.range(i + 1, (*itr)[2] - 1);
		sg.point_update(i, dp1[i]);
		//cout << dp1[i] << endl;
	}

	vll dp2(n + 1, 1);
	dp2[n - 1] = 2;
	for (ll i = n - 2; i >= 0; i--) {
		dp2[i] = dp2[i + 1];
		dp2[i] += dp2[dp1[i] + 1];
		dp2[i] %= p;
		//cout << dp2[i] << endl;
	}
	cout << dp2[0] << endl;
}

