//kより小さい要素のうち最大のもののインデックスを求める
int lower_bound(int k){
  int left=-1,right=n;
  while(right-left>1){
    int mid=(right+left)/2;
    if(a[mid]<k) left=mid;
    else right=mid;
  }
  return left;
}


