long long INF = (1 << 31) - 1;

class SegmentTree {
private:
	long long Size;
	vector<long long> Node;
public:
	SegmentTree(long long N) {
		Size = 1;
		while (Size < N) Size <<= 1;
		Node.resize(Size * 2, -INF);
	}
	SegmentTree(vector<long long>& V) {
		Size = 1;
		while (Size < V.size()) Size <<= 1;
		Node.resize(Size * 2, -INF);
		for (int i = 0; i < V.size(); i++) {
			Node[Size + i] = V[i];
		}
		for (int i = Size - 1; i > 0; i--) Node[i] = max(Node[i * 2], Node[i * 2 + 1]);
	}
	void Update(long long K, long long X) {
		K += Size;
		Node[K] = X;
		while (K > 1) {
			K >>= 1;
			Node[K] = max(Node[K * 2], Node[K * 2 + 1]);
		}
	}
	long long Query(long long L, long long R) {
		long long NOWS = Size, ANS = -INF;
		while (R > L) {
			if (L & 1) {
				ANS = max(ANS, Node[L + NOWS]);
				L++;
			}
			if (R & 1) {
				ANS = max(ANS, Node[R - 1 + NOWS]);
				R--;
			}
			L >>= 1, R >>= 1, NOWS >>= 1;
		}
		return ANS;
	}
};

