// Head

const int N = 212345;
const int MOD = 998244353;

pii a[N];
int n, maxm[N * 4];
LL dp[N];

int query(int o, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return maxm[o];
    int mid = l + (r - l) / 2;
    int ret = 0;
    if (ql <= mid) ret = max(ret, query(o * 2, l, mid, ql, qr));
    if (qr > mid) ret = max(ret, query(o * 2 + 1, mid + 1, r, ql, qr));
    return ret;
}

void update(int o, int l, int r, int pos, int val) {
    if (l == r) {
        maxm[o] = val;
        return;
    }

    int mid = l + (r - l) / 2;
    if (pos <= mid) update(o * 2, l, mid, pos, val);
    else update(o * 2 + 1, mid + 1, r, pos, val);
    maxm[o] = max(maxm[o * 2], maxm[o * 2 + 1]);
}

