    for (int i = n; i >= 1; --i) {
        int id = upper_bound(a + 1, a + n + 1, mp(a[i]._1 + a[i]._2, 0)) - a - 1;
        if (id == i) update(1, 1, n, i, i);
        else {
            int cur = query(1, 1, n, i + 1, id);
            update(1, 1, n, i, cur);
        }
    }

    dp[n + 1] = 1;
    for (int i = n; i >= 1; --i) {
        int pos = query(1, 1, n, i, i);
