long rec_max(std::vector<long>::iterator st, std::vector<long>::iterator en){
  if(st + 1 == en){
    return *st;
  }
  if(st + 2 == en){
    return std::max(*st, *(st+1));
  }
  std::vector<long>::iterator mid = st + (long)(en-st)/2 + (long)(en-st)%2;
  return std::max(rec_max(st,mid),rec_max(mid,en));
}

