        scanf("%lld%lld", &X, &D);
        pos.emplace_back(X);
        pos.emplace_back(X + D - 1);
        pos.emplace_back(X + D);
        seg.emplace_back(X, D);
    }
    sort(seg.begin(), seg.end());
    sort(pos.begin(), pos.end());
    pos.erase(unique(pos.begin(), pos.end()), pos.end());

    int M = pos.size();
    SegmentTree<ll> segtree(M, -LONGINF,
                            [](ll a, ll b) { return max(a, b); },
                            [](ll a, ll b) { return max(a, b); });

    // 根は N
    vector<ll> jump(N+1, -1), ans(N+1);
    seg.emplace_back(LONGINF, LONGINF);
    for(int i=N-1; i>=0; i--) {
        ll X, D; tie(X, D) = seg[i];
        int l = lower_bound(pos.begin(), pos.end(), X) - pos.begin();
        int r = lower_bound(pos.begin(), pos.end(), X+D) - pos.begin();
