    }

    ans[N] = 1;
    for(int i=N-1; i>=0; i--) {
        (ans[i] += ans[i+1]) %= MOD;
        (ans[i] += ans[ jump[i] ]) %= MOD;
    }
    ll res = ans[0];
    cout << res << endl;
    return 0;
}

