template<typename T>
struct SegmentTree{
private:
    int n;
    vector<T> node;
    using F=function<T(T,T)>;
    F op;
    T id;
    T get(int a,int b,int k,int l,int r){
        if(b<=l||r<=a)return id;
        if(a<=l&&r<=b){
            return node[k];
        }
        else{
            return op(get(a,b,2*k+1,l,(l+r)/2),get(a,b,2*k+2,(l+r)/2,r));
        }
    }
public:
    SegmentTree(int sz,F op,T id):op(op),id(id){
        n=1;
        while(n<sz)n*=2;
        node.resize(2*n-1,id);
    }
    SegmentTree(const vector<T> & v, F op,T id):SegmentTree(v.size(),op,id){
        for(int i=0;i<v.size();++i){
            node[i+n-1]=v[i];
        }
        for(int i=n-2;i>=0;--i){
            node[i]=op(node[2*i+1],node[2*i+2]);
        }
    }
    void update(int a,T x){
        a+=n-1;
        node[a]=x;
        while(a>0){
            a=(a-1)/2;
            node[a]=op(node[2*a+1],node[2*a+2]);
        }
    }
    T get(int a){
        return node[a+n-1];
    }
    T get(int a,int b){
        return get(a,b,0,0,n);
    }
};

