const long long MOD = 998244353;

using namespace std;


const long long INF2 = (((ll)1<<31)-1);

template<class T> class SegTree   // 0-indexed
{
private:
    int n;             // 葉の数
    vector<T> data;    // ノードの値を持つ配列
    T def;                // 初期値かつ単位元

    T operation(T a, T b)    // 区間クエリで使う処理
    {
        return min(a, b);   // 区間minクエリ
        //return a+b;       // 区間和クエリ
    }

    T update(T a, T b)      // 点更新で使う処理
    {
        //return a+b;   // 加算の場合
        return b;       // 更新の場合
    }

    // 区間[a,b)の総和。ノードk=[l,r)に着目している。
    T _query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return def; // 交差しない
        if (a <= l && r <= b)
            return data[k]; // a,l,r,bの順で完全に含まれる
        else {
            T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子
            T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子
            return operation(c1, c2);
        }
    }

public:
    SegTree(int _n) {     // _n:必要サイズ
        def = INF2;        // 初期値かつ単位元
        //def = 0;        // 初期値かつ単位元（0：区間和の場合）
        n = 1;
        while (n < _n) n *= 2;
        data = vector<T>(2 * n - 1, def);
    }

    // 場所i(0-indexed)の値をxで更新
    void change(int i, T x) {
        i += n - 1;
        data[i] = update(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    // [a, b)の区間クエリを実行
    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    // 添字でアクセス
    T operator[](int i) {
        return data[i + n - 1];
    }
};

void solve()
{
    int n;
    scanf("%d", &n);
    vector<pair<ll,ll> > z;
    int i;
    for (i = 0; i < n; i++) {
        int x,d;
        scanf("%d%d", &x, &d);
        z.push_back(make_pair((ll)x,(ll)d));
    }
    sort(z.begin(),z.end());
    z.push_back(make_pair(LINF,0));

    vector<ll> dp(n+1);
    dp[0]=1;
    SegTree<int> S(n);
    vector<int> next(n);
    for (i = n - 1; i >= 0; i--) {
        ll x=z[i].first, d=z[i].second;
        int k=lower_bound(z.begin(),z.end(),make_pair(x+d,-(ll)LINF))-z.begin();
        int val=-S.query(i+1,k);        
        if(val<0) val=i+1;
        S.change(i,-val);
        next[i]=val;
    }
    for(i=0; i<n; i++) {
        int val=next[i];
        dp[val]=(dp[val]+dp[i])%MOD;
        dp[i+1]=(dp[i+1]+dp[i])%MOD;
    }
    printf("%lld\n", dp[n]);

    return;
}

int main(int argc, char* argv[])
{
    solve();

	return 0;
}

