// Binary Indexed Tree (Fenwick Tree)
template <typename T>
struct BITsum {
    ll n, s = 0;
    vector<T> d;
    BITsum(ll n = 0) : n(n), d(n + 1) {}
    void add(ll i, T x = 1) {
        for (i++; i <= n; i += i & -i) {
            d[i] += x;
            d[i] %= MOD;
        }
        s = (s + x) % MOD;
    }
    T sum(ll i) {
        T x = 0;
        for (; i; i -= i & -i) {
            x += d[i];
        }
        x %= MOD;
        return (s - x + MOD) % MOD;
    }
};
// Binary Indexed Tree (Fenwick Tree)
template <typename T>
struct BITmax {
    ll n;
    vector<T> d;
    BITmax(ll n = 0) : n(n), d(n + 1) {}
    void add(ll i, T x = 1) {
        for (i++; i <= n; i += i & -i) {
            chmax(d[i], x);
        }
    }
    T sum(ll i) {
        T x = 0;
        for (i++; i; i -= i & -i) {
            chmax(x, d[i]);
        }
        return x;
    }
};

