struct UnionFind{
private:
    std::vector<int> par;
    std::vector<int> size;
public:
    UnionFind(int size_){
        par=std::vector<int>(size_);
        size=std::vector<int>(size_);
        for(int i=0;i<size_;++i){
            par[i]=i;
            size[i]=1;
        }
    }

    int root(int x){
        if(par[x]==x)return x;
        else {
            par[x]=root(par[x]);
            return par[x];
        }
    }

    bool same(int x,int y){//0-indexed
        return root(x)==root(y);
    }

    void unite(int x,int y){//0-indexed
        x=root(x);
        y=root(y);
        if(x==y)return;

        if(size[x]<size[y]){
            par[x]=y;
            size[y]+=size[x];
        }
        else{
            par[y]=x;
            size[x]+=size[y];
        }
    }
};

