ll modpow(ll x, ll y) {
	ll ans = 1;
	while (y) {
		if (y & 1)ans *= x;
		x *= x;
		ans %= MOD;
		x %= MOD;
		y /= 2;
	}
	return ans;
}

ll nck(ll x, ll y) {
	return fact[x] * inv[y] % MOD * inv[x - y] % MOD;
}

ll dfs(int x) {
	if (G[x].size() == 0) {
		return 2;
	}
	ll ans = 1;
	for (int c : G[x]) {
		ans *= dfs(c);
		ans %= MOD;
	}
	return ans + 1;
}

