const ll mod = 998244353;

template <typename T, typename F>
class SegTree{
  int n; T uni; F f;
  vector<T> dat;
public:
  SegTree(int _n, F f, T uni) : f(f), uni(uni) {
    n = 1;
    while(n < _n) n *= 2;
    dat = vector<T>(2*n,uni);
  }
  void set(int k, const T x) {
    dat[k+n] = x;
  }
  void build() {
    for(int i = n-1; i >= 0; i--) {
      dat[i] = f(dat[2*i],dat[2*i+1]);
    }
  }
  void update(int k, T x) {
    k += n;
    dat[k] = x;
    while(k >>= 1){
      dat[k] = f(dat[2*k],dat[2*k+1]);
    }
  }
  T query(int a, int b) {
    T l = uni, r = uni;
    for(a += n, b += n; a < b; a >>= 1, b >>= 1) {
      if(a & 1) l = f(l,dat[a++]);
      if(b & 1) r = f(dat[--b],r);
    }
    return f(l,r);
  }
};

int main(){
  int n;
  cin >> n;
  P p[n]; ll x[n];
  rep(i,n) cin >> p[i].first >> p[i].second;
  sort(p,p+n);
  rep(i,n) x[i] = p[i].first;
  auto f = [](ll a, ll b){return max(a,b);};
  SegTree<ll,decltype(f)> st(n,f,-1);
  rep(i,n) st.set(i,i);
  st.build();
  vector<int> c(n);
  for(int i = n-2; i >= 0; i--) {
    int b = lower_bound(x,x+n,x[i]+p[i].second) - x;
    st.update(i,st.query(i,b));
  }
  vector<ll> dp(n+1,1);
  dp[n-1] = 2;
  for(int i = n-2; i >= 0; i--) dp[i] = (dp[i+1] + dp[st.query(i,i+1)+1]) % mod;
  cout << dp[0] << endl;
  return 0;
}

#include<bits/stdc++.h>
using namespace std;
using u32 = uint_fast32_t;
using i32 = int_fast32_t;
using u64 = uint_fast64_t;

struct Segtree {
	u32 n;
	vector<u32> data;
	u32 U = numeric_limits<u32>::min();
	Segtree(u32 N) : n(calc_n(N)), data(n*2, U) {}
	void set(u32 p, u32 v) {
		p += n;
		data[p] = v;
		while (p) {
			p /= 2;
			data[p] = max(data[p*2], data[p*2+1]);
		}
	}
	u32 get(u32 l, u32 r) {
		u32 res = U;
		for (l += n, r += n; l < r; l /= 2, r /= 2) {
			if (l & 1) res = max(res, data[l++]);
			if (r & 1) res = max(res, data[--r]);
		}
		return res;
	}
	u32 get(u32 p) {
		return data[p+n];
	}
private:
	u32 calc_n(u32 N) {
		u32 n = 1;
		while (n < N) n *= 2;
		return n;
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	u32 N;
	cin >> N;
	vector<i32> X(N), D(N);
	{
		vector<pair<i32, i32>> v;
		for (u32 i = 0; i < N; i++) {
			u32 a, b; cin >> a >> b;
			v.emplace_back(a, b);
		}
		sort(v.begin(), v.end());
		for (u32 i = 0; i < N; i++) {
			X[i] = v[i].first;
			D[i] = v[i].second;
		}
	}
	Segtree R(N);
	for (u32 l = N - 1; ~l; l--) {
		R.set(l, l);
		u32 r = lower_bound(X.begin() + l, X.end(), X[l] + D[l]) - X.begin();
		R.set(l, R.get(l, r));
	}
	vector<u64> dp(N+1);
	dp[N] = 1;
	for (u32 i = N - 1; ~i; i--) {
		dp[i] = dp[i+1] + dp[R.get(i)+1];
		dp[i] %= 998244353;
	}
	cout << dp[0] << endl;
}

