        fin = true;
      }
    }
    if (fin) {
      at[i] = N-1;
    }
  }
  at[N-1] = N-1;
  for (int i = 0; i < N-1; i++) {
    int a = i;
    vector<int> l = {};
    while (depend[a] != -1) {
      a = depend[a];
      l.push_back(a);
    }
    at[i] = at[a];
    for (int j = 0; j < (int)l.size() - 1; j++) {
      depend[l[j]] = a;
    }
  }
  DP[0] = 1;
  for (int i = 0; i < N; i++) {
    DP[i+1] += DP[i];
    DP[at[i]+1] += DP[i];
    DP[i+1] %= Mod;
    DP[at[i]+1] %= Mod;
  }
  cout << DP[N] << endl;
  return 0;
}

