typedef long long ll;
const int N = 2e5;
typedef pair <int,int> pii;
const ll MOD = 998244353;

ll dmod(ll x){
	return x%MOD;
}

int n;

pii li[N+5];
int ST[4*N+5];

void update(int node, int l, int r, int pos, int val){
	if(pos > r || pos < l) return;
	if(l == r){
		ST[node] = val;
		return;
	}
	int mid = (l+r)/2;
	update(node*2,l,mid,pos,val);
	update(node*2+1,mid+1,r,pos,val);
	ST[node] = max(ST[node*2], ST[node*2+1]);
	return;
}

int query(int node, int l, int r, int ql, int qr){
	if(l > qr || r < ql) return 0;
	if(l >= ql && r <= qr) return ST[node];
	int mid = (l+r)/2;
	return max(query(node*2,l,mid,ql,qr),query(node*2+1,mid+1,r,ql,qr));
}

int cari(int x, int id){
	int ret = id;
	int l = id+1;
	int r = n;
	while(l<=r){
		int mid = (l+r)/2;
		if(li[mid].first <= x){
			l = mid + 1;
			ret = mid;
		} else {
			r = mid - 1;
		}
	}
	return ret;
}

ll fe(ll x, ll p){
	if(p==0) return 1ll;
	ll ret = fe(x,p/2);
	ret = dmod(ret*ret);
	if(p&1) ret = dmod(ret*x);
	return ret;
}

ll p2[N+5];

ll memo[N+5];
int kanan[N+5];

ll dp(int x){
	if(x > n) return 1;
	ll &ret = memo[x];
	if(ret != -1) return ret;
	ret = dp(x+1);
	ret += dp(kanan[x]+1);
	return ret;
}

int main(){
