ll nibutan() { //めぐる式

	ll ng = -1; //最大値ならs.size()
	ll ok = n + 1; // 最大値なら0

	while (abs(ok - ng) > 1) {
		ll mid = (ok + ng) / 2;

		if (solve(mid)) ok = mid;
		else ng = mid;
	}
	return ok; //満たさない最大ならng
}

