        if (l == r){
                st[k] = val;
                return;
        }
        ll mid = (l + r) >> 1;
        upd(k << 1, l, mid, x, val);
        upd(k << 1 | 1, mid + 1, r, x, val);
        st[k] = max(st[k << 1 | 1], st[k << 1]);
