ll get(ll k, ll l, ll r, ll x, ll y){
        if (x > r || y < l) return -1e18;
        if (x <= l && y >= r) return st[k];
        ll mid = (l + r) >> 1;
        return max(get(k << 1, l, mid, x, y), get(k << 1 | 1, mid + 1, r, x, y));
}
