template<typename T = int, class F = std::plus<T>, class F_INV = std::minus<T>, const T E = 0>
struct BinaryIndexedTree {
    const F op = F(); const F_INV op_inv = F_INV();
    int n; vector<T> dat;
    void build(const vector<T>& v) {
        n = v.size(); dat.assign(n, E); for (int i = 0; i < n; ++i) add(i, v[i]);
    }
    void add(int k, T v) { for (int i = k; i < n; i |= i + 1) dat[i] = op(dat[i], v) % MOD; }
    T query(int a, int b) const {
        T ret = E; if (a == b) return ret;
        for (int i = b - 1; i >= 0; i = (i & (i + 1)) - 1) ret = op(ret, dat[i]) % MOD;
        return (op_inv(ret, query(0, a)) + MOD) % MOD;
    }
};

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> XD(N);
    rep(i, N) cin >> XD[i].first >> XD[i].second;

    sort(all(XD));
    BinaryIndexedTree<ll> bit;
    bit.build(vector<ll>(N));
    set<int> s;

    vector<ll> ans(N + 2);
    ans[N] = ans[N + 1] = 1;
    for (int i = N - 1; i >= 0; --i) {
        int j = lower_bound(all(XD), make_pair(XD[i].first + XD[i].second, 0)) - XD.begin();
        auto begin = s.lower_bound(i + 1), end = s.lower_bound(j - 1);
        for (auto it = begin; it != end; ++it) {
            bit.add(*it, -bit.query(*it, *it + 1));
        }
        s.erase(begin, end);
        if (j == i + 1) {
            ans[i] = ans[i + 1] * 2 % MOD;
            bit.add(i, ans[i + 2]);
            s.insert(i);
        }
        else {
            ans[i] = (ans[i + 1] + bit.query(j - 1, N)) % MOD;
        }
    }
    write(ans[0]);
}

