      }
      sort(vec.begin(), vec.end());
      vector<mint> live(n+1);
      vector<mint> death(n+1);
      live[n-1] = death[n-1] = 1;

      // RangeMaximumQuery:
      auto f = [](ll a, ll b) { return max(a, b); };
      auto ID = 0LL;
      auto seg = SegTree<ll>(n, f, ID);
      rep(i, n) {
