    build_tree(1, 0, n - 1);
    RFOR(i, n-1, 0) {
        int r = distance(robx, upper_bound(robx, robx + n, robx[i] + robd[i] - 1)) - 1;
        farthest[i] = query_tree(1, 0, n - 1, i, r);
        update_tree(1, 0, n - 1, i, i, farthest[i]);
