        while (s.size() && p[i].second > p[s.top()].first) {
            f[i] = max(f[i], f[s.top()]);
            s.pop();
        }
        s.push(i);

        dp[i][0] = (dp[i + 1][0] + dp[i + 1][1]) % MOD;
        if (f[i] == n - 1)
            dp[i][1] = 1;
        else
            dp[i][1] = (dp[f[i] + 1][0] + dp[f[i] + 1][1]) % MOD;
    }

    cout << (dp[0][0] + dp[0][1]) % MOD << endl;

    return 0;
}

