vector<ll> R;

void dfs(int c) {
  if (R[c] != -1) return;
  R[c] = c;

  ll x = A[c].first, d = A[c].second;
  for (ll i = c + 1; i < N; i++) {
    ll nx = A[i].first;
    if (nx < x + d) {
      dfs(i);
      R[c] = max(R[c], R[i]);
    } else {
      break;
    }
  }
  return;
}

