  for (ll i = 0; i < N; i++) dfs(i);

  vector<ll> dp(N + 1, 0);
  dp[N] = 1;
  for (ll i = N - 1; i >= 0; i--) {
    dp[i] += dp[i + 1];
    dp[i] += dp[R[i] + 1];
