vector<bool> visited;
llongV R;

llong dfs(llong i) {
    if(visited[i]) return 0;
    visited[i] = true;

    llong ret = 1;
    FORS(to, i + 1, R[i]) {
        if(visited[to]) continue;
        ret = (ret * (dfs(to) + 1)) % MOD;
    }
    return ret;
}

