int dfs(int v)
{
    if (next[v] > 0)
        return next[v];

    int m = std::lower_bound(rag(xs), ps[v].first + ps[v].second) - std::begin(xs);

    int res = v + 1;

    for (int i = v + 1; i < m; ++i)
    {
        if (res == n)
            return next[v] = res;
        res = std::max(res, dfs(i));
    }

    return next[v] = res;
}

