struct chash {
  static uint64_t splitmix64(uint64_t x) {
    x += 0x9e3779b97f4a7c15;
    x = (x ^ x >> 30) * 0xbf58476d1ce4e5b9;
    x = (x ^ x >> 27) * 0x94d049bb133111eb;
    return x ^ x >> 31;
  }
  size_t operator()(uint64_t x) const {
    static const uint64_t r = rng<uint64_t>(0, 0);
    return splitmix64(x ^ r);
  }
};

template <class T, class Op = function<T(T, T)>> struct segtree {
  const Op op;
  const T e = T();
  const long long n = 0;
  gp_hash_table<long long, T, chash> t;
  T& operator[](long long i) { return t[n + i]; }
  T at(long long i) { return t.find(i) != end(t) ? t[i] : e; }
  T fold(long long l, long long r) {
    T a = e, b = e;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) a = op(a, at(l++));
      if (r & 1) b = op(at(--r), b);
    }
    return op(a, b);
  }
  void set(long long i, T a) {
    t[i += n] = a;
    while (i >>= 1) t[i] = op(at(2 * i), at(2 * i + 1));
  }
};
template <class T, class Op> auto make_segtree(long long n, Op op, T e) {
  return segtree<T, Op>{op, e, n};
}
auto maximum = [](auto l, auto r) { return l < r ? r : l; };

template <unsigned M> struct modular {
  using m = modular;
  unsigned v;
  modular(long long x = 0) : v((x %= M) < 0 ? x + M : x) {}
  m operator-() const { return m() -= *this; }
  m& operator+=(m b) { if ((v += b.v) >= M) v -= M; return *this; }
  m& operator-=(m b) { if (v < b.v) v += M; v -= b.v; return *this; }
  m& operator*=(m b) { v = (uint64_t)v * b.v % M; return *this; }
  m& operator/=(m b) { return *this *= power(b, M - 2); }
  friend m operator+(m a, m b) { return a += b; }
  friend m operator-(m a, m b) { return a -= b; }
  friend m operator*(m a, m b) { return a *= b; }
  friend m operator/(m a, m b) { return a /= b; }
  friend bool operator==(m a, m b) { return a.v == b.v; }
  friend string to_string(m a) { return to_string(a.v); }
};

