using ll = long long;
using P = pair<ll,ll>;
const ll mod = 998244353;
const int INF = 1e9;

template <typename T, typename F>
class SegTree{
  int n; T uni; F f;
  vector<T> dat;
public:
  SegTree(int _n, F f, T uni) : f(f), uni(uni) {
    n = 1;
    while(n < _n) n *= 2;
    dat = vector<T>(2*n,uni);
  }
  void set(int k, const T x) {
    dat[k+n] = x;
  }
  void build() {
    for(int i = n-1; i >= 0; i--) {
      dat[i] = f(dat[2*i],dat[2*i+1]);
    }
  }
  void update(int k, T x) {
    k += n;
    dat[k] = x;
    while(k >>= 1){
      dat[k] = f(dat[2*k],dat[2*k+1]);
    }
  }
  T query(int a, int b) {
    T l = uni, r = uni;
    for(a += n, b += n; a < b; a >>= 1, b >>= 1) {
      if(a & 1) l = f(l,dat[a++]);
      if(b & 1) r = f(dat[--b],r);
    }
    return f(l,r);
  }
};

int main(){
  int n;
  cin >> n;
  P p[n];
  rep(i,n) cin >> p[i].first >> p[i].second;
  sort(p,p+n);
  vector<ll> x(n);
  rep(i,n) x[i] = p[i].first;
  auto f = [](ll a, ll b){return max(a,b);};
  SegTree<ll,decltype(f)> st(n,f,-1);
  vector<int> c(n);
  c[n-1] = n-1;
  st.update(n-1,c[n-1]);
  for(int i = n-2; i >= 0; i--) {
    st.update(i,i);
    int b = lower_bound(x.begin(),x.end(),x[i]+p[i].second) - x.begin();
    c[i] = st.query(i,b);
    st.update(i,c[i]);
  }
  vector<ll> dp(n,0);
  dp[n-1] = 2;
  for(int i = n-2; i >= 0; i--) {
    if(c[i] == n-1) dp[i] = (dp[i+1] + 1) % mod;
    else dp[i] = (dp[i+1] + dp[c[i]+1]) % mod;
  }
  cout << dp[0] << endl;
  return 0;
}

