        r[i] -= 1;
    }

    //show(r);

    SegmentTree st(r);

    for (int i = n-1; i >= 0; i--)
    {
        int tmp = st.getmax(i, st.getval(i)+1);
        st.update(i, tmp);
    }

    // rep(i, n){
