    }
    SegmentTree seg(v, 0);
    for (int i = N - 2; i >= 0; i--) {
        int reach = lower_bound(X.begin(), X.end(), X[i] + D[i]) - X.begin();
        int r = seg.query(i, reach);
        seg.update(i, r);
    }

    vector<ll> dp(N + 1, 0);
    ll mod = 998244353;
    dp[N] = 1;
    for (int i = N - 1; i >= 0; i--) {
        dp[i] = (dp[i] + dp[i + 1]) % mod;
        dp[i] = (dp[i] + dp[seg.query(i, i + 1)]) % mod;
    }

    cout << dp[0] << endl;
}

