struct ST
{
	vector<int> node;
	int N;

	ST(int sz)
	{
		N = 1;
		while (N < sz)N *= 2;
		node.resize(2 * N - 1, -INF);
	}

	ST(int* a, int sz)
	{
		N = 1;
		while (N < sz)N *= 2;
		node.resize(2 * N - 1, -INF);

		rep(i, 0, sz)node[N - 1 + i] = a[i];
		rrep(i, 0, N - 1)node[i] = max(node[2 * i + 1], node[2 * i + 2]);
	}

	ST(vector<int> a)
	{
		N = 1;
		while (N < SZ(a))N *= 2;
		node.resize(2 * N - 1, -INF);

		rep(i, 0, SZ(a))node[N - 1 + i] = a[i];
		rrep(i, 0, N - 1)node[i] = max(node[2 * i + 1], node[2 * i + 2]);
	}

	void update(int i, int a)
	{
		node[N - 1 + i] = a;
		int k = N - 1 + i;
		while (k > 0)
		{
			k = (k - 1) / 2;
			node[k] = max(node[2 * k + 1], node[2 * k + 2]);
		}
	}

	int query(int a, int b, int k, int l, int r = -1)
	{
		if (r == -1)r = N;
		if (b <= l || r <= a)
		{
			return -INF;
		}
		if (a <= l && r <= b)
		{
			return node[k];
		}
		else
		{
			return max(query(a, b, 2 * k + 1, l, (l + r) / 2), query(a, b, 2 * k + 2, (l + r) / 2, r));
		}
	}
};

