void build(ll k,ll l,ll r,ll wei,ll val)
{
	ll m=(l+r)/2;
	if(l==wei&&wei==r)
	{
		tree[k]=val;
	}
	else if(l<=wei&&wei<=r)
	{
		build(k*2+1,l,m,wei,val);
		build(k*2+2,m+1,r,wei,val);
		tree[k]=max(tree[k*2+1],tree[k*2+2]);
	}
}
ll cal(ll k,ll l,ll r,ll l1,ll r1)
{
	ll m=(l+r)/2;
	if(l1<=l&&r<=r1)
	{
		return tree[k];
	}
	else if(r<l1||r1<l)
	{
		return -10000000000;
	}
	else
	{
		return max(cal(k*2+1,l,m,l1,r1),cal(k*2+2,m+1,r,l1,r1));
	}
}
ll bi(ll l,ll r,ll val)
{	
	ll m=(l+r)/2;
	if(l==r)
	{
		return m;
	}
	else if(a[m].x>=val)
	{
		return bi(l,m,val);
	}
	else
	{
		return bi(m+1,r,val);
	}
}
