template<class T>
class SegmentTree {
public:
    SegmentTree(int n_) : n(1) {
        while (n < n_) n *= 2;
        node.resize(2 * n - 1, def);
    }

    T comp(T a, T b) { return std::max(a, b); }
    // d[k] = a
    void update(int k, T x) {
        k += n - 1;
        node[k] = x;
        while (k > 0) {
            k = (k - 1) >> 1;
            node[k] = comp(node[2 * k + 1], node[2 * k + 2]);
        }
    }
    // comp() [a,b)
    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0)
            r = n;

        if (r <= a || b <= l)
            return def;
        if (a <= l && r <= b)
            return node[k];
        int vl = query(a, b, 2 * k + 1, l, (l + r) >> 1);
        int vr = query(a, b, 2 * k + 2, (l + r) >> 1, r);
        return comp(vl, vr);
    }
private:
    static const T def = std::numeric_limits<T>::min();
    int n;
    vector<T> node;
};

