class SegTree{
public:
    int sz;
    vector<ll> v;
    SegTree(int s){
        sz=s;
        v=vector<ll> (4*sz+10,-1e18);
    }
    void up(ll n,ll s,ll e,ll i,ll val){
        if(s==e){
            v[n]=max(v[n],val);return ;
        }
        ll m=(s+e)/2;
        if(i>=s&&i<=m)up(2*n,s,m,i,val);
        else up(2*n+1,m+1,e,i,val);
        v[n]=max(v[2*n],v[2*n+1]);
    }
    ll query(ll n,ll s,ll e,ll l,ll r){
        if(s>e||l>e||s>r)return -1e18;
        if(s>=l&&e<=r)return v[n];
        ll m=(s+e)/2;
        return max(query(2*n,s,m,l,r),query(2*n+1,m+1,e,l,r));
    }
};



