void upd(ll k, ll l, ll r, ll x, ll val){
        if (x > r || x < l) return;
        if (l == r){
                st[k] = val;
                return;
        }
        ll mid = (l + r) >> 1;
        upd(k << 1, l, mid, x, val);
        upd(k << 1 | 1, mid + 1, r, x, val);
        st[k] = max(st[k << 1 | 1], st[k << 1]);
}
ll get(ll k, ll l, ll r, ll x, ll y){
        if (x > r || y < l) return -1e18;
        if (x <= l && y >= r) return st[k];
        ll mid = (l + r) >> 1;
        return max(get(k << 1, l, mid, x, y), get(k << 1 | 1, mid + 1, r, x, y));
}
