int bs(ll val){
    int l = 0, r = v.size();
    while(r - l > 1){
        int m = (l+r)/2;
        if(v[m].x < val) l = m;
        else r = m;
    }
    return l;
}

void build(int v, int l, int r){
    if(l == r){
        t[v] = l;
    }else{
        int m = (l+r)/2;
        build(v*2, l, m);
        build(v*2+1, m+1, r);
        t[v] = max(t[v*2], t[v*2+1]);
    }
}

int get(int v, int tl, int tr, int l, int r){
    if(l > r)
        return 0;
    if(tl == l && tr == r){
        return t[v];
    }else{
        int m = (tl+tr)/2;
        return max(get(v*2, tl, m, l, min(r, m)),
                get(v*2+1, m+1, tr, max(l, m+1), r));
    }
}

void update(int v, int l, int r, int ind, int val){
    if(l == r)
        t[v] = val;
    else{
        int m = (l+r)/2;
        if(ind <= m) update(v*2, l, m, ind, val);
        else update(v*2+1, m+1, r, ind, val);
        t[v] = max(t[v*2], t[v*2+1]);
    }
}

