const int N = 2e5 + 5;
ll n;
ll nxt[N], st[4*N];
ll dp[N];
const ll MOD = 998244353;
ll compute(ll i)
{
    if( i == n ) return 1;
    if(dp[i] != -1) return dp[i];
    ll ans =  0;
    // take 
    ans += compute(nxt[i]);
    ans %= MOD;
    // dont take
    ans += compute(i+1);
    ans %= MOD;
    return dp[i] = ans;
}
int left(int i)
{
    return i<<1;
}
int right(int i)
{
    return (i<<1)+1;
}
void update(int p, int l, int r, int pos, int val)
{
    if(r < pos || pos < l) return;
    if(l==r){st[p]=val;return ;}
    int mid= (l+r)/2;
    update(left(p), l, mid, pos, val);
    update(right(p), mid+1, r, pos, val);
    st[p] = MAX2(st[left(p)], st[right(p)]);
}
int rmq(int p,int l, int r, int i , int j)
{
    if(i>r|| j<l)
        return ninf;
    if(l>=i&&r<=j)
        return st[p];
    int mid=(l+r)/2;
    return MAX2(rmq(left(p), l, mid, i, j), rmq(right(p), mid+1, r, i, j));
}

