		// printf("insert: %d, %d\n", ind, val);
		ind = ind + base - 1;
		bi[ind] = val;
		while (ind / 2) {
			ind /=2;
			bi[ind] = max(bi[2*ind], bi[2*ind + 1]);
		}
	};
