#define per(i,a,b) for(int i=a;i>=b;i--)
const int MAXN = 2e5+5;
const int MOD= 998244353;
int n,b[MAXN];
struct node{
    int x,y;
}a[MAXN];
bool cmp(node a,node b){
    return a.x<b.x;
}
ll dp[MAXN];
struct Node{
    int l,r,maxx;
}t[MAXN<<2];
void build(int rt,int l,int r){
    t[rt].l=l,t[rt].r=r;
    t[rt].maxx=-2e9-1;
    if(l==r)return;
    int mid=(t[rt].l+t[rt].r)>>1;
    build(rt<<1,l,mid);
    build(rt<<1|1,mid+1,r);
}
void update(int rt,int p,int val){
    if(t[rt].l==t[rt].r){
        t[rt].maxx=max(t[rt].maxx,val);
        return;
    }
    int mid=(t[rt].l+t[rt].r)>>1;
    if(p<=mid)update(rt<<1,p,val);
    else update(rt<<1|1,p,val);
    t[rt].maxx=max(t[rt<<1].maxx,t[rt<<1|1].maxx);
}
int query(int rt,int l,int r){
    if(t[rt].l>=l&&t[rt].r<=r)return t[rt].maxx;
    int ans=-2e9-1;
    int mid=(t[rt].l+t[rt].r)>>1;
    if(l<=mid)ans=max(ans,query(rt<<1,l,r));
    if(r>mid)ans=max(ans,query(rt<<1|1,l,r));
    return ans;
}
int main()
{
    scanf("%d",&n);
    build(1,1,n);
    rep(i,1,n){
        scanf("%d%d",&a[i].x,&a[i].y);
        a[i].y+=a[i].x-1;
    }
    sort(a+1,a+n+1,cmp);
    rep(i,1,n)b[i]=a[i].x;
    dp[n+1]=1;
    per(i,n,1){
        int p=upper_bound(b+1,b+n+1,a[i].y)-b;
        p--;
        int temp=max(query(1,i,p),a[i].y);
        update(1,i,temp);
        p=upper_bound(b+1,b+n+1,temp)-b;
        dp[i]=(dp[i+1]+dp[p])%MOD;
    }
    printf("%lld\n",dp[1]);
}

