struct SegTree{ //0indexed
    std::vector<int> nod;
    int size;
    SegTree(int x){
        size=1;
        while(x>size){
            size*=2;
        }
        nod=std::vector<int>(size*2-1,INT_MIN/2);
    }
    void update(int k,int a){
        k+=size-1;
        nod[k]=a;//最下の処理
        while(k>0){
            k=(k-1)/2;
            nod[k] = std::max(nod[k*2+1], nod[k*2+2]); //下から上へ 
        }
    }
    int query(int a,int b,int k,int l,int r){
        //[a,b)について
        //kは節点の番号,[l,r)はその節点がカバーする範囲
        if(r<=a||b<=l){ //[a,b)と[l,r)が重なって無いとき
            return INT_MIN/2;
        }
        if(a<=l && r<=b){ //[a,b)が[l,r)を完全に含んでいるとき
            return nod[k];
        }
        else{
            return std::max(query(a,b,k*2+1,l,(l+r)/2),query(a,b,k*2+2,(l+r)/2,r));
        }
    }
    void deb(){ //全ノードの出力
		for(int i=0;i<size*2-1;i++){
			if(i==size*2-2){
				std::cout << nod[i] <<std:: endl;
			}
			else{
				std::cout << nod[i] << ' ';
			}
		}
		return;
	}
};

using namespace std;

void interval(vector<Pii> &da, int n){
	SegTree st(n*2);
	vector<Pii> li(n*2);
	rip(i,n,0){
	li[i*2] = mapa(da[i].first, n+i);
	li[i*2+1] = mapa(da[i].first+da[i].second, i);
	}
	sort(all(li));
	for(int i=2*n-1;i>=0;i--){
		if(li[i].second < n){
			da[li[i].second].second = i;
		}
		else{
			da[li[i].second-n].second = max(st.query(i, da[li[i].second-n].second+1, 0, 0, st.size), li[da[li[i].second-n].second].first);
			st.update(i, da[li[i].second-n].second);
		}
	}
	return;
}

