class SegmentTree_min {
public:
	SegmentTree_min(int64_t size,const int64_t *d);
	SegmentTree_min(const SegmentTree_min& t);
	SegmentTree_min& operator=(const SegmentTree_min& t);
	int64_t calcmin(const int64_t a,const int64_t b) const;//[a,b]の間の最小値
	void change(const int64_t address,const int64_t value);
	virtual ~SegmentTree_min();
private:
	int64_t max_depth;
	int64_t calcmin(const int64_t a,const int64_t b,const int64_t ptr,const int64_t range_min,const int64_t range_max) const;
	//calcminからよばれる内部処理 [a,b]について、配列番号ptrのものを探索 配列番号ptrが指す範囲は、[range_min,range_max]
	int64_t size;
	int64_t *data;
};
SegmentTree_min::SegmentTree_min(int64_t dsize,const int64_t *d) {

	// TODO 自動生成されたコンストラクター・スタブ
	for(int i=63;i>=0;i--){
		if(dsize&((uint64_t)1<<i)){
			max_depth = i+1;
			break;
		}
	}
	this->size = ((uint64_t)1<<(max_depth));
	data = new int64_t[2*size-1];
	for(int64_t i=0;i<dsize;i++){
		data[size-1+i]=d[i];
	}
	for(int64_t i=dsize;i<size;i++){
		data[size-1+i]=std::numeric_limits<int64_t>::max();
	}
	for(int64_t i=size-2;i>=0;i--){
		data[i]=std::min(data[2*i+1],data[2*i+2]);
	}
}
SegmentTree_min::SegmentTree_min(const SegmentTree_min& t){
	if(&t==this){
		max_depth = 1;
		size = 1;
		data = new int64_t[1];
		data[0]=0;
	}else{
		max_depth = t.max_depth;
		size = t.size;
		data = new int64_t[2*size-1];
		for(int64_t i=0;i<(2*size-1);i++){
			data[i]=t.data[i];
		}
	}
}
SegmentTree_min& SegmentTree_min::operator=(const SegmentTree_min& t){
	if(&t!=this){
		delete[] data;
		max_depth = t.max_depth;
		size = t.size;
		data = new int64_t[2*size-1];
		for(int64_t i=0;i<(2*size-1);i++){
			data[i]=t.data[i];
		}
	}
	return *this;
}
int64_t SegmentTree_min::calcmin(const int64_t a,const int64_t b) const{
	return calcmin(a,b,0,0,size-1);
}
int64_t SegmentTree_min::calcmin(const int64_t a,const int64_t b,const int64_t ptr,const int64_t range_min,const int64_t range_max) const{
	if(a<=range_min&&b>=range_max){
		return data[ptr];
	}else{
		int64_t border = (range_max+range_min-1)/2;
		if(b<=border){
			return calcmin(a,b,2*ptr+1,range_min,border);
		}else if(a>=border+1){
			return calcmin(a,b,2*ptr+2,border+1,range_max);
		}else{
			return std::min(calcmin(a,border,ptr*2+1,range_min,border),calcmin(border+1,b,ptr*2+2,border+1,range_max));
		}
	}
}
void SegmentTree_min::change(const int64_t address,const int64_t value){
	data[address + size -1]=value;
	int64_t i=address+size-1;
	do{
		i=(i-1)/2;
		data[i]=std::min(data[2*i+1],data[2*i+2]);
	}while(i!=0);
}
SegmentTree_min::~SegmentTree_min() {
	// TODO Auto-generated destructor stub
	delete[] data;
}
