		}else{
			robots[i1].alpha=(robots[i1+1].alpha+robots[i1+1].beta)%998244353;
		}
		//calculate beta
		if(robots[i1].position+robots[i1].move>robots[n-1].position){
			robots[i1].beta=1;
		}else{
			if(robots[i1].position+robots[i1].move<=robots[i1+1].position){
				robots[i1].beta=(robots[i1+1].alpha+robots[i1+1].beta)%998244353;
			}else{
				Robot comp;
				comp.position=robots[i1].position+robots[i1].move;
				int64_t top_index = distance(robots.begin(),std::lower_bound(robots.begin(),robots.end(),comp))-1;
				robots[i1].beta=betas.calcmin(i1+1,top_index);
			}
		}
		betas.change(i1,robots[i1].beta);
	}
	cout<<(robots[0].alpha+robots[0].beta)%998244353<<endl;


}

