	cin.tie(0);
    ios::sync_with_stdio(false);

    ll n;
    cin >> n;
    ll x, l;
    vector<P> p(n);
    vll pos(n);
    REP(i, n) {
        cin >> x >> l;
        p[i] = {x, l};
        pos[i] = x;
    }
    VSORT(p);
    VSORT(pos);
    vll mem(n + 1);
    mem[n] = 1;
    REP(i, n) {
        a[i] = -(p[i].first + p[i].second);
    }
    vll right(n + 1);
