struct robot {
    int x, d;
    bool operator<(const robot& other) const {
        return x < other.x;
    }
} r[N];

int ans[N];

int seg[2*N];

void init() {
    for(int i = 0; i < n; ++i) {
        seg[i+n] = i+1;
    }

    for(int i = n-1; i > 0; --i) {
        seg[i] = max(seg[i<<1], seg[i<<1 | 1]);
    }
}

void upd(int i, int val) {
    i += n;
    seg[i] = val;
    for(; i > 1; i >>= 1) {
        seg[i>>1] = max(seg[i], seg[i^1]);
    }
}

int q(int l, int r) {
    int ret = 0;
    for(l += n, r += n; l < r; l >>= 1, r >>= 1) {
        if(l&1) ret = max(ret, seg[l++]);
        if(r&1) ret = max(ret, seg[--r]);
    }
    return ret;
}

