    int index1 = upper_bound(kk);
    int kkk = seg.query(i, index1, 0, 0, seg.size);
    kkk = max(kkk, kk);
    seg.update(i, kkk);
    dp[i] = dp[i+1] + dp[upper_bound(kkk)];
  }
  cout << dp[0].x << "\n";

  return 0;
}

