int main() {
	int n; scanf("%d", &n);
	std::vector<std::pair<int, int>> vec(n);
	for(int i = 0; i < n; i++) scanf("%d%d", &vec[i].first, &vec[i].second);
	sort(begin(vec), end(vec));

	mint ans = 1;
	std::vector<int> last(n, -1);
	for(int i = 0; i < n; i++) {
		auto solve = [&](auto&& solve, int now) -> mint {
			mint ret = 1;
			int next = now + 1, border = vec[now].first + vec[now].second;
			while(next < n and vec[next].first < border) {
				ret *= solve(solve, next); // next が食べる区間 [next, last[next]) の組合せ数，now が起動しない場合
				next = last[next];
			}
			ret += 1; // now が起動する場合 [now, last[now]) は食べられる．
			last[now] = next;

			return ret;
		};
		if(last[i] == -1) ans *= solve(solve, i);
	}
	printf("%llu\n", ans);
	return 0;
}

