class SegTree
{
public:
    SegTree(int size) : nodes_(4 * size + 4, 0), size_(size) {}

    void Set(int index, int value)
    {
        Set(0, 0, size_ - 1, index, value);
    }

    int Get(int left, int right) const
    {
        return Get(0, 0, size_ - 1, left, right);
    }

private:
    void Set(int node, int left, int right, int index, int value)
    {
        if (left == right) {
            nodes_[node] = value;
            return;
        }

        int mid = left + (right - left) / 2;
        if (index <= mid) {
            Set(LeftSon(node), left, mid, index, value);
        } else {
            Set(RightSon(node), mid + 1, right, index, value);
        }
        nodes_[node] = std::max(nodes_[LeftSon(node)], nodes_[RightSon(node)]);
    }

    int Get(int node, int left, int right, int x, int y) const
    {
        if (x <= left && right <= y) {
            return nodes_[node];
        }

        int mid = left + (right - left) / 2;
        int res = 0;

        if (x <= mid) {
            res = std::max(res, Get(LeftSon(node), left, mid, x, y));
        }
        if (mid < y) {
            res = std::max(res, Get(RightSon(node), mid + 1, right, x, y));
        }
        return res;
    }

    static int LeftSon(int node) { return 2 * node + 1; }
    static int RightSon(int node) { return 2 * node + 2; }

    std::vector<int> nodes_;
    int size_;
};

int FindClosest(const std::vector<std::pair<int, int>> &points, int limit)
{
    int res = -1;
    int pow = (1 << 20);

    while (pow > 0) {
        int next_res = res + pow;
        pow >>= 1;

        if (next_res < (int)points.size() && points[next_res].first < limit) {
            res = next_res;
        }
    }
    return res;
}

int main()
{
    int n;
    std::cin >> n;

    std::vector<std::pair<int, int>> points(n);
    for (auto &p : points) {
        std::cin >> p.first >> p.second;
    }
    std::sort(points.begin(), points.end());

    constexpr int kMod = 998244353;
    std::vector<int> ways(n, 0);
    std::vector<int> reach(n, -1);

    SegTree tree(n);
    for (int i = 0; i < n; i += 1) {
        reach[i] = i;
        tree.Set(i, reach[i]);
    }
    for (int i = n - 2; i >= 0; i -= 1) {
        int right = FindClosest(points, points[i].first + points[i].second);
        reach[i] = tree.Get(i, right);
        tree.Set(i, reach[i]);
    }

    ways[n - 1] = 2;
    for (int i = n - 2; i >= 0; i -= 1) {
        ways[i] = ways[i + 1];
        if (reach[i] + 1 < n) {
            ways[i] = (1LL * ways[i] + ways[reach[i] + 1]) % kMod;
        } else {
            ways[i] = (1LL * ways[i] + 1) % kMod;
        }
    }

    std::cout << ways[0] << "\n";
    return 0;
}

