template <typename T>
struct segtree {

  vector<T> seg, lazy;

  segtree(int n = 1e5) {
    n += 5;
    seg.assign(4*n, 0);
    lazy.assign(4*n, 0);
  }

  T join(T x, T y) {
    return max(x, y);
  }

  void lazy_update(int x, int s, int e) {
    if (!lazy[x])  return ;
    seg[x] = max(seg[x], lazy[x]);

    if( s != e )
      lazy[2*x] = max(lazy[2*x], lazy[x]), lazy[2*x+1] = max(lazy[2*x+1], lazy[x]);
    lazy[x] = 0;
  }

  void build(int x, int s, int e) {
    if (s == e) {
      seg[x] = 0;
      return; 
    }

    int mid = (s + e) >> 1;
    build(2 * x, s, mid);
    build(2 * x + 1, mid + 1, e);

    seg[x] = join(seg[2*x], seg[2*x+1]);
  }

  void update(int x ,int s ,int e ,int l ,int r ,T val) {
    lazy_update(x ,s ,e);
    if (s > r || e < l)  return ;

    if (s >= l && e <= r) {
      lazy[x] += val;
      lazy_update(x, s, e);
      return;
    }

    int mid = (s + e) >> 1;
    update(2 * x ,s ,mid ,l ,r ,val);
    update(2 * x + 1, mid + 1, e, l, r, val);

    seg[x] = join(seg[2 * x], seg[2 * x + 1]);
  }

  T query(int x, int s, int e, int l, int r) {
    lazy_update(x, s, e);
    if (e < l || s > r)  return 0;
    if (s >= l && e <= r){
      return seg[x];
    }

    int mid = (s + e) >> 1;
    return join(query(2 * x ,s ,mid ,l ,r), query(2 * x + 1, mid + 1, e, l, r));
  }
};

