signed main() {

	SS(int, N);
	vector<pair<int, int>> robots;
	REP(i, N) {
		SS(int, x, d);
		robots.emplace_back(x, d);
	}
	SORT(robots);

	SegmentTree<int> seg(N, [](int a, int b){ return max(a, b); }, 0);
	REP(i, N) seg.set(i, i);
	seg.build();

	for (int i = N - 2; i >= 0; --i) {
		int x, d;
		tie(x, d) = robots[i];
		int idx = lower_bound(robots.begin(), robots.end(), make_pair(x + d, -INF)) - robots.begin();
		seg.update(i, seg.query(i, idx));
	}

	vector<mint> dp(N + 1, mint(0));
	dp[0] = 1;
	REP(i, N) {
		dp[seg.query(i, i + 1) + 1] += dp[i];
		dp[i + 1] += dp[i];
	}
	print(dp[N]);

}

