    rrep(i, n-1){
        int j = lower_bound(p, p+n, make_pair(lim[i], 0LL)) - p;
        dp[i] = dp[i+1] + (j < n ? dp[j] : 1);
    }
    printf("%lld\n", dp[0].a);
}

