#define MOD 998244353

using namespace std;

using pii = pair<int, int>;

unsigned long long clp(unsigned long long x) {
    x -= 1;
    x = x | (x >>  1);
    x = x | (x >>  2);
    x = x | (x >>  4);
    x = x | (x >>  8);
    x = x | (x >> 16);
    x = x | (x >> 32);
    return x + 1;
}

template <class T>
class segment_tree {
private:
    const size_t n;
    const T UNIT;
    const std::function<T(const T&, const T&)> f;
    std::vector<T> a;
public:
    segment_tree(size_t size, std::function<T(const T&, const T&)> f, T UNIT) : n(clp(size)), UNIT(UNIT), f(f) {
        a.resize(2 * n - 1, UNIT);
    }

    void update(size_t i, const T &x) {
        i += n - 1;
        a[i] = x;
        while (i) {
            i = (i - 1) / 2;
            a[i] = f(a[2 * i + 1], a[2 * i + 2]);
        }
    }

    T query(size_t query_first, size_t query_last, size_t k = 0, size_t node_first = 0, size_t node_last = 0) const {
        if (k == 0) {
            node_last = n;
        }
        if (node_last <= query_first || query_last <= node_first) {
            return UNIT;
        }
        if (query_first <= node_first && node_last <= query_last) {
            return a[k];
        } else {
            size_t node_mid = (node_first + node_last) / 2;
            T vl = query(query_first, query_last, k * 2 + 1, node_first, node_mid);
            T vr = query(query_first, query_last, k * 2 + 2, node_mid, node_last);
            return f(vl, vr);
        }
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<pii> XD(N);
    REP(i, N) {
        int X, D;
        cin >> X >> D;
        XD[i] = pii(X, D);
    }
    sort(all(XD));
    vector<int> X(N), D(N);
    REP(i, N) {
        tie(X[i], D[i]) = XD[i];
    }

    // i 番目のロボットを起動したとき
    // 何番目のロボットまで連鎖するか
    segment_tree<int> rmq(N, [](int x, int y) { return max(x, y); }, INT_MIN);

    // dp[i] = (ロボット i 以降のみの組み合わせ)
    vector<int> dp(N + 1);
    dp[N] = 1;

    RREP(i, N) {
        // ロボット i を起動したとき, 直接的に起動するロボット (自身も含める) のうち最も右にあるもの,
        // つまり, X[k] < X[i] + D[i] を満たす k のうち最大のもの,
        // つまり, X[k + 1] >= X[i] + D[i] を満たす k のうち最小のものを求める.
        int k = lower_bound(X.begin() + i, X.end(), X[i] + D[i]) - X.begin() - 1;
        // ロボット i を起動したとき, 間接的に起動するロボットのうち最も右にあるもの.
        int l = rmq.query(i + 1, k + 1);
        // ロボット i を起動したとき, 起動するロボット (自身も含める) のうち最も右にあるもの.
        int m = max(k, l);
        rmq.update(i, m);
        // (ロボット i を起動しない場合) + (ロボット i を起動しない場合)
        dp[i] = (dp[i + 1] + dp[m + 1]) % MOD;
    }

    cout << dp[0] << endl;

    return 0;
}

