ll calc_num(const vi& robots, const int i, const int n) {
    if (i == n - 1) { return 2; }

    ll sum = 0;

    // Run.
    if (i + robots[i] == n - 1) {
        sum += 1;
    } else {
        sum += calc_num(robots, i + robots[i] + 1, n);
    }

    // Stop.
    sum += calc_num(robots, i + 1, n);
    return sum % MOD;
}


int main() {
    int n;
    cin >> n;

    vector<pair<int, int>> xd(n);
    rep(i, 0, n) {
        int x, d;
        cin >> x >> d;
        xd[i] = make_pair(x, d);
    }

    sort(xd.begin(), xd.end());

    vi robots(n, 0);
    rrep(i, 0, n-1) {
        int j = 1;
        while (xd[i].first + xd[i].second > xd[i + j].first) {
            robots[i] = max(robots[i], j + robots[i+j]);
            j++;
            if (i + j == n) { break; }
        }
    }

    ll ans = calc_num(robots, 0, n);    
    cout << ans << endl;

    return 0;
}

