        rmq.update(i, i + 1, -d);
    }

    ruiseki[N] = 0;
    REP(i, N)
    {
        int d = rmq.query(N - 1 - i, N - i);
        if (-d != N - 1 - i)
        {
            d = rmq.query(N - 1 - i, -d + 1);
        }
        rmq.update(N - 1 - i, N - i, d);

        ruiseki[N - 1 - i] = (1 + ruiseki[-d + 1]) + ruiseki[N - i];
        ruiseki[N - 1 - i] %= MOD;
    }
    cout << ruiseki[0] + 1 << endl;

    return 0;
}

