	static class DisjointSetUnion {
		public int[] parent;
		public int[] weight;
		public int count;

		public DisjointSetUnion(int nodes) {
			count = nodes;
			parent = new int[nodes];
			weight = new int[nodes];
			for (int i = 0; i < nodes; i++) {
				parent[i] = i;
				weight[i] = 1;
			}
		}
		//"find"
		public int root(int p) {
			while (p != parent[p]) {
				p = parent[p];
			}
			return p;
		}

		//"union"
		public void connect(int p, int q) {
			int rootP = root(p);
			int rootQ = root(q);
			if (rootP == rootQ) return;
			if (weight[rootP] < weight[rootQ]) {
				parent[rootP] = rootQ;
				weight[rootQ] += weight[rootP];
			} else {
				parent[rootQ] = rootP;
				weight[rootP] += weight[rootQ];
			}
			count--;
		}

		public boolean connected(int p, int q) {
			return root(p) == root(q);
		}
	}
	static class IntList{
		int tail = 0;
		final int[] element;
		public IntList(int cap) {
			element = new int[cap];
		}
		public int size() {
			return tail;
		}
		public int get(int index) {
			return element[index];
		}
		public void reset() {
			tail = 0;
		}
		public void add(int v) {
			element[tail++] = v;
		}
	}

	public void exec() throws Exception{
		final long M = 998244353L;
		final int N = sc.nextInt();
		final long[] U = new long[N];
		final long[] pattern = new long[N];
		int D = 0;
		for(int i=0;i<N;i++) {
			final int x = sc.nextInt();
			final int d = sc.nextInt();
			U[i] = pair(x, d);
			D = Math.max(D, d);
		}
		final IntList set = new IntList(N);
		final IntList fix = new IntList(N);
		Arrays.sort(U);
		set.add(N-1);

		// 一番右は必ず末端なので2通りある。
		pattern[N-1] = 2;

		for(int i=N-2;i>=0;i--) {
			final int size = set.size();
			set.reset();
			for(int s=0;s<size;s++) {
				int rx = getPair1(U[set.get(s)]);
				int x  = getPair1(U[i]);
				int d  = getPair2(U[i]);
				if(rx < x+d) {
					// 巻き込み範囲である場合、現在のルートは更新する。
					if(pattern[i]==0) {
						pattern[i] = pattern[set.get(s)];
					}else {
						pattern[i] = pattern[i] * pattern[set.get(s)];
					}
					pattern[i] %= M;
				}else if(x + D < rx){
					// 最大移動距離よりも離れた場合は、それ以上連携されないのでfixに移動する。
					fix.add(set.get(s));
				}else {
					// まだ左からアクセスが可能な場合があるので、再度探索対象にする。
					set.add(set.get(s));
				}
			}
			// 現在探索の一番左は必ずルートになる。
			set.add(i);
			// 末端だった場合にはパターン数を設定。
			if(pattern[i]==0) {
				pattern[i] = 2;
			}else {
				pattern[i] = (pattern[i]+1) % M;
			}
		}

//		err.println(Arrays.toString(root));
//		err.println(Arrays.toString(pattern));
//		err.println(Arrays.toString(Arrays.copyOf(set, tail)));

		long sum = 1;
		for(int i=0;i<fix.size();i++) {
			sum *= pattern[fix.get(i)];
			sum %= M;
		}
		for(int i=0;i<set.size();i++) {
			sum *= pattern[set.get(i)];
			sum %= M;
		}
		out.println(sum);
	}
}

