				if(ts.higher(a[i])==null)break;
				int b[] = ts.higher(a[i]);
				go = false;
				if(b[0]<a[i][0]+a[i][1]) {
					graph[i].add(b[2]);
					ts.remove(b);
					go = true;
				}
			}
		}

		long ans = 1;
