interface MonoidOperator<MONOID> {
    MONOID apply(MONOID m1, MONOID m2);
}


class SegmentTree<MONOID> {
    final int n;
    final MONOID defaultValue;
    final MONOID[] dat;
    final MonoidOperator<MONOID> monoidOperator;

    public SegmentTree(int n, MONOID defaultValue, MONOID[] dat, MonoidOperator<MONOID> monoidOperator) {
        this.n = n;
        this.defaultValue = defaultValue;
        this.dat = dat;
        this.monoidOperator = monoidOperator;
    }

    public static <MONOID> SegmentTree<MONOID> create(int n, final MONOID defaultValue, final MONOID[] dat, final MonoidOperator<MONOID> operator) {
        final int N = Integer.highestOneBit(n) << 1;
        Arrays.fill(dat, defaultValue);
        return new SegmentTree<>(N, defaultValue, dat, operator);
    }

    public static SegmentTree<Integer> createIntMaxTree(int n) {
        final int size = (Integer.highestOneBit(n) << 2) - 1;
        return create(n, Integer.MIN_VALUE, new Integer[size], Integer::max);
    }

    public static SegmentTree<Long> createLongMaxTree(int n) {
        final int size = (Integer.highestOneBit(n) << 2) - 1;
        return create(n, Long.MIN_VALUE, new Long[size], Long::max);
    }

    public static SegmentTree<Long> createLongMinTree(int n) {
        final int size = (Integer.highestOneBit(n) << 2) - 1;
        return create(n, Long.MAX_VALUE, new Long[size], Long::min);
    }

    public static SegmentTree<Long> createLongSumTree(int n) {
        final int size = (Integer.highestOneBit(n) << 2) - 1;
        return create(n, 0L, new Long[size], Long::sum);
    }

    public void update(int k, MONOID monoid) {
        k += n - 1;
        dat[k] = monoid;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = monoidOperator.apply(dat[k*2 + 1], dat[k*2 + 2]);
        }
    }

    private MONOID query(int a, int b, int k, int l, int r) {
        if (r < a || b < l) return defaultValue;

        if (a <= l && r <= b) return dat[k];
        else {
            final MONOID vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            final MONOID vr = query(a, b, k * 2 + 2, (l + r) / 2 + 1, r);
            return monoidOperator.apply(vl, vr);
        }
    }

    public MONOID query(int a, int b) {
        return query(a, b, 0, 0, n - 1);
    }

    public void display() {
        System.out.println("-------------Segment Tree-------------");
        for (int i = 1; i < dat.length; i *= 2) {
            for (int j = i; j < 2 * i; j++) {
                System.out.print(dat[j-1] + " ");
            }
            System.out.println();
        }
        System.out.println("----------------End------------------");
        System.out.println();
    }
}

class ModCombination {
    private final ModLib modLib;

    private final long[] fact;
    private final long[] invfact;

    private ModCombination(ModLib modLib, long[] fact, long[] invfact) {
        this.modLib = modLib;
        this.fact = fact;
        this.invfact = invfact;
    }

    public static ModCombination create(int size, ModLib modLib) {
        long[] fact = new long[size];
        fact[0] = 1;
        for (int i = 0; i < size - 1; i++) {
            fact[i+1] = modLib.mult(fact[i], i + 1);
        }
        long[] invfact = new long[size];
        invfact[size-1] = modLib.div(1, fact[size-1]);
        for (int i = size - 2; i >= 0; i--) {
            invfact[i] = modLib.mult(invfact[i+1], i + 1);
        }
        return new ModCombination(modLib, fact, invfact);
    }

    public long fact(int x) {
        return fact[x];
    }

    public long invfact(int x) {
        return invfact[x];
    }

    public long comb(int a, int b) {
        if (b > a) {
            return 0;
        }
        return modLib.mult(fact[a], modLib.mult(invfact[b], invfact[a-b]));
    }

}

class ModLib {
    final long mod;

    public ModLib(long mod) {
        this.mod = mod;
    }

    public long add(long a, long b) {
        return (a + b) % mod;
    }

    public long sub(long a, long b) {
        return (a - b + mod) % mod;
    }

    public long mult(long a, long b) {
        return ((a % mod) * (b % mod)) % mod;
    }

    public long pow(long a, long x) {
        long res = 1;
        for ( ; x > 0; x >>= 1) {
            if (x % 2 == 1) res = mult(res, a);
            a = mult(a, a);
        }

        return res;
    }

    public long div(long a, long b) {
        return mult(a, pow(b, mod - 2));
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        int n = sc.nextInt(); int mod = 998244353;
        Robot [] r = new Robot[n];
        for (int i = 0; i < n; i++) r[i] = new Robot(sc.nextLong(), sc.nextLong());
        Arrays.sort(r, Comparator.comparingLong(a -> a.start));
        long [] pos = new long[n];
        for (int i = 0; i < n; i++) pos[i] = r[i].start;
        int [] cover = new int[n];
        for (int i = 0; i < n; i++) {
            long find = r[i].start + r[i].dist;
            int idx = Arrays.binarySearch(pos, find);
            if (idx >= 0) idx--;
            else {
                idx = -idx - 2;
            }
            cover[i] = idx;
        }
        int [] end = new int[n];
        RangeTree seg = new RangeTree(n);
        end[n - 1] = n - 1; seg.update(n - 1, n - 1, n - 1);
        for (int i = n - 2; i >= 0; i--) {
            if (cover[i] == i) {
                end[i] = i; continue;
            }
            end[i] = (int) Math.max(cover[i], seg.maxQuery(i + 1, cover[i]));
            seg.update(i, i, end[i]);
        }
        long [] dp = new long[n + 1];
        dp[n] = 1; dp[n - 1] = 2;
        for (int i = n - 2; i >= 0; i--) dp[i] = (dp[i + 1] + dp[end[i] + 1]) % mod;
        out.println(dp[0]);
        out.close();
    }

    static class RangeTree {
        private long[] max;
        private long[] min;
        private long[] lazy;
        private long[] sum;
        private int size;
        public RangeTree(int size) {
            this.size = size;
            max = new long[4*size];
            min = new long[4*size];
            sum = new long[4*size];
            lazy = new long[4*size];
        }
        public void update(int l, int r, int inc) {
            update(1, 0, size-1, l, r, inc);
        }
        private void pushDown(int index, int l, int r) {
            min[index] += lazy[index];
            max[index] += lazy[index];
            sum[index] += lazy[index] * (r-l+1);
            if(l != r) {
                lazy[2*index] += lazy[index];
                lazy[2*index+1] += lazy[index];
            }
            lazy[index] = 0;
        }
        private void pullUp(int index, int l, int r) {
            int m = (l+r)/2;
            min[index] = Math.min(evaluateMin(2*index, l, m), evaluateMin(2*index+1, m+1, r));
            max[index] = Math.max(evaluateMax(2*index, l, m), evaluateMax(2*index+1, m+1, r));
            sum[index] = evaluateSum(2*index, l, m) + evaluateSum(2*index+1, m+1, r);
        }
        private long evaluateSum(int index, int l, int r) {
            return sum[index] + (r-l+1)*lazy[index];
        }
        private long evaluateMin(int index, int l, int r) {
            return min[index] + lazy[index];
        }
        private long evaluateMax(int index, int l, int r) {
            return max[index] + lazy[index];
        }
        private void update(int index, int l, int r, int left, int right, int inc) {
            if(r < left || l > right) return;
            if(l >= left && r <= right) {
                lazy[index] += inc;
                return;
            }
            pushDown(index, l, r);
            int m = (l+r)/2;
            update(2*index, l, m, left, right, inc);
            update(2*index+1, m+1, r, left, right, inc);
            pullUp(index, l, r);
        }
        public long minQuery(int l, int r) {
            return minQuery(1, 0, size-1, l, r);
        }
        private long minQuery(int index, int l, int r, int left, int right) {
            if(r < left || l > right) return Long.MAX_VALUE;
            if(l >= left && r <= right) {
                return evaluateMin(index, l, r);
            }
            pushDown(index, l, r);
            int m = (l+r)/2;
            long ret = Long.MAX_VALUE;
            ret = Math.min(ret, minQuery(2*index, l, m, left, right));
            ret = Math.min(ret, minQuery(2*index+1, m+1, r, left, right));
            pullUp(index, l, r);
            return ret;
        }
        public long maxQuery(int l, int r) {
            return maxQuery(1, 0, size-1, l, r);
        }
        private long maxQuery(int index, int l, int r, int left, int right) {
            if(r < left || l > right) return Long.MIN_VALUE;
            if(l >= left && r <= right) {
                return evaluateMax(index, l, r);
            }
            pushDown(index, l, r);
            int m = (l+r)/2;
            long ret = Long.MIN_VALUE;
            ret = Math.max(ret, maxQuery(2*index, l, m, left, right));
            ret = Math.max(ret, maxQuery(2*index+1, m+1, r, left, right));
            pullUp(index, l, r);
            return ret;
        }
        public long sumQuery(int l, int r) {
            return sumQuery(1, 0, size-1, l, r);
        }
        private long sumQuery(int index, int l, int r, int left, int right) {
            if(r < left || l > right) return 0;
            if(l >= left && r <= right) {
                return evaluateSum(index, l, r);
            }
            pushDown(index, l, r);
            int m = (l+r)/2;
            long ret = 0;
            ret += sumQuery(2*index, l, m, left, right);
            ret += sumQuery(2*index+1, m+1, r, left, right);
            pullUp(index, l, r);
            return ret;
        }
    }

