	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Beginner Contest 158 F問題
		 * 考察メモ
		 * 一番左のロボットについて
		 * 押した場合: そのロボットから連鎖する全てのロボットを消した連続区間の答え(連続区間なことは保証される)
		 * 押さない場合: そのロボットを取り除いた連続区間の答え
		 * これの2つの和になる
		 * よってこれを再帰的に解けば良い
		 * やるだけじゃん？
		 *
		 * さて、必要なことを纏めよう
		 * まず、各ロボットについて押した時に残る右側の区間を求めたい
		 * これは、右側のロボットから順に求めていく
		 * 区間(X, X+D)に含まれる全てのロボットに対し、その時の右側の最大値が欲しい
		 * これはセグ木とかで解決できるのではい
		 *
		 */
		int N = io.nextInt();
		Robot[] robot = new Robot[N];
		for (int i = 0;i < N;++ i) robot[i] = new Robot(io.nextInt(), io.nextInt());
		Arrays.sort(robot);
		SegmentTree<Integer> segtree = SegmentTree.create(N, N, new Maximum<Integer>());
		TreeSet<Pair> set = new TreeSet<>();
		ModUtility mod = new ModUtility(new Prime(998_244_353));
		ModInteger[] dp = new ModInteger[N + 1];
		dp[N] = mod.create(1);
		for (int i = N - 1;i >= 0;-- i) {
			Pair tmp = set.lower(new Pair(robot[i].X + robot[i].D, 0));
			int next = tmp == null ? i + 1 : segtree.get(i + 1, tmp.i);
			set.add(new Pair(robot[i].X, next));
			segtree.set(i, next);
			dp[i] = dp[i + 1].add(dp[next]);
		}
		io.println(dp[0]);
	}

