	public class Maximum<T extends Comparable<T>> implements CommutativeMonoid<T>{

		@Override
		public T apply(T left, T right) {
			if (left == null) return right;
			else if (right == null) return left;
			return left.compareTo(right) > 0 ? left : right;
		}

		@Override
		public T identity() {
			return null;
		}

		@Override
		public T hyper(T element, int repeat) {
			return element;
		}

	}
	public interface BinarySearch<T> {

		public int size();

		/**
		 * 指定した範囲で二分探索を行います。
		 * @param left 範囲の左区間
		 * @param right 範囲の右区間
		 * @param f 単調性を持つ関数
		 * @return 半開区間[left, right)において関数fがtrueを返す最大の値(無ければleft-1)<br>
		 * ただしleft>rightなら、半開区間[right, left)において関数fがtrueを返す最小の値(無ければleft)
		 */
		public int binarySearch(int left, int right, Predicate<T> f);

		/**
		 * 指定した範囲で二分探索を行います。
		 * @param range 二分探索を行う区間
		 * @param f 単調性を持つ関数
		 * @return 区間rangeにおいて関数fがtrueを返す最大の値(無ければrangeの左区間より小さい最大の値)
		 */
		public default int binarySearch(IntRange range, Predicate<T> f) {
			return binarySearch(range.getClosedLower(), range.getOpenUpper(), f);
		}

		/**
		 * 全区間で二分探索を行います。
		 * @param f 単調性を持つ関数
		 * @return 半開区間[0, size)において関数fがtrueを返す最大の値(無ければleft-1)
		 */
		public default int binarySearch(Predicate<T> f) {
			return binarySearch(0, size(), f);
		}

		/**
		 * 指定した範囲で二分探索を行います。
		 * @param left 範囲の左区間
		 * @param f 単調性を持つ関数
		 * @return 半開区間[left, size)において関数fがtrueを返す最大の値(無ければleft-1)
		 */
		public default int binarySearch(int left, Predicate<T> f) {
			return binarySearch(left, size(), f);
		}
	}

	/**
	 * セグメント木です。<br>
	 * １点更新をO(logN)、範囲取得をO(logN)でできるデータ構造です。
	 * @author 31536000
	 *
	 * @param <T> 更新及び範囲取得を行いたいクラス
	 */
	public static abstract class SegmentTree<T> extends Array<T> implements BinarySearch<T>{

		private static final long serialVersionUID = -6906482277965513109L;

		public static <T> SegmentTree<T> create(int N, Monoid<T> group) {
			if (N < 1 || group == null) throw new IllegalArgumentException();
			return new MonoidSegmentTree<>(N, group.identity(), group);
		}

		public static <T> SegmentTree<T> create(int N, T dat, Monoid<T> group) {
			if (N < 1 || dat == null || group == null) throw new IllegalArgumentException();
			return new MonoidSegmentTree<>(N, dat, group);
		}

		public static <T> SegmentTree<T> create(T[] dat, Monoid<T> group) {
			if (dat == null || dat.length < 1 || group == null) throw new IllegalArgumentException();
			return new MonoidSegmentTree<>(dat, group);
		}

		public static <T extends Monoid<T>> SegmentTree<T> create(T[] dat) {
			if (dat == null || dat.length < 1) throw new IllegalArgumentException();
			return new MonoidSegmentTree<>(dat, dat[0]);
		}

		public static <T> SegmentTree<T> create(int N, Abelian<T> group) {
			if (N < 1 || group == null) throw new IllegalArgumentException();
			return new FenwickTree<>(N, group.identity(), group);
		}

		public static <T> SegmentTree<T> create(int N, T dat, Abelian<T> group) {
			if (N < 1 || dat == null || group == null) throw new IllegalArgumentException();
			return new FenwickTree<>(N, dat, group);
		}

		public static <T> SegmentTree<T> create(T[] dat, Abelian<T> group) {
			if (dat == null || dat.length < 1 || group == null) throw new IllegalArgumentException();
			return new FenwickTree<>(dat, group);
		}

		public static <T extends Abelian<T>> SegmentTree<T> create(T[] dat) {
			if (dat == null || dat.length < 1) throw new IllegalArgumentException();
			return new FenwickTree<>(dat, dat[0]);
		}

		private SegmentTree(int length) {
			super(length);
		}

		private Object[] getLocal() {
			return super.get();
		}

		private static final class FenwickTree<T> extends SegmentTree<T> {

			private static final long serialVersionUID = -6757039207238116416L;
			private final Abelian<T> group;
			private final Object[] array;
			private final int size;

			private T getLocal(int index) {
				@SuppressWarnings("unchecked")
				T ret = (T)array[index];
				return ret;
			}

			private FenwickTree(int N, T dat, Abelian<T> group) {
				super(N + 1);
				size = N;
				this.group = group;
				array = super.getLocal();
				Arrays.fill(array, dat);
				for (int i = 1, j;i <= size();++ i) if ((j = i + (i & -i)) <= size()) array[j] = group.apply(getLocal(i), getLocal(j));
			}

			private FenwickTree(T[] dat, Abelian<T> group) {
				super(dat.length + 1);
				size = dat.length;
				this.group = group;
				array = super.getLocal();
				System.arraycopy(dat, 0, array, 1, dat.length);
				for (int i = 1, j;i <= size();++ i) if ((j = i + (i & -i)) <= size()) array[j] = group.apply(getLocal(i), getLocal(j));
			}

			@Override
			public T set(int index, T dat) {
				if (index < 0 || index >= size()) throw new IndexOutOfBoundsException("out of bounds: " + index);
				T ret = get(index);
				apply(index, group.apply(group.inverse(ret), dat));
				return ret;
			}

			@Override
			public void apply(int index, T dat) {
				if (index < 0 || index >= size()) throw new IndexOutOfBoundsException("out of bounds: " + index);
				for (++ index;index <= size(); index += index & -index) array[index] = group.apply(getLocal(index), dat);
			}

			@Override
			public Object[] get() {
				Object[] ret = new Object[size()];
				System.arraycopy(array, 1, ret, 0, size());
				for (int i = 1, j;i <= size();++ i) {
					if ((j = i + (i & -i)) <= size()) {
						@SuppressWarnings("unchecked")
						T t = (T)ret[j - 1];
						ret[j - 1] = group.apply(t, group.inverse(getLocal(i)));
					}
				}
				return ret;
			}

			@Override
			public T[] get(T[] array) {
				if (array.length < size()) {
					@SuppressWarnings("unchecked")
					T[] ret  = (T[])Arrays.copyOfRange(get(), 1, size() + 1, array.getClass());
					array = ret;
				} else System.arraycopy(this.array, 1, array, 0, size());
				for (int i = 1, j;i <= size();++ i) if ((j = i + (i & -i)) <= size()) array[j - 1] = group.apply(array[j - 1], group.inverse(getLocal(i)));
				return array;
			}

			@Override
			public T get(int l, int r) {
				if (l < 0 || l > r || r > size()) throw new IndexOutOfBoundsException("[" + l + ", " + r + ") is undefined.");
				T left = group.identity(), right = group.identity();
				for (;l != 0;l ^= l & -l) left = group.apply(left, getLocal(l));
				for (;r != 0;r ^= r & -r) right = group.apply(right, getLocal(r));
				return group.apply(group.inverse(left), right);
			}

			@Override
			public T getAvoid(int left, int right) {
				return group.apply(get(0, left), get(right, size));
			}

			@Override
			public int binarySearch(Predicate<T> f) {
				int ret = 0;
				T left = group.identity();
				for (int i = Integer.highestOneBit(size);i != 0;i >>= 1) {
					if (ret + i <= size && f.test(group.apply(left, getLocal(ret + i)))) {
						left = group.apply(left, getLocal(ret + i));
						ret += i;
					}
				}
				return ret - 1;
			}

			@Override
			public int binarySearch(int left, int right, Predicate<T> f) {
				int ret = left;
				T l = get(0, left);
				for (int i = Integer.highestOneBit(size);i != 0;i >>= 1) {
					if (ret + i <= size && f.test(group.apply(l, getLocal(ret + i)))) {
						l = group.apply(l, getLocal(ret + i));
						ret += i;
					}
				}
				return ret - 1;
			}

			private class Iter implements Iterator<T> {
				private int index;

				private Iter() {
					index = 0;
				}

				@Override
				public boolean hasNext() {
					return index < size();
				}

				@Override
				public T next() {
					return get(index++);
				}

				@Override
				public void remove() {
					set(index-1, group.identity());
				}
			}

			@Override
			public Iterator<T> iterator() {
				return new Iter();
			}
		}

		private static final class MonoidSegmentTree<T> extends SegmentTree<T> {

			private static final long serialVersionUID = 1099468778793692403L;
			private final Monoid<T> group;
			private final Object[] array;
			private final int size;

			private MonoidSegmentTree(int N, T dat, Monoid<T> group) {
				super(Integer.highestOneBit(N) << 2);
				this.group = group;
				size = N;
				array = super.getLocal();

				Arrays.fill(array, array.length >> 1, size | array.length >> 1, dat);
				Arrays.fill(array, size | array.length >> 1, array.length, group.identity());
				for (int i = array.length / 2 - 1; i > 0; --i) localSet(i, group.apply(localGet(i << 1), localGet(i << 1 | 1)));
			}

			private MonoidSegmentTree(T[] dat, Monoid<T> group) {
				super(Integer.highestOneBit(dat.length) << 2);
				this.group = group;
				size = dat.length;
				array = super.getLocal();
				System.arraycopy(dat, 0, array, array.length >> 1, dat.length);
				Arrays.fill(array, size | array.length >> 1, array.length, group.identity());
				for (int i = array.length / 2 - 1; i > 0; --i) localSet(i, group.apply(localGet(i << 1), localGet(i << 1 | 1)));
			}

			private void localSet(int index, T value) {
				array[index] = value;
			}

			@SuppressWarnings("unchecked")
			private T localGet(int index) {
				return (T)array[index];
			}

			@Override
			public T set(int index, T dat) {
				if (index < 0 || index >= size()) throw new IndexOutOfBoundsException("out of bounds: " + index);
				T ret = get(index);
				index |= array.length >> 1;
				localSet(index, dat);
				for (int i = index >> 1; i > 0; i >>= 1) localSet(i, group.apply(localGet(i << 1), localGet(i << 1 | 1)));
				return ret;
			}

			@Override
			public void apply(int index, T dat) {
				if (index < 0 || index >= size()) throw new IndexOutOfBoundsException("out of bounds: " + index);
				set(index, group.apply(get(index), dat));
			}

			@Override
			public Object[] get() {
				Object[] ret = new Object[size];
				System.arraycopy(array, array.length >> 1, ret, 0, size);
				return ret;
			}

			@Override
			public T[] get(T[] array) {
				if (array.length < size) {
					@SuppressWarnings("unchecked")
					T[] ret  = (T[])Arrays.copyOfRange(array, array.length >> 1, size | array.length >> 1, array.getClass());
					array = ret;
				} else System.arraycopy(array, array.length >> 1, array, 0, size);
				return array;
			}

			@Override
			public T get(int index) {
				if (index < 0 || index >= size()) throw new IndexOutOfBoundsException("out of bounds: " + index);
				return localGet(index | array.length >> 1);
			}

			@Override
			public T get(int l, int r) {
				if (l < 0 || l > r || r > size()) throw new IndexOutOfBoundsException("[" + l + ", " + r + ") is undefined.");
				T L = group.identity(), R = group.identity();
				l |= array.length >> 1;
				r |= array.length >> 1;
				while (l < r) {
					if ((l & 1) != 0) L = group.apply(L, localGet(l++));
					if ((r & 1) != 0) R = group.apply(localGet(r ^ 1), R);
					l >>= 1;
					r >>= 1;
				}
				return group.apply(L, R);
			}

			@Override
			public T getAvoid(int left, int right) {
				return group.apply(get(0, left), get(right, size));
			}

			@Override
			public int binarySearch(int left, int right, Predicate<T> f) { // FIXME バグってるので直して
				if (left < 0 || right > size()) throw new IndexOutOfBoundsException("[" + left + ", " + right + ") is undefined.");
				if (left > right) return revBinarySearch(left - 1, right - 1, f);
				left |= array.length >> 1;
				right |= array.length >> 1;
				T last = group.identity(), next;
				int i = 0;
				while (left < right >>> i) {
					if ((left & 1) == 0) { // 上がある
						left >>>= 1;
						++ i;
					} else {
						if (f.test(next = group.apply(last, localGet(left)))) { // このleft全部を含むか
							last = next;
							++ left;
						} else right = (left + 1 << i) - 1; // 左辺を移動
					}
				}
				while (i > 0) { // 今度は降下しながら見ていく
					left <<= 1;
					-- i;
					if ((right >>> i & 1) != 0) {
						if (f.test(next = group.apply(last, localGet(left)))) {
							last = next;
							++ left;
						} else right = (left + 1 << i) - 1;
					}
				};
				return left - (array.length >> 1) - 1;
			}

			private int revBinarySearch(int right, int left, Predicate<T> f) { // FIXME バグってるので直して
				if (left < 0 || right > size()) throw new IndexOutOfBoundsException("[" + left + ", " + right + ") is undefined.");
				left |= array.length >> 1;
				right |= array.length >> 1;
				T last = group.identity(), next;
				int i = 0;
				while (left >>> i < right) {
					if ((right & 1) == 0) { // 上がある
						if (f.test(next = group.apply(localGet(right), last))) { // このright全部を含むか
							last = next;
							-- right;
						} else left = right << i; // 左辺を移動
					} else {
						right >>>= 1;
						++ i;
					}
				}
				while (i > 0) { // 今度は降下しながら見ていく
					right = right << 1 | 1;
					-- i;
					if ((left >>> i & 1) == 0) {
						if (f.test(next = group.apply(localGet(right), last))) {
							last = next;
							-- right;
						} else left = right << i;
					}
				};
				return right - (array.length >> 1) + 1;
			}

			@Override
			public int size() {
				return size;
			}

			@Override
			public int length() {
				return size;
			}

			private class Iter implements Iterator<T> {
				private int index;

				private Iter() {
					index = 0;
				}

				@Override
				public boolean hasNext() {
					return index < size;
				}

				@Override
				public T next() {
					return get(index++);
				}

				@Override
				public void remove() {
					set(index-1, group.identity());
				}
			}

			@Override
			public Iterator<T> iterator() {
				return new Iter();
			}
		}

		/**
		 * データを更新します。<br>
		 * この操作により、indexの値は元の値にdatを演算した値となります。
		 * @param index 更新する場所
		 * @param dat 更新するデータ
		 */
		public abstract void apply(int index, T dat);

		@Override
		public T get(int index) {
			if (index < 0 || index >= size()) throw new IndexOutOfBoundsException("out of bounds: " + index);
			return get(index, index + 1);
		}

		/**
		 * 指定した範囲の合計を取得します。
		 * @param left 範囲の左区間
		 * @param right 範囲の右区間
		 * @return 半開区間[left, right)の合計
		 */
		public abstract T get(int l, int r);

		/**
		 * 指定した範囲の合計を取得します。
		 * @param range 範囲
		 * @return 区間range内の合計
		 */
		public T get(IntRange range) {
			return get(range.getClosedLower(), range.getOpenUpper());
		}

		/**
		 * 指定した値を除く場所の値を取得します。
		 * @param index 取得しない場所
		 * @return 全体からindexを取り除いた値
		 */
		public T getAvoid(int index) {
			return getAvoid(index, index + 1);
		}

		/**
		 * 指定した範囲を除く区間の合計を取得します。
		 * @param left 範囲の左区間
		 * @param right 範囲の右区間
		 * @return 半開区間[0, left)+[right, size)の合計
		 */
		public abstract T getAvoid(int left, int right);

		/**
		 * 指定した範囲を除く区間の合計を取得します。
		 * @param range 区間
		 * @return 区間rangeを除く範囲の合計
		 */
		public T getAvoid(IntRange range) {
			return getAvoid(range.getClosedLower(), range.getOpenUpper());
		}
	}

	/**
	 * 高速な入出力を提供します。
	 * @author 31536000
	 *
	 */
	public static class FastIO {
		private InputStream in;
		private final byte[] buffer = new byte[1024];
		private int read = 0;
		private int length = 0;
		private PrintWriter out;
		private PrintWriter err;
		private boolean autoFlush = false;

		public FastIO() {
			this(System.in, System.out, System.err);
		}

		public FastIO(InputStream in, PrintStream out, PrintStream err) {
			this.in = in;
			this.out = new PrintWriter(out, false);
			this.err = new PrintWriter(err, false);
		}

		public final void setInputStream(InputStream in) {
			this.in = in;
		}

		public final void setInputStream(File in) {
			try {
				this.in = new FileInputStream(in);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		public final void setOutputStream(PrintStream out) {
			this.out = new PrintWriter(out, false);
		}

		public final void setOutputStream(File out) {
			try {
				this.out = new PrintWriter(new FileOutputStream(out), false);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		public final void setErrorStream(PrintStream err) {
			this.err = new PrintWriter(err, false);
		}

		public final void setErrorStream(File err) {
			try {
				this.err = new PrintWriter(new FileOutputStream(err), false);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		public final void setAutoFlush(boolean flush) {
			autoFlush = flush;
		}

		private boolean hasNextByte() {
			if (read < length) return true;
			read = 0;
			try {
				length = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			return length > 0;
		}

		private int readByte() {
			return hasNextByte() ? buffer[read++] : -1;
		}

		private static boolean isPrintableChar(int c) {
			return 33 <= c && c <= 126;
		}

		private static boolean isNumber(int c) {
			return '0' <= c && c <= '9';
		}

		public final boolean hasNext() {
			while (hasNextByte() && !isPrintableChar(buffer[read])) read++;
			return hasNextByte();
		}

		public final char nextChar() {
			if (!hasNextByte())  throw new NoSuchElementException();
			return (char)readByte();
		}

		public final char[] nextChars() {
			return next().toCharArray();
		}

		public final char[] nextChars(char around) {
			return (around + next() + around).toCharArray();
		}

		public final char[][] nextChars(int height) {
			char[][] ret = new char[height][];
			for (int i = 0;i < ret.length;++ i) ret[i] = nextChars();
			return ret;
		}

		public final char[][] nextChars(int height, char around) {
			char[][] ret = new char[height + 2][];
			for (int i = 1;i <= height;++ i) ret[i] = nextChars(around);
			Arrays.fill(ret[0] = new char[ret[1].length], around);
			Arrays.fill(ret[ret.length - 1] = new char[ret[0].length], around);
			return ret;
		}

		public final String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b;
			while (isPrintableChar(b = readByte())) sb.appendCodePoint(b);
			return sb.toString();
		}

		public final String nextLine() {
			StringBuilder sb = new StringBuilder();
			int b;
			while(!isPrintableChar(b = readByte()));
			do sb.appendCodePoint(b); while(isPrintableChar(b = readByte()) || b == ' ');
			return sb.toString();
		}

		public final long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (!isNumber(b)) throw new NumberFormatException();
			while (true) {
				if (isNumber(b)) {
					n *= 10;
					n += b - '0';
				} else if (b == -1 || !isPrintableChar(b)) return minus ? -n : n;
				else throw new NumberFormatException();
				b = readByte();
			}
		}

		public final int nextInt() {
			long nl = nextLong();
			if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
			return (int) nl;
		}

		public final double nextDouble() {
			return Double.parseDouble(next());
		}

		public final int[] nextInt(int width) {
			int[] ret = new int[width];
			for (int i = 0;i < width;++ i) ret[i] = nextInt();
			return ret;
		}

		public final int[] nextInts() {
			return nextInts(" ");
		}

		public final int[] nextInts(String parse) {
			String[] get = nextLine().split(parse);
			int[] ret = new int[get.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = Integer.valueOf(get[i]);
			return ret;
		}

		public final long[] nextLong(int width) {
			long[] ret = new long[width];
			for (int i = 0;i < width;++ i) ret[i] = nextLong();
			return ret;
		}

		public final long[] nextLongs() {
			return nextLongs(" ");
		}

		public final long[] nextLongs(String parse) {
			String[] get = nextLine().split(parse);
			long[] ret = new long[get.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = Long.valueOf(get[i]);
			return ret;
		}

		public final int[][] nextInt(int width, int height) {
			int[][] ret = new int[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[i][j] = nextInt();
			return ret;
		}

		public final long[][] nextLong(int width, int height) {
			long[][] ret = new long[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[j][i] = nextLong();
			return ret;
		}

		public final boolean[] nextBoolean(char T) {
			char[] s = next().toCharArray();
			boolean[] ret = new boolean[s.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = s[i] == T;
			return ret;
		}

		public final boolean[][] nextBoolean(char T, int height) {
			boolean[][] ret = new boolean[height][];
			for (int i = 0;i < ret.length;++ i) {
				char[] s = next().toCharArray();
				ret[i] = new boolean[s.length];
				for (int j = 0;j < ret[i].length;++ j) ret[i][j] = s[j] == T;
			}
			return ret;
		}

		public final Point nextPoint() {
			return new Point(nextInt(), nextInt());
		}

		public final Point[] nextPoint(int width) {
			Point[] ret = new Point[width];
			for (int i = 0;i < width;++ i) ret[i] = nextPoint();
			return ret;
		}

		@Override
		protected void finalize() throws Throwable {
			try {
				super.finalize();
			} finally {
				in.close();
				out.close();
				err.close();
			}
		}

		public final boolean print(boolean b) {
			out.print(b);
			if (autoFlush) flush();
			return b;
		}

		public final Object print(boolean b, Object t, Object f) {
			return b ? print(t) : print(f);
		}

		public final char print(char c) {
			out.print(c);
			if (autoFlush) flush();
			return c;
		}

		public final char[] print(char[] s) {
			out.print(s);
			return s;
		}

		public final double print(double d) {
			out.print(d);
			if (autoFlush) flush();
			return d;
		}

		public final double print(double d, int length) {
			if (d < 0) {
				out.print('-');
				d = -d;
			}
			d += Math.pow(10, -length) / 2;
			out.print((long)d);
			out.print('.');
			d -= (long)d;
			for (int i = 0;i < length;++ i) {
				d *= 10;
				out.print((int)d);
				d -= (int)d;
			}
			if (autoFlush) flush();
			return d;
		}

		public final float print(float f) {
			out.print(f);
			if (autoFlush) flush();
			return f;
		}

		public final int print(int i) {
			out.print(i);
			if (autoFlush) flush();
			return i;
		}

		public final long print(long l) {
			out.print(l);
			if (autoFlush) flush();
			return l;
		}

		public final Object print(Object obj) {
			if (obj != null && obj.getClass().isArray()) {
				if (obj instanceof boolean[][]) print(obj, "\n", " ");
				else if (obj instanceof byte[][]) print(obj, "\n", " ");
				else if (obj instanceof short[][]) print(obj, "\n", " ");
				else if (obj instanceof int[][]) print(obj, "\n", " ");
				else if (obj instanceof long[][]) print(obj, "\n", " ");
				else if (obj instanceof float[][]) print(obj, "\n", " ");
				else if (obj instanceof double[][]) print(obj, "\n", " ");
				else if (obj instanceof char[][]) print(obj, "\n", " ");
				else if (obj instanceof Object[][]) print(obj, "\n", " ");
				else print(obj, " ");
			} else {
				out.print(obj);
				if (autoFlush) flush();
			}
			return obj;
		}

		public final String print(String s) {
			out.print(s);
			if (autoFlush) flush();
			return s;
		}

		public final Object print(Object array, String... parse) {
			print(array, 0, parse);
			if (autoFlush) flush();
			return array;
		}

		private final Object print(Object array, int check, String... parse) {
			if (check >= parse.length) {
				if (array != null && array.getClass().isArray()) throw new IllegalArgumentException("not equal dimension");
				print(array);
				return array;
			}
			String str = parse[check];
			if (array instanceof Object[]) {
				Object[] obj = (Object[]) array;
				if (obj.length == 0) return array;
				print(obj[0], check + 1, parse);
				for (int i = 1;i < obj.length;++ i) {
					print(str);
					print(obj[i], check + 1, parse);
				}
				return array;
			}
			if (array instanceof Collection) {
