    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = new Machine[N];
        for (int i = 0; i < N; i++) {
            M[i] = new Machine(sc.nextInt(), sc.nextInt());
        }

        System.out.println(solve());
    }

    static int solve() {
        Arrays.sort(M, Comparator.comparingInt(m -> m.x));

        // どこまで届くか
        //   正直もっとマシなやりようがありそう...
        RangeGet reach = new RangeGet(N, RangeGet.MAX);
        for (int i = N - 1; i >= 0; i--) {
            if( i == N-1 ) {
                reach.update(i, N-1);
            } else {
                Machine me = M[i];
                int idx = lowerBound(M, m -> m.x, me.x + me.d);
                int max = Math.max((int)reach.query(i, idx), idx-1);
                reach.update(i, max);
            }
        }

        int sum = 0;
        ArrayDeque<Node> q = new ArrayDeque<>();

        // 空集合相当
        q.add(new Node(Integer.MAX_VALUE, 1));
        sum++;

        for (int i = N-1; i >= 0; i--) {
            int curr = sum;
            int reachIdx = (int)reach.get(i);
            // 起動する -> 届く範囲のものを消す
            while( !q.isEmpty() ) {
                Node node = q.pollFirst();
                if( node.idx <= reachIdx ) {
                    // remove
                    sum -= node.cnt;

                } else {
                    // 戻す
                    q.addFirst(node);
                    break;
                }
            }

            // 起動しない
            q.addFirst( new Node(i, curr) );
            sum += curr;
        }

        int ans = 0;
        while(!q.isEmpty()) {
            Node node = q.pollFirst();
            ans = add(ans, node.cnt);
        }
        return ans;
    }

