class SegmentTree {
	//simple segment tree using long values and max
	long[] array;
	int len;
	long unit;
	public SegmentTree(int len) {

		this.array = new long[len*2];
		this.len = len;
		this.unit = Long.MIN_VALUE;
	}

	void update(int pos, long val) {
		int index = pos + this.len-1;
		array[index] = val;
		while (index > 0) {
			index = (index-1)/2;
			array[index] = Math.max(array[index*2+1], array[index*2+2]); // change here
		}
	}

	long query (int a, int b) {
		return query(a, b, 0, 0, this.len);
	}
	//Query for [a, b). k is the node number for [l,r)
	//usage: query(a, b, 0, 0, len)
	long query(int a, int b, int k, int l, int r) {
		if (b<=l || r<=a) {
			return unit;
		} else if (a<=l && r<=b) {
			return array[k];
		} else {
			return (Math.max(query(a,b,2*k+1,l,(l+r)/2), query(a,b,2*k+2,(l+r)/2,r))); // change here
		}
	}

	public String toString() {
		ArrayList<Long> list = new ArrayList<Long>();
		for (int i=0;i<10;i++) {
			list.add(array[len+i-1]);
		}
		return list.toString();
	}
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;
class Main {
    static int MOD = 998244353;
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        int[][] X = new int[N][2];
        for (int i = 0; i < N; i++) {
            X[i][0] = in.nextInt();
            X[i][1] = in.nextInt();
        }
        Arrays.sort(X, Comparator.comparing(x -> x[0]));
        int[] dp = new int[N+1];
        dp[N] = 1;
        dp[N-1] = 1;
        List<Integer> start = new ArrayList<>();
        start.add(N - 1);
        for (int i = N - 2; i >= 0; i--) {
            int j = start.size() - 1;
            int right = X[i][0] + X[i][1];
            for (; j >= 0; j--) {
                if (right > X[start.get(j)][0]) {
                    dp[i] = dp[start.get(j)] + start.remove(j) - i;
                } else {
                    break;
                }
            }
            start.add(i);
            if (dp[i] == 0) dp[i] = 1;
        }

        int res = 1;
        for (int i = N - 1; i >= 0; i--) {
            res = (res + dp[i + dp[i]]) % MOD;
            dp[i] = res;
        }
        System.out.println(res);
    }
}

