class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        var x = new long[n];
        var d = new long[n];
        for (int i = 0; i < n; i++)
        {
            sc.Multi(out x[i], out d[i]);
            Assert(-1000000000 <= x[i] && x[i] <= 1000000000);
            Assert(1 <= d[i] && d[i] <= 1000000000);
        }
        Array.Sort(x, d);
        var sg = new Segtree<long>(n, Math.Max, -LM);
        var dp = new long[n + 1];
        dp[n] = 1;
        for (int i = n - 1; i >= 0 ; i--)
        {
            int r = x.LowerBound(x[i] + d[i]);
            long rr = Math.Max(sg.run(i + 1, r), x[i] + d[i]);
            sg.update(i, rr);
            int k = x.LowerBound(rr);
            dp[i] = (dp[i + 1] + dp[k]) % M;
        }
        Prt(dp[0]);
    }
}

class pair<T, U> : IComparable<pair<T, U>> {
    public T v1;
    public U v2;
    public pair() : this(default(T), default(U)) {}
    public pair(T v1, U v2) { this.v1 = v1; this.v2 = v2; }
    public int CompareTo(pair<T, U> a) {
        int c = Comparer<T>.Default.Compare(v1, a.v1);
        return c != 0 ? c : Comparer<U>.Default.Compare(v2, a.v2);
    }
    public override string ToString() => v1 + " " + v2;
    public void Deconstruct(out T a, out U b) { a = v1; b = v2; }
}
