            dp[i] += dp[i + 1]; // not choose
            dp[i] %= mod;
            sum += dp[i];
            sum %= mod;
        }

        cout.WriteLine(dp[0]);
    }

    public static int LowerBound<T>(IList<T> A, T x) { return LowerBound(A, 0, A.Count, x); }
    public static int LowerBound<T>(IList<T> A, T x, Comparison<T> comp) { return LowerBound(A, 0, A.Count, x, comp); }
    public static int LowerBound<T>(IList<T> A, int start, int end, T x) { return LowerBound(A, start, end, x, Comparer<T>.Default.Compare); }
    public static int LowerBound<T>(IList<T> A, int start, int end, T x, Comparison<T> comparer) {
        int lower = start, upper = end - 1;
        int result = end;
        while (lower <= upper) {
            int pos = (lower + upper) >> 1;
            if (comparer(x, A[pos]) <= 0) {
                result = pos;
                upper = pos - 1;
            } else {
                lower = pos + 1;
            }
        }
        return result;
    }

}

public sealed class SegmentTree<TMonoid> {
    public int Count { get; private set; }
    private TMonoid[] _node;
    private readonly TMonoid _identity;
    private readonly Func<TMonoid, TMonoid, TMonoid> _merge;

    public SegmentTree(Func<TMonoid, TMonoid, TMonoid> merge, TMonoid identity) {
        _merge = merge;
        _identity = identity;
    }

    public void Build(IList<TMonoid> array) {
        Build(array.Count, i => array[i]);
    }

    public void Build(int n, Func<int, TMonoid> create) {
        Count = n;

        _node = new TMonoid[2 * Count];

        for (int i = 0; i < n; i++) {
            _node[i + Count] = create(i);
        }

        for (int i = Count - 1; i > 0; i--) {
            _node[i] = _merge(_node[i << 1], _node[i << 1 | 1]);
        }
    }

    public void Set(int index, TMonoid val) {
        int p = index + Count;
        _node[p] = val;
        while (p > 0) {
            p >>= 1;
            _node[p] = _merge(_node[p << 1], _node[p << 1 | 1]);
        }
    }

    public TMonoid Query(int begin, int end) {
        TMonoid lv = _identity, rv = _identity;
        int l = begin + Count;
        int r = end + Count - 1;
        for (; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { lv = _merge(lv, _node[l++]); }
            if ((r & 1) == 0) { rv = _merge(_node[r--], rv); }
        }
        return _merge(lv, rv);
    }

    public TMonoid this[int index] {
        get { return _node[index + Count]; }
        set { Set(index, value); }
    }
};
