	public static void Main() {
		checked{
			long  n;
			Lib_IO.rm(out n);
			P<ll,ll>[] xd;
			rl(n,out xd);
			Array.Sort(xd,(x,y)=>x.A.CompareTo(y.A));

			SegmentTree<ll> seg = new SegmentTree<ll>(n,(x,y)=>max(x,y), 0);
			seg.Update(n-1, n-1); 
			for (int i = (int)n-2; 0<=i; i--)
			{
				ll j = BS(xd,xd[i].A+xd[i].B)-1;
				if(i<j){
					seg.Update(i, seg.Query(i+1,j+1));
				}else{
					seg.Update(i, i); 
				}
			}


			ll[] dp = new ll[n+1];
			dp[n] = 1;
			for (int i = (int)n-1; 0<=i; i--)
