			}


			Lib_IO.wm(dp[0]);
		}
	}


	public static long BS<T>(IList<P<ll,ll>> seq, T value)  where T : IComparable<T> {
		int left = -1;
		int right = seq.Count;
		while (right - left > 1) {
			int mid = left + (right - left) / 2;
			if (0<=seq[mid].A.CompareTo(value)) right = mid;
			else left = mid;
		}
		return right;
	}

public struct SegmentTree<TM> {
	private int sz;
	private TM[] seg;
	private Func<TM,TM,TM> f;
	private TM M1;

	public SegmentTree(long n, Func<TM,TM,TM> f, TM M1) {
		this.f = f;
		this.M1 = M1;
		sz = 1;
		while(sz < n) sz <<= 1;
		seg = Enumerable.Repeat(M1, 2 * sz).ToArray();
	}
	public void Build() {
		for(int k = sz - 1; k > 0; k--) seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
	}
	public void Update(long k, TM x) {
		k += sz;
		seg[k] = x;
		while(0<(k >>= 1)) {
			seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
		}
	}
	public TM Query(long a, long b) {
		TM L = M1, R = M1;
		for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
			if((a & 1)==1) L = f(L, seg[a++]);
			if((b & 1)==1) R = f(seg[--b], R);
		}
		return f(L, R);
	}
	public TM this[long k] {
		get { return seg[k + sz]; }
		set { seg[k + sz] = value; }
	}

}











