{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc());

    #endregion
    public object Calc()
    {
        var N = cr.Int;
        var robots = cr.Repeat(N).Select(cr => new Robot { x = cr.Int, d = cr.Int });
        Array.Sort(robots, (r1, r2) => r1.x.CompareTo(r2.x));

        var t = new int[N];
        {
            var xs = robots.Select(r => r.x).ToArray();
            for (int i = 0; i < robots.Length; i++)
                t[i] = xs.LowerBound(robots[i].x + robots[i].d);

            var seg = new SegmentTree(t);
            for (int i = t.Length - 1; i >= 0; i--)
            {
                t[i] = seg.Query(i, t[i]);
                seg.Update(i, t[i]);
            }
        }
        Mod[] dp = new Mod[N + 1];
        dp[N] = 1;
        for (int i = N - 1; i >= 0; i--)
        {
            dp[i] = dp[i + 1] + dp[t[i]];
        }
        return dp[0];
    }
}

