    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        N = cr;
        {
            var origrobots = cr.Repeat(N).Select(cr => new Pair { v1 = cr, v2 = cr }).Sort(p => p.v1);
            var xs = new int[N];
            var ds = new int[N];
            robots = new int[N];
            for (int i = 0; i < origrobots.Length; i++)
            {
                xs[i] = origrobots[i].v1;
                ds[i] = origrobots[i].v2;
            }
            for (int i = 0; i < robots.Length; i++)
                robots[i] = xs.LowerBound(xs[i] + ds[i]);
            var seg = new SegmentTree(robots);
            for (int i = robots.Length - 1; i >= 0; i--)
                seg.Update(i, robots[i] = seg.Query(i, robots[i]));
        }
        Mod[] dp = NewArray(N + 1, Mod.invalid);
        dp[N] = 1;
        for (int i = N - 1; i >= 0; i--)
        {
            Mod on = dp[robots[i]];
            dp[i] = dp[i + 1] + on;
        }
        return dp[0];
    }
    int N;
    int[] robots;
}
