class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        var x = new int[n];
        var d = new int[n];
        for (int i = 0; i < n; i++)
        {
            sc.Multi(out x[i], out d[i]);
        }
        Array.Sort(x, d);
        var sg = new Segtree<int>(n, Math.Max, -M * 2);
        var dp = new long[n + 1];
        dp[n] = 1;
        for (int i = n - 1; i >= 0 ; i--)
        {
            int r = x.LowerBound(x[i] + d[i]);
            int rr = Math.Max(sg.run(i + 1, r), x[i] + d[i]);
            sg.update(i, rr);
            int k = x.LowerBound(rr);
            dp[i] = (dp[i + 1] + dp[k]) % M;
        }
        Prt(dp[0]);
    }
}

