type pii struct{ x, d int }

type segmentTree struct {
	arr []int
	n   int
}

func segmentTreeInit(a int) segmentTree {
	n := 1
	for n < a {
		n <<= 1
	}
	res := segmentTree{make([]int, 2*n-1), n}
	return res
}

func (st segmentTree) update(k, a int) {
	k += st.n - 1
	st.arr[k] = a
	for k > 0 {
		k = (k - 1) / 2
		st.arr[k] = max(st.arr[2*k+1], st.arr[2*k+2])
	}
}

func (st segmentTree) query(a, b, k, l, r int) int {
	if r <= a || b <= l {
		return 0
	}
	if a <= l && r <= b {
		return st.arr[k]
	}
	return max(st.query(a, b, 2*k+1, l, (l+r)/2), st.query(a, b, 2*k+2, (l+r)/2, r))
}

