	robots[i], robots[j] = robots[j], robots[i]
}

type solution struct {
	n                 int
	robots            robotList
	maxCollisionCache map[int]int
	answers           []int
}

func read(sc *inputScanner) *solution {
	N := sc.nextInt()
	robots := make(robotList, N)
	for i := 0; i < N; i++ {
		X, D := sc.nextInt(), sc.nextInt()
		robots[i] = &robot{
			start: X,
			end:   X + D,
		}
	}
	sort.Sort(robots)
	return &solution{
		n:                 N,
		robots:            robots,
		maxCollisionCache: make(map[int]int),
		answers:           make([]int, N),
	}
}

func (sol *solution) solve() int {
	return sol.solveSub(0)
}

func (sol *solution) solveSub(from int) int {
	if from == sol.n-1 {
		return 2
	}
	notMovedCount := sol.solveSub(from + 1)
	sol.answers[from+1] = notMovedCount
	curR := sol.robots[from]
	hasCollission := false
	var maxCollision int
	var r *robot
	for i := from + 1; i < sol.n; i++ {
		r = sol.robots[i]
		if r.start >= curR.end {
			break
		}
		hasCollission = true
		var collisionIndex = i
		for {
			i, ok := sol.maxCollisionCache[collisionIndex]
			if !ok {
				break
			}
			collisionIndex = i
		}
		if collisionIndex > maxCollision {
			maxCollision = collisionIndex
		}
	}
	if !hasCollission {
		return (notMovedCount * 2) % P
	}
	// has collision
	sol.maxCollisionCache[from] = maxCollision
	var movedCount int
	if maxCollision == sol.n-1 {
		movedCount = 1
	} else {
		movedCount = sol.answers[maxCollision+1]
	}
	return movedCount + notMovedCount
}

