const Mod = 998244353

type Pair struct {
	x int
	d int
}

type ByX []Pair

func (a ByX) Len() int {
	return len(a)
}

func (a ByX) Swap(i, j int) {
	a[i], a[j] = a[j], a[i]
}

func (a ByX) Less(i, j int) bool {
	return a[i].x < a[j].x
}

func main() {
	r := bufio.NewReader(os.Stdin)

	var n int
	fmt.Fscanf(r, "%d\n", &n)

	rb := make([]Pair, n)
	for i := 0; i < n; i++ {
		fmt.Fscanf(r, "%d %d\n", &rb[i].x, &rb[i].d)
	}

	sort.Sort(ByX(rb))

	p := New(n)
	sku := make([]int, n)
	for i := n - 1; i >= 0; i-- {
		lo, hi := i, n-1
		for lo <= hi {
			mid := (lo + hi) / 2
			if rb[i].x+rb[i].d <= rb[mid].x {
				hi = mid - 1
			} else {
				lo = mid + 1
				sku[i] = mid
			}
		}
		sku[i] = max(sku[i]+1, p.query(sku[i]+1))
		p.insert(i+1, sku[i])
	}

	dp := make([]int, n+1)
	dp[n] = 1
	for i := n - 1; i >= 0; i-- {
		dp[i] = (dp[i+1] + dp[sku[i]]) % Mod
	}

	fmt.Println(dp[0])
}

