    sum += a
  }
  return sum
}
func AbsInt(x int) int {
  if x < 0 { x = -x }
  return x
}

func Mod(I []int, P int) int {
  N := 0
  for _, i := range I {
    N = N * 10 + i
    N %= P
  }
  return N
}

type Robots [][]int
func (R Robots) Len() int { return len(R) }
func (R Robots) Less(i, j int) bool { return R[i][0] < R[j][0] }
func (R Robots) Swap(i, j int) { R[i], R[j] = R[j], R[i] }

func Search(R [][]int, x int) int {
  N := len(R)
  if R[N - 1][0] < x { return N - 1 }
  ltx, gex := 0, N - 1
  for 1 < gex - ltx {
    med := (gex + ltx) / 2
    if R[med][0] < x {
      ltx = med
    } else {
      gex = med
    }
  }
  return ltx
}

func Find(T *[]int, u int) int {
  if (*T)[u] == u { return u }
  (*T)[u] = Find(T, (*T)[u])
  return (*T)[u]
}
func Unite(T *[]int, u, v int) {
  ru, rv := Find(T, u), Find(T, v)
  if ru < rv {
    (*T)[ru] = rv
  } else {
    (*T)[rv] = ru
  }
}

const p = 998244353

func Solve() {
  var N int
  NextInt(&N)
  R := make([][]int, N)
  for i := range R {
    NextIntVec(&R[i])
  }
  sort.Sort(Robots(R))
  T := make([]int, N)
  for i := range T {
    T[i] = i
  }
  for i := N - 1; 0 <= i; i-- {
    Unite(&T, i, Search(R, R[i][0] + R[i][1]))
  }
  DP := make([][]int, N + 1)
  DP[N] = []int{0, 1}
  for i := N - 1; 0 <= i; i-- {
    DP[i] = make([]int, 2)
    DP[i][0] = (DP[i + 1][0] + DP[i + 1][1]) % p
    r := Find(&T, i) + 1
    DP[i][1] = (DP[r][0] + DP[r][1]) % p
  }
  Write(SumInt(DP[0]...) % p)
}

func main() {
  Solve()
  Output()
}

