	N := getInt()
	p := make(robots, N)
	for i := 0; i < N; i++ {
		x, d := getInt(), getInt()
		p[i] = robot{x, d}
	}
	sort.Sort(p)

	to = make([][]int, N)
	pq := make(PQ, 0)
	heap.Init(&pq)
	for i := N - 1; i >= 0; i-- {
		x := p[i].x
		d := p[i].y
		for pq.Len() > 0 {
			item := heap.Pop(&pq).(*Item)
			if item.priority < x+d {
				to[i] = append(to[i], item.x)
			} else {
				heap.Push(&pq, item)
				break
			}
		}
		heap.Push(&pq, &Item{x, i, 0})
	}

	ans := 1
	for pq.Len() > 0 {
		item := heap.Pop(&pq).(*Item)
		ans *= dfs(item.x)
		ans %= mod
	}
	out(ans)
}

