func (sol *solution) solveSub(from int) {
	if from == sol.n-1 {
		sol.answers[from] = 2
		return
	}
	sol.solveSub(from + 1)
	notMovedCount := sol.answers[from+1]
	curR := sol.robots[from]
	hasCollission := false
	var maxCollision int
	var r *robot
	for i, j := from+1, sol.n-1; i <= j; {
		middle := (i + j) / 2
		r = sol.robots[middle]
		if r.start >= curR.end {
			j = middle - 1
		} else {
			i = middle + 1
			maxCollision = middle
			hasCollission = true
		}
	}
	// fmt.Println(maxCollision)
	var movedCount int
	if !hasCollission {
		// no collision
		movedCount = notMovedCount
	} else {
		// has collision
		found := sol.maxIndexSegTree.query(from+1, maxCollision)
		if found != nil {
			maxCollision = int(*found)
		}
		sol.maxIndexSegTree.update(from, segmentTreeElement(maxCollision))
		// actual := *sol.maxIndexSegTree.query(from, from)
		// if maxCollision != int(actual) {
		// 	fmt.Printf("after update: expected: %d, actual: %d\n", maxCollision, actual)
		// 	fmt.Println("after update: ", sol.maxIndexSegTree.nodes)
		// 	panic("")
		// }
		// fmt.Println(sol.maxIndexSegTree.nodes)
		if maxCollision == sol.n-1 {
			movedCount = 1
		} else {
			movedCount = sol.answers[maxCollision+1]
		}
	}
	// fmt.Printf("m: %d, n:%d, t: %d, max: %d\n", movedCount, notMovedCount, movedCount+notMovedCount, maxCollision)
	sol.answers[from] = (movedCount + notMovedCount) % P
}

