const mod = 998244353

type pii struct{ x, d int }

type segmentTree struct {
	arr []int
	e   int
	n   int
	fn  func(a, b int) int
}

func segmentTreeInit(n int, fn func(a, b int) int, e int) segmentTree {
	a := 1
	for a < n {
		a <<= 1
	}
	res := segmentTree{make([]int, 2*a), e, a, fn}
	for i := 0; i < 2*a; i++ {
		res.arr[i] = e
	}
	return res
}

func (seg segmentTree) build(arr []int) {
	for i := 0; i < len(arr); i++ {
		seg.arr[i+seg.n] = arr[i]
	}
	for i := seg.n - 1; i > 0; i-- {
		seg.arr[i] = seg.fn(seg.arr[2*i], seg.arr[2*i+1])
	}
}

func (seg segmentTree) update(i, a int) {
	i += seg.n
	seg.arr[i] = a
	for i > 1 {
		i = i / 2
		seg.arr[i] = seg.fn(seg.arr[2*i], seg.arr[2*i+1])
	}
}

func (seg segmentTree) query(a, b int) int {
	var query func(a, b, k, l, r int) int
	query = func(a, b, k, l, r int) int {
		if r <= a || b <= l {
			return seg.e
		}
		if a <= l && r <= b {
			return seg.arr[k]
		}
		return seg.fn(query(a, b, 2*k, l, (l+r)/2), query(a, b, 2*k+1, (l+r)/2, r))
	}
	return query(a, b, 1, 0, seg.n)
}

