const mod = 998244353

func dfs(n int, e [][]int) int {
	ret := 1
	for _, v := range e[n] {
		ret *= dfs(v, e)
		ret %= mod
	}
	ret = (ret + 1) % mod
	return ret
}

func main() {
	sc.Split(bufio.ScanWords)
	N := getInt()
	r := make(robots, N)
	for i := 0; i < N; i++ {
		x, d := getInt(), getInt()
		r[i] = robot{x, d}
	}
	sort.Sort(r)
	// out(r)

	e := make([][]int, N)
	s := make([][2]int, 0)
	for i := N - 1; i >= 0; i-- {
		x := r[i].x
		d := r[i].d
		for len(s) > 0 && s[len(s)-1][0] < x+d {
			e[i] = append(e[i], s[len(s)-1][1])
			s = s[:len(s)-1]
		}
		s = append(s, [2]int{x, i})
	}
	// out(s)
	// out(e)
	ans := 1
	for _, v := range s {
		ans *= dfs(v[1], e)
		ans %= mod
	}
	out(ans)
}

