type mint int64

func (mt mint) mod() mint {
	m := mint(998244353)
	mt %= m
	if mt < 0 {
		return mt + m
	}
	return mt
}
func (mt mint) inv() mint {
	var m, y mint
	m.subAs(2)
	dbl := mt
	y = 1
	for i := 0; i < 31; i++ {
		if m%2 == 1 {
			y.mulAs(dbl)
		}
		m >>= 1
		dbl.mulAs(dbl)
	}
	return y
}
func (mt mint) add(x mint) mint {
	return (mt + x).mod()
}
func (mt mint) sub(x mint) mint {
	return (mt - x).mod()
}
func (mt mint) mul(x mint) mint {
	return (mt * x).mod()
}
func (mt mint) div(x mint) mint {
	return mt.mul(x.inv())
}
func (mt *mint) addAs(x mint) *mint {
	*mt = mt.add(x)
	return mt
}
func (mt *mint) subAs(x mint) *mint {
	*mt = mt.sub(x)
	return mt
}
func (mt *mint) mulAs(x mint) *mint {
	*mt = mt.mul(x)
	return mt
}
func (mt *mint) divAs(x mint) *mint {
	*mt = mt.div(x)
	return mt
}

type decomposition struct {
	h, chunk int
	unit     []int
	bucket   [][]int
}

func newDecomposition(n int) decomposition {
	unit := make([]int, 1)
	unit[0] = 1
	bucket := make([][]int, 1)
	bucket[0] = make([]int, n)
	chunk := 8
	for i := 0; n > 1; i++ {
		n = (n-1)/chunk + 1
		bucket = append(bucket, make([]int, n))
		unit = append(unit, unit[i]*chunk)
	}
	return decomposition{
		h:      len(unit),
		chunk:  chunk,
		unit:   unit,
		bucket: bucket,
	}
}
func (dec *decomposition) minimize(index int, value int) {
	dec.bucket[0][index] = value
	for i := 0; i < dec.h-1; i++ {
		p := index / dec.chunk
		r := (p + 1) * dec.chunk
		if r >= len(dec.bucket[i]) {
			r = len(dec.bucket[i])
		}
		dec.bucket[i+1][p] = value
		for j := p * dec.chunk; j < r; j++ {
			if dec.bucket[i+1][p] > dec.bucket[i][j] {
				dec.bucket[i+1][p] = dec.bucket[i][j]
			}
		}
		index /= dec.chunk
	}
}
func (dec *decomposition) min(l, r int) int {
	min := dec.bucket[0][l]
	if len(dec.bucket[0]) < r {
		r = len(dec.bucket[0])
	}
	i := 0
	for index := l; index < r; index += dec.unit[i] {
		for i < dec.h-1 && index%dec.unit[i+1] == 0 {
			i++
		}
		for index+dec.unit[i] > r {
			i--
		}
		ii := index / dec.unit[i]
		if min > dec.bucket[i][ii] {
			min = dec.bucket[i][ii]
		}
	}
	return min
}

