	curR := sol.robots[from]
	hasCollission := false
	var maxCollision int
	var r *robot
	for i := from + 1; i < sol.n; i++ {
		r = sol.robots[i]
		if r.start >= curR.end {
			break
		}
		hasCollission = true
		maxCollision = i
	}
	var movedCount int
	if !hasCollission {
		// no collision
		movedCount = notMovedCount
	} else {
		// has collision
		found := sol.maxIndexSegTree.query(from+1, maxCollision)
		if found != nil {
			maxCollision = int(*found)
