type segmentTreeElement int

type mergeFunc func(index int, left int, right int, leftElement segmentTreeElement, rightElement segmentTreeElement) segmentTreeElement

type segmentTree struct {
	nodes  []segmentTreeElement
	size   int
	mergeF mergeFunc
}

func newSegmentTree(elements []segmentTreeElement, mergeF mergeFunc) *segmentTree {
	size := len(elements)
	treeSize := 2*int(math.Pow(2.0, math.Ceil(math.Log2(float64(size))))) - 1
	nodes := make([]segmentTreeElement, treeSize)
	t := &segmentTree{
		nodes:  nodes,
		size:   size,
		mergeF: mergeF,
	}
	t.build(elements, 0, 0, size-1)
	return t
}

func (t *segmentTree) build(elements []segmentTreeElement, index int, leftBound int, rightBound int) {
	if leftBound == rightBound {
		t.nodes[index] = elements[leftBound]
		return
	}

	bisect := (leftBound + rightBound) / 2
	leftIndex := 2*index + 1
	rightIndex := 2*index + 2
	t.build(elements, leftIndex, leftBound, bisect)
	t.build(elements, rightIndex, bisect+1, rightBound)

	left := t.nodes[leftIndex]
	right := t.nodes[rightIndex]

	t.nodes[index] = t.mergeF(index, leftIndex, rightIndex, left, right)
}

func (t *segmentTree) query(left int, right int) *segmentTreeElement {
	query := &segmentQuery{
		t:     t,
		left:  left,
		right: right,
	}
	return query.queryRange(0, 0, t.size-1)
}

type segmentQuery struct {
	t     *segmentTree
	left  int
	right int
}

func (q *segmentQuery) queryRange(index int, leftBound int, rightBound int) *segmentTreeElement {
	if q.left > rightBound || q.right < leftBound {
		return nil
	}
	if q.left <= leftBound && q.right >= rightBound {
		return &q.t.nodes[index]
	}
	bisect := (leftBound + rightBound) / 2
	leftIndex := 2*index + 1
	rightIndex := 2*index + 2
	left := q.queryRange(leftIndex, leftBound, bisect)
	right := q.queryRange(rightIndex, bisect+1, rightBound)
	if left != nil && right != nil {
		element := q.t.mergeF(index, leftIndex, rightIndex, *left, *right)
		return &element
	} else if left != nil {
		return left
	} else {
		return right
	}
}

func (t *segmentTree) update(index int, value segmentTreeElement) {
	update := &segmentUpdate{
		t:     t,
		index: index,
		value: value,
	}
	update.updateRange(0, 0, t.size-1)
}

type segmentUpdate struct {
	t     *segmentTree
	index int
	value segmentTreeElement
}

func (u *segmentUpdate) updateRange(index int, leftBound int, rightBound int) {
	if leftBound == rightBound {
		u.t.nodes[index] = u.value
		return
	}
	leftIndex := 2*index + 1
	rightIndex := 2*index + 2
	bisect := (leftBound + rightBound) / 2
	if u.index <= bisect {
		u.updateRange(leftIndex, leftBound, bisect)
	} else {
		u.updateRange(rightIndex, bisect+1, rightBound)
	}
	left := u.t.nodes[leftIndex]
	right := u.t.nodes[rightIndex]

	u.t.nodes[index] = u.t.mergeF(index, leftIndex, rightIndex, left, right)
}

