func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	rr := make(robots, n)
	for i := 0; i < n; i++ {
		rr[i].x = getNextInt(scanner)
		rr[i].d = getNextInt(scanner)
	}
	sort.Sort(rr)

	dec := newDecomposition(n)
	for i := 0; i < n; i++ {
		dec.minimize(i, i)
	}
	dp := make([]mint, n+1)
	dp[0] = 1
	for i := 0; i < n; i++ {
		dp[i+1].addAs(dp[i])
		l := -1
		r := i
		for l+1 < r {
			m := (l + r) >> 1
			if rr[i].x+rr[i].d <= rr[m].x {
				l = m
				continue
			}
			r = m
		}
		if r < i {
			mn := dec.min(r, i)
			dp[i+1].addAs(dp[mn])
			dec.minimize(i, mn)
			continue
		}
		dp[i+1].addAs(dp[i])
	}
	fmt.Fprintln(writer, dp[n])
}

