type decomposition struct {
	h, chunk int
	unit     []int
	bucket   [][]int
}

func newDecomposition(n int) decomposition {
	unit := make([]int, 1)
	unit[0] = 1
	bucket := make([][]int, 1)
	bucket[0] = make([]int, n)
	chunk := 8
	for i := 0; n > 1; i++ {
		n = (n-1)/chunk + 1
		bucket = append(bucket, make([]int, n))
		unit = append(unit, unit[i]*chunk)
	}
	return decomposition{
		h:      len(unit),
		chunk:  chunk,
		unit:   unit,
		bucket: bucket,
	}
}
func (dec *decomposition) minimize(index int, value int) {
	dec.bucket[0][index] = value
	for i := 0; i < dec.h-1; i++ {
		p := index / dec.chunk
		r := (p + 1) * dec.chunk
		if r >= len(dec.bucket[i]) {
			r = len(dec.bucket[i])
		}
		dec.bucket[i+1][p] = value
		for j := p * dec.chunk; j < r; j++ {
			if dec.bucket[i+1][p] > dec.bucket[i][j] {
				dec.bucket[i+1][p] = dec.bucket[i][j]
			}
		}
		index /= dec.chunk
	}
}
func (dec *decomposition) min(l, r int) int {
	return dec.minh(l, r, 0)
}

func (dec *decomposition) minh(l, r, h int) int {
	m := dec.bucket[h][l]
	ll := (l + dec.chunk) / dec.chunk
	rr := r / dec.chunk
	for i := l; i < r && i < ll*dec.chunk; i++ {
		if m > dec.bucket[h][i] {
			m = dec.bucket[h][i]
		}
	}
	if ll < rr {
		mm := dec.minh(ll, rr, h+1)
		if m > mm {
			m = mm
		}
	}
	for i := rr * dec.chunk; i < r; i++ {
		if m > dec.bucket[h][i] {
			m = dec.bucket[h][i]
		}
	}
	return m
}

