            RS[i] = N-1;
            continue;
        }
        auto l = RS[i], r = N-1;
        while (l+1 < r) {
            auto m = (l+r)/2;
            if (rs[m].x >= d) {
                r = m;
            } else {
                l = m;
            }
        }
        RS[i] = RS[l];
    }

    auto DP = new long[](N);
    DP[] = -1;
    long solve(long i) {
        if (i == N) return 1;
        if (DP[i] == -1) {
            DP[i] = (solve(i+1) + solve(RS[i]+1)) % P;
        }
        return DP[i];
    }
    writeln(solve(0));
}

