auto solve( long[ 2 ][] xds )
{
	const M = 998244353L;

	// 各ロボットを起動したときの除外数を計算
	auto rs = new long[ xds.length ];
	{
		auto xds_s = xds.sort();
		auto st = SegmentTree!( max, long.min )( xds.length );
		foreach_reverse( i, xd; xds )
		{
			// 自分の移動距離
			auto dt = xd[ 0 ] + xd[ 1 ];

			// 連鎖した各ロボットのうちの最大移動距離
			auto fs = xds_s[ i .. $ ].lowerBound( [ dt, long.min ] );
			auto dm = max( dt, st.query( i, i + fs.length ) );
			st.set( i, dm );

			// 最大移動距離で何台除外されるか
			if( dt < dm ) fs = xds_s[ i .. $ ].lowerBound( [ dm, long.min ] );
			rs[ i ] = fs.length;
		}
	}

	// dp[ i番目 ] = 通り数
	auto dp = new long[ rs.length + 1 ];
	dp[ 0 ] = 1;
	foreach( i, r; rs )
	{
		dp[ i + 1 ] = ( dp[ i + 1 ] + dp[ i ] ) % M;		// 起動しない
		dp[ i + r ] = ( dp[ i + r ] + dp[ i ] ) % M;		// 起動する
	}
	return dp[ $ - 1 ];
}

