struct SegmentTree( alias op = ( ( a, b ) => a + b ), long I = long.init )
{
	long   n;
	long   nc;
	long   bc;
	long[] ps;

	this( long n )
	{
		this.n = n;
		for( nc = 1; nc < n; nc <<= 1 ){ /* nop */ }
		bc = nc - 1;
		ps.length = nc + bc;
		static if( I != long.init ) ps[] = I;
	}

	this( long[] qs )
	{
		this( qs.length );
		ps[ bc .. bc + qs.length ] = qs;
		foreach_reverse( i, ref p; ps[ 0L .. bc ] ) p = op( ps[ i * 2 + 1 ], ps[ i * 2 + 2 ] );
	}

	void set( long i, long v )
	{
		i = bc + i;
		ps[ i ] = v;
		while( 0 < i )
		{
			i = ( i - 1 ) / 2;
			ps[ i ] = op( ps[ i * 2 + 1 ], ps[ i * 2 + 2 ] );
		}
	}

	auto get( long i )
	{
		return ps[ bc + i ];
	}

	auto query( long l, long r )
	{
		long f( long l, long r, long i, long il, long ir )
		{
			if( ir <= l || r <= il ) return I;
			if( l <= il && ir <= r ) return ps[ i ];
			auto im = ( il + ir ) / 2;
			return op( f( l, r, i * 2 + 1, il, im ), f( l, r, i * 2 + 2, im, ir ) );
		}
		return f( l, r, 0, 0, nc );
	}

	auto length()
	{
		return n;
	}

	auto toString()
	{
		return ps[ bc .. bc + n ].to!( string );
	}
}

