  auto sta = new Stack!X;
  foreach_reverse(x; xs){
    long pos = x.pos, right = x.right, value = x.value;
    while(sta.length && sta.peek.pos < right){
      X popped = sta.pop;
      right.raiseTo(popped.right);
      value *= popped.value, value %= mod;
    }
    value += 1;
    sta.push(X(pos, right, value));
    log("x:", x, "sta:", sta);
  }

