from collections import deque


class SegmentTree():
    """セグメント木の実装"""

    def __init__(self, size, INF=-100000000):
        """セグメント木の初期化"""
        self.size = size
        self.n = 2 ** ((self.size-1).bit_length())
        self.treesize = 2 * self.n - 1
        self.inf = INF
        self.tree = [self.inf for i in range(self.treesize)]

    def update(self, key, value):
        """key番目の値をvalueに更新する"""
        k = key + self.n - 1
        self.tree[k] = value
        while k > 0:
            k = (k - 1) // 2
            self.tree[k] = max(self.tree[2 * k + 1], self.tree[2 * k + 2])

    def query(self, a, b):
        """区間[a, b)の最大値を求める"""
        if a > b:
            raise ValueError("a must be less than equal b.")
        q = deque()
        q.append((0, 0, self.n))
        s = deque()
        while len(q) > 0:
            k, l, r = q.pop()
            if r <= a or b <= l:
                continue
            elif a <= l and r <= b:
                s.append(self.tree[k])
            else:
                q.append((2 * k + 1, l, (l + r) // 2))
                q.append((2 * k + 2, (l + r) // 2, r))
        return max(s)

    def __setitem__(self, key, value):
        self.update(key, value)

    def __getitem__(self, key):
        left = self.treesize >> 1
        return self.tree[left + key]

    def tolist(self):
        left = self.treesize >> 1
        right = left + self.size
        return self.tree[left:right] 

    def __str__(self):
        return str(self.tolist())

    def __repr__(self):
        return str(self)



class Robot():

    def __init__(self, x, d):
        self.x = x
        self.d = d

    def __str__(self):
        return "({}, {})".format(self.x, self.d)

    def __repr__(self):
        return str(self)

    def __eq__(self, another):
        return self.x == another.x

    def __lt__(self, another):
        return self.x < another.x


def read():
    N = int(input().strip())
    robots = list()
    for i in range(N):
        x, d = list(map(int, input().strip().split()))
        robots.append(Robot(x, d))
    return N, robots


def solve(N, robots, MOD=998244353):
    dp = [0 for i in range(N+1)]
    dp[N] = 1
    robots = list(sorted(robots))
    rx = [robot.x for robot in robots]
    rdx = [robot.x + robot.d for robot in robots]
    # parent_idx = [i for i in range(N)]  # ここを工夫する
    parent_idx = SegmentTree(N)
    for i in range(N):
        parent_idx[i] = i

    for i in range(N-1, -1, -1):
        # 区間[x, x+d) にある全要素 R[i+1: i+j] を探す
        j = bisect.bisect_left(rx[i:], rdx[i])
        # parent_idx[i] = max(parent_idx[i:i+j])
        mv = parent_idx.query(i, i+j)
        parent_idx[i] = mv

    for i in range(N-1, -1, -1):
        dp[i] = dp[i+1] + dp[parent_idx[i]+1]
        dp[i] %= MOD
    return dp[0]


