class SegmentTree():
    """セグメント木の実装"""

    def __init__(self, size, INF=100000000):
        """セグメント木の初期化"""
        self.size = size
        n = 1
        while n < size:
            n <<= 1
        self.n = n
        self.treesize = 2 * self.n - 1
        self.tree = [-INF for i in range(self.treesize)]
        self.inf = INF

    def __setitem__(self, key, value):
        self.update(key, value)

    def update(self, key, value):
        """key番目の値をvalueに更新する"""
        k = key + self.n - 1
        self.tree[k] = value
        while k > 0:
            k = (k - 1) // 2
            self.tree[k] = max(self.tree[2 * k + 1], self.tree[2 * k + 2])

    def query(self, a, b):
        """区間[a, b)の最大値を求める"""
        if a > b:
            raise ValueError("a must be less than equal b.")
        return self.__query(a, b, 0, 0, self.n)

    def __query(self, a, b, k, l, r):
        if r <= a or b <= l:
            return -self.inf
        if a <= l and r <= b:
            return self.tree[k]
