            vl = self.__query(a, b, 2 * k + 1, l, (l + r) // 2)
            vr = self.__query(a, b, 2 * k + 2, (l + r) // 2, r)
            return max(vl, vr)

    def __getitem__(self, key):
        return self.tree[self.treesize - self.n + key]

    def __str__(self):
        return str(self.tree[self.treesize - self.n:self.treesize - self.n + self.size])

    def __repr__(self):
        return str(self)


