    N = int(input())
    robo = [None] * N
    for i in range(N):
        robo[i] = tuple(map(int, input().split()))
    robo.sort(key=itemgetter(0))
    pos = [x[0] for x in robo]
    dst = [x[0] + x[1] for x in robo]
    rmq = RangeMaximumQuery(dst)
    for i in range(N-1)[::-1]:
