class SegmentTree:
    def __init__(self,N,default):
        # 演算の定義
        self.op = max
        # 初期化の値
        self.default = default
        self.N0 = 2**(N-1).bit_length()
        self.tree = [self.default]*(2*self.N0)

    # k番目の値をxに更新
    def update(self,k,x):
        k += self.N0-1
        self.tree[k] = x
        while k >= 0:
            k = (k-1)//2
            self.tree[k] = self.op(self.tree[2*k+1], self.tree[2*k+2])

    # 区間[l,r]へのクエリ
    def query(self,l,r):
        L = l+self.N0
        R = r+self.N0+1 
        s = self.default
        while L < R:
            if R & 1:
                R -= 1
                s = self.op(s,self.tree[R-1])
            if L & 1:
                s = self.op(s,self.tree[L-1])
                L += 1
            L >>= 1; R >>= 1
        return s

    # k番目の値を取得
    def get(self,k):
        return self.tree[k+self.N0-1]

