const MOD: usize = 998244353;
fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    loop {
        let n = 4;
        let mut robots = vec![];
        let mut rng = thread_rng();
        for _ in 0..n {
            let x = rng.gen::<u8>() as i64;
            let d = rng.gen::<u8>() as i64 + 1;
            robots.push((x, d));
        }
        robots.sort_by_key(|r| r.0);

        let ans = solve(&robots);
        let naive = naive(&robots);
        assert_eq!(ans, naive, "ans:{} naive:{} {:?}", ans, naive, robots);
    }

    let n: usize = sc.read();
    let mut robots: Vec<(i64, i64)> = (0..n).map(|_| (sc.read(), sc.read())).collect();
    robots.sort_by_key(|r| r.0);
    let ans = solve(&robots);
    // let naive = naive(&robots);
    // assert_eq!(ans, naive, "ans:{} naive:{} {:?}", ans, naive, robots);
    println!("{}", ans);
