use std::cmp::{min, max};

fn main() {
    input!{
        n: usize,
        v: [(i64, i64); n]
    }
    let d = 998244353;
    let mut v: Vec<(i64, i64)> = v.iter().map(|&(x, d)| (x, x + d)).collect();
    v.sort_by_key(|x| x.0);
    let mut t = vec![vec![]; n];
    let mut i = 0;
    while i + 1 < n {
        i = dfs(i, i + 1, &v, &mut t);
    }
    let mut last: Vec<usize> = (0..n).collect();
    let mut done = vec![false; n];
    for i in 0..n {
        if done[i] {
            continue;
        }
        done[i] = true;
        dfs2(i, &t, &mut last, &mut done);
    }
    let mut dp = vec![0; n + 1];
    dp[0] = 1;
    for i in 0..n {
        dp[i + 1] = (dp[i + 1] + dp[i]) % d;
        dp[last[i] + 1] = (dp[last[i] + 1] + dp[i]) % d;
    }
    println!("{}", dp[n]);
}

fn dfs(r: usize, j: usize, v: &Vec<(i64, i64)>, t: &mut Vec<Vec<usize>>) -> usize {
    let n = v.len();
    let mut i = j;
    while i < n {
        if v[r].1 <= v[i].0 {
            break;
        }
        t[r].push(i);
        i = dfs(i, i + 1, v, t);
    }
    i
}

fn dfs2(r: usize, t: &Vec<Vec<usize>>, last: &mut Vec<usize>, done: &mut Vec<bool>) {
    for &v in &t[r] {
        done[v] = true;
        dfs2(v, t, last, done);
        last[r] = max(last[r], last[v]);
    }
}

