mod segment_tree {
    use std::cmp::*;

    pub struct SegmentTree<T> {
        n: usize,
        ini: T,
        xs: Vec<T>,
    }

    impl<T: Clone + Copy + PartialOrd> SegmentTree<T> {
        pub fn new(n: usize, ini: T) -> SegmentTree<T> {
            let n = n.next_power_of_two();
            SegmentTree {
                n: n,
                ini: ini,
                xs: vec![ini; 2 * n],
            }
        }
        pub fn update(&mut self, i: usize, x: T) {
            let mut i = i + self.n;
            self.xs[i] = x;
            i = i / 2;
            while i != 0 {
                self.xs[i] = if self.xs[2 * i] < self.xs[2 * i + 1] {
                    self.xs[2 * i]
                } else {
                    self.xs[2 * i + 1]
                };
                i /= 2;
            }
        }
        pub fn get_range_min(&self, l: usize, r: usize) -> T {
            let mut l = l + self.n;
            let mut r = r + self.n;
            let mut res = self.ini;
            while l < r {
                if l & 1 != 0 {
                    res = if res < self.xs[l] { res } else { self.xs[l] };
                    l += 1;
                }
                if r & 1 != 0 {
                    r -= 1;
                    res = if res < self.xs[r] { res } else { self.xs[r] };
                }
                l /= 2;
                r /= 2;
            }
            res
        }
        pub fn get(&self, i: usize) -> T {
            let i = i + self.n;
            self.xs[i]
        }
    }
}

