trait BinarySearch<T> {
    fn upper_bound(&self, value: &T) -> Option<usize>;
    fn lower_bound(&self, value: &T) -> Option<usize>;
}
impl<T: Ord> BinarySearch<T> for [T] {
    fn upper_bound(&self, value: &T) -> Option<usize> {
        let (mut ng, mut ok) = (-1, self.len() as isize);
        while (ok - ng).abs() > 1 {
            let mid = ((ok + ng) / 2) as usize;
            match value.cmp(&self[mid]) {
                Ordering::Less => {
                    ok = mid as isize;
                }
                Ordering::Equal | Ordering::Greater => {
                    ng = mid as isize;
                }
            };
        }
        if ok >= 0 && ok < self.len() as isize {
            Some(ok as usize)
        } else {
            None
        }
    }

    fn lower_bound(&self, value: &T) -> Option<usize> {
        let (mut ng, mut ok) = (-1, self.len() as isize);
        while (ok - ng).abs() > 1 {
            let mid = ((ok + ng) / 2) as usize;
            match value.cmp(&self[mid]) {
                Ordering::Less | Ordering::Equal => {
                    ok = mid as isize;
                }
                Ordering::Greater => {
                    ng = mid as isize;
                }
            };
        }
        if ok >= 0 && ok < self.len() as isize {
            Some(ok as usize)
        } else {
            None
        }
    }
}

