    let mut st = segment_tree::SegmentTree::new(n, 0, std::cmp::max);
    let mut to: Vec<usize> = (0..n).collect();
    for i in (0..n).rev() {
        let j = lower_bound(x[i] + d[i], &x);
        if j > i + 1 {
            to[i] = st.query(i, j);
        }
        st.update(i, to[i]);
    }

    let mut dp: Vec<u64> = vec![0; n + 1];
    dp[0] = 1;
    for i in 0..n {
        dp[i + 1] = (dp[i + 1] + dp[i]) % MOD;
        dp[to[i] + 1] = (dp[to[i] + 1] + dp[i]) % MOD;
    }
    println!("{}", dp[n]);
}

