use std::cmp;

struct SegmentTree {
    len: usize,
    node: Vec<usize>,
}

impl SegmentTree {
    fn new(n: usize) -> SegmentTree {
        let mut len: usize = 1;
        while len < n { len *= 2; }
        let node: Vec<usize> = vec![0; 2 * len - 1];
        SegmentTree { len, node }
    }

    fn update(&mut self, mut i: usize, x: usize) {
        i += self.len - 1;
        self.node[i] = x;
        while i > 0 {
            i = (i - 1) / 2;
            self.node[i] = {
                cmp::max(
                    self.node[2 * i + 1],
                    self.node[2 * i + 2],
                )
            };
        }
    }

    fn get(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> usize {
        if r <= a || b <= l {
            0
        } else if a <= l && r <= b {
            self.node[k]
        } else {
            cmp::max(
                self.get(a, b, 2 * k + 1, l, (l + r) / 2),
                self.get(a, b, 2 * k + 2, (l + r) / 2, r),
            )
        }
    }
}

const MOD: usize = 998_244_353;

fn main() {
    let n: usize = {
        let mut buf = String::new();
        std::io::stdin().read_line(&mut buf).unwrap();
        buf.trim_end().parse().unwrap()
    };

    let mut x: Vec<i32> = Vec::with_capacity(n);
    let mut d: Vec<i32> = Vec::with_capacity(n);
    for _ in 0..n {
        let mut buf = String::new();
        std::io::stdin().read_line(&mut buf).unwrap();
        let mut iter = buf.split_whitespace();
        x.push(iter.next().unwrap().parse().unwrap());
        d.push(iter.next().unwrap().parse().unwrap());
    }

    let mut ord: Vec<usize> = (0..n).collect();
    ord.sort_by(|&i, &j| x[i].cmp(&x[j]));
    let mut st = SegmentTree::new(n);
    let mut dp: Vec<usize> = vec![0; n + 1];
    dp[n] = 1;
    for i in (0..n).rev() {
        let (mut left, mut right) = (i, n);
        while right - left > 1 {
            let mid = (left + right) / 2;
            if x[ord[mid]] < x[ord[i]] + d[ord[i]] {
                left = mid;
            } else {
                right = mid;
            }
        }
        let k = cmp::max(i, st.get(i, right, 0, 0, st.len));
        st.update(i, k);
        dp[i] = (dp[i + 1] + dp[k + 1]) % MOD;
    }
    println!("{}", dp[0]);
}

