fn pow2(n: usize) -> ModInt {
    let mut res = ModInt::new(1);
    let mut beki = ModInt::new(2);
    let mut n = n;
    while n > 0 {
        if n % 2 == 1 {
            res *= beki;
        }
        beki *= beki;
        n /= 2;
    }
    res
}

trait Monoid<T>: SemiGroup<T> {
    fn identity() -> T;
}
trait SemiGroup<T>: Magma<T> {}
trait Magma<T> {
    fn operation(lhs: T, rhs: T) -> T;
}
#[derive(Debug)]
struct SegmentTree<T, U> {
    len: usize,
    nodes: Vec<T>,
    phantom: std::marker::PhantomData<U>,
}
impl<T, U> SegmentTree<T, U>
where
    U: Monoid<T>,
    T: Copy + Clone + std::fmt::Debug,
{
#[allow(dead_code)]
    fn new(n: usize) -> Self {
        let mut len = 1;
        while len < n {
            len *= 2;
        }
        SegmentTree {
            len: len,
            nodes: vec![U::identity(); 2 * len - 1],
            phantom: Default::default(),
        }
    }
#[allow(dead_code)]
    fn from_vec(vec: &Vec<T>) -> Self {
        let mut len = 1;
        while len < vec.len() {
            len *= 2;
        }
        let mut nodes = vec![U::identity(); 2 * len - 1];
        for i in 0..vec.len() {
            nodes[i + len - 1] = vec[i];
        }
        for i in (0..len - 1).rev() {
            nodes[i] = U::operation(nodes[2 * i + 1], nodes[2 * i + 2]);
        }
        SegmentTree {
            len: len,
            nodes: nodes,
            phantom: Default::default(),
        }
    }
#[allow(dead_code)]
    fn update(&mut self, index: usize, val: T) {
        let mut index = index;
        index += self.len - 1;
        self.nodes[index] = val;
        while index > 0 {
            index = (index - 1) / 2;
            self.nodes[index] = U::operation(self.nodes[2 * index + 1], self.nodes[2 * index + 2]);
        }
    }
    fn get(&self, l: usize, r: usize) -> T {
        self._get(l, r, 0, 0, self.len)
    }
    fn _get(&self, ql: usize, qr: usize, index: usize, l: usize, r: usize) -> T {
        if r <= ql || qr <= l {
            return U::identity();
        }
        if ql <= l && r <= qr {
            return self.nodes[index];
        }
        let vl = self._get(ql, qr, 2 * index + 1, l, (l + r) / 2);
        let vr = self._get(ql, qr, 2 * index + 2, (l + r) / 2, r);
        U::operation(vl, vr)
    }
}

struct IMonoid;
impl Monoid<usize> for IMonoid {
    fn identity() -> usize {
        0
    }
}
impl Magma<usize> for IMonoid {
    fn operation(lhs: usize, rhs: usize) -> usize {
        max!(lhs,rhs)
    }
}
impl SemiGroup<usize> for IMonoid {}

fn lower_bound<F>(l: usize, r: usize, criterion: F) -> usize
where
    F: Fn(usize) -> bool,
{
    let mut l = l;
    let mut r = r;
    while r - l > 1 {
        let mid = l + (r - l) / 2;
        if criterion(mid) {
            r = mid;
        } else {
            l = mid;
        }
    }
    l
}

fn solve() {
    let n = get!(usize);
    let mut xd = get!(isize, isize; n);
    xd.sort();

    let mut tree = SegmentTree::<usize, IMonoid>::new(n+1);
    for i in 0..n {
        tree.update(i,i);
    }
    for (i, &(x,d)) in xd.iter().rev().enumerate() {
        let i = n-i-1;
        let crit = |j: usize| -> bool {
            xd[j].0 > x+d-1
        };
        let j = lower_bound(i, n, crit);
        let mxi = tree.get(i,j+1);
        tree.update(i, mxi);
    }

    let mut dp = vec![ModInt::new(0); n+1];
    dp[n] = ModInt::new(1);

    for i in (0..n).rev() {
        dp[i] = dp[i+1]+dp[tree.get(i,i+1)+1];
    }
    println!("{}",dp[0]);
}

