    for i in 0..n {
        rmap.push((robots[i].0, i));
    }
    let mut seg = SegmentTree::new(n+10, 0, Rc::new(|a,b| max(a,b)));
    for i in 0..n {
        seg.set(i, i);
    }
    let mut to = vec![0; n];
    to[n-1] = n-1;
    for i in (0..n-1).rev() {
        let x = robots[i].0 + robots[i].1;
        let (_, idx) = rmap.peek_less((x, 0)).unwrap();
        to[i] = seg.compute_range(i, idx+1);
        seg.set(i, to[i]);
    }

    let mut tree = vec![vec![]; n];
    let mut pop_cnt = vec![0; n];

