    (0..n).map(|i| f(i)).collect()
}

const MODULO: usize = 998244353;

fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let (x, d): (Vec<i64>, Vec<i64>) = {
        let mut xd: Vec<(i64, i64)> = vec(n, |_| (scan(tokens), scan(tokens)));
        xd.sort();
        let x = xd.iter().map(|&(xi, _)| xi).collect();
        let d = xd.iter().map(|&(_, di)| di).collect();
        (x, d)
    };
    let mut parent: Vec<usize> = vec(n, |i| i);
    let mut children: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut stack = Vec::new();
    for i in 0..n {
        while !stack.is_empty() && {
            let j = *stack.last().unwrap();
            x[j] + d[j] <= x[i]
        } {
            stack.pop();
        }
        if !stack.is_empty() {
            let j = *stack.last().unwrap();
            parent[i] = j;
            children[j].push(i);
        }
        stack.push(i);
    }
    let mut ans = 1;
    for i in 0..n {
        if parent[i] == i {
            ans = ans * dfs(i, &children) % MODULO;
        }
    }
    println!("{}", ans);
}

fn dfs(i: usize, children: &Vec<Vec<usize>>) -> usize {
    let mut res = 1;
    for &j in &children[i] {
        res = res * dfs(j, children) % MODULO;
    }
    (res + 1) % MODULO
}

