    xd.sort();
    let mut dp = vec![Modi64(0); n + 1];
    dp[n] = 1.into();
    let mut v = vec![];
    v.extend(xd.iter().map(|&(x, _d)| x));
    let cmp = v.into_iter().collect::<Compress<_>>();
    let mut seg = SegmentTree::from_vec(vec![0; n + 1], MaxMonoid::new(0));
