fn solve(robots: &Vec<(i64, i64)>) -> usize {
    let n = robots.len();
    let mut dp = vec![[0, 0]; n];
    let mut seg = SegmentTree::new(n, 0, std::cmp::max);
    seg.update(n - 1, n - 1);
    dp[n - 1][0] = 1;
    dp[n - 1][1] = 1;
    for i in (0..(n - 1)).rev() {
        let touch = robots[i].0 + robots[i].1;
        let upper = robots
            .binary_search_by_key(&(touch * 2 - 1), |r| r.0 * 2)
            .err()
            .unwrap();
        assert!(upper == n || touch <= robots[upper].0);
        dp[i][0] = (dp[i + 1][0] + dp[i + 1][1]) % MOD;

        if upper <= i + 1 {
            dp[i][1] = (dp[i + 1][0] + dp[i + 1][1]) % MOD;
            seg.update(i, i);
        } else {
            let next = seg.query(i + 1, upper);
            seg.update(i, next);
            dp[i][1] = dp[next][1];
        }
    }
    (dp[0][0] + dp[0][1]) % MOD
}

fn naive(robots: &Vec<(i64, i64)>) -> usize {
    let n = robots.len();
    let mut set = std::collections::BTreeSet::new();
    for mask in 0..(1 << n) {
        let mut dead = 0;
        let mut cur_min = std::i64::MIN;
        for i in 0..n {
            if mask & (1 << i) != 0 || robots[i].0 < cur_min {
                cur_min = std::cmp::max(cur_min, robots[i].0 + robots[i].1);
            }
            if robots[i].0 < cur_min {
                dead += 1 << i;
            }
        }
        set.insert(dead);
    }
    set.len()
}
pub struct SegmentTree<T, F> {
    seg: Vec<T>,
    n: usize,
    f: F,
    initial_value: T,
}

impl<T: Copy, F> SegmentTree<T, F>
where
    F: Fn(T, T) -> T,
{
    pub fn new(size: usize, initial_value: T, f: F) -> SegmentTree<T, F> {
        let mut m = 1;
        while m <= size {
            m <<= 1;
        }
        SegmentTree {
            seg: vec![initial_value; m * 2],
            n: m,
            f: f,
            initial_value: initial_value,
        }
    }

    pub fn update(&mut self, k: usize, value: T) {
        let mut k = k;
        k += self.n - 1;
        self.seg[k] = value;
        while k > 0 {
            k = (k - 1) >> 1;
            self.seg[k] = (self.f)(self.seg[k * 2 + 1], self.seg[k * 2 + 2]);
        }
    }

    /// Get the minimum value in the array in the range [a, b)
    ///
    /// # Panics
    ///
    /// Panics if `a >= b`.
    pub fn query(&self, a: usize, b: usize) -> T {
        assert!(a < b);
        self.query_range(a, b, 0, 0, self.n)
    }

    fn query_range(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> T {
        if r <= a || b <= l {
            self.initial_value
        } else if a <= l && r <= b {
            self.seg[k]
        } else {
            let x = self.query_range(a, b, k * 2 + 1, l, (l + r) >> 1);
            let y = self.query_range(a, b, k * 2 + 2, (l + r) >> 1, r);
            (self.f)(x, y)
        }
    }
}
pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::Read;

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut p: Vec<_> = (0..n).map(|_| {
        let x: i64 = it.next().unwrap().parse().unwrap();
        let d: i64 = it.next().unwrap().parse().unwrap();
        (x, d)
    }).collect();
    p.sort();
    const MOD: u32 = 998_244_353;
    let mut dp = vec![0u32; n + 1];
    dp[n] = 1;
    let mut stack = vec![];
    for (i, &(x, d)) in p.iter().enumerate().rev() {
        let mut r = i + 1;
        while let Some((a, b)) = stack.pop() {
            if a >= x + d {
                stack.push((a, b));
                break;
            }
            r = std::cmp::max(r, b);
        }
        dp[i] = (dp[i + 1] + dp[r]) % MOD;
        stack.push((x, r));
    }
    println!("{}", dp[0]);
}

fn main() {
    run();
}

use std::str::FromStr;

fn get_one<T : FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    return s.trim().parse().ok().unwrap();
}

fn get_vec<T : FromStr>() -> Vec<T> {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    return s.trim().split_whitespace().map(|e| e.parse().ok().unwrap()).collect();
}

fn get_vec_by_lines<T : FromStr>(n : usize) -> Vec<T> {
    let mut v : Vec<T> = Vec::new();
    for _i in 0..n {
        let x : T = get_one();
        v.push(x);
    }
    return v;
}

fn dfs(v : &Vec<(i64,i64)>, cur : usize, till : i64) -> (i64, usize) {
    //println!("{} {} {:?}", cur, till, v[cur]);
    if cur >= v.len() || v[cur].0 > till {
        return (1,cur);
    }
    let mut x = cur+1;
    let mut clsans = 1;
    while x < v.len() && v[x].0 < v[cur].0+v[cur].1 {
        //println!("   {} {:?}", x, v[x]);
        let (lans, next) = dfs(v,x,v[x].0 + v[x].1);
        x = next;
        clsans *= lans;
        clsans %= 998244353;
    }
    return (1+clsans, x);
}

fn main() {
    let n : usize = get_one();

    let mut v : Vec<(i64, i64)> = Vec::new();
    for i in 0..n {
        let xd : Vec<i64> = get_vec();
        v.push((xd[0],xd[1]));
    }

    v.sort();
    let mut next = 0;
    let mut ans = 1;
    while next < v.len() {
        let (lans, lnext) = dfs(&v, next, v[next].0+1);
        next = lnext;
        ans *= lans;
        ans %= 998244353;
    }

    println!("{}", ans);
}

