fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut p = vec![];
    let mut z = vec![];
    for _ in 0..n {
        let x: i64 = it.next().unwrap().parse().unwrap();
        let d: i64 = it.next().unwrap().parse().unwrap();
        p.push((x, d));
        z.push(x);
        z.push(x + d);
    }
    p.sort();
    z.sort();
    z.dedup();
    let mut seg = segment_tree::PURQ::new(z.len(), 0, |a, b| std::cmp::max(a, b));
    let mut dp = vec![ModInt::zero(); p.len() + 1];
    dp[n] = ModInt::one();
    for (i, &(x, d)) in p.iter().enumerate().rev() {
        let l = z.binary_search(&x).unwrap();
        let r = z.binary_search(&(x + d)).unwrap();
        let v = seg.find(l, r);
        if v == 0 {
            seg.update(l, i + 1);
        } else {
            seg.update(l, v);
        }
        let k = seg.find(l, l + 1);
        dp[i] = dp[i + 1] + dp[k];
    }
    println!("{}", dp[0]);
