fn run() {
    input! {
        n: usize,
        p: [(i32, i32); n],
    }
    let mut p = p;
    p.sort();
    p.push((std::i32::MAX, std::i32::MAX));
    let mut dp = vec![ModInt::zero(); n + 1];
    dp[n] = ModInt::one();
    let mut stack: Vec<usize> = vec![n];
    for (i, &(x, d)) in p.iter().enumerate().rev().skip(1) {
        let mut way = dp[i + 1];// 動かさない
        while let Some(&k) = stack.last() {
            let y = p[k].0;
            if x + d <= y {
                break;
            } else {
                stack.pop();
            }
        }
        way += dp[*stack.last().unwrap()];
        dp[i] = way;
        stack.push(i);
    }
    let ans = dp[0];
    println!("{}", ans);
}

fn main() {
    run();
}

