fn solve(n: usize, coords: &[(i64, i64)]) -> u64 {
    let mut targets = vec![0; n];
    let mut segtree = SegmentTree::new(n);
    segtree.update(n - 1, n - 1);
    targets[n - 1] = n - 1;
    for i in (0..(n - 1)).rev() {
        let end = coords[i].0 + coords[i].1;
        let index = match coords.binary_search_by(|t| t.0.cmp(&end)) {
            Ok(j) => j - 1,
            Err(j) => j - 1,
        };
        if index > i {
            let r = segtree.query(i + 1, index);
            targets[i] = r;
            segtree.update(i, r);
        } else {
            targets[i] = i;
            segtree.update(i, i);
        }
    }
    let mut dp = vec![0; n];
    dp[n - 1] = 2;
    for i in (0..(n - 1)).rev() {
        dp[i] = dp[i + 1];
        if targets[i] != n - 1 {
            dp[i] += dp[targets[i] + 1];
        } else {
            dp[i] += 1;
        }
        dp[i] %= MOD;
    }
    dp[0]
}

struct SegmentTree {
    size: usize,
    values: Vec<usize>,
}

impl SegmentTree {
    fn new(n: usize) -> SegmentTree {
        let mut size = 1;
        while size < n {
            size *= 2;
        }
        let len = 2 * size - 1;
        SegmentTree {
            size,
            values: vec![0; len],
        }
    }

    fn update(&mut self, i: usize, x: usize) {
        let size = self.size;
        self.update_rec(0, 0, size - 1, i, x);
    }

    fn update_rec(&mut self, index: usize, l: usize, r: usize, i: usize, x: usize) {
        if l == i && r == i {
            self.values[index] = x;
            return;
        }
        let mid = (l + r) / 2;
        if i <= mid {
            self.update_rec(2 * index + 1, l, mid, i, x);
        } else {
            self.update_rec(2 * index + 2, mid + 1, r, i, x);
        }
        self.values[index] = max(x, self.values[index]);
    }

    fn query(&self, start: usize, end: usize) -> usize {
        self.query_rec(0, 0, self.size - 1, start, end)
    }

    fn query_rec(&self, index: usize, l: usize, r: usize, start: usize, end: usize) -> usize {
        if l == start && r == end {
            return self.values[index];
        }
        let mid = (l + r) / 2;
        if end <= mid {
            self.query_rec(2 * index + 1, l, mid, start, end)
        } else if start > mid {
            self.query_rec(2 * index + 2, mid + 1, r, start, end)
        } else {
            let left = self.query_rec(2 * index + 1, l, mid, start, mid);
            let right = self.query_rec(2 * index + 2, mid + 1, r, mid + 1, end);
            max(left, right)
        }
    }
}

