const M: i64 = 998244353;

/// 降順 xs について z 未満の最小添字を返す
fn bisearh(xs: &Vec<(i64, i64)>, z: i64) -> usize {
    let xs: Vec<_> = xs.iter().map(|&(x, _)| x).collect();
    let n = xs.len();
    if xs[0] < z { return 0 }
    let mut left = 0;  // xs[left] >= z
    let mut right = n;  // xs[right] < z
    for _ in 0..100 {
        let mid = (left + right) / 2;
        if xs[mid] >= z {
            left = mid;
        } else {
            right = mid;
        }
    }
    right
}

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let mut rs: Vec<_> = (0..n).map(|_| {
        let x: i64 = sc.cin();
        let d: i64 = sc.cin();
        (x, d)
    }).collect();
    rs.sort(); rs.reverse();
    // trace!(&rs);

    // st[i] = i 番目を起動した場合に起動する最小の番目
    let mut st = SegmentTree::new(n);
    st.update(0, MinInt::Val(0));
    {
        for i in 1..n {
            st.update(i, MinInt::Val(i));
            let (x, d) = rs[i];
            let k = bisearh(&rs, x + d);
            if let MinInt::Val(l) = st.product(k..i + 1) {
                st.update(i, MinInt::Val(l));
            }
            // trace!(i, k, st[i]);
        }
    }
    return;

    // dp[i][0] = i を起動しない 場合の 0..i の動かし方
    // dp[i][1] = i を起動する   場合の 0..i の動かし方
    let mut dp = vec![vec![ModInt(0, M); 2]; n];
    dp[0][0] += 1;
    dp[0][1] += 1;
    for i in 1..n {
        dp[i][0] = dp[i - 1][0] + dp[i - 1][1];
        let k = st[i].unwrap();
        dp[i][1] = if k == 0 {
            ModInt(1, M)
        } else {
            dp[k - 1][0] + dp[k - 1][1]
        };
    }

    put!(dp[n-1][0] + dp[n-1][1]);

}

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
struct ModInt(i64, i64);  // (residual, modulo)
impl ModInt {
    fn new(residual: i64, modulo: i64) -> ModInt {
        if residual >= modulo { ModInt(residual % modulo, modulo) }
        else if residual < 0 { ModInt((residual % modulo) + modulo, modulo) }
        else { ModInt(residual, modulo) }
    }
    fn unwrap(self) -> i64 { self.0 }
    fn inv(self) -> Self {
        fn exgcd(r0: i64, a0: i64, b0: i64, r: i64, a: i64, b: i64)
                -> (i64, i64, i64) {
            if r > 0 {
                exgcd(r, a, b, r0 % r, a0 - r0 / r * a, b0 - r0 / r * b)
            } else {
                (a0, b0, r0)
            }
        }
        let (a, _, r) = exgcd(self.0, 1, 0, self.1, 0, 1);
        if r != 1 { panic!("{:?} has no inverse!", self); }
        ModInt(((a % self.1) + self.1) % self.1, self.1)
    }
    fn pow(self, n: i64) -> Self {
        if n < 0 {
            self.pow(-n).inv()
        } else if n == 0 {
            ModInt(1, self.1)
        } else if n == 1 {
            self
        } else {
            let mut x = (self * self).pow(n / 2);
            if n % 2 == 1 { x *= self }
            x
        }
    }
}
impl std::fmt::Display for ModInt {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}
impl std::ops::Neg for ModInt {
    type Output = Self;
    fn neg(self) -> Self {
        if self.0 == 0 { return self }
        ModInt(self.1 - self.0, self.1)
    }
}
impl std::ops::Add<i64> for ModInt {
    type Output = Self;
    fn add(self, other: i64) -> Self { ModInt::new(self.0 + other, self.1) }
}
